returns text language plpgsql security invoker set search_path = '' as $official_bank$
declare
  v_bank jsonb := $official_bank_source${"code":"ECO101","courseId":"e01c0d3f-3f5e-5197-b96f-ac7935fc2fe8","seedActor":"00000000-0000-4000-8000-000000000042","actor":"00000000-0000-4000-8000-000000000043","bankCount":916,"shell":{"contentKey":"principles-economics-1","titles":["Principles of Economics I"],"level":"100-level","semesters":["first-semester"]},"audited":[],"keep":[],"retire":[],"add":[{"itemId":"b7bb76ac-5f9e-5df9-9bc8-fb1c6985f19f","questionId":"ac18f5a3-8d11-5ae7-9029-9dcfbc479dbb","sourceKey":"bank:ECO101:ECO-0031","payload":{"prompt":"A point on a production possibilities frontier:","options":["could indicate an optimal use of resources.","is less efficient that a point inside the production possibilities frontier","reflects an unattainable level unless technology is further developed to fully employ all resources to their optimum capacity","Implies that too much labor and not enough capital is being used"],"correctOption":0,"section":"Nature of Economic Science","explanation":"Points on the production possibilities frontier show combinations where all resources are fully and efficiently used, so a point on it can show an optimal use of resources. Option B has it backwards, because points inside the frontier are the inefficient ones. Option C describes points outside the frontier, and option D has no basis in the PPC."}},{"itemId":"8ba58ee0-650c-5f28-905a-2a8880758e88","questionId":"b9fef29a-8fef-5cfb-9669-18a1371e99a9","sourceKey":"bank:ECO101:ECO-0034","payload":{"prompt":"What is the opportunity cost of one year at College or University?","options":["one year to re-write UTME.","at least one year of earnings in a paid employment","Joblessness","idleness and social vices."],"correctOption":1,"section":"Nature of Economic Science","explanation":"Opportunity cost is the value of the next best alternative given up, and for a year at university that is mainly the earnings you could have made from a paid job in that year. Options A, C and D are not alternatives you give up by choosing school; they are other situations, not the forgone next best use of your time."}},{"itemId":"b5a13dbf-7577-5299-ad8b-cca6d722524a","questionId":"3b117a87-302f-5993-87d3-60b78aed379b","sourceKey":"bank:ECO101:ECO-0051","payload":{"prompt":"Opportunity cost is","options":["Implicit cost","Alternative forgone","Economic surplus denied","Sacrifice for Consumption"],"correctOption":1,"section":"Nature of Economic Science","explanation":"Opportunity cost is the next best alternative given up when a choice is made. Option A, implicit cost, is one kind of opportunity cost to a firm, not the definition. Options C and D are vague and not the standard meaning."}},{"itemId":"adc9e6f4-077b-5159-a9ad-169f361ca118","questionId":"e4b333fd-edb9-5ada-b741-78dc78f7303e","sourceKey":"bank:ECO101:ECO-0094","payload":{"prompt":"The central problem of every society is","options":["to maintain peace and order","to prevent riots in our cities","the scarcity of economic resources","to prevent democracy"],"correctOption":2,"section":"Nature of Economic Science","explanation":"Every society faces scarcity: resources are limited while human wants are unlimited, so choices must be made. Options A and B are political or security goals, not the central economic problem, and option D has nothing to do with economics."}},{"itemId":"11fa0880-9b17-5540-ab54-32a23b568da6","questionId":"7779a6d9-0a96-5f5d-9915-859c76653d13","sourceKey":"bank:ECO101:ECO-0095","payload":{"prompt":"The word \"Economic\" refers to","options":["scarce","limited","commanding a price","all of the above"],"correctOption":3,"section":"Nature of Economic Science","explanation":"In economics, something is economic when it is scarce or limited in supply relative to wants and therefore commands a price. Options A, B and C each describe one part of this meaning, so all of the above is the best answer."}},{"itemId":"76e55e53-411f-5260-a33a-5e10bdf1a011","questionId":"d663cb1f-f89b-5620-8ce7-9e08ca260a63","sourceKey":"bank:ECO101:ECO-0096","payload":{"prompt":"The fundamental questions that every society must answer because of scarcity are","options":["what to produce","how to produce","for whom to produce","all of the above"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Because of scarcity, every society must decide what to produce, how to produce it and for whom to produce it. These three questions together make up the basic economic problem, so picking only A, B or C leaves out the other two."}},{"itemId":"94a647aa-cd59-542a-a8e1-36f4947a5e94","questionId":"dbd2df21-a9ff-5b3a-ad9c-0d70d80570ff","sourceKey":"bank:ECO101:ECO-0097","payload":{"prompt":"In a free enterprise economy, the question of what, how and for whom to produce are solved by","options":["planning committee","the central problem of every society","the price mechanism","none of the above"],"correctOption":2,"section":"Nature of Economic Science","explanation":"In a free enterprise (market) economy, prices signal what people want and what is profitable, so the price mechanism decides what, how and for whom to produce. Option A, a planning committee, is how a command economy works. Option B is just the problem, not the way it is solved."}},{"itemId":"d6bbb67c-dea7-540b-a015-19120d5ada1d","questionId":"afa2d929-7f18-5cdd-8a15-371e53d853fd","sourceKey":"bank:ECO101:ECO-0098","payload":{"prompt":"Economics studies how individuals and organizations in society engage in the","options":["production of goods and services","exchange of goods and services","consumption of goods and services","all of the above"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Economics studies how people and organisations engage in production, exchange and consumption of goods and services. Options A, B and C each name only one of these activities, so all of the above is correct."}},{"itemId":"7617e029-161b-5f79-9157-25dc7e33e72f","questionId":"9c850159-34ea-5f59-a977-6bf4dc1bbc5a","sourceKey":"bank:ECO101:ECO-0108","payload":{"prompt":"A graph that describes the maximum amount of one good that can be produced for every level of production of the other good is","options":["Opportunity cost","Comparative advantage","Production possibilities","Allocative efficiency"],"correctOption":2,"section":"Nature of Economic Science","explanation":"The production possibilities curve (frontier) shows the maximum amount of one good that can be produced for each level of output of the other good, given resources and technology. Option A, opportunity cost, is shown by the slope of this curve but is not the graph itself. Options B and D are related ideas, not the name of the graph."}},{"itemId":"f8fa622d-9eda-5721-98c1-86e04b1ec892","questionId":"e2ca8610-87d1-5de2-8ad9-84b9f7d53834","sourceKey":"bank:ECO101:ECO-0111","payload":{"prompt":"Scarcity means","options":["Resources are limited relative to wants","Welfare is maximized","Choices are limited","Economic surplus exist"],"correctOption":0,"section":"Nature of Economic Science","explanation":"Scarcity means that resources are limited compared with people's unlimited wants, so not every want can be satisfied. Option C mixes this up: scarcity forces people to make choices, it does not mean that choices are limited. Options B and D describe possible outcomes in an economy, not what scarcity means."}},{"itemId":"a6ed3040-ab59-5843-a50b-0cce7a3b51d6","questionId":"46c8e160-34f8-57e0-ae1e-0b4e5e304edc","sourceKey":"bank:ECO101:ECO-0114","payload":{"prompt":"Microeconomics is the study of","options":["Individual choice under scarcity.","Performance of national economic","Economic naturalism","No-free lunch principle"],"correctOption":0,"section":"Nature of Economic Science","explanation":"Microeconomics studies how individual households and firms make choices under scarcity and how they interact in particular markets. Option B, the performance of the national economy, is macroeconomics. Options C and D are ideas used in economics, not the definition of microeconomics."}},{"itemId":"b4298a3b-041b-5624-b13b-00b50ecbf21d","questionId":"63ade6b8-353d-5a96-985d-982f858b9b02","sourceKey":"bank:ECO101:ECO-0198","payload":{"prompt":"According to marginal analysis, optimal decision-making involves:","options":["Taking actions whenever the marginal benefit exceeds the marginal cost.","Taking actions whenever the marginal benefit is positive.","Taking actions only if the marginal cost is zero.","All of the above."],"correctOption":0,"section":"Nature of Economic Science","explanation":"Marginal analysis says you should take an action as long as its extra benefit is greater than its extra cost, stopping where they are equal. Option B ignores cost completely, and option C is too strict, since many worthwhile actions have positive marginal cost."}},{"itemId":"7d4f110d-744b-5802-a145-b8a9a4644600","questionId":"491c6d72-edd0-54ce-adbf-75ae65d8021a","sourceKey":"bank:ECO101:ECO-0234","payload":{"prompt":"________ is a fundamental problem caused by shortage of land, labour, capital, and entrepreneurship.","options":["fiscal surplus","deficit","scarcity","corruption"],"correctOption":2,"section":"Nature of Economic Science","explanation":"Scarcity is the basic economic problem: resources such as land, labour, capital and entrepreneurship are limited compared with people's wants. Options A and B are budget ideas, and option D is a social problem, not the fundamental economic one."}},{"itemId":"c3c30336-8a6b-5c03-aff4-ba8f1924585a","questionId":"a3cd9e36-6489-5d23-b34f-50f1b42f2f76","sourceKey":"bank:ECO101:ECO-0235","payload":{"prompt":"An imagined point D outside of the Production Possibility Frontier (PPF) is called","options":["achievable combinations","desirable combinations","attainable combinations","unattainable combinations"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Points outside the PPF cannot be produced with the economy's current resources and technology, so they are unattainable combinations. Option C describes points on or inside the frontier. Option B may be true in the sense that people would like more, but it does not describe what the point represents."}},{"itemId":"8d279593-b0d1-5f9e-b204-09377d625845","questionId":"471ea44f-2dbe-59a2-87fb-d7764dd11b5c","sourceKey":"bank:ECO101:ECO-0237","payload":{"prompt":"________ measures the cost of anything that we have chosen relative to alternatives that could have been chosen.","options":["concept of opportunity cost","concept of demand and supply","theory of cost","theory of consumption"],"correctOption":0,"section":"Nature of Economic Science","explanation":"Opportunity cost is the value of the next best alternative given up when a choice is made, so it measures the cost of a choice relative to the alternatives. Option C, the theory of cost, deals with a firm's production costs, not the cost of choosing."}},{"itemId":"cf1f2d8f-607f-5e46-948d-318b67ae7945","questionId":"4a277346-f3e3-596e-b050-826c5029581d","sourceKey":"bank:ECO101:ECO-0238","payload":{"prompt":"An economy that is situated inside of its Production Possibility Frontier (PPF) can still","options":["give out more resources as aids","use available resources more efficiently","borrow more resources","consumes more of its resources"],"correctOption":1,"section":"Nature of Economic Science","explanation":"A point inside the PPF means some resources are idle or used inefficiently, so the economy can produce more by using what it has more efficiently, moving towards the frontier. Options A, C and D do not explain how production can rise from within the frontier."}},{"itemId":"45c3b27e-bbb6-503f-9f36-4864150d1917","questionId":"0b6d6fe2-3165-5756-94bf-c823555f3f07","sourceKey":"bank:ECO101:ECO-0247","payload":{"prompt":"Common economic systems include: traditional system, command system, ________ and mixed system","options":["pure market system","free market forces","free democratic system","pure democratic system"],"correctOption":0,"section":"Nature of Economic Science","explanation":"The main economic systems are the traditional, command, market (free enterprise) and mixed systems, so the missing one is the pure market system. Option B describes the forces of demand and supply at work in a market, not a type of economic system, and options C and D are political rather than economic systems."}},{"itemId":"d51d8dbf-8c43-5e60-998b-5f9b01b5deb3","questionId":"92626be1-6583-5e1d-8f8a-0a1c51e9af01","sourceKey":"bank:ECO101:ECO-0251","payload":{"prompt":"Economic agents make choices because ________","options":["goods and services are readily available","resources at their disposal are scarce","They have the resources","the free market forces are active"],"correctOption":1,"section":"Nature of Economic Science","explanation":"Because resources are scarce relative to wants, economic agents cannot have everything and must choose among alternatives. Option A is the opposite of scarcity, and option C alone does not explain why choice is needed."}},{"itemId":"b261e1cb-f1ec-5c47-8f87-21b8265a98a2","questionId":"12ef44cb-f5c7-5c97-a7ab-d1f0d3584aad","sourceKey":"bank:ECO101:ECO-0254","payload":{"prompt":"In a modern mixed economy, the state","options":["controls consumption","determines who produces","solely produces for the economy","intervenes in market transactions"],"correctOption":3,"section":"Nature of Economic Science","explanation":"In a mixed economy, most economic activity is carried out by private individuals and firms, but the government intervenes in markets through regulation, taxes and public provision. Option C describes a command economy, and options A and B overstate the state's role."}},{"itemId":"ac96bb93-e988-5929-9780-a36693967d70","questionId":"81240b9f-d071-5c7b-b660-8e4f8bbcc2ca","sourceKey":"bank:ECO101:ECO-0258","payload":{"prompt":"The concept of 'scarcity' can lead to the following except","options":["Makes economic goods to command prices","Makes supply of resources readily available","Imposes the need to make choices.","Imposes the need to study economics."],"correctOption":1,"section":"Nature of Economic Science","explanation":"Scarcity means resources are limited relative to wants, so it cannot make resources readily available. Scarcity is exactly what makes goods command prices (A), forces people to make choices (C) and creates the need to study economics (D)."}},{"itemId":"747ee713-0dc3-5d90-bbfc-d29144ddf105","questionId":"b0fef80e-ce3f-51c7-8f22-39b7b0a61fa1","sourceKey":"bank:ECO101:ECO-0261","payload":{"prompt":"One of the following fails to describe a market economy","options":["Individuals are for their own self-interest","Incentives drive people's behavior","Prices are centrally controlled","Activities are governed by legal framework"],"correctOption":2,"section":"Nature of Economic Science","explanation":"In a market economy prices are set freely by the forces of demand and supply, so prices being centrally controlled does not describe it. Self-interest (A), incentives (B) and a legal framework that protects property and contracts (D) are all features of a market economy."}},{"itemId":"b6ad6221-f2dd-500e-aea9-8320dea94991","questionId":"9cc607f4-4b2c-57fa-8cca-ae121091c541","sourceKey":"bank:ECO101:ECO-0264","payload":{"prompt":"Means in economics simply means ________","options":["road to the market","goods and services","available economic resource","money"],"correctOption":2,"section":"Nature of Economic Science","explanation":"In economics, 'means' are the scarce resources available to satisfy human wants, such as land, labour and capital. Option B, goods and services, are what people want to end up with, and option D, money, is only one form of resource."}},{"itemId":"29ea3ea3-305c-549e-be5e-e6c4fef4da21","questionId":"af7db925-eefa-5101-9a4b-86c886a9b323","sourceKey":"bank:ECO101:ECO-0267","payload":{"prompt":"The assumptions of production possibility frontier include the following except","options":["Resources are used on just two commodities.","Resources are fully utilized.","Resources are limited in supply.","Resources are sufficient for all production."],"correctOption":3,"section":"Nature of Economic Science","explanation":"The PPF assumes resources are limited, fully used, and shared between just two goods, so options A, B and C are assumptions. Option D is not, because if resources were sufficient for all production there would be no scarcity and no need to choose."}},{"itemId":"dbd47df5-a9fa-5da0-b059-550e9e223442","questionId":"3db5507f-ed5e-5284-8c95-02cc1c242c6f","sourceKey":"bank:ECO101:ECO-0269","payload":{"prompt":"In a free market setting, anyone who provides goods and services is called","options":["an innovator","a good manufacturer","an entrepreneur","a producer"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Anyone who provides goods and services in the market is a producer. Option C, an entrepreneur, is the specific person who organises the factors and bears risk, so not every provider is one, and option A, an innovator, is narrower still."}},{"itemId":"e0dc2e0d-05e1-5ce3-b7e3-17e3a8805237","questionId":"382682c6-2b46-5cc7-a31c-b63b05e3405c","sourceKey":"bank:ECO101:ECO-0270","payload":{"prompt":"In a modern market economy, the state performs all of the following functions, except","options":["provision of laws of contract","provision of laws of ownership","provision of laws controlling prices","provision of stable-valued money"],"correctOption":2,"section":"Nature of Economic Science","explanation":"In a market economy prices are set by demand and supply, so laws controlling prices are not one of the state's basic functions. The state does provide contract law (A), property law (B) and a stable currency (D), which markets need to work well."}},{"itemId":"62fb0e17-b1fa-5a9a-8e82-c64e0419d9e8","questionId":"a3b78c79-9e33-5412-b6a3-cc7648cee7e8","sourceKey":"bank:ECO101:ECO-0370","payload":{"prompt":"There would be no economic problem if:","options":["We were dealing with an economy consisting of one man on a desert island","Man did not live in nation - states","We were dealing with societies whose wants could be more than fully satisfied by the resources at their command","None of the above"],"correctOption":2,"section":"Nature of Economic Science","explanation":"The economic problem exists because wants exceed the resources available to satisfy them; if resources could more than fully satisfy all wants, there would be nothing to economise. Option A is wrong because even one person alone on an island has limited time and resources and must make choices. Option B is irrelevant, since scarcity exists with or without nation-states."}},{"itemId":"542c38b7-f565-5b21-82f7-95f1b670265f","questionId":"e5a990ac-2088-5b83-a0b6-f143d660b7a5","sourceKey":"bank:ECO101:ECO-0371","payload":{"prompt":"Which of the following is not a feature of a centrally planned economy?","options":["Priorities in agricultural production set by farmers","State direction and ownership of the economy","State ownership of land","Limited operation of the market mechanism"],"correctOption":0,"section":"Nature of Economic Science","explanation":"In a centrally planned economy the state, not individual farmers, sets production priorities, so farmers setting their own priorities is not a feature of it. Options B, C and D, state direction and ownership, state ownership of land and limited use of the market, are all typical features of central planning."}},{"itemId":"71f139c8-12e5-5d84-a53d-2355d1456a43","questionId":"eeaf1539-a70f-533e-af2e-66fdbca8c6a7","sourceKey":"bank:ECO101:ECO-0375","payload":{"prompt":"A command economy is one in which","options":["The government allows the individuals to have a say in production and consumption","Prices set freely by demand and supply guide production and consumption","The government makes all the decisions about production and consumption","None of the above"],"correctOption":2,"section":"Nature of Economic Science","explanation":"In a command economy the government makes all the major decisions about what to produce, how to produce and for whom. Option B describes a market economy, where the price mechanism, not the state, guides these decisions. Option A describes a market or mixed system, where individuals have a say."}},{"itemId":"f7e50a4c-38f9-5bfb-98e3-978a32da711a","questionId":"f54f447b-b4d4-5dae-b0f1-99183f9fea55","sourceKey":"bank:ECO101:ECO-0376","payload":{"prompt":"A mixed economy is one in which","options":["The government and the private sector interact in solving economic problems","The government makes all decisions","The private sector is given a free hand to operate","All of the above"],"correctOption":0,"section":"Nature of Economic Science","explanation":"A mixed economy combines private enterprise with government participation, so both sectors work together to solve the basic economic problems. Option B describes a command economy, and option C describes a free-market economy, so D cannot be right either."}},{"itemId":"70093386-f3f5-51a5-87f4-67a77a92cffc","questionId":"049cfd0b-27ec-54f0-a1d3-65442a17460c","sourceKey":"bank:ECO101:ECO-0377","payload":{"prompt":"Choices are necessary because","options":["Resources are scarce","Resources are abundant","Human beings are difficult to please","All of the above"],"correctOption":0,"section":"Nature of Economic Science","explanation":"Choice is necessary because resources are scarce relative to our wants, so we cannot have everything and must decide what to give up. Option B is the opposite, since abundant resources would remove the need to choose. Option C is a personal trait, not the economic reason for choice."}},{"itemId":"dfa7393c-6aed-58c1-9a48-bf03698d5383","questionId":"c1cfc3e7-ed5e-539b-a878-6c7174074946","sourceKey":"bank:ECO101:ECO-0378","payload":{"prompt":"Consumption is the act of","options":["Saving part of income for future use","Making goods and services","Using goods and services to satisfy wants","All of the above"],"correctOption":2,"section":"Nature of Economic Science","explanation":"Consumption is the act of using goods and services to satisfy wants. Option B describes production, the making of goods and services, not their use. Option A describes saving, which is the part of income not spent on consumption, so D cannot be right either."}},{"itemId":"fc205077-9edf-546f-8885-b54c6783b543","questionId":"a229ba36-b40a-56be-9f3c-5028af2163b9","sourceKey":"bank:ECO101:ECO-0384","payload":{"prompt":"Economics is the study of","options":["How scarce resources are distributed","How goods and services are produced in an economy","How society decides what, how and for whom to produce","How human beings choose between their wants and their goods"],"correctOption":2,"section":"Nature of Economic Science","explanation":"Economics studies how society decides what to produce, how to produce it and for whom, given scarce resources. Options A and B each cover only one part of this, distribution or production. Option D is close, but it is vaguely worded, while C captures the full set of choices economics studies."}},{"itemId":"5c085527-408c-53cd-8550-b097dc72b644","questionId":"8d32bcee-c69c-5c9a-91b0-d87e95bb7e16","sourceKey":"bank:ECO101:ECO-0394","payload":{"prompt":"The fundamental problem of economics is","options":["The establishment of a political framework to determine the what, how and for whom of production","To establish an equitable distribution of income","The scarcity of productive resources relative to society's unlimited wants","The establishment of prices for the factors of production"],"correctOption":2,"section":"Nature of Economic Science","explanation":"The fundamental economic problem is scarcity: resources are limited while human wants are unlimited. Option A describes how a society might organise its response to scarcity, not the problem itself. Options B and D are specific issues that only arise because of scarcity."}},{"itemId":"1c298392-dfb3-5f24-9570-06cf46f0b43b","questionId":"1822a501-4b87-5371-8d3a-67460d7f4285","sourceKey":"bank:ECO101:ECO-0402","payload":{"prompt":"Micro-economics is often referred to as price theory. Why?","options":["Because it focuses on the general price level of the whole economy","Because it focuses on how relative prices of small units of economic elements are determined and various equilibria reached","Because it deals with small units","Because it determines price"],"correctOption":1,"section":"Nature of Economic Science","explanation":"Microeconomics is called price theory because it explains how the prices of individual goods and factors are determined in particular markets and how equilibrium is reached. Option A is wrong because the general price level is a macroeconomic variable. Option C mentions small units without explaining the link to price, and option D is too vague."}},{"itemId":"a4bf5219-cd2a-50e5-b43d-a6bc751ee18f","questionId":"f574a713-4dfd-5a03-b34d-23e7fe4e5153","sourceKey":"bank:ECO101:ECO-0403","payload":{"prompt":"Markets in which governments do not intervene are called:","options":["Open markets","Close market","Free markets","International markets"],"correctOption":2,"section":"Nature of Economic Science","explanation":"A free market is one where prices and quantities are set by demand and supply without government intervention. Option A, open markets, usually refers to markets open to all buyers or to central bank operations, not the absence of government. Option D refers to trade between countries."}},{"itemId":"2ac702c8-3f8e-5ac4-9646-55ec7765f2e1","questionId":"21c6163d-45b2-5215-b5cd-527cb490fb4f","sourceKey":"bank:ECO101:ECO-0469","payload":{"prompt":"Economics is defined as a science which studies human behaviour as a relationship between ends and scarce means by:","options":["Alfred Marshall","Adam Smith","Lionel Robbins","F. A. Walker"],"correctOption":2,"section":"Nature of Economic Science","explanation":"Lionel Robbins defined economics as the science that studies human behaviour as a relationship between ends and scarce means which have alternative uses. Option A, Alfred Marshall, defined it as a study of mankind in the ordinary business of life, and option B, Adam Smith, saw it as an inquiry into the nature and causes of the wealth of nations."}},{"itemId":"1a43e460-256b-5c29-82e6-3a2ea6af8e45","questionId":"bc650b58-e67e-5d4f-8d52-285e33c42d95","sourceKey":"bank:ECO101:ECO-0470","payload":{"prompt":"The opportunity cost of a free good is:","options":["One","Zero","Negative","Positive"],"correctOption":1,"section":"Nature of Economic Science","explanation":"A free good, such as air, is available in unlimited quantity, so using more of it means giving up nothing else, and its opportunity cost is zero. Option D, positive, applies to economic (scarce) goods. Option C is wrong because opportunity cost cannot be negative."}},{"itemId":"611b0c08-9a99-58f4-9a32-4a89add8a1cd","questionId":"c1903c20-3232-5a02-a933-47acd9503cc2","sourceKey":"bank:ECO101:ECO-0476","payload":{"prompt":"The basic economic problems include:","options":["What and how much to produce","How to produce","For whom to produce","All of the above"],"correctOption":3,"section":"Nature of Economic Science","explanation":"The basic economic problems every society faces are what (and how much) to produce, how to produce it, and for whom to produce it. Options A, B and C each state one of these questions, so the full answer is all of them; picking just one leaves out the other two."}},{"itemId":"a3c6eb7d-7b56-5f67-8ff9-a51d49f3f162","questionId":"7d4cbcda-dbab-536f-a3a5-d68857f4ad35","sourceKey":"bank:ECO101:ECO-0489","payload":{"prompt":"Examples of demerit goods include:","options":["Alcohol","Cigarettes","Drugs","All of the above"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Demerit goods are goods whose consumption harms the user and often other people, so society believes they are over-consumed. Alcohol, cigarettes and harmful drugs all fit this description, so 'all of the above' is correct. Choosing only A, B or C leaves out the other examples, which are just as much demerit goods."}},{"itemId":"dfb9e36e-6c4d-5a48-bdeb-50555761a488","questionId":"35475117-5e69-523a-b56a-3c4679e68306","sourceKey":"bank:ECO101:ECO-0490","payload":{"prompt":"The PPC is also known as:","options":["PPB","PPF","Transformation curve","All of the above"],"correctOption":3,"section":"Nature of Economic Science","explanation":"The production possibility curve (PPC) is also called the production possibility frontier (PPF), the production possibility boundary (PPB) and the transformation curve, because it shows how resources can be shifted from one good to another. Since options A, B and C are all correct names, the best answer is all of the above."}},{"itemId":"0abd75e2-0caf-5ca5-9192-76bbf1af6a6e","questionId":"cbeb3ce5-2f96-5bee-9424-3d451fd50550","sourceKey":"bank:ECO101:ECO-0499","payload":{"prompt":"A type of good whose benefits people underestimate is called a:","options":["Merit good","Luxury good","Demerit good","Giffen good"],"correctOption":0,"section":"Nature of Economic Science","explanation":"Merit goods, such as education and healthcare, are goods whose benefits people tend to underestimate, so they consume less of them than is good for themselves and society. Option C, demerit goods, are the opposite: goods whose harm people underestimate. Option B, luxury goods, are defined by income, not by how their benefits are judged."}},{"itemId":"eb599bcd-8ba8-535a-9e61-c88d07484c03","questionId":"cbe180ad-13b8-5b1a-bac0-f6c8fc3fe3a2","sourceKey":"bank:ECO101:ECO-0523","payload":{"prompt":"Reasons why the government intervenes in the economy include:","options":["To redistribute income and wealth to improve equality of opportunity and equality of outcome","To overcome market failure","To overcome prolonged recessions and reduce unemployment","All of the above"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Governments intervene in the economy to redistribute income and wealth, to correct market failures, and to fight prolonged recessions and unemployment, among other reasons. Since options A, B and C are all valid reasons, the answer is all of the above."}},{"itemId":"64846bc6-96ad-5a2b-a0fb-c3b98f59d9ef","questionId":"0ce148f8-a178-546a-b636-86386a4f0000","sourceKey":"bank:ECO101:ECO-0649","payload":{"prompt":"The curve that shows the different combinations of two goods an economy can produce when it uses all its resources fully and efficiently is called the:","options":["Indifference curve","Production possibility curve","Demand curve","Revealed preference curve"],"correctOption":1,"section":"Nature of Economic Science","explanation":"The production possibility curve (PPC) traces the maximum combinations of two goods an economy can produce with its given resources and technology. Option A is the tempting one, but an indifference curve shows combinations of goods that give a consumer equal satisfaction, which is about tastes rather than production."}},{"itemId":"08ea4ad8-d3f2-5005-b04f-b952cf9f69db","questionId":"1bc4efc0-1ce4-5c16-b261-a5b614b92d40","sourceKey":"bank:ECO101:ECO-0650","payload":{"prompt":"The definition of economics associated with Lionel Robbins is known as the:","options":["Welfare definition","Scarcity definition","Growth definition","Wealth definition"],"correctOption":1,"section":"Nature of Economic Science","explanation":"Robbins defined economics as the science that studies human behaviour as a relationship between ends and scarce means which have alternative uses, which is why it is called the scarcity definition. Option A belongs to Alfred Marshall, D to Adam Smith, and C to Paul Samuelson."}},{"itemId":"5c335e85-1203-5d60-b168-f5f8eeab4ff1","questionId":"f67e16d2-a026-5d7c-a58a-e0cb02f25807","sourceKey":"bank:ECO101:ECO-0652","payload":{"prompt":"In a free enterprise economy such as a market-driven Lagos trading system, the questions of what, how and for whom to produce are answered mainly by:","options":["A central planning committee","The price mechanism","The central bank","Trade unions"],"correctOption":1,"section":"Nature of Economic Science","explanation":"In a free enterprise economy, buyers and sellers respond to prices: rising prices signal what to produce more of, costs guide how to produce, and incomes decide who can buy the output. Option A describes a command (planned) economy, where government rather than the market makes these choices."}},{"itemId":"fcb7263d-7f9d-5448-891b-c37d76a343af","questionId":"7a80c2c6-2de9-5b7b-bc8c-e6592bae11fe","sourceKey":"bank:ECO101:ECO-0653","payload":{"prompt":"Which economist described political economy as \"an inquiry into the nature and causes of the wealth of nations\"?","options":["Adam Smith","J.B. Say","Alfred Marshall","J.M. Keynes"],"correctOption":0,"section":"Nature of Economic Science","explanation":"Adam Smith's famous 1776 book was titled An Inquiry into the Nature and Causes of the Wealth of Nations, which gave rise to the wealth definition of economics. Option C, Marshall, is linked with the welfare definition, and D, Keynes, is linked with macroeconomics."}},{"itemId":"f8aa9dee-853e-5073-b45c-40d0d75462ce","questionId":"c9249002-d0a1-577d-9792-39898d728bfa","sourceKey":"bank:ECO101:ECO-0654","payload":{"prompt":"Which definition of economics brings in the idea of a scale of preference, where wants are ranked in order of importance?","options":["Wealth definition","Welfare definition","Scarcity definition","Growth definition"],"correctOption":2,"section":"Nature of Economic Science","explanation":"The scarcity definition says people have many wants but limited means with alternative uses, so they must rank their wants on a scale of preference and choose which to satisfy first. The wealth and welfare definitions (A and B) focus on wealth and material well-being rather than on ranking competing ends."}},{"itemId":"c4d312b4-332b-5b0b-9416-e6953f2a384a","questionId":"edf9bed4-94ec-5e8a-979d-47e57643b243","sourceKey":"bank:ECO101:ECO-0655","payload":{"prompt":"Which of the following is the most widely accepted way of describing economics?","options":["The science of material welfare","The science of wealth","The study of mankind in the ordinary business of life","The science of making choices under scarcity"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Most modern economists see economics as the study of how people make choices when resources are scarce and have alternative uses, which grows out of Robbins's scarcity definition. Option C is Marshall's well-known phrase and A sums up his welfare view, but both have been criticised for being too narrow, while B is the older wealth view."}},{"itemId":"41e8984f-ee3f-5b14-8f39-c605141439f7","questionId":"866011d4-4dd8-50e0-96c5-8f81a063d7b9","sourceKey":"bank:ECO101:ECO-0656","payload":{"prompt":"The basic economic problem facing every economy is:","options":["Exchange of goods","Decisions made by government","Economic welfare","Scarce resources alongside unlimited wants"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Every economy has limited resources but people's wants keep growing, and this mismatch forces choices about how resources should be used. Options A, B and C are activities or goals that arise because of this problem, not the problem itself."}},{"itemId":"f63ebeed-702f-5329-9ac4-9f2dd23903cb","questionId":"b7de6eba-3196-5166-b4d7-186b9cf14b78","sourceKey":"bank:ECO101:ECO-0658","payload":{"prompt":"Economics is best described as:","options":["A positive science only","An art only","Neither a science nor an art","Both a science and an art, depending on how and for what purpose it is used"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Economics is a science because it studies cause-and-effect relationships systematically, and it is also an art because its knowledge is applied to solve practical problems such as designing policies. Option A is tempting, but economics also has normative and practical sides, so calling it only a positive science leaves out part of the picture."}},{"itemId":"23de1ab7-9496-58d1-b78b-dffcc30d5b64","questionId":"31829ca7-51b8-527a-8835-53a38c33dfee","sourceKey":"bank:ECO101:ECO-0671","payload":{"prompt":"The word 'economic' is most closely linked with the word:","options":["Free","Scarce","Unlimited","Unrestricted"],"correctOption":1,"section":"Nature of Economic Science","explanation":"Something is an economic good because it is scarce relative to the wants for it, so choices have to be made about how to use it. Options A, C and D describe free goods, such as air, which have no price and do not involve economic choice."}},{"itemId":"87eacce8-79f4-55f6-8ae7-2d598ba2754c","questionId":"c226c5c6-4ff7-59ef-8422-715726810e92","sourceKey":"bank:ECO101:ECO-0677","payload":{"prompt":"The subject matter of economics is best described as the study of:","options":["Wealth","Welfare","Scarcity","Scarcity and choice"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Because resources are scarce, people, firms and governments must choose how to use them, and economics studies both the scarcity and the choices it forces. Option C is tempting but incomplete, since scarcity only matters because it leads to choices, while A and B reflect older, narrower definitions."}},{"itemId":"b8cbde98-d73f-5b45-b784-44c817f3feb7","questionId":"fe75de33-d0fa-50da-8ae9-2c578daefc0b","sourceKey":"bank:ECO101:ECO-0678","payload":{"prompt":"The 'growth' definition of economics is linked with which economist?","options":["Paul Samuelson","Lionel Robbins","Milton Friedman","Alfred Marshall"],"correctOption":0,"section":"Nature of Economic Science","explanation":"Paul Samuelson's definition focuses on how society chooses to use scarce resources to produce goods over time and distribute them, which is why it is called the growth definition. Option B, Robbins, gave the scarcity definition, and D, Marshall, gave the welfare definition."}},{"itemId":"ca0c6f6c-e298-50f6-b106-088774015fa6","questionId":"7514260b-5a76-5d9a-9061-fcc6cf2c132a","sourceKey":"bank:ECO101:ECO-0687","payload":{"prompt":"The growth definition of economics is mainly concerned with:","options":["Scarcity alone","Welfare","Wealth","Economic growth over time"],"correctOption":3,"section":"Nature of Economic Science","explanation":"The growth definition, linked with Samuelson, looks at how society uses scarce resources to produce goods over time, so it brings economic growth and development into the subject. Options B and C are the focus of the older welfare and wealth definitions."}},{"itemId":"45cf125e-8394-5798-bd5c-b1c90a7a97b1","questionId":"d6fd5292-594a-55f2-b6eb-14aa05830689","sourceKey":"bank:ECO101:ECO-0690","payload":{"prompt":"Studies that examine individuals' relationships with, and interactions within, society belong to:","options":["Natural science","Physical science","Life science","Social science"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Social sciences, including economics, sociology and political science, study human behaviour and how people relate to each other in society. Options A, B and C study the natural and physical world or living organisms, not human society."}},{"itemId":"4da96c8c-0758-5d3d-b75d-587a801385af","questionId":"e647176b-2775-5c65-a5f9-28e54949508f","sourceKey":"bank:ECO101:ECO-0692","payload":{"prompt":"Which social science is distinctive for its much heavier use of mathematics than the others?","options":["Sociology","Political science","Economics","Anthropology"],"correctOption":2,"section":"Nature of Economic Science","explanation":"Economics uses mathematics more than other social sciences, for example in demand and supply equations, utility analysis and cost functions. Sociology, political science and anthropology also use data, but they rely far less on mathematical models."}},{"itemId":"27f87d72-3d24-51c7-a48c-9b1d8c354ab9","questionId":"f0a285d1-8633-57b8-982b-6ebe07362f96","sourceKey":"bank:ECO101:ECO-0789","payload":{"prompt":"The scarcity definition of economics was given by:","options":["Paul Samuelson","Adam Smith","Lionel Robbins","Alfred Marshall"],"correctOption":2,"section":"Nature of Economic Science","explanation":"Lionel Robbins defined economics as the science that studies human behaviour as a relationship between ends and scarce means which have alternative uses. Adam Smith (B) is linked to the wealth definition, and Marshall (D) to the welfare definition."}},{"itemId":"77041ba3-080a-5c97-bac4-2feb2987ec86","questionId":"d3ba8bb7-58bc-5697-8555-5fcca8a51448","sourceKey":"bank:ECO101:ECO-0792","payload":{"prompt":"A market economy is also called a:","options":["socialist economy","capitalist economy","mixed economy","developing economy"],"correctOption":1,"section":"Nature of Economic Science","explanation":"In a market (capitalist) economy, resources are mostly privately owned and prices are set by demand and supply. Option A, a socialist economy, relies on state ownership and planning, and Option C, a mixed economy, combines market forces with significant government involvement."}},{"itemId":"ddc33d9a-2efb-5cd5-a3d5-b3d4f5b4274e","questionId":"1e5b9b27-aa02-5769-a570-441032510b87","sourceKey":"bank:ECO101:ECO-0841","payload":{"prompt":"'Economics is a study of mankind in the ordinary business of life.' This definition was given by:","options":["Adam Smith","Lionel Robbins","Alfred Marshall","Paul Samuelson"],"correctOption":2,"section":"Nature of Economic Science","explanation":"This is Alfred Marshall's welfare definition, which focuses on how people earn and use income to promote well-being. Adam Smith (A) is linked to the wealth definition, and Robbins (B) to the scarcity definition based on ends and scarce means."}},{"itemId":"3ea1bdb2-4223-5dbb-a17e-2b4fe363297f","questionId":"16b6b1c4-b63d-50aa-a920-aa1eaa8f5b2c","sourceKey":"bank:ECO101:ECO-0842","payload":{"prompt":"The branch of economics that deals mainly with how scarce resources are allocated among different uses (which goods to produce and how their prices are set) is:","options":["microeconomics","macroeconomics","econometrics","economic history"],"correctOption":0,"section":"Nature of Economic Science","explanation":"Microeconomics studies individual decision-makers, such as households and firms, and how prices guide the allocation of scarce resources between competing uses. Macroeconomics (B) studies economy-wide aggregates like national income and inflation, and econometrics (C) is the use of statistical methods to test economic relationships."}},{"itemId":"b4f13a90-ca33-56c4-94c2-82f340b7ce0c","questionId":"8a10663d-6abf-5c79-bbb8-78cf7a5bb126","sourceKey":"bank:ECO101:ECO-0844","payload":{"prompt":"A point inside a production possibility curve shows that:","options":["resources are being used beyond their capacity","some resources are unemployed or used inefficiently","the economy has full employment of all resources","the economy has experienced growth"],"correctOption":1,"section":"Nature of Economic Science","explanation":"Inside the PPC, the economy could produce more of one good without giving up any of the other, which means some resources are idle or wasted. Option A would be a point outside the curve, which is unattainable, and Option C, full employment, is shown by points on the curve itself."}},{"itemId":"d41e2e34-2c83-5934-a2d6-e9c2dbc55a05","questionId":"0a04c37f-0acb-57c1-a5bb-8fbd8a539d82","sourceKey":"bank:ECO101:ECO-0845","payload":{"prompt":"In which type of economy do consumers and producers make choices guided mainly by the market forces of demand and supply?","options":["Open economy","Controlled economy","Command economy","Market economy"],"correctOption":3,"section":"Nature of Economic Science","explanation":"In a market economy, prices set by demand and supply signal what to produce, how to produce and for whom. Options B and C are planned systems where the government makes these decisions, and Option A, an open economy, simply refers to a country that trades with others."}},{"itemId":"09f6140d-a7fb-5201-bab2-b791f3ebcf30","questionId":"4f67ee23-5dc3-5513-be40-0890c5f39d79","sourceKey":"bank:ECO101:ECO-0846","payload":{"prompt":"In a free market economy, prices are:","options":["fixed by the government","determined by the free interaction of demand and supply","partly fixed by the government","set by producers alone"],"correctOption":1,"section":"Nature of Economic Science","explanation":"In a free market, the price of each good settles where the quantity buyers want equals the quantity sellers offer, through the free interaction of demand and supply. Options A and C involve government price control, which belongs to command or mixed systems, and Option D ignores the role of buyers."}},{"itemId":"d1e34759-d9c8-5255-8163-c2b4f6f38e51","questionId":"7b517fd0-5ba0-5cae-b81c-8130de3e4c6f","sourceKey":"bank:ECO101:ECO-0850","payload":{"prompt":"In Robbins' definition of economics, the 'means' available to satisfy wants are:","options":["scarce","unlimited","undefined","free"],"correctOption":0,"section":"Nature of Economic Science","explanation":"Robbins described economics as the study of the relationship between unlimited ends (wants) and scarce means that have alternative uses. Option B confuses means with ends, since it is wants, not means, that are unlimited."}},{"itemId":"3b8403c4-b35b-56fb-8c74-54eed88819fc","questionId":"38cbe43d-f66a-5570-9420-8d555f6fe44a","sourceKey":"bank:ECO101:ECO-1877","payload":{"prompt":"At the most basic level, every economic question is about","options":["how to make as much money as possible.","what goods a country should produce.","how to cope with scarcity.","how to satisfy all of our wants."],"correctOption":2,"section":"Nature of Economic Science","explanation":"Every economic question, whether about prices, jobs or production, exists because resources are limited compared with our wants, so it is ultimately about coping with scarcity. Option B (what to produce) is only one of the questions scarcity forces on us, not the root of all of them. Option D is impossible, since scarcity means we can never satisfy all our wants, and Option A confuses economics with simply getting rich."}},{"itemId":"955de889-f774-5a43-b084-a0312729e284","questionId":"e347817f-a7be-56b3-a286-9b0cd39a7ea7","sourceKey":"bank:ECO101:ECO-1878","payload":{"prompt":"In economics, an incentive","options":["can be a reward but can never be a penalty.","can be a penalty but can never be a reward.","can be either a reward or a penalty.","is the opposite of a tradeoff."],"correctOption":2,"section":"Nature of Economic Science","explanation":"An incentive is anything that encourages or discourages an action, so it can be a reward (a bonus for meeting targets) or a penalty (a fine for late tax payment). Options A and B each wrongly rule out one of these two forms. Option D is wrong because an incentive and a tradeoff are different ideas, not opposites."}},{"itemId":"78552a69-1755-5fb8-bf91-65a39f66b1f2","questionId":"15db5220-98f1-5f68-97dd-7b0a473f5c72","sourceKey":"bank:ECO101:ECO-1879","payload":{"prompt":"A reward or penalty that encourages a person to take a particular action is called","options":["the marginal benefit.","the marginal cost.","the opportunity cost.","an incentive."],"correctOption":3,"section":"Nature of Economic Science","explanation":"An incentive is an inducement that pushes people towards or away from an action, such as a discount that encourages customers to buy. Options A and B (marginal benefit and marginal cost) measure the gain or cost of one more unit of an activity, not the inducement itself. Option C, opportunity cost, is the best alternative given up when a choice is made."}},{"itemId":"97417456-cd59-57cf-943c-a7d84c332163","questionId":"e532219a-f466-586d-8a8c-e279ba6d5d41","sourceKey":"bank:ECO101:ECO-1880","payload":{"prompt":"Economic questions arise mainly because we","options":["want more than we can get.","want more than we actually need.","have an abundance of resources.","have limited wants that need to be satisfied."],"correctOption":0,"section":"Nature of Economic Science","explanation":"Economic questions exist because our wants are greater than what our limited resources can provide, so we always want more than we can get. Option B is tempting, but the problem is not wanting more than we need; even needs alone can outrun resources. Options C and D get the situation backwards, since resources are limited and wants are unlimited."}},{"itemId":"05b2bfe0-9bd7-519a-89fa-db7ab326219f","questionId":"476a27a4-cdef-5839-b555-b8019f4bd9d0","sourceKey":"bank:ECO101:ECO-1881","payload":{"prompt":"The most fundamental economic problem facing any society is","options":["security.","scarcity.","health.","the fact that a country imports more than it exports."],"correctOption":1,"section":"Nature of Economic Science","explanation":"Scarcity, meaning that limited resources cannot satisfy unlimited wants, is the basic problem from which all other economic questions arise. Security and health (Options A and C) are important goals, but they compete for scarce resources rather than being the root problem. Option D describes a trade deficit, which is a specific issue some countries face, not the fundamental problem of every society."}},{"itemId":"e9544826-6e37-582d-ae7e-750a5538ce4c","questionId":"a1cf9e99-fc61-5cc9-81e8-1405cfcdb259","sourceKey":"bank:ECO101:ECO-1884","payload":{"prompt":"Economists point out that scarcity is faced by","options":["neither the poor nor the rich.","the poor but not the rich.","the rich but not the poor.","both the poor and the rich."],"correctOption":3,"section":"Nature of Economic Science","explanation":"Scarcity affects everyone, because even a very rich person has limited time and cannot have everything they want. Option B is the tempting wrong answer, since it confuses scarcity with poverty. A rich Lagos businessman still has to choose how to spend his 24 hours and his money, so the rich face scarcity too."}},{"itemId":"a7891b4a-314a-5ed0-8e5d-9338b52e8eba","questionId":"3bf82cc9-942a-5235-af58-9a523c9b8c7f","sourceKey":"bank:ECO101:ECO-1885","payload":{"prompt":"Because of scarcity, people must","options":["cooperate.","compete.","trade.","make choices."],"correctOption":3,"section":"Nature of Economic Science","explanation":"Scarcity means we cannot have everything we want, so we are forced to choose among alternatives. Cooperation, competition and trade (Options A, B and C) are things people may do in response to scarcity, but none of them is unavoidable in the way that making choices is."}},{"itemId":"cf5af137-5f54-5025-b0b7-394689462862","questionId":"55893def-8aaa-5afc-a8bf-507548e56ff4","sourceKey":"bank:ECO101:ECO-1889","payload":{"prompt":"When an economist talks about scarcity, he or she is referring to the","options":["ability of society to employ all of its resources.","ability of society to consume all that it produces.","inability of society to satisfy all human wants because resources are limited.","ability of society to keep making technological breakthroughs and raise production."],"correctOption":2,"section":"Nature of Economic Science","explanation":"In economics, scarcity is society's inability to satisfy all human wants because the resources needed to produce goods and services are limited. Option A describes full employment, and Option D describes technological progress; both are about using resources well, not about the basic limit itself. Option B has nothing to do with the wants-versus-resources gap."}},{"itemId":"7566f233-8bdb-5a2f-919e-a4c91189d9da","questionId":"35558df1-bfd7-5bb4-95ed-2fb558c422f8","sourceKey":"bank:ECO101:ECO-1893","payload":{"prompt":"Scarcity can be eliminated through","options":["the use of market mechanisms.","exploration that helps us find new resources.","wise use of our resources.","none of the above, because scarcity cannot be eliminated."],"correctOption":3,"section":"Nature of Economic Science","explanation":"Scarcity can never be eliminated, because human wants keep growing while resources at any point in time remain limited. Markets (Option A), discovering new resources (Option B) and careful use of resources (Option C) can all help us get more from what we have, but they only ease scarcity rather than remove it."}},{"itemId":"928e6fe3-44a4-50df-9708-e6bb90da1303","questionId":"5a498f83-9482-50d7-a444-7aa7531044fb","sourceKey":"bank:ECO101:ECO-1894","payload":{"prompt":"As an economic concept, scarcity applies to","options":["both money and time.","money but not time.","time but not money.","neither time nor money."],"correctOption":0,"section":"Nature of Economic Science","explanation":"Scarcity applies to anything that is limited relative to the uses we would like to make of it, and both money and time fit this. A student with N10,000 and only 24 hours in a day must choose how to spend both. Options B and C each wrongly leave one of them out."}},{"itemId":"df52db5b-750c-5c87-8d05-6efd0d71c45a","questionId":"7f5ec3fd-057b-5ae4-b684-5fa2e5acf972","sourceKey":"bank:ECO101:ECO-1895","payload":{"prompt":"Scarcity is common to all economic systems because resources are","options":["unlimited because of constant technological advances.","limited, and so are human wants.","unlimited, and so are human wants.","limited, but human wants are unlimited."],"correctOption":3,"section":"Nature of Economic Science","explanation":"Every economic system faces scarcity because resources are limited while human wants are unlimited. Option B is tempting, but if wants were also limited they could eventually be fully satisfied and scarcity would disappear. Options A and C are wrong because technology raises output but does not make resources unlimited."}},{"itemId":"34ed3396-f6f7-5f4a-83ad-17e7447273cb","questionId":"e6a3b790-9eb6-5486-8907-a2534c85c38c","sourceKey":"bank:ECO101:ECO-1897","payload":{"prompt":"The problem of scarcity applies","options":["only to industrially developed countries, because resources there are heavily used.","only to underdeveloped countries, because they have few productive resources.","only to economies that are just beginning to develop, because specialised resources are rare.","to all economic systems, whatever their level of development."],"correctOption":3,"section":"Nature of Economic Science","explanation":"Scarcity is universal: every economy, from the richest to the poorest, has limited resources and unlimited wants. Option B is the most tempting, but even highly developed economies must choose how to use their resources. Options A and C wrongly limit scarcity to one stage of development."}},{"itemId":"8c850130-9569-5a55-9789-81d1e0e1bdf2","questionId":"92bb2e95-245f-55b9-9fc3-7b2ac395e0d5","sourceKey":"bank:ECO101:ECO-1898","payload":{"prompt":"A wealthy businessman in Lagos is unable to get a ticket to a sold-out concert. He is experiencing","options":["economics.","scarcity.","opportunity cost.","the fallacy of composition."],"correctOption":1,"section":"Nature of Economic Science","explanation":"The businessman cannot get something he wants because the tickets are limited, which is exactly what scarcity means, and it shows that even the rich face it. Option C, opportunity cost, is what he gives up when he makes a choice, but here he is not choosing between alternatives. Option D refers to wrongly assuming that what is true for one person is true for everyone."}},{"itemId":"319ef88c-f00f-5d5c-8c9c-2b41ee4586bf","questionId":"9ba00f69-47c6-57d5-a45f-780e291a11a3","sourceKey":"bank:ECO101:ECO-1904","payload":{"prompt":"Which of the following best defines the subject of economics?","options":["the science that studies unemployment, inflation and economic stability","the art of making money","the study of choices that businesses make to maximise profit","the study of the choices people make to cope with scarcity"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Economics is the study of the choices individuals, firms and governments make to cope with scarcity. Option A describes only macroeconomics, and Option C describes only part of microeconomics, so both are too narrow. Option B confuses economics with simply making money."}},{"itemId":"03520e15-c63a-58bd-92e1-aa48dabea82e","questionId":"bf4f743f-8135-597d-90db-0d29e25d3c1a","sourceKey":"bank:ECO101:ECO-1935","payload":{"prompt":"When an economy produces more houses and fewer typewriters, it is answering the ________ question.","options":["\"what\"","\"how\"","\"where\"","\"for whom\""],"correctOption":0,"section":"Nature of Economic Science","explanation":"Deciding which goods to produce, and in what quantities, answers the 'what' question, so shifting production towards houses and away from typewriters is a 'what' decision. Option B, 'how', is about the methods and resources used to produce. Option D, 'for whom', is about who gets the goods once they are produced."}},{"itemId":"ce06703a-045a-5ced-adec-a2391c4b4c8d","questionId":"795613fd-8d70-559c-8dc0-3220c4c63c79","sourceKey":"bank:ECO101:ECO-1937","payload":{"prompt":"________ all the objects that we value and are willing to pay for.","options":["Resources are","Goods and services are","Wants are","Capital is"],"correctOption":1,"section":"Nature of Economic Science","explanation":"Goods and services are the things people value and are willing to pay for: goods are physical items like bread, and services are tasks performed for people, like a haircut. Option A, resources, are the inputs used to produce goods and services. Option C, wants, are our desires for goods and services, and Option D, capital, is one type of resource."}},{"itemId":"25a357ae-552a-5fe1-a26a-00a892622c76","questionId":"f0852bde-27cd-50df-914f-33b248042afd","sourceKey":"bank:ECO101:ECO-1938","payload":{"prompt":"A Lagos fast-food chain decides to make more shawarma and fewer burgers. It is answering the ________ question.","options":["\"what\"","\"why\"","\"when\"","\"scarcity\""],"correctOption":0,"section":"Nature of Economic Science","explanation":"Choosing which products to make, and how much of each, answers the 'what' question, so switching from burgers towards shawarma is a 'what' decision. Option C, 'when', is not one of the basic economic questions, which are what, how and for whom. Options B and D are not among these questions either."}},{"itemId":"70cb5f9f-e29f-5a76-b2b0-fd3129b9fd48","questionId":"da16c337-0480-58c0-8b0a-b1f3a61e2c72","sourceKey":"bank:ECO101:ECO-1952","payload":{"prompt":"A state government builds a road using very few machines and a great deal of labour. It is answering the ________ question.","options":["\"what\"","\"how\"","\"where\"","\"for whom\""],"correctOption":1,"section":"Nature of Economic Science","explanation":"The 'how' question is about the method of production, meaning the combination of labour, machines and other resources used. Choosing a labour-intensive method over a machine-intensive one is a 'how' decision. Option A, 'what', would be the decision to build a road instead of something else, and Option D is about who receives the output."}},{"itemId":"571e623f-25f1-5935-872e-bbf0eaba9fa0","questionId":"59ee9cc7-1ec1-5dd1-9401-825328a592e4","sourceKey":"bank:ECO101:ECO-1959","payload":{"prompt":"To meet increased demand for its product, a firm decides to hire a few highly skilled workers rather than many low-skilled workers. The firm is answering the ________ question.","options":["\"how\"","\"when\"","\"what\"","\"scarcity\""],"correctOption":0,"section":"Nature of Economic Science","explanation":"Deciding which mix of inputs to use, here a few skilled workers instead of many unskilled ones, is a choice about the method of production, which answers the 'how' question. Option C, 'what', would apply if the firm were deciding which product to make, but the product stays the same. Options B and D are not among the basic economic questions."}},{"itemId":"d5281d8e-ee9d-52e2-bbde-028bbf8a8f43","questionId":"cc37ab37-978b-5ae8-9286-d89444975f9b","sourceKey":"bank:ECO101:ECO-1963","payload":{"prompt":"To answer the 'for whom' question, economists study","options":["the global economy.","income differences.","business cycles.","technological change."],"correctOption":1,"section":"Nature of Economic Science","explanation":"Who gets the goods and services an economy produces depends mainly on people's incomes, so the 'for whom' question is answered by studying income differences. Option D, technological change, relates more to the 'how' question. Options A and C are broad macroeconomic topics that do not directly explain who gets what."}},{"itemId":"0d4a17ca-02e8-589a-9795-d1c6881eea30","questionId":"85ca131d-4d40-5950-9d61-30e0f8c37125","sourceKey":"bank:ECO101:ECO-1995","payload":{"prompt":"Ada, a lawyer, earns N50,000 an hour, while Musa, a mechanic, earns N5,000 an hour. This income difference is most directly an example of an economy answering the ________ question.","options":["\"when\"","\"scarcity\"","\"for whom\"","\"how\""],"correctOption":2,"section":"Nature of Economic Science","explanation":"The 'for whom' question is about who gets the goods and services produced, and that depends largely on incomes. Since Ada earns far more than Musa, she can buy far more of the economy's output. Option D, 'how', is about production methods, and Options A and B are not among the basic economic questions."}},{"itemId":"f957a7dd-c9ac-580f-bc19-2d915640c64b","questionId":"b8a5db6c-6ac7-5c3f-9966-9148bc0fa01b","sourceKey":"bank:ECO101:ECO-2001","payload":{"prompt":"An economist says that raising taxes on petrol would be in the social interest. What does the economist mean?","options":["Higher taxes on petrol would benefit society as a whole.","Higher taxes on petrol would benefit most people.","Higher taxes on petrol would benefit everyone.","Higher taxes on petrol would benefit some social groups."],"correctOption":0,"section":"Nature of Economic Science","explanation":"A choice is in the social interest when it is best for society as a whole, using resources efficiently and fairly overall. Option B is tempting, but the social interest is about society's overall wellbeing, not a simple head count. Option C goes too far, since some people may lose, and Option D describes the interest of particular groups."}},{"itemId":"a22f5f91-104c-520e-ac93-a455c09b06cf","questionId":"63414305-3594-5e2f-a049-fb5384f722c5","sourceKey":"bank:ECO101:ECO-2002","payload":{"prompt":"In a market economy, what people do in pursuit of their self-interest","options":["usually conflicts with the social interest.","usually promotes the social interest.","always promotes the social interest.","always conflicts with the social interest."],"correctOption":1,"section":"Nature of Economic Science","explanation":"In a market economy, people pursuing their own interest usually end up promoting the social interest as well; this is Adam Smith's 'invisible hand' idea. A trader who wants profit must supply what customers want. Option C goes too far, because there are cases, such as pollution, where self-interest harms society, and Options A and D overstate the conflict."}},{"itemId":"5a0d45b6-6485-58c8-b3c8-f9d6513febc1","questionId":"61327dcd-223f-56e3-ac5e-f220ab4a2852","sourceKey":"bank:ECO101:ECO-2003","payload":{"prompt":"Which of the following is NOT one of the basic economic questions every society must answer?","options":["What goods and services are produced?","How are goods and services produced?","For whom are goods and services produced?","Why do incentives affect only marginal costs?"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Every society must decide what to produce, how to produce it and for whom it is produced, so Options A, B and C are the basic economic questions. Option D is not one of them, and it is also false, because incentives can affect both the costs and the benefits of a choice."}},{"itemId":"3af5cb01-3693-582f-a535-2ead322d7f75","questionId":"8b8f6000-bd32-531c-997e-4123ec563cbf","sourceKey":"bank:ECO101:ECO-2005","payload":{"prompt":"Tradeoffs arise in all of the following questions EXCEPT","options":["What goods and services should be produced?","How should goods and services be produced?","For whom should goods and services be produced?","Why should goods and services be produced?"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Because of scarcity, every society faces tradeoffs over what to produce, how to produce it and for whom, which are the three basic economic questions in Options A, B and C. 'Why should goods and services be produced?' is not one of these questions, so it is the exception."}},{"itemId":"fb6c4c2b-00f8-5891-9c3c-e634331ac436","questionId":"5f773aeb-831a-569e-8d09-0ce43f872c50","sourceKey":"bank:ECO101:ECO-2006","payload":{"prompt":"In economics we learn that","options":["sometimes there is such a thing as a \"free lunch.\"","tradeoffs allow us to avoid opportunity cost.","opportunity cost is the total of all the alternatives given up when a choice is made.","none of the above."],"correctOption":3,"section":"Nature of Economic Science","explanation":"None of the statements is correct. Option A is false because every choice has an opportunity cost, so there is no free lunch, and Option B is false because tradeoffs are exactly what create opportunity cost. Option C is the most tempting, but opportunity cost is only the single highest-valued alternative given up, not all the alternatives added together."}},{"itemId":"8512be35-9a1e-57ce-874d-b9aa658c5a34","questionId":"680cbb97-722e-5bbe-9735-6074812635ca","sourceKey":"bank:ECO101:ECO-2013","payload":{"prompt":"Because we face scarcity, every choice involves","options":["spending money.","the \"what\" question.","giving up something for nothing.","an opportunity cost."],"correctOption":3,"section":"Nature of Economic Science","explanation":"Scarcity means that choosing one thing always means giving up the next best alternative, and that sacrifice is the opportunity cost. Option A is wrong because many choices, such as how to use your time, involve no money at all. Option C is wrong because we give something up in exchange for what we choose, not for nothing."}},{"itemId":"2d97dc78-e43b-54e4-992f-dd7376814018","questionId":"0d1415d4-1e0d-59ab-94b2-786e475f70f2","sourceKey":"bank:ECO101:ECO-2015","payload":{"prompt":"The loss of the highest-valued alternative given up when a choice is made is called","options":["marginal benefit.","scarcity.","entrepreneurship.","opportunity cost."],"correctOption":3,"section":"Nature of Economic Science","explanation":"Opportunity cost is the value of the best alternative you give up when you make a choice. For example, if you spend Saturday at work instead of at a study group, the study time is your opportunity cost. Option B, scarcity, is the reason choices must be made, and Option A, marginal benefit, is the gain from one more unit of an activity."}},{"itemId":"daa601a3-3b64-5d7c-8fff-160a8765e8eb","questionId":"fc124f47-d16e-5fd8-b192-2ee5dd612f09","sourceKey":"bank:ECO101:ECO-2021","payload":{"prompt":"Which of these statements are correct? I. The highest-valued alternative given up to get something is its opportunity cost. II. Rich economies do not face opportunity costs. III. Scarcity gives rise to opportunity costs.","options":["I only","I and II","I and III","I, II and III"],"correctOption":2,"section":"Nature of Economic Science","explanation":"Statement I is the definition of opportunity cost, and statement III is right because scarcity forces choices, and every choice means giving something up. Statement II is false: even rich economies have limited resources compared with their wants, so they also face opportunity costs. That rules out options B and D, and option A leaves out the true statement III."}},{"itemId":"f125235b-3850-5986-80ac-00183390bbfd","questionId":"f8bacf62-88b6-5821-9c08-781f0f486470","sourceKey":"bank:ECO101:ECO-2022","payload":{"prompt":"Which of the following best defines opportunity cost?","options":["The amount of money paid for something.","The money and time needed to consume something.","The value of the next best alternative sacrificed when a choice is made.","The sum of all the alternatives sacrificed when a choice is made."],"correctOption":2,"section":"Nature of Economic Science","explanation":"Opportunity cost is the value of the single next best alternative you sacrifice. Option D is the common trap: you could only have taken one of the other options anyway, so adding all of them together overstates the cost. Options A and B focus on money and time spent rather than on the alternative given up."}},{"itemId":"8f5cbb50-7194-524f-822a-599f5a29e5af","questionId":"4d50565a-ec6d-5ba5-b49e-352d2e09a092","sourceKey":"bank:ECO101:ECO-2028","payload":{"prompt":"Tunde can spend next week on holiday in Calabar, working at his job in Lagos, or repainting his flat. If he chooses the holiday, his opportunity cost is","options":["both working and repainting the flat.","working or repainting the flat, whichever he would have done instead.","working, because he gives up his pay.","nothing, because he will enjoy the holiday."],"correctOption":1,"section":"Nature of Economic Science","explanation":"Opportunity cost is only the next best alternative, the one Tunde would actually have chosen if he had not gone on holiday. Option A adds both alternatives together, but he could not have done both in the same week. Option C assumes work is the next best choice just because it pays, and option D is wrong because enjoying a choice does not make it free."}},{"itemId":"ab401967-9987-53b7-a81d-71d6ffc2cf9e","questionId":"d72b22c6-a935-52c8-91e3-6b196b03d3c4","sourceKey":"bank:ECO101:ECO-2029","payload":{"prompt":"The night before a test, Bisi goes to a party instead of studying and scores 60 percent. Had she studied, she would have scored 70 percent. What was the opportunity cost of the party?","options":["10 percentage points off her score.","60 percent.","70 percent.","Zero."],"correctOption":0,"section":"Nature of Economic Science","explanation":"By going to the party Bisi gave up the extra marks that studying would have earned her: 70 - 60 = 10 percentage points. Options B and C give whole scores rather than the difference she sacrificed. Option D ignores that the evening had a better alternative use."}},{"itemId":"4db74b90-6ab6-5d39-afe4-c00c68fc15b0","questionId":"3ad41655-d8d0-5bba-a109-95f03edd0c6a","sourceKey":"bank:ECO101:ECO-2030","payload":{"prompt":"On Saturday morning Chidi ranks his options in this order: go to the library, go to the gym, have breakfast with friends, sleep late. If he goes to the library, his opportunity cost is","options":["going to the gym, having breakfast with friends and sleeping late.","going to the gym.","zero, because using the library is free.","impossible to tell from the information given."],"correctOption":1,"section":"Nature of Economic Science","explanation":"The library is his first choice, so his opportunity cost is his second-ranked option, the gym. Option A lists every other option, but opportunity cost is only the next best one. Option C confuses a zero money price with zero cost, and option D is wrong because the ranking gives us exactly what we need."}},{"itemId":"cb99acd4-300b-5b7c-bed4-8b5bcfb7cf5d","questionId":"38caf2f9-7715-5d94-9b09-7143ef55625a","sourceKey":"bank:ECO101:ECO-2031","payload":{"prompt":"Femi and Ngozi are each given free tickets to the same film and both decide to go. Which statement is correct?","options":["Both face an opportunity cost, because each could have done something else with the time.","Both face exactly the same opportunity cost, because they are doing the same thing.","Their opportunity cost cannot be worked out, because the tickets were free.","Their opportunity cost is zero, because the tickets were free."],"correctOption":0,"section":"Nature of Economic Science","explanation":"Even a free ticket uses up time that could have gone to another activity, so each person gives up something to watch the film. Option B is wrong because their next best alternatives may differ, so their opportunity costs need not be the same. Options C and D confuse a zero money price with a zero opportunity cost."}},{"itemId":"145877a8-c6eb-5385-8ada-531c3b66159e","questionId":"7ade7149-6f4e-5586-94fb-cbfce64adb2f","sourceKey":"bank:ECO101:ECO-2036","payload":{"prompt":"By deciding to attend a lecture, you know you are giving up the chance to watch a film at home. You are applying the idea of","options":["opportunity cost.","the fallacy of composition.","the post hoc fallacy.","involuntary exchange."],"correctOption":0,"section":"Nature of Economic Science","explanation":"Recognising what you give up when you make a choice is exactly what opportunity cost means. Option B, the fallacy of composition, is assuming what is true for one person is true for everyone. Option C, the post hoc fallacy, is assuming that because one event came first it caused the other, and option D has nothing to do with a personal choice."}},{"itemId":"92abacf1-bc98-5f1a-8972-1f00675e21bb","questionId":"e622723b-72f6-5fc1-8132-80c0451c38b9","sourceKey":"bank:ECO101:ECO-2038","payload":{"prompt":"Adaeze takes a holiday that costs her N200,000. While away she misses work where she would have earned N75,000. The opportunity cost of the holiday is","options":["N200,000.","N75,000.","N275,000.","N125,000."],"correctOption":2,"section":"Nature of Economic Science","explanation":"The full cost includes the money spent plus the earnings given up: N200,000 + N75,000 = N275,000. Option A counts only the spending and option B counts only the lost wages. Option D subtracts the two, but both are sacrifices, so they are added."}},{"itemId":"8f5c1c21-149e-53fa-b240-f2985573b282","questionId":"0b78f3eb-45f9-574a-9b5a-48e6b0c163d3","sourceKey":"bank:ECO101:ECO-2039","payload":{"prompt":"The idea of opportunity cost emphasises that","options":["there may be such a thing as a free lunch.","some people will not make the most of life's chances because they fail to reach their goals.","managers do not always spot profit opportunities quickly enough.","every decision about using a resource involves a costly choice."],"correctOption":3,"section":"Nature of Economic Science","explanation":"Because resources are scarce, using one for any purpose means giving up its next best use, so every choice carries a cost. Option A contradicts this idea, which is often summed up as 'there is no free lunch.' Options B and C use the word 'opportunity' in an everyday sense that has nothing to do with the economic concept."}},{"itemId":"6fd91b9e-6a15-5667-bb35-50346ebdba99","questionId":"d726f418-2b6f-50f1-be48-aa11c417ae30","sourceKey":"bank:ECO101:ECO-2042","payload":{"prompt":"Which of the following is NOT an example of opportunity cost?","options":["By spending Thursday night preparing for an economics test, a student could not finish her accounting assignment.","Because Musa used all his leave days to renovate his house, he could not visit his family in Kano.","Because Halima now earns a higher salary, she can afford a new car even though she is moving into a bigger flat.","By choosing to study full time, Ifeanyi had to stop working as an electrician and gave up his earnings."],"correctOption":2,"section":"Nature of Economic Science","explanation":"Option C describes Halima affording more because her income rose; nothing is being given up, so no opportunity cost is shown. Options A, B and D each describe a choice where one thing was sacrificed to get another: the assignment, the trip to Kano and the electrician's earnings."}},{"itemId":"eb5861ea-44fe-58dd-9249-ac0feda3ed49","questionId":"3ba47ea6-b1b2-56ff-9c9a-3873ba578769","sourceKey":"bank:ECO101:ECO-2043","payload":{"prompt":"Between 6 p.m. and 9 p.m., Amaka can watch a football match, attend a concert, or go to a book reading. She chooses the concert and decides that if she had not gone, she would have watched the match. Her opportunity cost of the concert is","options":["watching the match and going to the book reading.","watching the match.","going to the book reading.","three hours of her time."],"correctOption":1,"section":"Nature of Economic Science","explanation":"Amaka tells us her next best alternative is the football match, so that is what she gives up by going to the concert. Option A wrongly adds the book reading too, which she would not have chosen anyway. Option D names the time used, but opportunity cost is measured by the best alternative use of that time, not the hours themselves."}},{"itemId":"e0cc0290-d110-537c-b796-833747e119fb","questionId":"e6f4d530-54e1-55e6-b087-f91ee2687e6d","sourceKey":"bank:ECO101:ECO-2044","payload":{"prompt":"When the government uses resources to build a dam, those resources can no longer be used to build a highway. This illustrates","options":["the market mechanism.","macroeconomics.","opportunity cost.","the fallacy of composition."],"correctOption":2,"section":"Nature of Economic Science","explanation":"Resources used for the dam are no longer available for the highway, so the highway is what is sacrificed, which is opportunity cost. Option A refers to how prices allocate resources, not to a single trade-off. Options B and D are unrelated: macroeconomics is the study of the whole economy and the fallacy of composition is a reasoning error."}},{"itemId":"03459673-201e-5196-8b87-58e065f51d17","questionId":"5b3741c5-4625-5901-8f23-14e8ef7ebba0","sourceKey":"bank:ECO101:ECO-2045","payload":{"prompt":"Kemi is thinking about taking holiday courses. Fees and books cost N120,000, accommodation N40,000 and food N30,000. If she skips the courses, she lives at home for free, spends only N10,000 on food and works full time earning N500,000. If she takes the courses she can still work part time, earning at most N100,000. What is her opportunity cost of taking the courses?","options":["N400,000","N190,000","N690,000","N580,000"],"correctOption":3,"section":"Nature of Economic Science","explanation":"Count only what changes because of the courses: fees and books N120,000 + accommodation N40,000 + extra food (30,000 - 10,000) = N20,000 + lost earnings (500,000 - 100,000) = N400,000, giving N580,000. Option A counts only the lost earnings and option B counts only the spending. Option C adds the full N500,000 wage and all the food, ignoring the part-time pay she keeps and the food she would buy anyway."}},{"itemId":"5dadd083-30b0-5d2c-a895-5f4c85ac6113","questionId":"6434da72-3f33-504a-bef4-b2f407443b0e","sourceKey":"bank:ECO101:ECO-2046","payload":{"prompt":"After graduating, Seun accepts a job paying N4.5 million a year. His other offers were from a supermarket chain at N3.8 million and a consulting firm at N4.2 million, and of those two he preferred the consulting firm. What is his opportunity cost of the job he accepted?","options":["The N4.5 million he will earn in the job he accepted.","The N4.2 million from the consulting firm.","The N3.8 million from the supermarket chain.","The N4.2 million from the consulting firm plus the N3.8 million from the supermarket."],"correctOption":1,"section":"Nature of Economic Science","explanation":"Opportunity cost is the next best alternative given up, and Seun ranked the consulting job above the supermarket job, so it is the N4.2 million offer. Option A is what he gains, not what he gives up. Option D adds both offers, but he could only have taken one of them."}},{"itemId":"9872f8eb-188f-5a81-9a2c-c4dd92a83802","questionId":"d8b4bc27-33ac-57f2-9147-95923ba77bc2","sourceKey":"bank:ECO101:ECO-2047","payload":{"prompt":"On graduating, Dayo can play professional football for N200 million a year or coach for N5 million a year, and he chooses football. Eight years later, although he could keep playing for N200 million a year, he quits to act in films for N300 million a year. His opportunity cost of football at graduation was ____, and of acting eight years later was ____.","options":["N5 million; N200 million","N200 million; N200 million","N200 million; N300 million","N5 million; N5 million"],"correctOption":0,"section":"Nature of Economic Science","explanation":"At graduation the best alternative to football was coaching, worth N5 million. Eight years later the best alternative to acting is the football career he gives up, worth N200 million. Option C uses the income from the chosen activity each time, but opportunity cost is always the value of what is given up."}},{"itemId":"4e687e66-0877-5199-83df-ebfc7ff6304b","questionId":"f96fab72-8dc7-5423-a8a8-0ead08a4b8ef","sourceKey":"bank:ECO101:ECO-2049","payload":{"prompt":"Zainab has already spent 5 hours cleaning her room. When she decides whether to clean for one more hour, she is applying the principle of","options":["scarcity.","ceteris paribus.","choosing at the margin.","productivity."],"correctOption":2,"section":"Nature of Economic Science","explanation":"Deciding whether to do one more hour of an activity is a choice at the margin: she weighs the extra benefit of that hour against its extra cost. Option A, scarcity, explains why choices are needed but is not the principle being used here. Option B means 'other things being equal,' a tool for analysis, not a way of making this decision."}},{"itemId":"adf55601-ac84-5478-ab6a-5135fd940436","questionId":"0399926f-9afd-525d-a060-92796c685dc8","sourceKey":"bank:ECO101:ECO-2053","payload":{"prompt":"Marginal benefit is the","options":["extra gain from one more unit of an activity.","extra cost of one more unit of an activity.","loss of the highest-valued alternative.","opportunity that has been given up."],"correctOption":0,"section":"Nature of Economic Science","explanation":"Marginal benefit measures the additional gain from one more unit of something, like one more plate of food or one more hour of study. Option B describes marginal cost, the mirror image. Options C and D describe opportunity cost, which is a cost, not a benefit."}},{"itemId":"aacf4896-4da7-5e79-9e53-36f04d572ecb","questionId":"8c13fd0a-e621-5b85-8ed5-edd8c67dfe1f","sourceKey":"bank:ECO101:ECO-2056","payload":{"prompt":"Your employer asks you to work overtime and offers N1,800 for each hour beyond 40 hours a week. Each of the first 40 hours still pays the usual N1,500. In naira terms, what is the marginal benefit of each overtime hour?","options":["Zero","N300","N1,500","N1,800"],"correctOption":3,"section":"Nature of Economic Science","explanation":"The marginal benefit of an overtime hour is what that extra hour pays you, which is N1,800. Option B is the difference between the two wage rates, but you receive the full N1,800 for the extra hour, not just the increase. Option C is the pay for a normal hour, not the extra one."}},{"itemId":"f198f3dc-3490-55a9-b434-68da9aece2f5","questionId":"19962642-d5d5-5977-938b-7a327377679d","sourceKey":"bank:ECO101:ECO-2057","payload":{"prompt":"A student studies for 2 hours a day and is deciding whether to add a third hour. Her marginal benefit","options":["depends on the grade she finally gets in the exam.","is the benefit she gets from studying all 3 hours.","is the benefit she gets from the extra hour.","is greater than her marginal cost."],"correctOption":2,"section":"Nature of Economic Science","explanation":"Marginal benefit is the gain from the additional unit, so here it is the benefit of the third hour only. Option B describes the total benefit of all three hours. Option D cannot be known until she weighs it; it is true only if she actually decides the extra hour is worth it."}},{"itemId":"91d13f2a-cf53-5e44-a02d-703b47a68014","questionId":"25ce66e8-0ee5-5200-b5b7-20ad19295e43","sourceKey":"bank:ECO101:ECO-2059","payload":{"prompt":"You study economics for 2 hours a day and your score is 85 percent. You add an extra hour a day and your score rises to 90 percent. Your marginal benefit is the","options":["90 percent score that you now get.","extra hour per day spent studying.","5-point increase in your score.","3 hours a day spent studying."],"correctOption":2,"section":"Nature of Economic Science","explanation":"Marginal benefit is the gain from the extra hour of study, which is the rise in your score from 85 to 90 percent, or 5 points. Option A is the total score you end up with, not the extra gain that the added hour brings. Options B and D describe the time spent studying, which is the cost side, not the benefit."}},{"itemId":"331bf9b2-3baa-504a-838d-4f390f3ee813","questionId":"0750b309-56f5-524e-a6f5-99b20f19143b","sourceKey":"bank:ECO101:ECO-2063","payload":{"prompt":"Marginal cost is the","options":["cost of a small increase in an activity.","total cost of an activity.","cost of an activity minus its benefits.","cost of all the alternatives given up."],"correctOption":0,"section":"Nature of Economic Science","explanation":"Marginal cost is the extra cost from a small increase in an activity, such as producing one more unit. Option B is total cost, the cost of everything. Option D is wrong twice: opportunity cost is only the best alternative, and marginal cost is about the extra unit."}},{"itemId":"d0e6756e-c9a0-5232-b455-ae2c65c683b5","questionId":"71c36dfd-f8c9-5f7f-97b1-8e81bc09a662","sourceKey":"bank:ECO101:ECO-2064","payload":{"prompt":"A production manager at a Lagos electronics firm is deciding whether to make a few more television sets. She is choosing at the margin when she compares","options":["total revenue from all sets with the total cost of producing all of them.","the extra revenue from the additional sets with the extra cost of producing them.","the extra revenue from the additional sets with the average cost of producing them.","her firm's televisions with those of rival firms."],"correctOption":1,"section":"Nature of Economic Science","explanation":"A marginal decision compares the extra revenue from the additional units with the extra cost of making them. Option A uses totals, which do not tell her whether the next few sets are worth producing. Option C mixes a marginal benefit with an average cost, which is not the right comparison."}},{"itemId":"55aa9419-2ddd-514c-8b69-ef032ae787bb","questionId":"b63c19c4-9b1d-5b5c-8424-7c01b1dbf3b3","sourceKey":"bank:ECO101:ECO-2065","payload":{"prompt":"Managers at a Lagos phone assembler are deciding whether to raise output by 4,000 handsets a month. Doing so will increase revenue by N10 million a month and costs by N9 million a month, and total monthly profit will be N30 million. The managers","options":["should go ahead because the firm will make a large total profit.","should go ahead because the marginal benefit of the extra output exceeds its marginal cost.","should not go ahead because it costs too much.","cannot decide without knowing total profit before the increase."],"correctOption":1,"section":"Nature of Economic Science","explanation":"The extra revenue (N10 million) is greater than the extra cost (N9 million), so the change adds N1 million to profit and is worth doing. Option A gets the decision right for the wrong reason, because the size of total profit does not tell you whether this particular change pays. Option D is wrong because the marginal figures alone are enough to decide."}},{"itemId":"06642a38-f625-55a7-a0cb-1a9916441b85","questionId":"0342cc99-bcc9-5543-8cdf-5cee9b0b9a3b","sourceKey":"bank:ECO101:ECO-2066","payload":{"prompt":"A cleaning company is deciding whether to add one more worker to its team. The marginal cost of hiring this worker depends on the","options":["total amount paid to the new worker.","total amount paid to all the workers already hired.","total amount paid to all workers, new and old.","extra revenue the new worker brings in."],"correctOption":0,"section":"Nature of Economic Science","explanation":"The marginal cost of hiring is the extra cost of that one additional worker, which is what the firm pays the new worker. Options B and C include wages already being paid, which do not change with this decision. Option D describes the marginal benefit of hiring, not its cost."}},{"itemId":"badc454c-c73b-5839-a5be-04173a4dffad","questionId":"3dc7a6ee-6aff-5891-b661-23c190944d10","sourceKey":"bank:ECO101:ECO-2067","payload":{"prompt":"A shop sells 5 pens for N150 and 6 pens for N175. What is the marginal cost of the sixth pen?","options":["N25","N150","N175","N325"],"correctOption":0,"section":"Nature of Economic Science","explanation":"Marginal cost is the change in total cost from one more unit: N175 - N150 = N25. Option C is the total cost of all six pens and option B is the total for five. Option D wrongly adds the two totals."}},{"itemId":"e75e5036-3a55-59b9-b645-f9bc4d9c2e35","questionId":"5227bba2-8aaf-5b2e-98c7-f69b29250098","sourceKey":"bank:ECO101:ECO-2068","payload":{"prompt":"If the marginal cost of an activity is greater than its marginal benefit, then","options":["the activity will take place because of the high marginal cost.","the costs of the alternatives given up must rise.","an alternative action will be chosen.","the person must focus on the total benefits of the activity."],"correctOption":2,"section":"Nature of Economic Science","explanation":"When the extra cost of doing more exceeds the extra benefit, a rational person will not do that extra unit and will choose something else instead. Option A gets the logic backwards, since a high cost discourages the activity. Option D is wrong because decisions at the margin depend on extra benefit and extra cost, not totals."}},{"itemId":"e08510c2-cc80-5c4c-81e9-08f84029762a","questionId":"75eccc31-dd1c-5036-acf0-445567441baa","sourceKey":"bank:ECO101:ECO-2069","payload":{"prompt":"To decide whether to travel to Badagry beach during the semester break, you should","options":["compare the marginal cost with the marginal benefit of the trip.","avoid the fallacy of composition.","avoid the post hoc fallacy.","separate cause from effect."],"correctOption":0,"section":"Nature of Economic Science","explanation":"Choosing whether to take one trip is a decision at the margin, so you weigh what the trip adds against what it costs you. Options B, C and D are rules for avoiding mistakes in economic reasoning, not a method for making a personal choice."}},{"itemId":"ef352fe2-0885-57ba-b95d-6c632d0f8f84","questionId":"d41217fd-ace5-532d-9138-ee4bdc1160d2","sourceKey":"bank:ECO101:ECO-2070","payload":{"prompt":"A shop in Yaba opens from 8 a.m. to 4 p.m. on weekdays. The owner is deciding whether to stay open one more hour each evening. The owner's marginal benefit","options":["is the benefit from staying open from 8 a.m. to 5 p.m.","depends on the revenue earned during the day.","must be at least equal to the marginal cost if the owner decides to stay open.","is the benefit from staying open from 8 a.m. to 6 p.m."],"correctOption":2,"section":"Nature of Economic Science","explanation":"Marginal benefit is the extra benefit from the extra hour, and a sensible owner stays open that hour only if its benefit is at least as large as its cost. Option A describes the benefit of the whole day from 8 a.m. to 5 p.m., which is a total, not a marginal, benefit. Option D is also a total for an even longer day, and option B ignores that only the extra hour matters."}},{"itemId":"b5d68f7f-0163-574f-9a70-7f3568d8efc4","questionId":"2341e2ae-bd61-5993-967a-b8c4a3dc1eb7","sourceKey":"bank:ECO101:ECO-2071","payload":{"prompt":"If the marginal cost of an activity falls or its marginal benefit rises, a person will","options":["do less of the activity.","do more of the activity.","not change how much of the activity they do.","stop the activity completely."],"correctOption":1,"section":"Nature of Economic Science","explanation":"A fall in marginal cost or a rise in marginal benefit makes extra units of the activity more worthwhile, so people do more of it. This is how incentives work. Option A is the response to the opposite changes, and option D would only happen if the activity stopped being worth doing at all."}},{"itemId":"e66deef0-5bac-582a-9efd-b6620193bfb4","questionId":"fc4fd32d-2262-50a5-83c1-71c31867c9c6","sourceKey":"bank:ECO101:ECO-2073","payload":{"prompt":"Suppose Lagos State promises a tax cut to a firm if it stays in Lagos rather than moving to another state. This policy is ____, designed to make the ____ of the firm staying in Lagos.","options":["an incentive; marginal benefit exceed the marginal cost","an incentive; marginal cost exceed the marginal benefit","a command; marginal benefit exceed the marginal cost","a command; marginal cost exceed the marginal benefit"],"correctOption":0,"section":"Nature of Economic Science","explanation":"A tax cut is an incentive, a reward that changes the firm's choice, and it raises the benefit of staying so that it outweighs the cost. Options C and D call it a command, but the state is not ordering the firm to stay. Option B gets the direction wrong, because a firm stays only when benefit exceeds cost."}},{"itemId":"37f90606-fed1-5e14-9cf8-688389e353d6","questionId":"31ab1031-6cdb-5841-9fb0-cfab124ef638","sourceKey":"bank:ECO101:ECO-2074","payload":{"prompt":"Obinna scored 50 percent in a test. An extra-credit task would raise his score by 20 percentage points but would take 10 hours. Obinna will do the task if he values","options":["the 20 percentage points more than the 10 hours of his time.","the 10 hours of his time more than the 20 percentage points.","the 70 percentage points more than the 10 hours of his time.","a higher score."],"correctOption":0,"section":"Nature of Economic Science","explanation":"The marginal benefit of the task is the extra 20 points and its marginal cost is the 10 hours, so he does it only if the points are worth more to him than the time. Option C uses his total score of 70, but the first 50 points are already his and are not affected by this decision. Option B describes when he would skip the task."}},{"itemId":"994d89bf-d22b-569d-b487-47b10d228144","questionId":"c0d7c96d-43ab-5a3d-bc00-19bd762cb8f8","sourceKey":"bank:ECO101:ECO-2078","payload":{"prompt":"When the government spends its tax revenue on national security, this choice","options":["involves giving up other goods and services, such as education, for more security.","shows that scarcity does not always exist.","involves no trade-off, because security is necessary.","mainly affects who gets the goods and services produced."],"correctOption":0,"section":"Nature of Economic Science","explanation":"Tax revenue is limited, so naira spent on security cannot also be spent on schools or hospitals, which is a trade-off. Option C is wrong because even a necessary item still has an opportunity cost. Option B gets it backwards, since the trade-off exists only because of scarcity."}},{"itemId":"72e21a3d-c603-5a87-8d70-534df38f7d32","questionId":"cf67fc1d-b32a-5641-8eee-0333a4fa0dd2","sourceKey":"bank:ECO101:ECO-2079","payload":{"prompt":"Making a choice at the margin means","options":["letting someone else decide for you.","waiting until the last minute to decide.","deciding whether to do a little more or a little less of an activity.","deciding by comparing total benefit with total cost."],"correctOption":2,"section":"Nature of Economic Science","explanation":"A marginal choice is about one more or one less unit, such as one extra hour of study. Option D is the tempting one, but margin decisions compare the extra benefit with the extra cost of that small change, not the totals. Options A and B use 'margin' in an everyday sense that has nothing to do with economics."}},{"itemId":"b9797e8a-dbf7-5e92-9c9a-3af60983d092","questionId":"11de6fe6-a9d7-5352-a637-ee39ab15888c","sourceKey":"bank:ECO101:ECO-2080","payload":{"prompt":"For two months you studied economics one hour a day. You now decide to study two hours a day. During those two months,","options":["the marginal cost of an hour of economics study must have been greater than its marginal benefit.","the marginal cost of studying economics must have fallen.","the marginal benefit of an hour of economics study must have been greater than its marginal cost.","the opportunity cost of studying economics must have risen."],"correctOption":2,"section":"Nature of Economic Science","explanation":"You chose to study one hour a day, which you would only do if that hour was worth more to you than it cost. Option A describes a case in which you would not have studied at all. Options B and D talk about changes that may explain your new decision, but nothing in the question tells us they happened."}},{"itemId":"156dce57-9c61-574e-9e85-a4c60cc7a62a","questionId":"a58e343b-093e-5e23-b9f0-987792845ada","sourceKey":"bank:ECO101:ECO-2119","payload":{"prompt":"The Governor of the Central Bank of Nigeria must choose whether to spend an afternoon meeting the Minister of Finance or a committee of the National Assembly. This reflects the fact that the Governor","options":["faces scarcity.","is an entrepreneur.","responds to incentives.","uses capital."],"correctOption":0,"section":"Nature of Economic Science","explanation":"The Governor has limited time and cannot do both meetings at once, so he faces scarcity and must choose. Option C is about reacting to rewards or penalties, which the question does not describe. Options B and D refer to factors of production, not the problem of limited time."}},{"itemId":"d7cf5d7f-dea6-5b30-bb42-490f98086046","questionId":"eba18924-1d67-5454-9bc9-e9d9022296dc","sourceKey":"bank:ECO101:ECO-2127","payload":{"prompt":"A TV station decides to produce another season of a reality show instead of a new drama series. The station is","options":["answering the what question.","facing no trade-off, because air time is unlimited.","answering the how question.","facing no scarcity, because many actors are looking for work."],"correctOption":0,"section":"Nature of Economic Science","explanation":"Picking which programme to make is a 'what to produce' decision. Option B is wrong because air time is limited, so choosing one show means giving up another. Option C would apply to how the show is produced, and option D is wrong because the station still has limited money and time."}},{"itemId":"782d0180-3493-51a2-8b0d-02d4757ad4f5","questionId":"f0d04131-2d19-587e-ae3f-47fe44e28b56","sourceKey":"bank:ECO101:ECO-2128","payload":{"prompt":"When an airline encourages customers to book tickets online instead of by phone, it is","options":["answering the what question.","facing natural resource depletion.","making a choice only in the social interest.","answering the how question."],"correctOption":3,"section":"Nature of Economic Science","explanation":"Switching from phone bookings to online bookings changes the method used to provide the service, which is the 'how to produce' question. Option A would apply if the airline were changing which services it offers. Option C is wrong because the airline is mainly acting in its own interest, for example to cut costs."}},{"itemId":"f4bd4a1f-d3db-576c-b5a7-464b5184b3f7","questionId":"d999f4fe-de2a-51db-b90a-b50c12db260a","sourceKey":"bank:ECO101:ECO-2130","payload":{"prompt":"When a football club pays a new player a N100 million signing bonus, it is answering","options":["the what question.","the how question.","the for whom question.","the how and what questions."],"correctOption":2,"section":"Nature of Economic Science","explanation":"Paying a player a bonus decides who receives income and therefore who gets to enjoy goods and services, which is the 'for whom' question. Options A and B deal with which goods are produced and how, which the bonus does not decide."}},{"itemId":"885095b2-99ae-56fe-9aea-47a2853b7e07","questionId":"b0607428-4f26-5bd3-bea8-f79d7087f072","sourceKey":"bank:ECO101:ECO-2131","payload":{"prompt":"One political party wants higher income tax on the highest earners, while another wants to keep the current tax structure. The parties are answering the ____ question.","options":["for whom","what","how","microeconomic"],"correctOption":0,"section":"Nature of Economic Science","explanation":"Income tax affects how much income different groups keep, and therefore who gets the goods and services produced, which is the 'for whom' question. Options B and C are about which goods are made and how they are made, which the tax debate does not decide directly."}},{"itemId":"6d5d1945-b64a-5c45-9342-e040501f10e0","questionId":"8b32f0f6-6d6c-5061-8fdf-f09e3a035f72","sourceKey":"bank:ECO101:ECO-2137","payload":{"prompt":"Which of the following statements about scarcity is correct?","options":["Scarcity affects only people who are in need.","Scarcity affects both the rich and the poor.","Rich people do not face scarcity because they can buy whatever they want.","Scarcity affects only poor people."],"correctOption":1,"section":"Nature of Economic Science","explanation":"Scarcity means wants are greater than the resources available to satisfy them, and that is true for everyone, rich or poor. Options D, C and A confuse scarcity with poverty; even a very rich person has limited time and must choose how to use it."}},{"itemId":"dbd960be-3260-5e10-baab-13371b37b60c","questionId":"cee7fb1b-68d3-5621-af35-4364e84891b4","sourceKey":"bank:ECO101:ECO-2140","payload":{"prompt":"Which statement correctly describes the link between scarcity and opportunity cost?","options":["Scarcity and opportunity cost are unrelated ideas.","Opportunity cost exists only when there is no scarcity.","Scarcity arises because of opportunity costs.","Opportunity costs arise because of scarcity."],"correctOption":3,"section":"Nature of Economic Science","explanation":"Because resources are scarce we must choose, and every choice means giving up the next best alternative, which is opportunity cost. Option C reverses the cause and effect, which is the most common mistake. Options A and B ignore that scarcity is the very reason opportunity costs exist."}},{"itemId":"9ba882e5-cb81-560f-872b-7918255a8e05","questionId":"ddfcff23-7ea6-5bd7-9844-ce6b5376e200","sourceKey":"bank:ECO101:ECO-2142","payload":{"prompt":"Macroeconomics is the study of","options":["aggregate variables such as national output and unemployment.","the price of a single good in one market.","how one firm decides how many workers to hire.","the choices of individual households and firms."],"correctOption":0,"section":"Nature of Economic Science","explanation":"Macroeconomics looks at the economy as a whole, using aggregates such as total output, unemployment and the general price level. Options D, B and C describe individual decision makers or single markets, which belong to microeconomics."}},{"itemId":"ca459831-d12e-5ffc-9c6a-7e48f5a02fad","questionId":"9d0bb8e8-b1aa-5d19-a179-154f12141f9f","sourceKey":"bank:ECO101:ECO-2146","payload":{"prompt":"A country that builds a dam using mainly labour rather than mainly machines is answering which basic economic question?","options":["What to produce","When to produce","How to produce","For whom to produce"],"correctOption":2,"section":"Nature of Economic Science","explanation":"Choosing between labour and machines is a choice of production method, which is the 'how' question. Option A would apply if the country were deciding whether to build the dam at all, and option D is about who receives the output. Option B is not one of the basic economic questions."}},{"itemId":"d784db54-336e-5522-905e-98d94881ca7d","questionId":"27e993ef-43c0-5f73-9233-5c78ededf490","sourceKey":"bank:ECO101:ECO-2149","payload":{"prompt":"Ada buys a N2,000 cinema ticket instead of two novels that would have cost the same amount. What is her opportunity cost of going to the cinema?","options":["Nothing, since she enjoyed the film.","The film plus the two novels.","The two novels she did not buy.","The N2,000 ticket itself."],"correctOption":2,"section":"Nature of Economic Science","explanation":"Opportunity cost is the best alternative given up, and here that is the two novels the money could have bought. Option D names what she chose rather than what she gave up. Option A is wrong because enjoying a choice does not make it free, and option B adds in the thing she actually chose."}},{"itemId":"db48cf87-ba15-5f40-8745-37d1f679766f","questionId":"e49aefb3-cba4-5c68-9517-3f442be4719c","sourceKey":"bank:ECO101:ECO-0107","payload":{"prompt":"Which of the following is a normative economics statement?","options":["Next year inflation rate will be under 4%","Consumers will buy more kerosene over Christmas holiday even if its price is 10 naira higher than it was during the Independence holiday.","The government cuts in welfare spending impose an unfair hardship on the poor.","The current agricultural output surplus is the result of federal policies."],"correctOption":2,"section":"Methodology of Economics","explanation":"A normative statement is a value judgement about what ought to be, and calling welfare cuts an 'unfair hardship' is a matter of opinion. Options A, B and D are positive statements: they are claims about what will happen or what caused something, which can be checked against facts."}},{"itemId":"6d720cb4-2b6e-534f-be51-266b500f97e3","questionId":"aafb5321-9fe0-533a-9175-5e2a407527b8","sourceKey":"bank:ECO101:ECO-0112","payload":{"prompt":"How people should behave is","options":["Microeconomics","Macroeconomics","Normative economic principle","All of the above"],"correctOption":2,"section":"Methodology of Economics","explanation":"Normative economics deals with how people or society ought or should behave, so it involves value judgements. Options A and B, micro and macroeconomics, describe the level of study (individual units versus the whole economy), and both can be either positive or normative."}},{"itemId":"4a682c69-192d-5f9b-a4fd-9d4adf224184","questionId":"4c07661c-7262-5808-ac6e-d1fdd882487e","sourceKey":"bank:ECO101:ECO-0113","payload":{"prompt":"Positive economic principle predicts","options":["How people will behave","How people should behave","Scarcity and choices","Irrational choices"],"correctOption":0,"section":"Methodology of Economics","explanation":"Positive economics describes and predicts how people will actually behave, using statements that can be checked against facts. Option B, how people should behave, is normative economics. Options C and D are not what positive economics predicts."}},{"itemId":"9a696a29-3f7b-5795-989d-de087bbd1d65","questionId":"6342fb1f-f3f2-5c4f-881a-16c76eb76f9c","sourceKey":"bank:ECO101:ECO-0123","payload":{"prompt":"Constant (or parameter) is","options":["a quantity that is fixed in value","a dependent variable","an independent variable","a free variable"],"correctOption":0,"section":"Methodology of Economics","explanation":"A constant (or parameter) is a quantity whose value is fixed within a given model, such as the 50 in Q = 50 - 2P. Options B and C are variables whose values change, and option D is also a variable, not a fixed value."}},{"itemId":"82e84ede-37dc-5163-8896-b1fc62d38310","questionId":"2cf42c55-f328-5161-8c79-0567fd5bb738","sourceKey":"bank:ECO101:ECO-0138","payload":{"prompt":"Ceteris paribus means","options":["nothing is unchangeable","price cannot be constant","technology is given","all things remaining equal"],"correctOption":3,"section":"Methodology of Economics","explanation":"Ceteris paribus is Latin for 'other things being equal', meaning all other factors are held constant while we study the effect of one variable. Option C, technology being given, is just one example of something held constant, not the full meaning. Options A and B do not express the idea at all."}},{"itemId":"104ef6d4-9089-5840-87be-005c54e5a1b6","questionId":"4ba3fc0b-d2d1-5b34-9b17-711426979398","sourceKey":"bank:ECO101:ECO-0197","payload":{"prompt":"The steps involved in constructing economic models are:","options":["Deduction, testing and abstraction","Deduction, abstraction and testing","Abstraction, Deduction and Testing","Abstraction, testing and deduction"],"correctOption":2,"section":"Methodology of Economics","explanation":"Building an economic model starts with abstraction (simplifying reality by keeping only key variables), then deduction (working out logical predictions from the assumptions), and finally testing (checking the predictions against real data). Options A, B and D put these steps in the wrong order."}},{"itemId":"99927530-3688-5bbf-aaee-9cee79831736","questionId":"1aa983f2-31e5-5d1a-ad13-ee15416d8cf2","sourceKey":"bank:ECO101:ECO-0257","payload":{"prompt":"The aspect of economics that deals with aggregate variables is refer to ________","options":["positive economics","macroeconomics","normative economics","microeconomics"],"correctOption":1,"section":"Methodology of Economics","explanation":"Macroeconomics studies the economy as a whole, using aggregate variables such as national income, inflation and unemployment. Option D, microeconomics, studies individual consumers, firms and markets. Options A and C are about whether statements are factual or value-based, not about the scale of study."}},{"itemId":"d95b0f13-65fb-5437-a898-b2533a49e1f4","questionId":"2f7e5028-9026-5106-8704-5c82324a0227","sourceKey":"bank:ECO101:ECO-0294","payload":{"prompt":"The branch of economics that studies individual markets, consumers and firms is called","options":["Macroeconomics","Development economics","Microeconomics","National income accounting"],"correctOption":2,"section":"Methodology of Economics","explanation":"Microeconomics focuses on small units of the economy, such as how one market sets the price of rice or how a single firm decides its output. Option A, macroeconomics, studies the economy as a whole instead. Option D measures total output for the whole country, so it belongs to macroeconomics."}},{"itemId":"83b692cc-1988-51c7-8b7f-d7b311867a93","questionId":"fe38b89c-47dc-5a38-b423-c30bcd94d7f2","sourceKey":"bank:ECO101:ECO-0651","payload":{"prompt":"An economic hypothesis is best tested by:","options":["How realistic its assumptions are","How unrealistic its assumptions are","Whether it can accurately predict outcomes that follow logically from its assumptions","Whether economists agree with it"],"correctOption":2,"section":"Methodology of Economics","explanation":"A hypothesis is judged by checking its predictions against real-world evidence: if the outcomes it predicts actually happen, it is supported. Option A is tempting, but all models simplify reality, so realistic assumptions alone do not prove a hypothesis right, and agreement among economists (D) is not a test at all."}},{"itemId":"d0d8f924-259f-51bd-8da1-b7934a352c5e","questionId":"759783c7-c056-5c00-8f80-863e64d96a8b","sourceKey":"bank:ECO101:ECO-0659","payload":{"prompt":"Which school of thought emphasised the normative (ethical) side of economics?","options":["The English classical school","Lionel Robbins","The German historical school","None of these"],"correctOption":2,"section":"Methodology of Economics","explanation":"The German historical school argued that economics should be concerned with ethics and what ought to be, and should be studied through history rather than pure abstract reasoning. Option B is wrong because Robbins insisted that economics is a positive science that should stay neutral between ends, and the classical economists (A) also stressed a mainly positive, deductive approach."}},{"itemId":"fbf88b55-1d29-502b-bb0f-234cecb84f4b","questionId":"de9e2daf-eb31-5f1e-91d6-fc7d652ac770","sourceKey":"bank:ECO101:ECO-0661","payload":{"prompt":"Which of the following statements about methods of economic analysis is correct?","options":["The deductive method moves from general principles to particular conclusions","The inductive method moves from general principles to particular conclusions","The classical economists mainly used the inductive method","The deductive method depends mainly on experimentation"],"correctOption":0,"section":"Methodology of Economics","explanation":"Deduction starts from general assumptions, such as people seeking to maximise satisfaction, and reasons down to specific conclusions. Option B swaps the two methods, since induction moves from particular facts to general conclusions, and the classical economists actually favoured deduction, which rules out C."}},{"itemId":"0110fb3f-5303-54e4-9795-67cf8198f1c3","questionId":"56eb0645-b330-5ff0-9e78-ff1255bc4da5","sourceKey":"bank:ECO101:ECO-0663","payload":{"prompt":"Which of the following is a feature of the deductive method?","options":["It is abstract","It is highly realistic","It assumes economic conditions are always changing","It was strongly supported by the historical school"],"correctOption":0,"section":"Methodology of Economics","explanation":"The deductive method reasons logically from simplified assumptions, so its conclusions are abstract and may be far from real-life conditions. Option B is the opposite of this, and D is wrong because the historical school favoured the inductive method and criticised deduction."}},{"itemId":"5c41989e-f4a6-5950-8a58-b2c1c5f2c03e","questionId":"e117e613-1532-5000-9f03-4f4f1e4081e0","sourceKey":"bank:ECO101:ECO-0664","payload":{"prompt":"Which of the following is a feature of the inductive method?","options":["It is hypothetical","It is empirical","It ignores experimentation","It is static"],"correctOption":1,"section":"Methodology of Economics","explanation":"The inductive method collects and studies real facts and data before arriving at general conclusions, which makes it empirical. Option A better describes the deductive method, which works from assumed premises, and C is wrong because induction relies on observation and testing."}},{"itemId":"369f6e55-30d9-5742-9d22-5e787245744f","questionId":"bef9f61d-a6b7-58fb-95bd-701fa852a2b2","sourceKey":"bank:ECO101:ECO-0665","payload":{"prompt":"Which statement about economic models is correct?","options":["The predictions of economic models cannot be tested against evidence","Models turn verbal statements into more precise, scientific forms","Models do not rely on any assumptions","Economic models cover every aspect of the economy at once"],"correctOption":1,"section":"Methodology of Economics","explanation":"A model expresses an economic idea in a precise form, such as an equation like Qd = 100 - 2P or a graph, so it can be analysed and tested. Option A is wrong because predictions can be checked against data, C is wrong because every model rests on simplifying assumptions, and D is wrong because models deliberately focus on a few variables."}},{"itemId":"7f799f6c-b8fd-57d4-b453-74019bf870a2","questionId":"3cce4957-8b50-5f2f-ae9f-c2bf20d73567","sourceKey":"bank:ECO101:ECO-0666","payload":{"prompt":"Microeconomic theory studies how a free enterprise economy determines:","options":["The prices of goods","The prices of services","The prices of resources (factors of production)","All of these"],"correctOption":3,"section":"Methodology of Economics","explanation":"Microeconomics covers price theory in full: product pricing, which includes both goods and services, and factor pricing, such as wages, rent and interest. Option A is true but incomplete, so it is not the best answer when D includes it along with services and resources."}},{"itemId":"ff2b46ca-f2ed-536b-9932-11fdc0d5ef24","questionId":"71fa4c3e-7c19-5abf-b8ab-5a8c55b67ed4","sourceKey":"bank:ECO101:ECO-0667","payload":{"prompt":"Which aspect of a tax is a question of normative economics?","options":["Who finally bears the burden of the tax","Whether the tax is fair","How the tax affects people's incentive to work","All of the above"],"correctOption":1,"section":"Methodology of Economics","explanation":"Normative economics deals with value judgements about what ought to be, and whether a tax is fair depends on opinions about justice. Options A and C are positive questions because they can be checked with evidence, which also rules out D."}},{"itemId":"6b7eeff3-bbd2-5c74-9a96-578c7d8f854c","questionId":"62b02d6d-59ba-5073-9006-4ef7f1fa404b","sourceKey":"bank:ECO101:ECO-0668","payload":{"prompt":"Microeconomics deals mainly with:","options":["Comparative statics, general equilibrium and positive economics","Comparative statics, partial equilibrium and normative economics","Dynamics, partial equilibrium and positive economics","Comparative statics, partial equilibrium and positive economics"],"correctOption":3,"section":"Methodology of Economics","explanation":"Most microeconomic analysis compares equilibrium positions (comparative statics), looks at one market at a time (partial equilibrium) and describes how things are rather than how they ought to be (positive economics). Each other option swaps in one less typical element: general equilibrium in A, normative economics in B, and dynamics in C."}},{"itemId":"39e93e3c-d6ad-5a96-80ad-130217c459b3","questionId":"4b88cc2a-f44a-5dbb-bd61-54e8cbcfd305","sourceKey":"bank:ECO101:ECO-0669","payload":{"prompt":"Which of the following statements about microeconomics is INCORRECT?","options":["Microeconomics is mainly concerned with what, how and for whom to produce","Microeconomics is mainly concerned with the behaviour of individual decision-making units at equilibrium","Microeconomics is mainly concerned with the time path by which one equilibrium evolves into another","Microeconomics is mainly concerned with comparative statics rather than dynamics"],"correctOption":2,"section":"Methodology of Economics","explanation":"Studying the time path from one equilibrium to another is dynamic analysis, while microeconomics mainly compares equilibrium positions (comparative statics), so statement C is the incorrect one. Statements A, B and D correctly describe what microeconomics focuses on."}},{"itemId":"74fee1c7-eb48-5889-978e-67be5408f5b1","questionId":"d6370a56-ef37-56ce-8f6d-eb49803d6a84","sourceKey":"bank:ECO101:ECO-0673","payload":{"prompt":"Microeconomics studies the decision-making behaviour of:","options":["Society as a whole","An individual unit such as a household","The whole population of a country","The economy as a whole"],"correctOption":1,"section":"Methodology of Economics","explanation":"Microeconomics looks at individual economic units, such as a household deciding what to buy or a Lagos firm deciding how much to produce. Options A, C and D describe aggregates, which are the subject of macroeconomics."}},{"itemId":"d8e78cf1-17fd-55f3-ac66-690d28de74f9","questionId":"94e978b8-bb0c-54ca-a062-e65875fc6d64","sourceKey":"bank:ECO101:ECO-0674","payload":{"prompt":"Which economist first introduced the term 'micro' into economics?","options":["J.M. Keynes","Ragnar Frisch","J.R. Hicks","Alfred Marshall"],"correctOption":1,"section":"Methodology of Economics","explanation":"The Norwegian economist Ragnar Frisch is credited with first using the terms microeconomics and macroeconomics. Option A, Keynes, is closely linked with the growth of macroeconomics, but he was not the one who coined the terms."}},{"itemId":"c0b8d9ad-17a5-5ea0-9a3f-a3ad54349448","questionId":"31b7cb28-15b7-55ae-8f31-7a8b51ca5dba","sourceKey":"bank:ECO101:ECO-0675","payload":{"prompt":"In economics, a function refers to:","options":["The demand for a commodity","The supply of a commodity","The demand and supply of a commodity, service or resource","The relationship between a dependent variable and one or more independent variables"],"correctOption":3,"section":"Methodology of Economics","explanation":"A function shows how one variable depends on others; for example, Qd = f(P, Y) says quantity demanded depends on price and income. Options A, B and C are examples of things that can be written as functions, but none of them defines what a function is."}},{"itemId":"f2e0193d-0ea0-5e21-9597-0a897ae6ab54","questionId":"235c6a13-663b-5ffa-9019-6e39f02e9aec","sourceKey":"bank:ECO101:ECO-0680","payload":{"prompt":"Microeconomics deals with:","options":["The theory of factor pricing","The theory of product pricing","The theory of economic welfare","All of the above"],"correctOption":3,"section":"Methodology of Economics","explanation":"Microeconomics covers how prices of products are set, how factors of production such as labour and land are paid, and welfare economics, which asks whether resources are allocated efficiently. Each of A, B and C is part of microeconomics, so D is the complete answer."}},{"itemId":"a2acf3c6-371f-5f52-857a-0cc228563273","questionId":"641f87c1-f9e3-5995-a888-e0d92ef1795e","sourceKey":"bank:ECO101:ECO-0682","payload":{"prompt":"In economics, a theory is best described as:","options":["An assumption","A hypothesis that has been tested and supported by evidence","Any 'if-then' statement","An untested hypothesis"],"correctOption":1,"section":"Methodology of Economics","explanation":"A hypothesis becomes a theory once it has been tested against facts and found to hold, so a theory is a validated hypothesis. Option D is the tempting one, but an untested hypothesis is only a proposed explanation, and an assumption (A) is just a starting point for reasoning."}},{"itemId":"304fa812-5cd5-5882-a39e-df2f8e070510","questionId":"e83a0156-687f-571e-9e27-065a2dabdc37","sourceKey":"bank:ECO101:ECO-0685","payload":{"prompt":"A hypothesis is:","options":["A statement of established facts","A record of observations made by a researcher","The final result of a research study","A proposition whose validity is yet to be tested"],"correctOption":3,"section":"Methodology of Economics","explanation":"A hypothesis is a tentative explanation or proposition that is put forward to be tested against evidence. Option A is wrong because a hypothesis is not yet established, and B and C describe data collected and findings reached, not the starting proposition."}},{"itemId":"14e218f1-8e11-5897-971a-081036d419e3","questionId":"04008455-5137-5138-bcbb-41f43867bc69","sourceKey":"bank:ECO101:ECO-0697","payload":{"prompt":"Research carried out mainly by observing real-life data or analysing patterns of actual events in order to identify trends is called:","options":["Empirical research","Action research","Laboratory research","Exploratory research"],"correctOption":0,"section":"Methodology of Economics","explanation":"Empirical research draws its conclusions from observed, real-world evidence, which links closely to the inductive method in economics. Option C relies on controlled experiments, and D aims to explore a new problem loosely rather than to analyse actual data patterns."}},{"itemId":"84959f60-7db0-555a-8763-66b8b8cb8d83","questionId":"50d813b0-bba3-5e00-8164-8e75866aa815","sourceKey":"bank:ECO101:ECO-0843","payload":{"prompt":"A study of how a rise in the company income tax rate would affect the economy's natural rate of unemployment is an example of:","options":["macroeconomics","descriptive economics","microeconomics","normative economics"],"correctOption":0,"section":"Methodology of Economics","explanation":"The natural rate of unemployment is an economy-wide aggregate, so studying how a tax change affects it is macroeconomics. Option C would focus on a single firm or market, and Option D is wrong because the study asks what would happen, not what ought to happen, which makes it a positive question."}},{"itemId":"168d3a20-3e22-5062-8557-ddd54e8ce559","questionId":"976ba7a8-fbe0-5af7-a2c2-8ed35796fe9c","sourceKey":"bank:ECO101:ECO-0847","payload":{"prompt":"Which of the following topics falls under microeconomics?","options":["National income","The general price level","Factor pricing","National saving and investment"],"correctOption":2,"section":"Methodology of Economics","explanation":"Factor pricing studies how the prices of individual factors, such as wages for labour and rent for land, are determined in their own markets, which is a microeconomic topic. National income, the general price level and national saving and investment (A, B and D) are economy-wide aggregates studied in macroeconomics."}},{"itemId":"67725682-555a-50c0-8507-52d977e482ec","questionId":"223c0191-98c6-5dfd-88ed-a2a0192a99fc","sourceKey":"bank:ECO101:ECO-0849","payload":{"prompt":"Under the inductive method, reasoning proceeds from:","options":["the general to the particular","the particular to the general","both the general to the particular and the reverse","neither"],"correctOption":1,"section":"Methodology of Economics","explanation":"The inductive method starts from specific facts and observations, such as price data from many markets, and builds general conclusions from them. Option A describes the deductive method, which starts from general assumptions and reasons down to particular conclusions."}},{"itemId":"d59c6326-3742-554c-ab2e-80660a20ab1d","questionId":"7d724379-f370-5f58-9f8d-fb177fd866da","sourceKey":"bank:ECO101:ECO-1906","payload":{"prompt":"Which of the following is a macroeconomic topic?","options":["the reasons for a rise in the price of rice","the reasons for a rise in the average level of prices","why electricians earn more than cleaners","whether the army should buy more vehicles or more rifles"],"correctOption":1,"section":"Methodology of Economics","explanation":"Macroeconomics studies the economy as a whole, and a rise in the average level of prices (inflation) is an economy-wide issue. Option A is tempting, but the price of one good like rice is a microeconomic question about a single market. Options C and D are also about specific markets or specific spending decisions, so they are microeconomic."}},{"itemId":"4facfa61-0510-52dc-886b-32499ad6c804","questionId":"593fbfb5-d158-5914-a936-e4fb88abfc0c","sourceKey":"bank:ECO101:ECO-1911","payload":{"prompt":"Which term best describes the study of the decisions of individuals and businesses and how these decisions interact?","options":["marginal analysis","macroeconomics","microeconomics","scarcity science"],"correctOption":2,"section":"Methodology of Economics","explanation":"Microeconomics looks at the decisions of individual people and businesses and how these decisions interact in markets. Option B, macroeconomics, studies the economy as a whole rather than individual decision makers. Option A, marginal analysis, is a tool economists use, not a branch of study."}},{"itemId":"5d674f26-88e1-5c12-b467-c876c05e4297","questionId":"e0c2f53c-5847-5ff4-b4fb-032cf69b77ed","sourceKey":"bank:ECO101:ECO-1912","payload":{"prompt":"Which of the following questions would be studied in microeconomics?","options":["Why did total output and the number of jobs in Nigeria shrink during a recession?","Will the current government budget deficit affect the well-being of the next generation?","How will a lower price of smartphones affect the quantity of smartphones sold?","What is the current national unemployment rate?"],"correctOption":2,"section":"Methodology of Economics","explanation":"Microeconomics studies individual markets, and asking how a lower smartphone price changes the quantity sold is a question about one market. Option D, the national unemployment rate, is an economy-wide measure, so it belongs to macroeconomics. Options A and B are also macroeconomic, since they deal with total output, total jobs and the government budget as a whole."}},{"itemId":"7bf81516-68e9-58ad-b8d7-7797a2bdc92b","questionId":"4b7b72ce-07b0-51f3-943f-78043b86ec2f","sourceKey":"bank:ECO101:ECO-1914","payload":{"prompt":"One topic a microeconomist would study is the","options":["factors that lead to inflation.","factors that affect total unemployment in the economy.","effect an increase in the price of petrol has on an individual.","effect of an increase in government spending on the nation's total production."],"correctOption":2,"section":"Methodology of Economics","explanation":"Microeconomics focuses on individual decision makers, so how a rise in the price of petrol affects one person's choices is a microeconomic topic. Options A, B and D (inflation, total unemployment and national output) are economy-wide issues, which makes them macroeconomic topics."}},{"itemId":"f9127e28-2b01-58f1-b9c5-0c4a04a64542","questionId":"eaefcc56-dc47-5e9c-bc1b-da49439de6eb","sourceKey":"bank:ECO101:ECO-1918","payload":{"prompt":"Macroeconomics differs from microeconomics in that","options":["macroeconomics studies the decisions of individuals.","microeconomics looks at the economy as a whole.","macroeconomics studies the behaviour of government while microeconomics studies private companies.","macroeconomics focuses on the national economy and the global economy."],"correctOption":3,"section":"Methodology of Economics","explanation":"Macroeconomics studies the performance of the national and global economies, using aggregates like national output and inflation. Options A and B swap the two branches around. Option C is tempting, but both branches can study government; microeconomics, for example, looks at how a tax affects one market."}},{"itemId":"99dcfd78-a0eb-5ed2-88d6-8d7c74dc1ab9","questionId":"4ef7b2ea-0812-5501-bcbf-cd9264461441","sourceKey":"bank:ECO101:ECO-1920","payload":{"prompt":"Which of the following is a macroeconomic issue?","options":["How many more packets of biscuits will a consumer buy if the price of biscuits falls?","What effect would a cure for a poultry disease have on the market for chicken?","What are the future growth prospects of an economy?","How many workers should the owner of a small business hire?"],"correctOption":2,"section":"Methodology of Economics","explanation":"Economic growth of a whole economy is a macroeconomic issue, because it concerns total output rather than any single market or firm. Options A and B deal with individual markets (biscuits and chicken), and Option D deals with the decision of one firm, so they are all microeconomic questions."}},{"itemId":"607b403b-e083-5628-a346-9c7039a4a661","questionId":"2372612c-7bad-5fae-af75-bf00b81a7a63","sourceKey":"bank:ECO101:ECO-1922","payload":{"prompt":"Microeconomics studies all of the following EXCEPT the","options":["buying decisions made by an individual consumer.","effect on inflation of an increase in the money supply.","hiring decisions made by a business.","effect on cigarette sales of an increase in the tax on cigarettes."],"correctOption":1,"section":"Methodology of Economics","explanation":"How the money supply affects inflation is an economy-wide question, so it belongs to macroeconomics, not microeconomics. Options A and C are classic microeconomic topics about individual consumers and firms. Option D might look like a government policy question, but it concerns one market (cigarettes), so it is also microeconomic."}},{"itemId":"c5e75050-789a-5a54-8d7b-c40f35897566","questionId":"3f759873-03d6-56e1-9596-30b6c27390cc","sourceKey":"bank:ECO101:ECO-1923","payload":{"prompt":"In broad terms, the difference between microeconomics and macroeconomics is that","options":["they use completely different sets of tools and ideas.","microeconomics studies the decisions of individual people and firms, while macroeconomics studies the national economy as a whole.","macroeconomics studies the effect of government regulation and taxes on the prices of individual goods, while microeconomics does not.","microeconomics studies the effect of government taxes on the national unemployment rate."],"correctOption":1,"section":"Methodology of Economics","explanation":"Microeconomics looks at individual people, firms and markets, while macroeconomics looks at the whole national economy. Option A is wrong because both branches share the same basic tools, such as demand and supply and marginal analysis. Options C and D mix up the two, since effects on individual prices are micro and the national unemployment rate is macro."}},{"itemId":"fdfcbfa7-f5d8-5ca8-99b9-c46a085a580f","questionId":"8f4c83ba-4ab2-5fa6-bffe-772022bca730","sourceKey":"bank:ECO101:ECO-1924","payload":{"prompt":"Studying how prices are determined in individual markets is mainly a concern of","options":["positive economics.","negative economics.","macroeconomics.","microeconomics."],"correctOption":3,"section":"Methodology of Economics","explanation":"Microeconomics studies individual markets, including how demand and supply determine the price of a particular good. Option C, macroeconomics, deals with the overall price level rather than prices in individual markets. Option A, positive economics, describes statements about what is, and Option B is not a recognised branch of economics."}},{"itemId":"1885612e-25b5-56ac-961c-952c785185a1","questionId":"6779e645-69fa-5754-9591-f0903f91810d","sourceKey":"bank:ECO101:ECO-1929","payload":{"prompt":"Macroeconomics is the branch of economics that studies","options":["the prices of individual goods.","how individual markets work.","the economy as a whole.","important, as opposed to trivial, issues."],"correctOption":2,"section":"Methodology of Economics","explanation":"Macroeconomics looks at the economy as a whole, focusing on aggregates such as national output, total employment and the general price level. Options A and B describe microeconomics, which studies individual goods and markets. Option D is wrong because the word 'macro' refers to the size of what is studied, not how important it is."}},{"itemId":"e802fe45-91e7-5550-bf5b-f4b22cbb16fe","questionId":"a60cea7b-8d17-5c84-988a-b4a21ab19975","sourceKey":"bank:ECO101:ECO-2084","payload":{"prompt":"A positive statement","options":["is a strongly worded statement that affirms something.","is a statement of what ought to be.","is a statement of what is.","cannot be tested against the facts."],"correctOption":2,"section":"Methodology of Economics","explanation":"Positive statements are claims about what is, and they can in principle be tested against evidence. Option A uses 'positive' in its everyday sense of optimistic or confident. Options B and D describe normative statements."}},{"itemId":"356eea6e-7694-5dbc-abb2-a4e33c93d452","questionId":"d3931d2f-170e-5edf-901f-fd1e5aa51004","sourceKey":"bank:ECO101:ECO-2085","payload":{"prompt":"Which of these are true of positive statements? I. They describe what ought to be. II. They describe what we believe about how the world is. III. They can be tested to see if they are true.","options":["I and II","II and III","I and III","I, II and III"],"correctOption":1,"section":"Methodology of Economics","explanation":"Positive statements are claims about how the world is, and they can be checked against the facts, so II and III are true. Statement I describes normative statements, which is why options A, C and D are wrong."}},{"itemId":"aa7460b6-ee70-5ac7-8b62-d7ac3940148c","questionId":"6aa8f8e4-52a4-5a3d-be2e-f58310fe229f","sourceKey":"bank:ECO101:ECO-2086","payload":{"prompt":"Positive and normative statements differ in that","options":["positive statements can be tested, while normative statements cannot.","normative statements can be tested, while positive statements cannot.","normative statements describe what is and positive statements describe what ought to be.","normative statements never use the word 'should'."],"correctOption":0,"section":"Methodology of Economics","explanation":"Positive statements are factual claims that evidence can confirm or reject, while normative statements are value judgements that facts cannot settle. Options B and C swap the two types around. Option D is wrong because 'should' is in fact a common sign of a normative statement."}},{"itemId":"a6f3d355-ed50-5000-b7c2-b31d3ca53983","questionId":"f1691921-b437-56ea-aba4-adcd1d316461","sourceKey":"bank:ECO101:ECO-2089","payload":{"prompt":"Which of the following is a positive statement?","options":["An unemployment rate of 9 percent is a national disgrace.","Unemployment is a more important problem than inflation.","When the national unemployment rate is high, youth unemployment is usually much higher.","Unemployment and inflation are equally important problems."],"correctOption":2,"section":"Methodology of Economics","explanation":"Option C is a claim about how unemployment rates are related, which data can check, so it is positive. Options A, B and D all rest on value judgements, such as what is a disgrace or which problem matters more, so they are normative."}},{"itemId":"a0c70c16-6314-5cdd-9d40-acdf593e6463","questionId":"18aad787-675d-57c2-a1d1-0c929d545c15","sourceKey":"bank:ECO101:ECO-2091","payload":{"prompt":"A normative statement involves","options":["what can be proven.","what is correct.","what is incorrect.","a value judgement."],"correctOption":3,"section":"Methodology of Economics","explanation":"Normative statements express opinions about what is good, bad or desirable, which are value judgements. Option A describes positive statements, which can be tested. Options B and C are tempting, but facts cannot show a normative statement to be correct or incorrect."}},{"itemId":"c9c812fd-12a0-59c1-8f93-e4746aea8ea0","questionId":"1a6deca6-f83a-5b86-bced-1795bbabee01","sourceKey":"bank:ECO101:ECO-2092","payload":{"prompt":"Normative economic statements","options":["describe what ought to be.","describe what is rather than what ought to be.","describe how economic policy is made.","deal with economic hypotheses that are not yet well established."],"correctOption":0,"section":"Methodology of Economics","explanation":"Normative statements say how things ought to be, so they reflect values. Option B is the definition of a positive statement. Option D is a trap: an untested hypothesis is still positive, because it is a claim about how the world works."}},{"itemId":"b91df4d1-54e0-5b2c-948b-0fa7943a4138","questionId":"5a9af4b4-f517-5afc-830d-740d580a4d68","sourceKey":"bank:ECO101:ECO-2093","payload":{"prompt":"The statement 'Strawberry ice cream is better than vanilla ice cream'","options":["can be tested using the scientific method.","is a normative statement.","is a positive statement.","tells us which flavour will sell the most."],"correctOption":1,"section":"Methodology of Economics","explanation":"Saying one flavour is 'better' is a matter of personal taste, which is a value judgement, so the statement is normative. Options A and C are wrong because no data can prove one taste is better. Option D is wrong because a personal opinion does not predict market sales."}},{"itemId":"e046c6c8-3b38-5f83-9501-e437b9778c4b","questionId":"ee3419bc-d3fc-5929-83ee-870c21c413ff","sourceKey":"bank:ECO101:ECO-2094","payload":{"prompt":"The statement 'Unemployment should be kept at or below 6 percent' is","options":["a positive statement.","a normative statement.","a prediction.","an assumption."],"correctOption":1,"section":"Methodology of Economics","explanation":"The word 'should' shows that this is a judgement about what policy ought to aim for, so it is normative. Options A and C are wrong because it does not describe or predict what is happening. It is a goal based on values, not an assumption used in a model, so option D is also wrong."}},{"itemId":"fb3b74b4-42b3-5615-a1ba-d30837b5c75e","questionId":"5b9dec7e-a10d-5052-bb68-bfbe46cf729e","sourceKey":"bank:ECO101:ECO-2095","payload":{"prompt":"Which of the following is a positive statement?","options":["Government should not redistribute income.","Firms ought to give more to charity.","Households are the main source of saving.","Trade with other countries should be more tightly controlled."],"correctOption":2,"section":"Methodology of Economics","explanation":"Option C is a factual claim about where saving comes from, and it can be checked with data. Options A, B and D use 'should' or 'ought,' which signals a judgement about what is desirable, so they are normative."}},{"itemId":"0a621525-ef38-53b3-9165-646082ad292a","questionId":"1824a294-706a-566a-b11e-4efa3f218fb6","sourceKey":"bank:ECO101:ECO-2098","payload":{"prompt":"The statement 'A rise in the price of petrol will lead to a fall in the quantity bought' is","options":["a political statement.","a positive statement.","a normative statement.","a moral statement."],"correctOption":1,"section":"Methodology of Economics","explanation":"This statement predicts how buyers respond to a price change, and evidence can test it, so it is positive. Option C is wrong because the statement does not say whether the outcome is good or bad. Options A and D describe statements based on politics or values, which this is not."}},{"itemId":"8868238e-2aea-5b71-b835-2e1ec1b4bfdf","questionId":"39e742fa-84b6-59d3-b244-89acfaa75751","sourceKey":"bank:ECO101:ECO-2105","payload":{"prompt":"Which of the following is a normative statement?","options":["A bar of chocolate costs N500.","Chocolate is more expensive than chewing gum.","You should eat less chocolate.","Chocolate and popcorn are sold at cinemas."],"correctOption":2,"section":"Methodology of Economics","explanation":"Option C tells you what you ought to do, which is a value judgement, so it is normative. Options A, B and D are factual claims that could be checked by looking at prices or shops, so they are positive."}},{"itemId":"42124812-179e-5bf7-b030-fdc7fe7880a5","questionId":"4002ab39-ff6e-572a-9d54-71cb05ad6e1a","sourceKey":"bank:ECO101:ECO-2106","payload":{"prompt":"Which of these propositions is normative?","options":["Tariffs and import restrictions make most people worse off.","Cash payments to the poor make them better off than gifts in kind of the same value.","Redistributing income is a legitimate role for government.","Rent controls reduce the supply of housing."],"correctOption":2,"section":"Methodology of Economics","explanation":"Whether something is a 'legitimate' role for government is a matter of values, so option C is normative. Options A, B and D are claims about cause and effect that evidence could support or reject, so they are positive, even though they sound like opinions."}},{"itemId":"7a35eccd-6140-528f-89a9-e0b1913ef358","questionId":"eac2d1f0-fe03-51bf-b804-d90f29811ba5","sourceKey":"bank:ECO101:ECO-2112","payload":{"prompt":"An economist tells you that Nigerians do not save enough of their income. This is an example of ____ statement.","options":["an autonomous","a positive","a normative","a ceteris paribus"],"correctOption":2,"section":"Methodology of Economics","explanation":"Saying people do not save 'enough' judges what the right amount of saving is, which is a value judgement, so the statement is normative even though it does not use the word 'should.' Option B is tempting because it sounds factual, but there is no objective test of what is 'enough.'"}},{"itemId":"80e9427f-e430-59c9-97a3-2e12041444c5","questionId":"f79eab49-9133-5a84-b1cb-477bc4883536","sourceKey":"bank:ECO101:ECO-2113","payload":{"prompt":"Economic models","options":["are completely different from those used in other sciences.","always use graphs.","simplify reality.","include all relevant facts."],"correctOption":2,"section":"Methodology of Economics","explanation":"An economic model is a simplified picture of the economy that keeps only the features needed to explain something. Option D is the opposite of what a model does. Option B is wrong because models can also be written in words or as equations."}},{"itemId":"6504bdb0-ee26-599f-b171-c73ea9c88356","questionId":"3c7a1e4f-20a3-52a3-a61d-d0030bc1ef11","sourceKey":"bank:ECO101:ECO-2114","payload":{"prompt":"A good economic model","options":["describes every aspect of the economy, without exception.","includes every feature of the world that can be measured.","includes only the features of the world needed for the purpose at hand.","should never include more than two variables."],"correctOption":2,"section":"Methodology of Economics","explanation":"A good model leaves out unnecessary detail and keeps only what matters for the question being studied. Options A and B would make the model as complicated as the real world and therefore useless. Option D sets an arbitrary limit; models can have as many variables as the purpose requires."}},{"itemId":"308630af-c8f5-569f-8409-2abce7d03d35","questionId":"eb8bf74f-f171-51f5-8bed-f8d07970a98a","sourceKey":"bank:ECO101:ECO-2120","payload":{"prompt":"When the chief executive of a commercial bank speaks to lawmakers about lending standards in the banking industry, the topic is","options":["macroeconomic.","microeconomic.","about incentives.","the big trade-off."],"correctOption":1,"section":"Methodology of Economics","explanation":"Lending standards in one industry concern the behaviour of particular firms and markets, which is microeconomics. Option A would apply to economy-wide issues such as total output, inflation or unemployment."}},{"itemId":"88f04c81-2cdc-5b35-8794-b6afa228e418","questionId":"5544362d-4acb-542a-bcf6-ddc136653987","sourceKey":"bank:ECO101:ECO-2121","payload":{"prompt":"When the Governor of the Central Bank of Nigeria speaks to lawmakers about Nigeria's role in the world economy, the topic is","options":["macroeconomic.","microeconomic.","scarcity.","incentives."],"correctOption":0,"section":"Methodology of Economics","explanation":"A country's place in the world economy is about the economy as a whole, so it is a macroeconomic topic. Option B, microeconomics, deals with individual households, firms and markets, not with the whole national economy."}},{"itemId":"01624dfc-b7e6-51af-a76d-8c2e302dfe62","questionId":"19f4af54-4ce3-5694-b9db-865fb0556436","sourceKey":"bank:ECO101:ECO-2134","payload":{"prompt":"'If the central bank buys shares in commercial banks, the inflation rate will rise.' This is","options":["a positive statement.","a normative statement.","a microeconomic statement.","the big trade-off."],"correctOption":0,"section":"Methodology of Economics","explanation":"The statement predicts a cause and effect that could be tested with evidence, so it is positive, whether or not it turns out to be true. Option B is wrong because it makes no judgement about what ought to happen. Option C is wrong because inflation is an economy-wide, macroeconomic variable."}},{"itemId":"876f7ea7-a7b2-522b-ae1e-10f7fc02c3ba","questionId":"3291fe81-5d95-58dc-96e2-d350904738e1","sourceKey":"bank:ECO101:ECO-2150","payload":{"prompt":"The horizontal axis of a graph","options":["always measures time on a scatter diagram.","measures the quality of a variable.","is called the y-axis.","is called the x-axis."],"correctOption":3,"section":"Methodology of Economics","explanation":"The horizontal line on a graph is the x-axis. Option C is wrong because the y-axis is the vertical one. Option A is wrong because a scatter diagram plots two variables against each other, and neither has to be time."}},{"itemId":"fc19be7e-013b-58b7-91f8-6f2977dda53d","questionId":"747e7e8e-4853-5b2b-a153-294851454e87","sourceKey":"bank:ECO101:ECO-2151","payload":{"prompt":"The vertical axis of a graph","options":["is called the y-axis.","is called the x-axis.","always measures time in a cross-section graph.","has no origin."],"correctOption":0,"section":"Methodology of Economics","explanation":"The vertical line on a graph is the y-axis. Option B names the horizontal axis. Option C is wrong because a cross-section graph compares groups at one point in time, and option D is wrong because both axes meet at the origin."}},{"itemId":"2c52f209-ad5f-52ca-a204-6579444b23e8","questionId":"4414336c-3878-5a46-b6a3-0d9339bfe90d","sourceKey":"bank:ECO101:ECO-2152","payload":{"prompt":"The y-coordinate of a point on a graph is the length of a line from the point to the","options":["origin.","scale.","x-axis.","y-axis."],"correctOption":2,"section":"Methodology of Economics","explanation":"The y-coordinate is the height of the point, and you measure it straight down from the point to the horizontal x-axis. Option D is the trap: the distance to the y-axis gives the x-coordinate instead. Option A, the distance to the origin, is a diagonal line, not a coordinate."}},{"itemId":"eda9070b-7a2c-5660-8f34-7963a16e7b30","questionId":"3935e28a-10a1-51cf-adca-41ca5a6e95b0","sourceKey":"bank:ECO101:ECO-2153","payload":{"prompt":"The x-coordinate of a point on a graph is the length of a line from the point to the","options":["origin.","scale.","x-axis.","y-axis."],"correctOption":3,"section":"Methodology of Economics","explanation":"The x-coordinate shows how far across the point is, which is measured horizontally from the point to the vertical y-axis. Option C is the trap: the distance to the x-axis gives the y-coordinate. Option A, the distance to the origin, is a diagonal line, not a coordinate."}},{"itemId":"c53d71c4-5d68-567f-ab8c-cd0d763e70ee","questionId":"582349c0-f9e7-57c6-94b3-11c659266590","sourceKey":"bank:ECO101:ECO-2154","payload":{"prompt":"On the horizontal axis of a graph, generally","options":["values increase from left to right.","values increase from right to left.","values can be positive and/or negative.","both a and c are correct."],"correctOption":3,"section":"Methodology of Economics","explanation":"Values on the x-axis rise as you move to the right, and the axis can extend to the left of the origin to show negative values. So statements a and c are both true, which makes D the best answer. Option B describes the opposite direction."}},{"itemId":"6839258e-5ee1-5326-b887-2dce20165bd0","questionId":"ec2b2e8a-e7a5-56de-bc6d-d37cf0d4e685","sourceKey":"bank:ECO101:ECO-2157","payload":{"prompt":"A graph that shows time on the horizontal axis and one or more variables on the vertical axis is called a","options":["cross-section graph.","time-series graph.","inverted graph.","one-dimensional graph."],"correctOption":1,"section":"Methodology of Economics","explanation":"A time-series graph tracks how a variable changes over time, so time runs along the x-axis. Option A, a cross-section graph, compares different groups at one point in time rather than tracking change."}},{"itemId":"0f7e26a0-bdc5-5163-a01f-d307a6ea71f8","questionId":"6d66752e-8cbb-5f26-a6ab-ddf88a695bc2","sourceKey":"bank:ECO101:ECO-2159","payload":{"prompt":"Which of the following is correct about a time-series graph? I. The x-axis measures time. II. It can show whether a variable has a trend.","options":["I only","II only","both I and II","neither I nor II"],"correctOption":2,"section":"Methodology of Economics","explanation":"A time-series graph puts time on the x-axis, and following the line over time reveals any trend, so both statements are true. Options A and B each leave out one correct statement."}},{"itemId":"f2cecd4a-7e3d-5461-b02e-d816b1a689cb","questionId":"5d07539a-adf8-54d9-ac64-a5b5668e078a","sourceKey":"bank:ECO101:ECO-2160","payload":{"prompt":"From a time-series graph of shoe sales in naira on the vertical axis, it is NOT possible to tell","options":["the level of sales at a given time.","how sales changed over time.","how fast sales changed over time.","none of these, because all of them can be read from the graph."],"correctOption":3,"section":"Methodology of Economics","explanation":"A time-series graph shows the level of sales at each date (option A), the direction of change (option B) and, through the steepness of the line, how fast sales changed (option C). Since all three can be read from it, D is correct."}},{"itemId":"ec01f8d8-fc85-5cf1-a0e9-d96c6f06823f","questionId":"3446027f-1e6b-5116-95a2-fd19ff5ec9cb","sourceKey":"bank:ECO101:ECO-2161","payload":{"prompt":"A time-series graph can quickly show a reader","options":["the level of a variable at any point in time.","the direction in which a variable is changing over time.","whether the variable has a trend over time.","All of the above."],"correctOption":3,"section":"Methodology of Economics","explanation":"A time-series graph plots a variable against time, so at a glance you can read its level in any year, see whether it is going up or down, and spot any general trend. Options A, B and C are each true on their own, which is why D, which combines them, is the best answer."}},{"itemId":"20ebce9c-b1a2-5394-9662-6abe3a175951","questionId":"a584ea35-74fe-552c-86a7-85ae1768d5ea","sourceKey":"bank:ECO101:ECO-2162","payload":{"prompt":"A time-series graph can reveal whether there is a ________, which means ________.","options":["trend in a variable; a general tendency for the variable to rise or fall","relationship between two variables; a cross-section graph","trend in a variable; that the variables are unrelated","relationship between two variables; a trend in a variable"],"correctOption":0,"section":"Methodology of Economics","explanation":"A trend is a general tendency for a variable to rise or fall over time, and a time-series graph is exactly the tool that shows it. Options B and D talk about a relationship between two variables, which is what a scatter diagram shows, and option C wrongly defines a trend as variables being unrelated."}},{"itemId":"d51fbe51-981b-5592-9f93-1db2c2a817b5","questionId":"3f3989ab-2d30-55f7-ab07-ee1a0fc1b70e","sourceKey":"bank:ECO101:ECO-2163","payload":{"prompt":"A time-series graph of total output in a country from 1990 to 2020 shows a positive trend. This tells us that total output","options":["fell every year between 1990 and 2020.","rose every year between 1990 and 2020.","was lower in 2020 than in 1990.","was higher in 2020 than in 1990."],"correctOption":3,"section":"Methodology of Economics","explanation":"A positive trend means the variable generally rose over the period, so output ended higher in 2020 than it started in 1990. Option B is tempting, but a trend is only a general tendency: output could still have dipped in some years. Options A and C describe a falling pattern, which is the opposite of a positive trend."}},{"itemId":"1c3982d2-2a7f-5029-9c3f-8857d1a73058","questionId":"027d1f99-fb24-5cb1-81e6-47feb59560d0","sourceKey":"bank:ECO101:ECO-2164","payload":{"prompt":"A time-series graph of a country's unemployment rate from 2000 to 2020 shows a negative trend. It is likely that the unemployment rate","options":["fell every year between 2000 and 2020.","rose every year between 2000 and 2020.","was lower in 2020 than in 2000.","was higher in 2020 than in 2000."],"correctOption":2,"section":"Methodology of Economics","explanation":"A negative trend means the variable generally fell over the period, so the unemployment rate most likely ended lower in 2020 than in 2000. Option A goes too far, because a downward trend still allows for some years in which unemployment rose. Options B and D describe an upward movement instead."}},{"itemId":"88610bb1-d839-5b92-ac9e-fb21ed3436fe","questionId":"1fd588c0-885d-580f-bfb1-159b7b0bfc07","sourceKey":"bank:ECO101:ECO-2166","payload":{"prompt":"You want to show how the inflation rate differs across several West African countries in one particular year. The best graph to use is","options":["a time-series graph.","a cross-section graph.","a scatter diagram.","none of these, because any type of graph might mislead."],"correctOption":1,"section":"Methodology of Economics","explanation":"A cross-section graph shows the values of one variable for different groups, here different countries, at a single point in time. Option A is for showing how a variable changes over time, and option C shows the relationship between two variables. Option D is wrong because the possibility of misleading graphs does not stop us choosing the right one."}},{"itemId":"87330590-6422-5c86-8e6f-2c44f3a525be","questionId":"5bd7345e-8001-5dce-a41b-a5963ae582d8","sourceKey":"bank:ECO101:ECO-2168","payload":{"prompt":"On a time-series graph, the horizontal axis","options":["measures the variable being graphed.","measures units of time, such as years or months.","runs parallel to the y-axis.","measures how the variable being graphed changes."],"correctOption":1,"section":"Methodology of Economics","explanation":"In a time-series graph, time (years, quarters, months) runs along the horizontal axis and the variable of interest is measured on the vertical axis. Option A describes the vertical axis, and option C is impossible because the two axes are at right angles to each other."}},{"itemId":"73679fe1-e4ad-5bcd-936e-1c1ec964761a","questionId":"9829ffcc-5bc1-5398-96ee-2c931cd28695","sourceKey":"bank:ECO101:ECO-2170","payload":{"prompt":"The price of a bag of rice in a Lagos market climbed steadily from 2015 to 2022. A time-series graph with the price on the vertical axis and years on the horizontal axis would show","options":["the price as a horizontal line.","that the price followed a decreasing trend.","that the price had a positive trend.","that the price had a negative trend."],"correctOption":2,"section":"Methodology of Economics","explanation":"A variable that rises steadily over time has a positive (upward) trend, so the line on the graph slopes up from left to right. Options B and D describe a falling price, and option A would only happen if the price stayed the same every year."}},{"itemId":"a470a724-478c-5391-bcdc-8f142c138860","questionId":"4db251a5-9e1a-5aaa-af07-5403335dd05b","sourceKey":"bank:ECO101:ECO-2171","payload":{"prompt":"A time-series graph shows the price of cocoa over time. The line has a negative slope during periods when the","options":["price of cocoa is falling.","price of cocoa is rising.","quantity of cocoa is falling.","price of cocoa is low but not changing."],"correctOption":0,"section":"Methodology of Economics","explanation":"On a time-series graph, a negative (downward) slope means the variable on the vertical axis is falling as time passes, so the price of cocoa is going down. Option B would give a positive slope, option D would give a flat line, and option C is about quantity, which this graph does not measure."}},{"itemId":"97fbf643-728f-5539-b0bd-e122f71ebf2f","questionId":"3f3910f8-e7b0-5d9c-8378-f822add0d594","sourceKey":"bank:ECO101:ECO-2172","payload":{"prompt":"A time-series graph shows the wage rate of factory workers in Ikeja over several years. The line has a positive slope during periods when the wage rate is","options":["falling.","rising.","high but no longer rising.","low."],"correctOption":1,"section":"Methodology of Economics","explanation":"A positive slope on a time-series graph means the variable is increasing as time moves forward, so the wage rate is rising. Option C would give a flat line, because a high but unchanging wage has zero slope, and whether wages are high or low (option D) says nothing about the direction of the line."}},{"itemId":"b12e0458-d7b5-51de-bb0e-566a334d623e","questionId":"7bea9730-804f-5603-b202-4ad6e103577d","sourceKey":"bank:ECO101:ECO-2173","payload":{"prompt":"A trend is","options":["a measure of how close together the points are on a scatter diagram.","a general tendency for a variable to rise or fall.","the highest value a variable reaches.","the lowest value a variable reaches."],"correctOption":1,"section":"Methodology of Economics","explanation":"A trend is the general tendency for a variable to rise or fall over time, even if it moves up and down from year to year. Option A describes how strong a correlation looks on a scatter diagram, and options C and D describe a maximum and a minimum, not a trend."}},{"itemId":"b2d9fd07-f7c9-5fab-ace5-3b0e8bd47af9","questionId":"ebc6040b-f902-5521-aaea-571e8a0a0411","sourceKey":"bank:ECO101:ECO-2176","payload":{"prompt":"Which of the following statements about trends is TRUE? I. A cross-section graph shows trends. II. A time-series graph shows trends. III. A scatter diagram shows trends over time.","options":["I only","II only","I and II","II and III"],"correctOption":1,"section":"Methodology of Economics","explanation":"Only a time-series graph measures time on an axis, so it is the graph that shows a trend. A cross-section graph (statement I) compares groups at one point in time, and a scatter diagram (statement III) plots two variables against each other rather than against time, which rules out options A, C and D."}},{"itemId":"fd6bb3d0-9632-5c24-9d36-ac94c1add918","questionId":"6a05333d-e91f-51d9-b7ce-33dc5e9bc02a","sourceKey":"bank:ECO101:ECO-2177","payload":{"prompt":"A cross-section graph shows the value of a variable","options":["for different groups at a point in time.","for one group over a period of time.","as an absolute rate of change over time.","as a percentage rate of change over time."],"correctOption":0,"section":"Methodology of Economics","explanation":"A cross-section graph compares different groups, such as states, cities or age groups, at the same point in time. Option B describes a time-series graph, and options C and D are also about change over time, which a cross-section graph does not show."}},{"itemId":"5a4af7c4-8a57-53a4-b2a5-0f4913194feb","questionId":"17c89973-2618-5cf7-b47d-f5fd41a76049","sourceKey":"bank:ECO101:ECO-2178","payload":{"prompt":"A ________ shows the values of a variable for different groups at a particular point in time.","options":["time-series graph","regression","cross-section graph","scatter diagram"],"correctOption":2,"section":"Methodology of Economics","explanation":"A cross-section graph takes a snapshot at one point in time and compares groups, for example average income in different Nigerian states in one year. Option A tracks one variable over time, and option D plots two variables against each other to show whether they are related."}},{"itemId":"4a9fefee-6267-51d0-980e-91fd47ca2c17","questionId":"b096ceaf-722c-5928-9e11-fddb6fa84722","sourceKey":"bank:ECO101:ECO-2188","payload":{"prompt":"You have data on the amount of rainfall in 30 Nigerian cities for the month of June. The best type of graph to display these data is a","options":["time-series graph.","multi-variable time-series graph.","cross-section graph.","scatter diagram."],"correctOption":2,"section":"Methodology of Economics","explanation":"The data compare many cities for the same month, which is exactly what a cross-section graph is designed for. Options A and B need data spread over many time periods, and option D needs two different variables to plot against each other."}},{"itemId":"610aa969-91a3-53f5-b6ab-559b24563289","questionId":"995cda31-da72-5dd7-90fb-ae6b3dae7710","sourceKey":"bank:ECO101:ECO-2192","payload":{"prompt":"Which type of graph is most useful for finding out whether two variables are correlated?","options":["A time-series graph","A scatter diagram","A cross-section graph","None of these"],"correctOption":1,"section":"Methodology of Economics","explanation":"A scatter diagram plots the value of one variable against the value of another, so you can see whether they tend to move together. Option A shows one variable over time and option C compares groups at one point in time, so neither directly shows the link between two variables."}},{"itemId":"a692e4a9-c019-564f-85df-783df1c4807e","questionId":"d7a607bf-e185-554c-9ca4-1cece1bafe3d","sourceKey":"bank:ECO101:ECO-2193","payload":{"prompt":"Which type of graph should you use to check how strong the relationship is between household saving and household income?","options":["A time-series graph","A scatter diagram","A trend diagram","A bar chart"],"correctOption":1,"section":"Methodology of Economics","explanation":"A scatter diagram plots each observation of saving against income, so the pattern of points shows whether there is a relationship and how strong it is. Options A and C focus on how a variable changes over time, and a bar chart (option D) is mainly used to compare groups."}},{"itemId":"e6bba87d-2ce0-5e22-91ad-de6766acd073","questionId":"e43c202b-e133-590f-915c-3ed4bc55e0de","sourceKey":"bank:ECO101:ECO-2194","payload":{"prompt":"You notice that whenever interest rates rise, the prices of new houses in Lagos tend to fall. This observation means that","options":["the link between interest rates and house prices must be false causality.","higher interest rates must cause lower house prices.","a scatter diagram of interest rates and house prices will show a negative relationship.","a cross-section graph of interest rates and house prices will show a negative relationship."],"correctOption":2,"section":"Methodology of Economics","explanation":"When one variable tends to rise as the other falls, a scatter diagram of the two shows a negative relationship. Option B is tempting, but seeing two variables move together does not prove that one causes the other, and option A goes too far the other way by insisting the link must be false. Option D is wrong because a cross-section graph shows one variable across groups, not the relationship between two variables."}},{"itemId":"5199c1d1-6184-5d3a-b827-fe05b96c3ea8","questionId":"73d4edbe-93a9-5ab4-9f03-06bfe9844126","sourceKey":"bank:ECO101:ECO-2197","payload":{"prompt":"Plotting household incomes against household spending on food on one graph produces","options":["a time-series graph.","a scatter diagram.","both a time-series graph and a scatter diagram.","neither a time-series graph nor a scatter diagram."],"correctOption":1,"section":"Methodology of Economics","explanation":"Plotting one variable (income) against another variable (food spending) gives a scatter diagram, which shows whether the two are related. It is not a time-series graph (option A or C), because time is not measured on either axis."}},{"itemId":"de2f1de9-bba0-53ce-afba-afde13f17a2b","questionId":"e54ef760-58ab-58a8-aaf6-71ae5d41a527","sourceKey":"bank:ECO101:ECO-2198","payload":{"prompt":"On a graph, a high correlation between the variable on the x-axis and the variable on the y-axis","options":["means that changes in the x-axis variable must cause changes in the y-axis variable.","means that changes in the y-axis variable must cause changes in the x-axis variable.","means that changes in either variable must cause changes in the other.","does NOT mean that a change in the x-axis variable must cause a change in the y-axis variable."],"correctOption":3,"section":"Methodology of Economics","explanation":"Correlation only tells us that two variables tend to move together; it does not prove that one causes the other. Both could be driven by a third factor, or the link could be pure coincidence. That is why options A, B and C, which all claim that one change must cause the other, are wrong."}},{"itemId":"18ad8615-8e4c-5d71-b9a2-76df8ca936ee","questionId":"3917bf47-474a-5e34-b71a-0d5d60e071f6","sourceKey":"bank:ECO101:ECO-2199","payload":{"prompt":"The best way to show how an economic variable, such as the inflation rate, changes from one year to the next is a","options":["one-variable graph.","time-series graph.","linear graph.","cross-section graph."],"correctOption":1,"section":"Methodology of Economics","explanation":"A time-series graph puts time on the horizontal axis and the variable on the vertical axis, so you can follow how it changes year by year. Option D compares different groups at one point in time, and option C describes the shape of a line, not a type of graph."}},{"itemId":"6bde471f-8a4b-5d86-883b-8bdc144a547d","questionId":"b555f83b-812d-57d2-b88c-c15a4ca63f5c","sourceKey":"bank:ECO101:ECO-2200","payload":{"prompt":"You believe that the total quantity of goods produced in Nigeria has generally increased over the years. On a time-series graph of total production, you would expect to see","options":["an upward trend.","no relationship between time and the amount produced.","an inverse relationship between time and the amount produced.","a straight-line relationship."],"correctOption":0,"section":"Methodology of Economics","explanation":"If production has generally increased, the time-series graph will show an upward (positive) trend. Option C describes a falling pattern, which is the opposite of your belief, and option D is wrong because a general rise can follow a curved or uneven path rather than a perfectly straight line."}},{"itemId":"a58b2c0b-3d96-5d24-94b1-d7d517a6b922","questionId":"544493ce-8447-58e7-a40c-76d4bba0ada0","sourceKey":"bank:ECO101:ECO-2202","payload":{"prompt":"You suspect that more bottled water is sold in Kano during hotter months. Which of these would best show whether you are right?","options":["A time-series graph of bottled water sales in Kano over the last 10 years","A time-series graph of the average temperature in Kano over the last 10 years","A scatter diagram plotting the average monthly temperature in Kano against bottled water sales","A trend graph comparing water sales over 10 years with the temperature 10 years ago and this year"],"correctOption":2,"section":"Methodology of Economics","explanation":"To test whether two variables are related, plot them against each other in a scatter diagram; if the points rise together, hotter months do go with higher sales. Options A and B each show only one variable over time, so neither can reveal a link between temperature and sales."}},{"itemId":"3b6c736b-f9e0-56b9-8e50-1fa088e42d08","questionId":"8b8057d4-e7e7-5d5b-b213-c3ec447eb04b","sourceKey":"bank:ECO101:ECO-2203","payload":{"prompt":"Which type of graph can be misleading?","options":["A time-series graph","A cross-section graph","A scatter diagram","Any type of graph"],"correctOption":3,"section":"Methodology of Economics","explanation":"Any graph can mislead, for example through a stretched or squeezed scale, an axis that does not start at zero, or a carefully chosen time period. Options A, B and C each name a single type, but none of them is immune."}},{"itemId":"65988b6e-17a8-558f-b6f5-f858ce3f7b2e","questionId":"6a80e2ca-f754-5da0-b3aa-49e78db90f5f","sourceKey":"bank:ECO101:ECO-2204","payload":{"prompt":"If two variables are positively related, then","options":["they move in opposite directions.","they are independent of each other.","they move in the same direction.","their graph has a negative slope."],"correctOption":2,"section":"Methodology of Economics","explanation":"A positive (direct) relationship means that when one variable rises the other also rises, and when one falls the other also falls. Options A and D describe a negative relationship, and option B describes variables that are unrelated."}},{"itemId":"6bdb43ed-d9ec-5b55-b3c0-bb994e18fd2c","questionId":"6d289b93-cb61-56d0-adbe-428d1ed04894","sourceKey":"bank:ECO101:ECO-2206","payload":{"prompt":"If there is a direct relationship between two variables,","options":["the graph of the relationship will slope upward.","the graph of the relationship will slope downward.","the slope of the line, or of a tangent to the curve, will be negative.","Both A and C are correct."],"correctOption":0,"section":"Methodology of Economics","explanation":"A direct relationship is the same as a positive relationship: both variables move in the same direction, so the graph slopes upward and its slope is positive. Options B and C describe an inverse (negative) relationship, which also rules out option D."}},{"itemId":"d8d94092-89b5-51d7-bd04-810cf233de41","questionId":"033658ec-da3e-56ed-afc3-86d589bc5444","sourceKey":"bank:ECO101:ECO-2208","payload":{"prompt":"A positive relationship exists between two variables if","options":["one variable has no effect on the other.","a fall in one variable goes with a rise in the other.","a fall in one variable goes with a fall in the other.","both variables are affected by inflation."],"correctOption":2,"section":"Methodology of Economics","explanation":"In a positive relationship the two variables move in the same direction, so a fall in one goes with a fall in the other (and a rise with a rise). Option B describes a negative relationship, and option A describes variables that are unrelated."}},{"itemId":"38be06a8-9e4d-52fa-b41a-13b7c1c41e4b","questionId":"9308033a-0439-52bd-a832-6842b270c835","sourceKey":"bank:ECO101:ECO-2209","payload":{"prompt":"If the line showing the relationship between variable x and variable y has a positive slope, then","options":["when x increases, y decreases.","when x decreases, y decreases.","the two variables are unrelated.","the two variables have an inverse relationship."],"correctOption":1,"section":"Methodology of Economics","explanation":"A positive slope means x and y move in the same direction, so when x falls, y falls too. Options A and D describe a negative (inverse) relationship, and option C would be shown by a horizontal or vertical line."}},{"itemId":"028c1d4e-00ae-571a-92da-eed72006c330","questionId":"a188f3ff-c30b-55a6-899a-8bff587cce19","sourceKey":"bank:ECO101:ECO-2211","payload":{"prompt":"A chin-chin maker finds that one worker produces 10 packs a day, a second worker adds 8 more packs, and a third worker adds 6 more packs. A graph with the number of workers on the horizontal axis and total packs per day on the vertical axis shows","options":["a positive linear relationship.","an upward-sloping curve that gets flatter as more workers are hired.","a negative linear relationship.","a downward-sloping curve that gets flatter as more workers are hired."],"correctOption":1,"section":"Methodology of Economics","explanation":"Total output keeps rising (10, then 18, then 24 packs), so the curve slopes upward, but each extra worker adds less (10, then 8, then 6), so it gets flatter. Option A would need every worker to add the same amount, and options C and D wrongly suggest that output falls as workers are added."}},{"itemId":"75330635-368f-5bfe-86c9-36e8bf5a84b2","questionId":"4006b6fd-c4bc-5e82-b438-9e4af6620978","sourceKey":"bank:ECO101:ECO-2212","payload":{"prompt":"\"The more hours you spend studying, the higher your CGPA.\" A graph of this relationship would show","options":["a positive relationship.","a direct relationship.","an inverse relationship.","Both A and B are correct."],"correctOption":3,"section":"Methodology of Economics","explanation":"Study hours and CGPA move in the same direction, which is a positive relationship, and \"direct relationship\" is simply another name for the same thing. So A and B are both correct, which makes D the best answer. Option C, an inverse relationship, would mean CGPA falls as study hours rise."}},{"itemId":"5af4a82b-2bb9-5dba-8734-6e2419aa6f60","questionId":"c5b224c4-741f-5be4-831f-c653e756e08c","sourceKey":"bank:ECO101:ECO-2213","payload":{"prompt":"\"As interest rates rise, people save more money.\" A graph of this relationship would show","options":["an inverse relationship.","a positive relationship.","a cross-section graph.","a positive and then a negative relationship."],"correctOption":1,"section":"Methodology of Economics","explanation":"Interest rates and saving move in the same direction here, so the relationship is positive and the graph slopes upward. Option A would mean saving falls as interest rates rise, and option C names a type of graph rather than a kind of relationship."}},{"itemId":"a35df363-cc77-5249-a230-7d8e5f733cc6","questionId":"2e069914-7a89-506b-8fb0-11cca6e4b947","sourceKey":"bank:ECO101:ECO-2216","payload":{"prompt":"A Lagos furniture maker makes 10 chairs a day at a total cost of N100,000. Total cost rises to N110,000 for 15 chairs and to N130,000 for 20 chairs. A graph of total cost against the number of chairs made would be","options":["a negatively sloped line that gets steeper.","a positively sloped line that gets steeper.","a negatively sloped line that gets flatter.","a positively sloped line that gets flatter."],"correctOption":1,"section":"Methodology of Economics","explanation":"Total cost rises with output, so the slope is positive. From 10 to 15 chairs the slope is N10,000 / 5 = N2,000 per chair, and from 15 to 20 chairs it is N20,000 / 5 = N4,000 per chair, so the line gets steeper. Option D gets the direction right but not the shape, and options A and C wrongly suggest that cost falls as output rises."}},{"itemId":"257d2a48-996c-50de-9e7a-85689a309218","questionId":"829d214f-4b27-5a7c-a941-20551faf67b4","sourceKey":"bank:ECO101:ECO-2217","payload":{"prompt":"Whenever one variable increases, another variable decreases. The two variables are","options":["definitely linked through a third variable.","negatively related.","positively related.","unrelated to each other."],"correctOption":1,"section":"Methodology of Economics","explanation":"When two variables move in opposite directions they are negatively (inversely) related. Option C would need them to move in the same direction, and option A goes too far, because nothing in the information tells us that a third variable is involved."}},{"itemId":"4c3ac317-826f-5736-9fd5-6d385e04dc35","questionId":"273e956c-066c-52ce-a5c7-cb4e2e77f615","sourceKey":"bank:ECO101:ECO-2219","payload":{"prompt":"If there is an inverse relationship between variable x and variable y, an increase in x will be accompanied by","options":["an increase in y.","a decrease in y.","no change in y.","y reaching its maximum value."],"correctOption":1,"section":"Methodology of Economics","explanation":"An inverse (negative) relationship means the two variables move in opposite directions, so a rise in x goes with a fall in y. Option A describes a positive relationship, and option C describes variables that are unrelated."}},{"itemId":"b6f31211-6e10-5380-ac7b-0c8e33a31fcf","questionId":"0e6bd44e-c388-54ee-aabf-107a03f20d60","sourceKey":"bank:ECO101:ECO-2220","payload":{"prompt":"If there is an inverse relationship between two variables,","options":["the graph of the relationship will be a horizontal line.","the graph of the relationship will slope downward.","the slope of the line, or of a tangent to the curve, will be positive.","the graph of the relationship will slope upward."],"correctOption":1,"section":"Methodology of Economics","explanation":"In an inverse relationship, as the x-axis variable rises the y-axis variable falls, so the graph slopes downward from left to right and its slope is negative. Options C and D describe a positive relationship, and option A describes variables that are unrelated."}},{"itemId":"432d9edf-5bc8-5490-ad10-47c1e8c7073a","questionId":"e91c9886-5a09-5265-b33a-d04aee09983b","sourceKey":"bank:ECO101:ECO-2222","payload":{"prompt":"Along a curve, whenever one variable increases the other decreases. This curve has","options":["a zero slope.","a positive slope.","a negative slope.","a slope that rises and then falls."],"correctOption":2,"section":"Methodology of Economics","explanation":"When the variables move in opposite directions, the curve slopes downward, which means it has a negative slope. A positive slope (option B) needs both variables to move in the same direction, and a zero slope (option A) means the y-axis variable does not change at all."}},{"itemId":"d4f1e00e-340d-56f1-8c2d-d40c3c2d283e","questionId":"f5deba3b-86f8-5761-a156-d60d294d42f4","sourceKey":"bank:ECO101:ECO-2223","payload":{"prompt":"\"As interest rates fall, people spend more.\" A graph of the relationship between interest rates and spending would have","options":["an inverse relationship.","a negative slope and then a positive slope.","a negative slope.","Both A and C are correct."],"correctOption":3,"section":"Methodology of Economics","explanation":"Interest rates and spending move in opposite directions, so the relationship is inverse, and an inverse relationship is drawn with a negative slope. A and C describe the same fact in two ways, so D is the best answer. Option B would describe a curve with a minimum point, which the statement does not suggest."}},{"itemId":"941352c9-20c1-5bd8-b705-8f9fac9b8440","questionId":"e894f1dd-a911-5ed2-83ab-696cf5b14fae","sourceKey":"bank:ECO101:ECO-2229","payload":{"prompt":"Students' grades and the time they spend at parties move in opposite directions. A graph of the relationship between these two variables would slope","options":["upward and be a straight line.","upward and could be straight or curved.","downward and be a straight line.","downward and could be straight or curved."],"correctOption":3,"section":"Methodology of Economics","explanation":"Variables that move in opposite directions have a negative relationship, so the graph slopes downward. Knowing only the direction does not tell us whether the line is straight or curved, so option C claims too much. Options A and B have the slope going the wrong way."}},{"itemId":"0b96063e-ff42-552d-9cf0-773e854cf06f","questionId":"12315a08-6ad8-595a-9850-0f906218b08e","sourceKey":"bank:ECO101:ECO-2230","payload":{"prompt":"The faster a car is driven, the fewer kilometres it travels per litre of fuel. This means that a car's speed and its kilometres per litre have","options":["a direct relationship.","an inverse relationship.","a linear relationship.","a maximum relationship."],"correctOption":1,"section":"Methodology of Economics","explanation":"As speed rises, kilometres per litre falls, so the two variables move in opposite directions: an inverse relationship. Option A would mean they move together, and option C claims a straight-line shape, which the information does not tell us."}},{"itemId":"14af91ad-41ec-5ed1-b7be-e605c2fc9797","questionId":"f1b5c013-54ef-585e-bd56-a777a98251d0","sourceKey":"bank:ECO101:ECO-2233","payload":{"prompt":"A graph shows a negative relationship between two variables that then turns into a positive relationship. This curve","options":["is always an upward-sloping line.","has a minimum point.","has a maximum point.","is always a downward-sloping line."],"correctOption":1,"section":"Methodology of Economics","explanation":"The curve first falls and then rises, so it is U-shaped and has a lowest point, a minimum, where it changes direction. Option C, a maximum, would need the curve to rise first and then fall, and options A and D ignore the change of direction."}},{"itemId":"03e3b9ea-3cb4-5b45-969e-a4451d8743da","questionId":"8f421659-8560-5b7b-8b4c-c2f3c7e8c7e0","sourceKey":"bank:ECO101:ECO-2234","payload":{"prompt":"As a firm increases its output, its average cost (cost per unit) first falls and then rises. Average cost and output have","options":["a relationship with a minimum.","a relationship with a maximum.","no relationship.","a positive linear relationship."],"correctOption":0,"section":"Methodology of Economics","explanation":"Average cost falls and then rises, giving a U-shaped curve with a lowest point, so the relationship has a minimum. Option B would need cost to rise first and then fall, and option D ignores the first stage, when average cost is falling."}},{"itemId":"58769cbb-c774-5a36-95a2-281cdc8977ec","questionId":"c8251e8c-825c-5908-b19e-0a17ef2d17d5","sourceKey":"bank:ECO101:ECO-2235","payload":{"prompt":"As a curve rises towards its maximum point and then falls, its slope","options":["is positive before the maximum and negative after it.","is negative before the maximum and positive after it.","stays the same on both sides of the maximum.","increases both before and after the maximum."],"correctOption":0,"section":"Methodology of Economics","explanation":"Before the maximum the curve is rising, so its slope is positive; after the maximum it is falling, so its slope is negative. Option B describes a curve with a minimum, where it falls first and then rises."}},{"itemId":"aa65b6fd-a0cd-5434-8a1c-4030fc78aba9","questionId":"aae9f6de-e9af-50c1-9934-e4f1b78c08e5","sourceKey":"bank:ECO101:ECO-2236","payload":{"prompt":"If a curve rises and then falls, it has a","options":["maximum.","minimum.","linear relationship.","constant slope."],"correctOption":0,"section":"Methodology of Economics","explanation":"A curve that rises and then falls reaches a highest point, a maximum, where it turns around. Option B, a minimum, belongs to a curve that falls first and then rises, and options C and D cannot be right because the slope changes from positive to negative."}},{"itemId":"b5122036-0a17-5437-baac-37d0687c250e","questionId":"35f26a6d-7484-5574-b618-b75e065e46aa","sourceKey":"bank:ECO101:ECO-2238","payload":{"prompt":"Along a curve, the slope at the maximum point","options":["is greater than zero.","is zero.","is less than zero.","could be greater than, less than or equal to zero."],"correctOption":1,"section":"Methodology of Economics","explanation":"At the maximum the curve stops rising and has not yet started falling, so the tangent there is flat and the slope is zero. The slope is positive (option A) just before the maximum and negative (option C) just after it, but not at the top itself."}},{"itemId":"57e0d089-84c0-5133-85c8-3823bdefb8a5","questionId":"51935f35-0144-5907-aefb-ec7cb46dc4c5","sourceKey":"bank:ECO101:ECO-2239","payload":{"prompt":"Monthly rainfall in Lagos and a household's monthly cable TV subscription fee","options":["are linearly related.","are positively related.","are unrelated.","Both A and B are correct."],"correctOption":2,"section":"Methodology of Economics","explanation":"The cable TV fee is set by the provider and does not depend on how much it rains, so the two variables are unrelated; on a graph this would be a horizontal or vertical line. Options A, B and D all assume a link between the two that does not exist."}},{"itemId":"9046d6f1-f053-518e-b46e-70c60cdd5180","questionId":"8ebb1eb9-6605-50d9-b6d5-e061203f777a","sourceKey":"bank:ECO101:ECO-2240","payload":{"prompt":"When y changes, x stays the same. The line showing this relationship would be","options":["vertical.","horizontal.","straight with a negative slope.","straight with a positive slope."],"correctOption":0,"section":"Methodology of Economics","explanation":"With y on the vertical axis, if y changes but x does not, every point sits directly above the same x value, which forms a vertical line. Option B, a horizontal line, is the opposite case, where x changes but y stays the same."}},{"itemId":"5a0c7c51-cff9-5c5b-8a2e-3c38e7a2b5cc","questionId":"1c530485-880e-5d6b-8e0c-99b3133b877a","sourceKey":"bank:ECO101:ECO-2241","payload":{"prompt":"A graph measures y on the vertical axis and x on the horizontal axis. The line on the graph is horizontal. From this we know that","options":["the value of x never changes.","the value of y does not depend on the value of x.","the ratio of x to y is constant.","the slope is undefined because y never changes."],"correctOption":1,"section":"Methodology of Economics","explanation":"A horizontal line means y stays the same whatever value x takes, so y does not depend on x. Option A is wrong because x does change along a horizontal line, and option D is wrong because a horizontal line has a slope of zero, not an undefined slope."}},{"itemId":"8914842f-1683-59c2-921c-07ef191c8785","questionId":"ed6fb333-f6f7-55cd-8ce2-e3506fef8084","sourceKey":"bank:ECO101:ECO-2242","payload":{"prompt":"A graph measures y on the vertical axis and x on the horizontal axis. The line on the graph is vertical. From this we know that","options":["the value of x does not change when the value of y changes.","the value of y is constant.","the ratio of x to y is constant.","the ratio of y to x is constant."],"correctOption":0,"section":"Methodology of Economics","explanation":"Along a vertical line, x stays the same while y takes many different values, so x does not change when y changes. Option B describes a horizontal line, and options C and D are wrong because, with x fixed and y changing, neither ratio stays the same."}},{"itemId":"52e03b76-a0e2-568a-87c9-c7492dbba706","questionId":"a6bcb825-ec28-505b-ba70-c0da4d0bee6f","sourceKey":"bank:ECO101:ECO-2243","payload":{"prompt":"The graph of two variables, x and y, is a horizontal line. This shows that x and y are","options":["positively related.","negatively related.","not related.","falsely related."],"correctOption":2,"section":"Methodology of Economics","explanation":"A horizontal line means y stays the same no matter what happens to x, so the two variables are unrelated. Options A and B would need an upward-sloping or a downward-sloping line."}},{"itemId":"54093179-d80d-5c94-9c9e-2f0b706a9606","questionId":"1f764611-1c39-59d3-b7a1-0f4e1e5cf2de","sourceKey":"bank:ECO101:ECO-2244","payload":{"prompt":"On a graph, two variables that are unrelated (independent) are shown by","options":["an upward-sloping line.","a horizontal or a vertical line.","a downward-sloping line.","a steeply sloped line."],"correctOption":1,"section":"Methodology of Economics","explanation":"If one variable stays the same while the other changes, they are unrelated, and the graph is either horizontal (y stays the same) or vertical (x stays the same). Options A and C show positive and negative relationships, and option D still shows a relationship, just a strong one."}},{"itemId":"fd1f7be3-c864-5df5-98fb-9fc05d47e5cf","questionId":"0f9d2768-4ce1-5248-8f9d-87146fcf0fd0","sourceKey":"bank:ECO101:ECO-2245","payload":{"prompt":"A graph shows the price of a basket of tomatoes at Mile 12 market on the vertical axis and the number of new cars sold by a Lagos car dealer on the horizontal axis. The price of tomatoes stays the same as car sales increase. The graph of these data is","options":["a horizontal line.","a vertical line.","a curve with a maximum.","a positively sloped line."],"correctOption":0,"section":"Methodology of Economics","explanation":"The variable on the vertical axis (the price of tomatoes) stays the same while the variable on the horizontal axis (car sales) changes, so the graph is a horizontal line. Option B would need car sales to stay fixed while the price changes, and option D would need the price to rise as car sales rise."}},{"itemId":"a65478c5-3250-57fa-8fb8-40b9e6c7134a","questionId":"f7ac6243-199f-571c-adc9-d9ebab491170","sourceKey":"bank:ECO101:ECO-2247","payload":{"prompt":"The term \"direct relationship\" means the same as","options":["correlation.","trend.","positive relationship.","negative relationship."],"correctOption":2,"section":"Methodology of Economics","explanation":"A direct relationship is one in which the variables move in the same direction, which is exactly what a positive relationship means. Option D is the opposite, and option B describes how one variable moves over time, not how two variables are related."}},{"itemId":"b80238e4-1ee3-5026-a111-20ce145c9a5f","questionId":"680dbc24-2f97-56d9-86cf-eab08afd6a39","sourceKey":"bank:ECO101:ECO-2249","payload":{"prompt":"The slope of a line equals the","options":["change in the x-axis variable divided by the change in the y-axis variable.","change in the y-axis variable divided by the change in the x-axis variable.","change in the x-axis variable minus the change in the y-axis variable.","change in the x-axis variable multiplied by the change in the y-axis variable."],"correctOption":1,"section":"Methodology of Economics","explanation":"Slope is \"rise over run\": the change in the variable on the vertical (y) axis divided by the change in the variable on the horizontal (x) axis. Option A turns the ratio upside down, and options C and D use subtraction and multiplication instead of division."}},{"itemId":"24ae394b-fc4d-5560-a816-02f60504d9a0","questionId":"3e3cb212-d57b-5865-b1a1-d7e48d3b9c6c","sourceKey":"bank:ECO101:ECO-2251","payload":{"prompt":"The slope of the relationship between Y (on the vertical axis) and X (on the horizontal axis) is","options":["zero.","the change in Y divided by the starting value of X.","the change in Y divided by the change in X.","the percentage change in Y divided by the percentage change in X."],"correctOption":2,"section":"Methodology of Economics","explanation":"Slope = (change in Y) / (change in X), which measures how much Y changes for each one-unit change in X. Option D is tempting, but a ratio of percentage changes is an elasticity, not a slope, and option B divides by a level of X rather than a change in X."}},{"itemId":"f9b508f2-6237-513d-98f6-cd9f887b1b04","questionId":"39c14eef-37bb-5d46-88d8-94ad933619c4","sourceKey":"bank:ECO101:ECO-2256","payload":{"prompt":"If a large change in the x-axis variable goes with a small change in the y-axis variable, the line is ________ and the slope is ________.","options":["downward-sloping; large","downward-sloping; small","upward-sloping; small","either downward- or upward-sloping; small"],"correctOption":3,"section":"Methodology of Economics","explanation":"Slope = (change in y) / (change in x), and a small number divided by a large number gives a small slope (in absolute size). The information does not say whether y rises or falls, so the line could slope either way. Options B and C each pick just one direction, and option A gets the size of the slope wrong."}},{"itemId":"f5e3c4b1-4769-565c-bdbc-0d05bb08fb27","questionId":"9236f8e6-03af-559f-80b1-aeb841884834","sourceKey":"bank:ECO101:ECO-2257","payload":{"prompt":"y is measured on the vertical axis and x on the horizontal axis, and the relationship between them is a straight line. The slope of the line is positive but less than 1. This means that a change in x goes with","options":["a bigger change in y.","a smaller change in y.","no change in y.","an equal change in y."],"correctOption":1,"section":"Methodology of Economics","explanation":"A slope below 1 means (change in y) / (change in x) is less than 1, so y changes by less than x. For example, with a slope of 0.5, a 2-unit rise in x goes with only a 1-unit rise in y. Option A describes a slope greater than 1, and option D describes a slope of exactly 1."}},{"itemId":"daf150e5-c86a-5c19-99de-f73274f8da8e","questionId":"fe52177b-50c2-5333-b4ee-7bab5e5a21e8","sourceKey":"bank:ECO101:ECO-2259","payload":{"prompt":"y is measured on the vertical axis and x on the horizontal axis, and the relationship between them is a straight line. The slope of the line is greater than 1. This means that","options":["a change in x goes with a bigger change in y.","a change in x goes with a smaller change in y.","a change in x goes with no change in y.","a change in x goes with an equal change in y."],"correctOption":0,"section":"Methodology of Economics","explanation":"A slope above 1 means (change in y) / (change in x) is greater than 1, so y changes by more than x. With a slope of 3, for instance, a 1-unit change in x goes with a 3-unit change in y. Option B describes a slope between 0 and 1, and option D a slope of exactly 1."}},{"itemId":"b1bbc801-6ff9-5215-b7aa-93e6df7a4d19","questionId":"a00ad6ae-d99c-5c11-9a47-7871ba6850f1","sourceKey":"bank:ECO101:ECO-2261","payload":{"prompt":"On a graph, a line has a negative slope if","options":["the line is vertical.","the line is horizontal.","the line rises from right to left.","the line rises from left to right."],"correctOption":2,"section":"Methodology of Economics","explanation":"A negatively sloped line falls as you move from left to right, which is the same as saying it rises from right to left. Option D describes a positively sloped line, a horizontal line (option B) has a slope of zero, and a vertical line (option A) has an undefined slope."}},{"itemId":"695589dc-f169-501a-b4bd-aef4397a0022","questionId":"9d793672-66e3-5f12-8233-c057d23f99ff","sourceKey":"bank:ECO101:ECO-2263","payload":{"prompt":"If the slope of the relationship between saving and the interest rate is 0.5, then","options":["saving and the interest rate have a positive relationship.","saving and the interest rate have a negative relationship.","saving and the interest rate have no relationship.","saving and the interest rate have an inverse relationship."],"correctOption":0,"section":"Methodology of Economics","explanation":"Any positive slope, even a small one like 0.5, means the two variables move in the same direction, so the relationship is positive. Options B and D would need a negative slope, and option C would need a slope of zero (or a vertical line)."}},{"itemId":"cc1840d6-de7f-5ff9-b9b8-dea30934d9d4","questionId":"07d3a3a5-3a92-56af-8619-2b8bce7ee371","sourceKey":"bank:ECO101:ECO-2264","payload":{"prompt":"If x (on the horizontal axis) increases from 6 to 8 units and y (on the vertical axis) decreases from 4 to 3 units, the slope equals","options":["2.","-2.","1/2.","-1/2."],"correctOption":3,"section":"Methodology of Economics","explanation":"Slope = (change in y) / (change in x) = (3 - 4) / (8 - 6) = -1/2. Option B turns the ratio upside down (change in x divided by change in y), and option C forgets the minus sign, even though y falls as x rises."}},{"itemId":"64ab8b11-fe7d-59f3-aa70-50a1b992554d","questionId":"e3a7aa2d-db29-5179-8318-85006554c183","sourceKey":"bank:ECO101:ECO-2265","payload":{"prompt":"The slope of a straight line is","options":["variable.","increasing.","decreasing.","constant."],"correctOption":3,"section":"Methodology of Economics","explanation":"A straight line rises (or falls) by the same amount for every one-unit change in x, so its slope is the same everywhere along it. Options A, B and C describe curved lines, whose slope changes from point to point."}},{"itemId":"d19cdb4c-cf13-57db-9e36-aa84d0208fd6","questionId":"deda5c73-f789-5367-94af-7cec52c6a51a","sourceKey":"bank:ECO101:ECO-2269","payload":{"prompt":"The slope of a straight line is 3/4. When x equals 20, y equals 14. When x equals 32, y equals","options":["17.","23.","9.","26."],"correctOption":1,"section":"Methodology of Economics","explanation":"Change in y = slope x change in x = (3/4) x (32 - 20) = (3/4) x 12 = 9, so the new y = 14 + 9 = 23. Option C is just the change in y (9) rather than the new value of y, and option A adds only 3 to y, using the numerator of the slope instead of the full change."}},{"itemId":"8b909eb6-3c6f-5190-a983-03e0e3cae90b","questionId":"df8ae14a-af21-50d0-8f5f-655594c6b1b4","sourceKey":"bank:ECO101:ECO-2270","payload":{"prompt":"The slope of a straight line is 3. When x equals 10, y equals 33. When x equals 11, y equals","options":["27.","30.","36.","39."],"correctOption":2,"section":"Methodology of Economics","explanation":"x rises by 1, so y changes by slope x change in x = 3 x 1 = 3, giving y = 33 + 3 = 36. Option B subtracts instead of adds, which would only be right if the slope were -3, and options A and D use the wrong size of change."}},{"itemId":"5933cbaf-07a2-5596-bce0-a668a0937dcf","questionId":"94220b75-ee00-55fc-bbe3-a04046f6e8a3","sourceKey":"bank:ECO101:ECO-2271","payload":{"prompt":"Along a straight line, when x equals 90, y equals 30. When x equals 120, y equals 40. The slope of the line is","options":["1/3.","-1/3.","3.","-3."],"correctOption":0,"section":"Methodology of Economics","explanation":"Slope = (change in y) / (change in x) = (40 - 30) / (120 - 90) = 10 / 30 = 1/3. Option C turns the ratio upside down (change in x divided by change in y), and the negative options are wrong because y rises as x rises."}},{"itemId":"6c105c64-cee7-53ff-89dd-dd8c57e3988e","questionId":"58ed8249-35d0-5e27-823b-2afcbf54a23f","sourceKey":"bank:ECO101:ECO-2272","payload":{"prompt":"Along a straight line, y always equals x. The slope of the line is","options":["-1.","0.","1.","infinite."],"correctOption":2,"section":"Methodology of Economics","explanation":"If y always equals x, any change in x produces exactly the same change in y, so (change in y) / (change in x) = 1. Option B would be a horizontal line, option D a vertical line, and option A a line on which y falls as x rises."}},{"itemId":"8b9b0153-4a27-5cbb-87c1-5d053bb91140","questionId":"5e4295f6-8dc3-5da0-a1f8-605a2933605a","sourceKey":"bank:ECO101:ECO-2273","payload":{"prompt":"If the change in y is -4 and the change in x is 2, there is","options":["an independent relationship between y and x.","a positive relationship between y and x.","a negative relationship between y and x.","no relationship between y and x."],"correctOption":2,"section":"Methodology of Economics","explanation":"Slope = (change in y) / (change in x) = -4 / 2 = -2. A negative slope means y falls as x rises, which is a negative relationship. Option B would need both changes to have the same sign, and options A and D would need y to stay the same as x changes."}},{"itemId":"2e89ea47-17c5-5116-9032-9c3d56f249c8","questionId":"e691a92f-53ea-5c02-913e-6038a0f4c2a2","sourceKey":"bank:ECO101:ECO-2275","payload":{"prompt":"The change in y is -20 and the change in x is -4. There is therefore","options":["no relationship between y and x.","a negative relationship between y and x.","a positive relationship between y and x.","an independent relationship between y and x."],"correctOption":2,"section":"Methodology of Economics","explanation":"Slope = (change in y) / (change in x) = -20 / -4 = 5, which is positive. Both variables fell together, and moving in the same direction means a positive relationship. Option B is tempting because both numbers are negative, but a negative divided by a negative gives a positive slope."}},{"itemId":"11c57e7c-8e9e-5d5b-98eb-36f99d4eefe9","questionId":"a0faeace-17f4-5cb1-8e99-ee010f4ce98c","sourceKey":"bank:ECO101:ECO-2276","payload":{"prompt":"On a graph, an upward-sloping curve that gets flatter as you move away from the origin shows a","options":["positive relationship with an increasing slope.","positive relationship with a decreasing slope.","negative relationship with an increasing slope.","negative relationship with a decreasing slope."],"correctOption":1,"section":"Methodology of Economics","explanation":"Sloping upward means the relationship is positive, and getting flatter means the slope is getting smaller as you move along the curve. Option A would be a curve that gets steeper, and options C and D are ruled out because the curve slopes upward, not downward."}},{"itemId":"b4511ea6-a763-5581-81a7-c08a00af635d","questionId":"ff434bbf-18c6-51ae-94cd-1dbef39b336e","sourceKey":"bank:ECO101:ECO-2277","payload":{"prompt":"The price of oranges is on the vertical axis and the quantity of oranges demanded is on the horizontal axis. The slope between two points on the line linking price and quantity is","options":["the change in price multiplied by the change in quantity.","the change in price divided by the change in quantity.","the change in quantity divided by the change in price.","price divided by quantity."],"correctOption":1,"section":"Methodology of Economics","explanation":"Slope is always the change in the vertical-axis variable divided by the change in the horizontal-axis variable, so here it is (change in price) / (change in quantity). Option C turns the ratio upside down, and option D divides levels rather than changes."}},{"itemId":"467e2753-ad84-5564-9f56-e93ff53fea48","questionId":"2b2659db-e7dc-5ad8-b508-c8d98f00f8ec","sourceKey":"bank:ECO101:ECO-2278","payload":{"prompt":"The formula for the slope across an arc is used to approximate the slope of","options":["straight lines only.","a curved line.","positive relationships only.","negative relationships only."],"correctOption":1,"section":"Methodology of Economics","explanation":"A curve's slope changes from point to point, so we approximate it by calculating the slope of a straight line joining two points on the curve, which is the slope across an arc. A straight line (option A) does not need an approximation because its slope is constant, and the method works for both positive and negative relationships, which rules out options C and D."}},{"itemId":"3a91a106-0733-58dd-9264-2246b091ab02","questionId":"9bcb78f4-53ee-51a2-9e5c-7e6bd050b9c2","sourceKey":"bank:ECO101:ECO-2279","payload":{"prompt":"The slope of a curved line can be approximated by","options":["the average value of the y-axis variable divided by the average value of the x-axis variable.","the reciprocal of the slope of a straight line.","the average value of the x-axis variable divided by the average value of the y-axis variable.","the slope across an arc from one point on the curve to another."],"correctOption":3,"section":"Methodology of Economics","explanation":"We can approximate a curve's slope by taking two points on it and calculating (change in y) / (change in x) between them, which is the slope across an arc. Options A and C divide average levels rather than changes, so they do not measure slope at all."}},{"itemId":"588a0214-3796-54d8-92c1-accf0e0989da","questionId":"a36924a7-6156-5057-9ee8-fabf5f9261e9","sourceKey":"bank:ECO101:ECO-2281","payload":{"prompt":"A linear relationship","options":["always has a maximum.","always has a constant slope.","always slopes upward to the right.","never has a constant slope."],"correctOption":1,"section":"Methodology of Economics","explanation":"A linear relationship is drawn as a straight line, and a straight line has the same slope everywhere. Option C is wrong because a straight line can also slope downward, and option A is wrong because only curves that change direction have a maximum."}},{"itemId":"4ac5a1cf-8ad5-5f33-9d2b-7a672e000fa7","questionId":"7851ede1-29cd-5e8c-9704-992560e4cea6","sourceKey":"bank:ECO101:ECO-2283","payload":{"prompt":"When we study the relationship between x and y, ceteris paribus means that other variables","options":["are not relevant to x and y.","move in the opposite direction to x and y.","are not changing while x and y change.","move together with x and y."],"correctOption":2,"section":"Methodology of Economics","explanation":"Ceteris paribus means \"other things being equal\": we hold all other relevant variables constant so we can see the effect of x on y alone. Option A is wrong because those other variables may well matter; we simply keep them fixed. Options B and D describe the other variables changing, which is the opposite of ceteris paribus."}},{"itemId":"4b7ff29d-4c28-52c0-89de-3ba28b3063ae","questionId":"6fc992e1-19a3-53db-ac81-c513f2f9edb5","sourceKey":"bank:ECO101:ECO-2284","payload":{"prompt":"On a graph of the relationship between x and y, the ceteris paribus condition means that","options":["no other variables are related to x and y.","the value of x is held constant.","the value of y is held constant.","other variables not shown on the graph are held constant."],"correctOption":3,"section":"Methodology of Economics","explanation":"Ceteris paribus means all other influences that are not shown on the graph are kept fixed, so the graph shows only how x and y are related. Options B and C cannot be right because x and y are the variables allowed to change, and option A is wrong because other variables may matter but are being held constant."}},{"itemId":"39a2eef9-4428-5112-8837-f67ccd127121","questionId":"ddcfe5ac-9bcf-55a2-80cf-3f3a072a8c08","sourceKey":"bank:ECO101:ECO-2285","payload":{"prompt":"Suppose the quantity of suya bought depends on three things: the price of suya, buyers' income, and buyers' taste for suya. When we graph the relationship between the price of suya and the quantity bought,","options":["the price of suya and buyers' income are the only variables allowed to change.","the price of suya and the quantity bought are the only variables allowed to change.","buyers' taste for suya and buyers' income are the only variables allowed to change.","none of these is correct."],"correctOption":1,"section":"Methodology of Economics","explanation":"A two-dimensional graph shows only the two variables on its axes, here price and quantity, while income and taste are held constant under ceteris paribus. Option A wrongly lets income change, and option C lets the two background variables change while ignoring the two that are actually being graphed."}},{"itemId":"3ddda041-a3b5-5e22-be47-c40cfd4dc9f1","questionId":"4f779d27-1ef3-52e1-9b40-044cf7d624b0","sourceKey":"bank:ECO101:ECO-2286","payload":{"prompt":"To draw a relationship that involves several variables on a two-axis graph, ________ variable(s) are shown on the axes and allowed to change, while all the others are held constant under the ________ assumption.","options":["one; scarcity","two; ceteris paribus","three; marginal benefit","one; ceteris paribus"],"correctOption":1,"section":"Methodology of Economics","explanation":"A graph has two axes, so two variables are shown and allowed to change while all the others are held constant using the ceteris paribus (other things being equal) assumption. Option D names the right assumption but puts only one variable on the graph, which would not give a relationship to plot. Options A and C name assumptions that have nothing to do with holding other variables fixed."}},{"itemId":"1d391b5b-a486-512e-a0b1-a484277af27b","questionId":"1d196753-a956-55ef-8859-422d8e3afd29","sourceKey":"bank:ECO101:ECO-2287","payload":{"prompt":"Which of the following statements about the axes of a graph is correct?","options":["The vertical axis can only show positive values.","Both axes can show negative as well as positive values, depending on the variables measured.","Only the horizontal axis can show negative values.","Negative values can only be shown on a time-series graph."],"correctOption":1,"section":"Methodology of Economics","explanation":"Axes can be extended below and to the left of the origin, so either axis can show negative values, for example a negative profit or a negative growth rate. Option A is a common misconception, and options C and D are wrong because no type of graph or axis is limited to positive values."}},{"itemId":"07948b20-e4ad-5d2d-b206-bd0087142ee3","questionId":"17eac4cb-a147-5fb0-a21f-7adf48d5dd9c","sourceKey":"bank:ECO101:ECO-0082","payload":{"prompt":"When action of an individual imposes a direct cost or benefit on another individual, it is called.....","options":["positive externality","negative externality","externality","market imperfection"],"correctOption":2,"section":"Major Areas of Specialization in Economics","explanation":"An externality is a cost or benefit that one person's action imposes on others who are not part of the decision. Because the stem covers both costs and benefits, the general term is the best answer. Options A and B each cover only one side, benefits (positive) or costs (negative)."}},{"itemId":"64136605-4ecc-58ba-affb-161332bbe447","questionId":"5ae83a1b-a0e0-55a2-96cc-1b318b8837ad","sourceKey":"bank:ECO101:ECO-0083","payload":{"prompt":"When some products do not have market it is called","options":["missing market","asymmetric information","public goods","externality"],"correctOption":0,"section":"Major Areas of Specialization in Economics","explanation":"A missing market exists when there is no market for a good or service, so it cannot be bought or sold even though people value it. Option B, asymmetric information, is when one side knows more than the other. Options C and D are separate causes of market failure."}},{"itemId":"5dc99439-4fd4-5626-909c-2e185e831eb0","questionId":"f7b37f5a-8d6b-5012-b4c5-f3543cdf8aee","sourceKey":"bank:ECO101:ECO-0084","payload":{"prompt":"When one or more distortions disallow the market system from allowing efficient allocation, it is called.....","options":["missing market","imperfect market","externality","market failure"],"correctOption":3,"section":"Major Areas of Specialization in Economics","explanation":"Market failure is when the free market does not allocate resources efficiently, because of distortions such as externalities, public goods or monopoly power. Options A and C are particular causes of market failure, not the general name, and option B is a type of market structure."}},{"itemId":"e7ab0284-bfd8-5a34-b2ab-f67b7354fc08","questionId":"68bbdbe9-2f22-5dac-bb30-34a23a202c87","sourceKey":"bank:ECO101:ECO-0085","payload":{"prompt":"Market failure exists as a result of the following except....","options":["property right failure","externalities","public goods","private goods"],"correctOption":3,"section":"Major Areas of Specialization in Economics","explanation":"Private goods are rival and excludable, so markets supply them efficiently; they are not a cause of market failure. Options A, B and C, property right failure, externalities and public goods, are all standard causes of market failure."}},{"itemId":"924e61c9-515a-5ff5-83ba-2e4677cbcc18","questionId":"42fcd13e-6001-546c-98e8-59c2d7ebef99","sourceKey":"bank:ECO101:ECO-0472","payload":{"prompt":"A branch of economics devoted to determining the optimal allocation of resources in society?","options":["Micro economics","Welfare Economics","Behavioural economics","Positive economics"],"correctOption":1,"section":"Major Areas of Specialization in Economics","explanation":"Welfare economics studies how resources should be allocated to make society as well off as possible, focusing on efficiency and social welfare. Option A, microeconomics, is the broader study of individual units such as households and firms. Option D, positive economics, describes what is rather than what would be best for society."}},{"itemId":"d65e3ef0-2f9e-544b-bdc9-3fa336c8ddfe","questionId":"19108714-a67f-53dd-abb5-c67268892bec","sourceKey":"bank:ECO101:ECO-0497","payload":{"prompt":"A type of good which has negative externalities is a:","options":["Neutral good","Luxury good","Demerit good","Giffen good"],"correctOption":2,"section":"Major Areas of Specialization in Economics","explanation":"Demerit goods, such as cigarettes, are goods whose consumption creates negative externalities, harming people other than the consumer. Option B, luxury goods, are defined by their high income elasticity, not by harm to others. Option D, Giffen goods, are inferior goods with upward-sloping demand, which has nothing to do with externalities."}},{"itemId":"962dc7c2-c613-5f8c-93f1-cc0f3aecc7d3","questionId":"1ba9bd75-91d9-50e4-a795-88c02c943e53","sourceKey":"bank:ECO101:ECO-0521","payload":{"prompt":"________ occurs when the consumption or production of a good causes a benefit to a third party","options":["Social Benefit","Negative Externalities","Behavioural economics","Positive Externalities"],"correctOption":3,"section":"Major Areas of Specialization in Economics","explanation":"A positive externality is a benefit that spills over to a third party who is not directly involved in buying or selling, such as neighbours benefiting from someone else's vaccination. Option B, negative externalities, is the opposite case, where the third party bears a cost rather than receiving a benefit. Option A, social benefit, is the total benefit to society, including the private benefit to the user."}},{"itemId":"1cb62417-594e-5e2b-b823-8146bb3a1779","questionId":"7b8a3c65-81ce-5936-a9e0-efc506f2381a","sourceKey":"bank:ECO101:E101N1-001","payload":{"prompt":"Which area of specialization in economics is concerned with improving economic well-being and quality of life in developing countries through growth, poverty reduction, reduced inequality and good policy?","options":["Institutional economics","Energy and environmental economics","International economics","Development economics"],"correctOption":3,"section":"Major Areas of Specialization in Economics","explanation":"Development economics studies how poorer countries can raise living standards, looking at growth, poverty, inequality and the policies that tackle them. International economics also touches developing countries, but its focus is trade, investment and monetary relations between countries rather than improving quality of life within them."}},{"itemId":"8274c3d5-9c54-5d4c-a10d-3baf7ae6cc09","questionId":"1b33b708-95dc-542d-968f-dd9f58646398","sourceKey":"bank:ECO101:E101N1-002","payload":{"prompt":"The branch of economics that studies economic interactions between countries, such as trade, investment and monetary relations, is","options":["development economics","institutional economics","international economics","welfare economics"],"correctOption":2,"section":"Major Areas of Specialization in Economics","explanation":"International economics deals with how countries interact economically, covering trade flows, cross-border investment and exchange-rate and monetary relations. Development economics may discuss foreign aid and trade policy, but its central concern is raising living standards in developing countries."}},{"itemId":"9cc02892-a257-54d0-a4a4-5078a077853e","questionId":"623ef467-c4d8-5441-88bd-f586669734f2","sourceKey":"bank:ECO101:E101N1-003","payload":{"prompt":"A researcher at UNILAG studies how energy use, climate change and the management of natural resources affect, and are affected by, economic activity. Her field is","options":["institutional economics","development economics","energy and environmental economics","international economics"],"correctOption":2,"section":"Major Areas of Specialization in Economics","explanation":"Energy and environmental economics examines the relationship between economic activity and the environment, including energy use, climate change and sustainable resource management. Development economics does include sustainable development as one concern, but a study centred on energy, climate and resources belongs to energy and environmental economics."}},{"itemId":"828a9810-f6a7-5e1e-b8d3-250b1076f795","questionId":"284c8565-aba5-5f24-9834-d281880a4764","sourceKey":"bank:ECO101:E101N1-004","payload":{"prompt":"Institutional economics studies the role of institutions in shaping economic behaviour and outcomes. In this field, institutions include","options":["formal rules such as laws and informal rules such as norms and culture","only formal written laws passed by the legislature","only government ministries and parastatals","only banks and other financial intermediaries"],"correctOption":0,"section":"Major Areas of Specialization in Economics","explanation":"Institutional economics treats institutions as the rules of the game, both formal rules like laws and regulations and informal rules like norms and culture. Restricting institutions to formal written laws leaves out the informal norms that the field regards as equally important in shaping behaviour."}},{"itemId":"123531d3-a344-54b8-bf45-7f5fbf934105","questionId":"00c18d49-ae86-52b6-a197-f3f776b52f35","sourceKey":"bank:ECO101:E101N1-006","payload":{"prompt":"Which theory of development holds that societies move along a linear path of progress from a traditional stage to a modern stage?","options":["Neoliberalism","Dependency theory","Modernization theory","Endogenous growth theory"],"correctOption":2,"section":"Major Areas of Specialization in Economics","explanation":"Modernization theory sees development as linear progress in which traditional societies gradually become modern ones. Dependency theory takes the opposite view, blaming underdevelopment on poor countries' historical dependence on rich nations."}},{"itemId":"13fc6609-f591-51d4-bdec-1673f8de1878","questionId":"a546ce50-ebcd-5014-ae79-c7c55ea955d5","sourceKey":"bank:ECO101:E101N1-007","payload":{"prompt":"A scholar argues that Nigeria's underdevelopment is largely the result of its historical dependence on rich industrialised nations. This view is associated with","options":["the Heckscher-Ohlin theory","dependency theory","modernization theory","neoliberalism"],"correctOption":1,"section":"Major Areas of Specialization in Economics","explanation":"Dependency theory explains underdevelopment as the outcome of poor countries' historical dependence on rich nations. Modernization theory instead treats underdevelopment as an early stage on a linear path towards becoming a modern society."}},{"itemId":"e26be4d9-1e43-59fe-9122-7f3c2b784143","questionId":"c29a4461-949a-56c7-b749-e7a2571568a7","sourceKey":"bank:ECO101:E101N1-008","payload":{"prompt":"A development economist recommends free markets, deregulation and the privatization of state-owned enterprises as the route to growth. This position is known as","options":["institutional change theory","modernization theory","neoliberalism","dependency theory"],"correctOption":2,"section":"Major Areas of Specialization in Economics","explanation":"Neoliberalism is the development theory that stresses free markets, deregulation and privatization. Modernization theory describes a path from traditional to modern society; it is not defined by a policy package of deregulation and privatization."}},{"itemId":"46bef20d-3141-5563-a7b4-1926686939bb","questionId":"39a0edec-ed0d-53cb-b833-b63d05115b48","sourceKey":"bank:ECO101:E101N1-009","payload":{"prompt":"Which growth theory emphasises human capital and innovation as the main drivers of economic growth?","options":["Environmental Kuznets Curve","Dependency theory","Modernization theory","Endogenous growth theory"],"correctOption":3,"section":"Major Areas of Specialization in Economics","explanation":"Endogenous growth theory explains growth through human capital and innovation generated within the economy. The Environmental Kuznets Curve is about the link between growth and environmental damage, not about what drives growth."}},{"itemId":"4794cb2e-6fc9-54ca-b0ea-c49b4e782889","questionId":"dd2822c8-99b2-5d3c-8781-917870bfa3fc","sourceKey":"bank:ECO101:E101N1-010","payload":{"prompt":"Within development economics, economic growth is described as","options":["sufficient on its own to guarantee development","the same thing as human development","necessary but not sufficient for development","neither necessary nor useful for development"],"correctOption":2,"section":"Major Areas of Specialization in Economics","explanation":"Development economics treats growth as necessary for development but not enough on its own, because poverty, inequality, education and health also matter. Saying growth alone guarantees development ignores these other dimensions that the field studies."}},{"itemId":"1c391f40-3444-55c6-b321-246c4913da40","questionId":"65ae8902-cd1f-5126-bc61-26bb49b000b4","sourceKey":"bank:ECO101:E101N1-011","payload":{"prompt":"A development economist studying Nigeria looks beyond GDP to measure progress in education and health. This focus is called","options":["capital accumulation","human development","transaction costs","balance of payments"],"correctOption":1,"section":"Major Areas of Specialization in Economics","explanation":"Human development is the focus on education and health as measures of well-being beyond GDP. Capital accumulation is a driver of economic growth, not a measure of people's education and health."}},{"itemId":"9428eaff-f8f7-5df5-9e6a-dd73c6046e23","questionId":"5075b21a-6db9-5855-b175-e54db254b3bd","sourceKey":"bank:ECO101:E101N1-012","payload":{"prompt":"A development economist evaluates the effect of microfinance, rural roads and social safety nets on poverty in Kano. These are examples of","options":["externalities","terms of trade","policy interventions","property rights"],"correctOption":2,"section":"Major Areas of Specialization in Economics","explanation":"Policy interventions in development economics include action by government, foreign aid and international organizations, such as microfinance, infrastructure and safety nets. Externalities are side-effects of production or consumption on third parties, not policy tools."}},{"itemId":"5b69c5aa-0d80-55d9-8a79-a3ae228bc5b6","questionId":"e21de5d2-9b68-5814-82f0-b74ff1543445","sourceKey":"bank:ECO101:E101N1-013","payload":{"prompt":"The theory that a country should specialize in producing goods in which its opportunity cost is lower, so that all trading partners gain, is the","options":["Coase theorem","Ricardian theory of comparative advantage","Heckscher-Ohlin theory","dependency theory"],"correctOption":1,"section":"Major Areas of Specialization in Economics","explanation":"Ricardian comparative advantage says countries should specialize where their opportunity cost is lower, which produces mutual gains from trade. The Heckscher-Ohlin theory also deals with trade, but it explains comparative advantage through differences in factor endowments."}},{"itemId":"c4ac1658-fac2-53ac-b145-a4fb35af0bb7","questionId":"43420bfb-9083-5d0e-9a14-892230824d75","sourceKey":"bank:ECO101:E101N1-014","payload":{"prompt":"According to the Heckscher-Ohlin theory, a country's comparative advantage is determined by","options":["the strength of its formal and informal institutions","the rate at which its population grows","the level of its interest rates and exchange rates","its endowments of factors such as land, labour and capital"],"correctOption":3,"section":"Major Areas of Specialization in Economics","explanation":"The Heckscher-Ohlin theory holds that relative endowments of land, labour and capital decide what a country produces most cheaply and therefore exports. Interest rates and exchange rates are the concern of monetary theories of international economics, not Heckscher-Ohlin."}},{"itemId":"7240c7ab-d32f-5af6-af42-de36379c8f4b","questionId":"22a84a53-fb07-5ff1-99a2-112dec90aeda","sourceKey":"bank:ECO101:E101N1-015","payload":{"prompt":"Which of the following is NOT one of the key theories of international economics?","options":["Dependency theory","Ricardian comparative advantage","Monetary theories of exchange rates","Heckscher-Ohlin theory"],"correctOption":0,"section":"Major Areas of Specialization in Economics","explanation":"Dependency theory is a theory of development economics that blames underdevelopment on dependence on rich nations. Ricardian comparative advantage, Heckscher-Ohlin and monetary theories of exchange rates, interest rates and monetary policy are the three theories of international economics."}},{"itemId":"0a9302f1-47f4-5b63-852a-4f4903719372","questionId":"80d04272-1cad-5a8a-b322-fda4a1bd44b0","sourceKey":"bank:ECO101:E101N1-016","payload":{"prompt":"The record of all economic transactions between residents of a country and the rest of the world over a period is the","options":["balance of trade","terms of trade","foreign direct investment","balance of payments"],"correctOption":3,"section":"Major Areas of Specialization in Economics","explanation":"The balance of payments records all transactions with the rest of the world. The balance of trade is narrower: it covers only visible exports minus visible imports."}},{"itemId":"e93f6ca5-13e9-57fa-a983-b8645ef35b1a","questionId":"867023b0-fa2e-5dfa-9793-4663701c8e9c","sourceKey":"bank:ECO101:E101N1-017","payload":{"prompt":"In a given year, Nigeria's index of export prices is 120 and its index of import prices is 150. What are its terms of trade?","options":["125","80","30","270"],"correctOption":1,"section":"Major Areas of Specialization in Economics","explanation":"Terms of trade = (index of export prices / index of import prices) x 100 = (120 / 150) x 100 = 80. The figure 125 comes from dividing import prices by export prices, which turns the formula upside down."}},{"itemId":"7b0d004f-7b32-5824-8075-f78a390a2d79","questionId":"2023a4f5-ff1c-580f-9a55-d36704286161","sourceKey":"bank:ECO101:E101N1-018","payload":{"prompt":"In a year, a country's visible exports are worth N8 trillion and its visible imports are worth N10 trillion. Its balance of trade is","options":["a surplus of N2 trillion","a deficit of N2 trillion","a surplus of N18 trillion","a deficit of N18 trillion"],"correctOption":1,"section":"Major Areas of Specialization in Economics","explanation":"Balance of trade = visible exports - visible imports = N8 trillion - N10 trillion = -N2 trillion, so it is a deficit. Calling it a surplus of N2 trillion subtracts in the wrong order."}},{"itemId":"24c40d4f-1c23-5be7-a864-106acd3f5c07","questionId":"e21e0c9c-3183-511d-8330-0f4b9164c6e2","sourceKey":"bank:ECO101:E101N1-019","payload":{"prompt":"The Federal Government places a tax on imported rice entering Nigeria. This tax is called","options":["a tariff","dumping","a subsidy","a quota"],"correctOption":0,"section":"Major Areas of Specialization in Economics","explanation":"A tariff is a tax on imports, and it raises the price of imported goods. A quota also restricts imports, but it does so by limiting the quantity allowed in, not by taxing it."}},{"itemId":"284637c8-fae9-5c13-9f1a-77e1102a1d9d","questionId":"e7c4adcb-afda-58a1-b225-74cc096cf645","sourceKey":"bank:ECO101:E101N1-020","payload":{"prompt":"A foreign steel maker sells its steel in Nigeria at a price below the price it charges in its own home market. This practice is called","options":["comparative advantage","a tariff","a quota","dumping"],"correctOption":3,"section":"Major Areas of Specialization in Economics","explanation":"Dumping means selling goods abroad below the domestic price. A tariff is a tax on imports, which is a measure a country might use against dumping, not the practice itself."}},{"itemId":"6b6c8b7e-f387-5d76-816a-2089f0f0c5e5","questionId":"c5188940-2c80-5bc6-b990-9e6b38ae5972","sourceKey":"bank:ECO101:E101N1-021","payload":{"prompt":"Nigeria can produce a tonne of cocoa using fewer resources than Ghana. Nigeria is therefore said to have","options":["an absolute advantage in cocoa","a comparative advantage in cocoa","favourable terms of trade in cocoa","a balance of trade surplus in cocoa"],"correctOption":0,"section":"Major Areas of Specialization in Economics","explanation":"Absolute advantage means producing a good with fewer resources than another country. Comparative advantage is a different idea that depends on having the lower opportunity cost, and it cannot be judged from resource use alone."}},{"itemId":"d571941c-443f-5195-bcc3-f3ca941ada62","questionId":"63516813-b88d-50f8-b01f-33ecd111936b","sourceKey":"bank:ECO101:E101N1-022","payload":{"prompt":"In Nigeria, producing one bale of cloth costs 2 bags of cocoa in forgone output, while in Ghana it costs 4 bags of cocoa. Which statement is correct?","options":["Nigeria has a comparative advantage in cloth","Neither country can gain from trade","Nigeria has a comparative advantage in both goods","Ghana has a comparative advantage in cloth"],"correctOption":0,"section":"Major Areas of Specialization in Economics","explanation":"Comparative advantage goes to the producer with the lower opportunity cost: cloth costs Nigeria 2 bags of cocoa but costs Ghana 4, so Nigeria has the comparative advantage in cloth. Ghana, in turn, has the lower opportunity cost of cocoa (1/4 bale of cloth against Nigeria's 1/2), so no country can hold a comparative advantage in both goods."}},{"itemId":"20fda0c1-1aca-5f4e-ae6c-096e049304af","questionId":"e18d9eed-3a4a-5048-882f-5f75be44f06e","sourceKey":"bank:ECO101:E101N1-023","payload":{"prompt":"Under the Environmental Kuznets Curve, as a country's economy grows, environmental degradation","options":["falls steadily from the start","stays constant at all income levels","rises steadily without limit","rises up to a point and then falls"],"correctOption":3,"section":"Major Areas of Specialization in Economics","explanation":"The Environmental Kuznets Curve says degradation rises with growth up to a point and then falls, giving an inverted-U shape. Saying it rises without limit ignores the turning point that defines the curve."}},{"itemId":"6e0a8de6-b619-50af-a316-69cf9be5c328","questionId":"bfef7ebb-f8ca-50e2-951c-019ecced8e53","sourceKey":"bank:ECO101:E101N1-024","payload":{"prompt":"The Coase theorem states that private bargaining between parties will produce an efficient outcome when","options":["the government imposes a corrective tax","property rights are unclear and transaction costs are high","property rights are clear and transaction costs are low","the market is controlled by a single seller"],"correctOption":2,"section":"Major Areas of Specialization in Economics","explanation":"The Coase theorem says private bargaining leads to efficient outcomes provided property rights are clearly defined and transaction costs are low. A corrective tax is a government remedy for externalities, which is the alternative to private bargaining rather than its condition."}},{"itemId":"12e7b308-064a-5205-8385-1fe56e624fa7","questionId":"34b9dbd9-59cc-5e50-a5a4-174e9518c700","sourceKey":"bank:ECO101:E101N1-025","payload":{"prompt":"A cement factory in Ewekoro pollutes nearby farms. Which of the following would NOT help internalize this externality?","options":["A subsidy for cleaner production methods","A tax on each tonne of pollution","A system of tradable emissions permits","A price ceiling on cement"],"correctOption":3,"section":"Major Areas of Specialization in Economics","explanation":"A price ceiling on cement controls its selling price but does nothing to make the factory bear the cost of its pollution. Taxes, subsidies and emissions trading are the tools used to internalize externalities such as pollution."}},{"itemId":"7e6b9a2a-bd1f-5f66-a11b-970f28e3339e","questionId":"43e3e474-99e2-5f14-8412-f64e46b4eeda","sourceKey":"bank:ECO101:E101N1-026","payload":{"prompt":"A policy that sets a limit on total carbon emissions and allows firms to buy and sell emission permits is called","options":["cap-and-trade","a quota on imports","a tariff","a Pigovian subsidy"],"correctOption":0,"section":"Major Areas of Specialization in Economics","explanation":"Cap-and-trade sets a ceiling on total emissions and lets firms trade permits, and it is one of the climate-change policies studied in energy and environmental economics. A tariff is a tax on imports and has nothing to do with emission permits."}},{"itemId":"ad06317c-5c90-5834-8909-7cc277e4e9db","questionId":"ac2f4424-f2bf-51d7-97ef-d55dcc338172","sourceKey":"bank:ECO101:E101N1-027","payload":{"prompt":"Which of the following is an example of a renewable resource?","options":["Tin ore","Limestone deposits","Forests","Gold reserves"],"correctOption":2,"section":"Major Areas of Specialization in Economics","explanation":"Renewable resources such as forests and fisheries can regenerate if managed well. Tin ore, limestone and gold are minerals, which are non-renewable because once extracted they are not replaced."}},{"itemId":"6eb355d4-d65f-5f22-9604-a6906ad59e53","questionId":"eabd2dfc-d633-5023-adae-d101a04e5d1c","sourceKey":"bank:ECO101:E101N1-028","payload":{"prompt":"Which of the following is NOT a type of transaction cost studied in institutional economics?","options":["Enforcement costs","Depreciation of machinery","Search costs","Negotiation costs"],"correctOption":1,"section":"Major Areas of Specialization in Economics","explanation":"Depreciation is the wearing out of capital equipment in production, not a cost of carrying out an exchange. Transaction costs are the costs of searching for partners, negotiating deals and enforcing agreements."}},{"itemId":"c14f186a-a04a-5da4-8c78-ac477425fe67","questionId":"08b74ab4-4d29-54fb-b7c1-6d5687f3ee2b","sourceKey":"bank:ECO101:E101N1-029","payload":{"prompt":"In institutional economics, which of the following is an example of an informal institution?","options":["A Lagos State tax law","Cultural norms about how traders settle debts","A Central Bank of Nigeria regulation","The Companies and Allied Matters Act"],"correctOption":1,"section":"Major Areas of Specialization in Economics","explanation":"Informal institutions are unwritten rules such as norms and culture, so customs about settling debts among traders fit this category. An Act, a regulation or a tax law are formal rules backed by the state."}},{"itemId":"244b9c90-7c39-5f14-b370-3e5893db169b","questionId":"dbb3ab62-a090-5d0d-bb76-c8de15d63696","sourceKey":"bank:ECO101:E101N1-030","payload":{"prompt":"Path dependence, the idea that past choices shape how institutions develop, belongs to","options":["modernization theory","theories of institutional change","the Heckscher-Ohlin theory","the Environmental Kuznets Curve"],"correctOption":1,"section":"Major Areas of Specialization in Economics","explanation":"Theories of institutional change, including path dependence, explain how institutions evolve and why past decisions constrain present ones. The Heckscher-Ohlin theory is about trade and factor endowments, not institutions."}},{"itemId":"efb71e42-2fe8-50d5-b21b-ea477678676f","questionId":"41a76e1a-1d6d-5b89-adc2-431a52567962","sourceKey":"bank:ECO101:E101N1-031","payload":{"prompt":"An economist studies how corruption, weak property rights and information asymmetry affect how markets work in Nigeria. She is working mainly in","options":["institutional economics","development economics","international economics","energy and environmental economics"],"correctOption":0,"section":"Major Areas of Specialization in Economics","explanation":"Property rights, market functioning (including information asymmetry), and governance and corruption are key areas of institutional economics. Development economics is also concerned with poor countries, but these specific topics are the core of the institutional field."}},{"itemId":"ad97b232-cb44-59e6-84b5-85d445ceecdf","questionId":"14515432-5bd8-59a1-952e-43ccf81f5a48","sourceKey":"bank:ECO101:E101N1-032","payload":{"prompt":"A Lagos company automatically enrols new staff in a savings scheme unless they choose to opt out, which raises saving. This is an example of","options":["nudging in behavioural economics","path dependence in institutional economics","comparative advantage in international economics","a Pigovian tax in welfare economics"],"correctOption":0,"section":"Major Areas of Specialization in Economics","explanation":"Behavioural economics combines psychology and economics, and nudging, such as automatic enrolment in savings, gently steers choices without forcing them. A Pigovian tax changes behaviour by raising costs on harmful activities, which is quite different from changing the default option."}},{"itemId":"c9814f8f-8f1e-5996-acbf-3def09e1dbd3","questionId":"1274bae4-ae2e-5464-be53-93d40b306bb1","sourceKey":"bank:ECO101:E101N1-033","payload":{"prompt":"Which of the following is NOT one of the behavioural biases studied in behavioural economics?","options":["Present bias","Herd behaviour","Loss aversion","Comparative advantage"],"correctOption":3,"section":"Major Areas of Specialization in Economics","explanation":"Comparative advantage is a principle of international trade about lower opportunity cost, not a psychological bias. Loss aversion, the endowment effect, present bias and herd behaviour are the biases behavioural economics examines."}},{"itemId":"7fada652-d0f8-5e0e-a950-5dfbf7dda017","questionId":"03c75dfb-70e3-5b3a-8827-b3add8265ae2","sourceKey":"bank:ECO101:ECO-0050","payload":{"prompt":"Diamond is non essential to life and yet command a great price while air is essential to life but has no economic price to a great extent, this is","options":["Paradox of gift of nature","paradox of value","paradox of goods","None of the above"],"correctOption":1,"section":"Historical Development of Economic Thought","explanation":"The paradox of value (the diamond-water paradox) is the puzzle that essential things like air or water are cheap while non-essentials like diamonds are expensive. It is explained by scarcity and marginal utility: diamonds are scarce, so the last unit is highly valued. Options A and C are not recognised names for this idea."}},{"itemId":"c31d22d7-0ff9-5b74-beca-f8e19a08c6ea","questionId":"c56873e7-6d6e-5e14-a5b5-b467909bc61d","sourceKey":"bank:ECO101:ECO-0073","payload":{"prompt":"The following are the early classical theories of income distribution except","options":["marginal productivity theory","subsistence theory","wages fund theory","residual claimant theory"],"correctOption":0,"section":"Historical Development of Economic Thought","explanation":"Marginal productivity theory came later, from the neoclassical economists, who explained factor payments by the value of what the last unit of a factor adds to output. Option B (subsistence theory) and option C (wages fund theory) are early classical theories of wages. Option D, the residual claimant theory, is also an older theory than marginal productivity."}},{"itemId":"9bc219b6-2331-5311-8617-84460e629f01","questionId":"d5116abd-94af-52a7-b75e-d7ff9b10e44d","sourceKey":"bank:ECO101:ECO-0081","payload":{"prompt":"A resource allocation from which it is impossible to move to another allocation that makes some people better off without making anybody worse off is termed","options":["Pareto optimality","Arrow's impossibility theory","equity","perfect market"],"correctOption":0,"section":"Historical Development of Economic Thought","explanation":"Pareto optimality is a situation where it is impossible to make someone better off without making someone else worse off. Option B, Arrow's impossibility theorem, is about combining individual preferences into social choices. Option C, equity, is about fairness, not efficiency."}},{"itemId":"f4206a1f-24cb-52ea-9e0f-9a3c276083da","questionId":"7d9bde26-a967-56f4-95fc-38344fd9fb49","sourceKey":"bank:ECO101:ECO-0498","payload":{"prompt":"When there is an optimal distribution of goods and services, taking into account consumers' preferences, this is known as:","options":["Full utilisation","Effectiveness","Allocative efficiency","All of the above"],"correctOption":2,"section":"Historical Development of Economic Thought","explanation":"Allocative efficiency occurs when resources produce the mix of goods and services that consumers value most, so output matches consumer preferences (where price equals marginal cost). Option A, full utilisation, only means all resources are employed, which can still produce the wrong mix of goods. Option B, effectiveness, is a general word, so option D, all of the above, is also wrong."}},{"itemId":"dfdb8639-d4b4-5bde-bbfe-a042214bd967","questionId":"ca26496c-4578-5b62-80b4-880af395282f","sourceKey":"bank:ECO101:ECO-0683","payload":{"prompt":"The book 'Principles of Economics' (1890) was written by:","options":["J.M. Keynes","Alfred Marshall","Paul Samuelson","A.C. Pigou"],"correctOption":1,"section":"Historical Development of Economic Thought","explanation":"Alfred Marshall wrote Principles of Economics, which introduced ideas such as partial equilibrium and gave the welfare definition of economics. Option A, Keynes, wrote The General Theory of Employment, Interest and Money, and D, Pigou, was Marshall's student."}},{"itemId":"057f159b-fac9-58f0-a123-b552c26d9ec9","questionId":"a41af5fe-4e35-5d33-bbd9-030b3932e3ff","sourceKey":"bank:ECO101:ECO-0781","payload":{"prompt":"Who is widely known as the father of economics?","options":["Alfred Marshall","David Ricardo","Adam Smith","J.M. Keynes"],"correctOption":2,"section":"Historical Development of Economic Thought","explanation":"Adam Smith is called the father of economics because his book The Wealth of Nations (1776) laid the foundation of economics as a separate discipline. Ricardo (B) and Marshall (A) built on classical ideas later, and Keynes (D) is regarded as the father of modern macroeconomics."}},{"itemId":"c7197647-c0b0-56f2-8d75-1d13995ae45d","questionId":"e67c2a1c-3ccd-5d27-a8dc-94f0e4c72695","sourceKey":"bank:ECO101:ECO-0782","payload":{"prompt":"The Wealth of Nations was written by:","options":["Alfred Marshall","J.S. Mill","Adam Smith","Lionel Robbins"],"correctOption":2,"section":"Historical Development of Economic Thought","explanation":"Adam Smith wrote An Inquiry into the Nature and Causes of the Wealth of Nations, the classic work that explained the division of labour and the 'invisible hand' of the market. Marshall (A) is known for Principles of Economics, and Robbins (D) for the scarcity definition of economics."}},{"itemId":"aa372d62-f1e1-5414-841b-cd9e7a687925","questionId":"8084f64a-a0bb-5079-b727-4e47a231b458","sourceKey":"bank:ECO101:E101N1-034","payload":{"prompt":"Classical economics developed in the late 18th and early 19th centuries largely as a reaction to","options":["neoclassical marginalism","Keynesian demand management","mercantilism and feudal systems","utilitarian cost-benefit analysis"],"correctOption":2,"section":"Historical Development of Economic Thought","explanation":"Classical economics arose in the late 18th and early 19th centuries as a reaction to mercantilism and feudal systems. Neoclassical marginalism came later, in the late 19th century, as a refinement of classical ideas, so classical thought could not have been reacting to it."}},{"itemId":"06334da7-d218-549c-adb5-3be286701d26","questionId":"ad0342a6-d966-5360-b525-cdb6f736f293","sourceKey":"bank:ECO101:E101N1-035","payload":{"prompt":"Which of the following economists is NOT usually grouped with the classical school?","options":["David Ricardo","Adam Smith","Thomas Malthus","Leon Walras"],"correctOption":3,"section":"Historical Development of Economic Thought","explanation":"Leon Walras was a neoclassical economist of the late 19th century, best known for general equilibrium theory. Adam Smith, David Ricardo and Thomas Malthus are the leading classical economists."}},{"itemId":"9a9c3dfd-8ad5-5a87-8d2b-0db80fffbb1d","questionId":"1489abb8-f822-5c85-afda-6aa56ca0adbf","sourceKey":"bank:ECO101:E101N1-036","payload":{"prompt":"Which of the following did classical economists emphasise?","options":["Extensive state control of prices and output","Marginal utility as the only basis of value","Simultaneous equilibrium across all markets","Free markets that regulate themselves with limited government"],"correctOption":3,"section":"Historical Development of Economic Thought","explanation":"Classical economists stressed free markets, self-regulation, a natural tendency towards equilibrium and limited government. Simultaneous equilibrium across all markets is Walras's general equilibrium idea from the neoclassical period."}},{"itemId":"e4e44e54-2b13-58f4-b401-f5c415841cc4","questionId":"515bfd8b-c728-5a5f-addd-3fceac24e75f","sourceKey":"bank:ECO101:E101N1-037","payload":{"prompt":"The classical idea that the value of a good is determined by the amount of labour required to produce it is the","options":["labour theory of value","theory of marginal utility","theory of rent","principle of utility"],"correctOption":0,"section":"Historical Development of Economic Thought","explanation":"The labour theory of value holds that a good's value is set by the labour needed to produce it, and it is a core classical idea. Marginal utility theory came later with the neoclassical school, which located value in the extra satisfaction from the last unit."}},{"itemId":"320f7e7e-92c3-5e78-baaf-731f6a1299b7","questionId":"81cbe84c-0e87-5d37-b10b-88120b5bc622","sourceKey":"bank:ECO101:E101N1-038","payload":{"prompt":"The idea that individuals pursuing their own self-interest in free markets are guided, as if by an unseen force, to promote the good of society is the","options":["invisible hand, associated with Adam Smith","general equilibrium theory of Leon Walras","invisible hand, associated with David Ricardo","greatest happiness principle of Jeremy Bentham"],"correctOption":0,"section":"Historical Development of Economic Thought","explanation":"The invisible hand is Adam Smith's idea that self-interested behaviour in free markets ends up serving society. Bentham's greatest happiness principle is a utilitarian rule about maximizing happiness for the greatest number, not about market coordination."}},{"itemId":"566905ee-a6d4-5fca-ac78-160f6f01431e","questionId":"4a6b7471-f621-5659-8b9a-02fb5f690656","sourceKey":"bank:ECO101:E101N1-039","payload":{"prompt":"A shoe factory in Ikeja splits production so that one worker cuts leather, another stitches and a third fixes soles, and output per worker rises sharply. This illustrates Adam Smith's idea of","options":["marginalism","the labour theory of value","comparative advantage","division of labour"],"correctOption":3,"section":"Historical Development of Economic Thought","explanation":"Division of labour, emphasised by Adam Smith, means breaking production into specialised tasks so that productivity rises. Comparative advantage is Ricardo's idea about specialization between countries according to opportunity cost, not between workers within a factory."}},{"itemId":"ac4d654b-4fa7-512a-95e9-49351bac4565","questionId":"deb01318-575c-562f-ab41-607259d914a6","sourceKey":"bank:ECO101:E101N1-040","payload":{"prompt":"In what year was Adam Smith's An Inquiry into the Nature and Causes of the Wealth of Nations published?","options":["1776","1817","1890","1798"],"correctOption":0,"section":"Historical Development of Economic Thought","explanation":"The Wealth of Nations appeared in 1776. The year 1817 is when Ricardo published Principles of Political Economy and Taxation, and 1798 is the year of Malthus's Essay on the Principle of Population."}},{"itemId":"036a2b52-94f1-50c7-a532-9ec9f743063c","questionId":"184d674e-652e-54e5-98f5-173f97d9c8a8","sourceKey":"bank:ECO101:E101N1-041","payload":{"prompt":"Under Adam Smith's idea of laissez-faire, the role of government should be","options":["expanded to owning the major industries","limited to functions such as defence and infrastructure","focused on redistributing all income equally","extended to fixing the prices of all goods"],"correctOption":1,"section":"Historical Development of Economic Thought","explanation":"Laissez-faire means leaving markets largely free, with government limited to tasks like defence and infrastructure. Fixing prices or owning major industries would be heavy state intervention, the opposite of laissez-faire."}},{"itemId":"fd130ac9-28f0-54a0-aed0-c33e1a2535f0","questionId":"003a4d04-5073-5e9c-9615-28d3b1c96f8b","sourceKey":"bank:ECO101:E101N1-042","payload":{"prompt":"Principles of Political Economy and Taxation (1817) was written by","options":["David Ricardo","Adam Smith","Alfred Marshall","Thomas Malthus"],"correctOption":0,"section":"Historical Development of Economic Thought","explanation":"David Ricardo wrote Principles of Political Economy and Taxation in 1817. Alfred Marshall wrote a book with a similar-sounding title, Principles of Economics, but that appeared in 1890."}},{"itemId":"cc343e4c-dbb2-5196-b31a-2e96749e4980","questionId":"0cbc9ef1-7d02-5f3e-b8be-305391516c15","sourceKey":"bank:ECO101:E101N1-043","payload":{"prompt":"David Ricardo argued that two countries can both gain from trade by specializing in what they produce relatively more efficiently","options":["only if the government fixes the exchange rate","only if both countries have identical factor endowments","even if one country is less efficient in producing all goods","only if each country is more efficient in at least one good"],"correctOption":2,"section":"Historical Development of Economic Thought","explanation":"Ricardo's comparative advantage shows that trade benefits both countries even when one is less efficient at producing everything, because what matters is relative efficiency. Requiring each country to be more efficient in at least one good confuses comparative advantage with absolute advantage."}},{"itemId":"5372c65d-6375-50cd-858a-23724e08a0b7","questionId":"97698f51-1073-5500-bb26-1e4a8e2163ad","sourceKey":"bank:ECO101:E101N1-044","payload":{"prompt":"David Ricardo's theory of rent predicts that as population rises,","options":["rent falls towards zero","food output grows faster than population","wages rise well above subsistence","landowners gain"],"correctOption":3,"section":"Historical Development of Economic Thought","explanation":"Ricardo's theory of rent holds that landowners gain as population grows and the demand for land increases. Saying rent falls towards zero gets the direction wrong, since rising population pushes rents up."}},{"itemId":"7377d213-1399-50a0-acc8-bd87a3f0fa76","questionId":"48505c6c-6bde-5c96-87d0-46bb52ced338","sourceKey":"bank:ECO101:E101N1-045","payload":{"prompt":"An Essay on the Principle of Population (1798) was written by","options":["Thomas Malthus","Jeremy Bentham","Vilfredo Pareto","David Ricardo"],"correctOption":0,"section":"Historical Development of Economic Thought","explanation":"Thomas Malthus published An Essay on the Principle of Population in 1798. David Ricardo was a fellow classical economist, but his main work is Principles of Political Economy and Taxation (1817)."}},{"itemId":"075b7ab0-2bba-5875-bbe6-2a2b24ef650c","questionId":"d4e8a810-0343-5499-859d-f150ccf93d99","sourceKey":"bank:ECO101:E101N1-046","payload":{"prompt":"Thomas Malthus argued that population tends to grow","options":["geometrically while food supply grows arithmetically","at the same rate as food supply","arithmetically while food supply grows geometrically","geometrically while food supply stays constant"],"correctOption":0,"section":"Historical Development of Economic Thought","explanation":"Malthus held that population grows geometrically while food grows only arithmetically, leading to poverty and famine unless population is checked. Reversing the two rates removes the very gap that drives his gloomy conclusion."}},{"itemId":"0aba901a-aa90-593b-9642-f8e065f88ece","questionId":"1a815de5-ff0e-572d-9d73-d6228e0d8a8b","sourceKey":"bank:ECO101:E101N1-047","payload":{"prompt":"In Malthus's population theory, which of the following is an example of moral restraint?","options":["Disease spreading through a city","Delaying marriage and having fewer births","Famine reducing the population","War reducing the number of people"],"correctOption":1,"section":"Historical Development of Economic Thought","explanation":"Moral restraint is the voluntary check of delaying marriage and having fewer children. Famine, disease and war are natural checks that reduce population after it has outgrown food supply."}},{"itemId":"a96328f9-3416-5ec2-9c06-dc7e9528a6c5","questionId":"49f443f1-6769-56b7-aaf8-2a50f94e65d8","sourceKey":"bank:ECO101:E101N1-048","payload":{"prompt":"Which of the following is a natural check on population in Malthus's theory?","options":["Moral restraint","Disease","Delayed marriage","Fewer births by choice"],"correctOption":1,"section":"Historical Development of Economic Thought","explanation":"Malthus's natural checks are famine, disease and war, which raise deaths when population outgrows food. Delayed marriage and fewer births by choice are forms of moral restraint, the voluntary check."}},{"itemId":"22a21ced-a004-51b7-a97f-bf3cf28b2097","questionId":"1ca98707-901d-561e-a8db-10d3856f1e62","sourceKey":"bank:ECO101:E101N1-049","payload":{"prompt":"Neoclassical economics emerged in the late 19th century as","options":["a reaction to feudal systems","a refinement of classical economics","the first school to study population","a rejection of all market analysis"],"correctOption":1,"section":"Historical Development of Economic Thought","explanation":"Neoclassical economics developed in the late 19th century as a refinement of classical economics, with leading figures such as Alfred Marshall and Leon Walras. The reaction to feudal systems describes classical economics, which came about a century earlier."}},{"itemId":"62fa8175-b1d0-5bfe-897a-67236deaacf8","questionId":"6cc6cce4-1368-57e1-84bc-da65f6486967","sourceKey":"bank:ECO101:E101N1-050","payload":{"prompt":"The neoclassical approach that focuses on the value of an additional unit rather than on total value is called","options":["the invisible hand","marginalism","laissez-faire","the labour theory of value"],"correctOption":1,"section":"Historical Development of Economic Thought","explanation":"Marginalism focuses on marginal rather than total value, and it is a core neoclassical idea. The labour theory of value is a classical idea that ties value to the labour needed to make a good."}},{"itemId":"ac17e2e0-83fd-5553-bf05-60e681ddde29","questionId":"93c35f67-9132-5a98-828d-926e5d70477c","sourceKey":"bank:ECO101:E101N1-051","payload":{"prompt":"A student lists the core ideas of the school led by Alfred Marshall and Leon Walras. Which entry on the list is wrong?","options":["Marginalism","General equilibrium","Labour theory of value","Utility theory"],"correctOption":2,"section":"Historical Development of Economic Thought","explanation":"The labour theory of value belongs to classical economics, not to the neoclassical school. Marginalism, utility theory, general equilibrium, market equilibrium and price theory are the neoclassical core ideas."}},{"itemId":"ed0585e4-1b9b-52cd-8349-4fc157245d26","questionId":"642ef003-7a5d-532f-be8e-aafd3ae143fb","sourceKey":"bank:ECO101:E101N1-052","payload":{"prompt":"Which of the following is NOT a core idea of classical economics?","options":["The invisible hand","Division of labour","The labour theory of value","Marginalism"],"correctOption":3,"section":"Historical Development of Economic Thought","explanation":"Marginalism, the focus on marginal rather than total value, is a neoclassical idea. Division of labour, the invisible hand and the labour theory of value are all core classical ideas, alongside comparative advantage and Malthus's population theory."}},{"itemId":"6e6c3b59-469d-5b66-b64b-2234a2c10a17","questionId":"2786bec1-7907-529a-b73f-01814fc4f2e6","sourceKey":"bank:ECO101:E101N1-053","payload":{"prompt":"The idea that consumers seek to maximize utility and that each additional unit of a good gives less satisfaction than the one before is part of","options":["Malthusian population theory","neoclassical utility theory","classical labour theory of value","Ricardian theory of rent"],"correctOption":1,"section":"Historical Development of Economic Thought","explanation":"Neoclassical utility theory assumes people maximize utility and that marginal utility diminishes as more is consumed. The classical labour theory of value explains value by labour input, not by consumers' satisfaction."}},{"itemId":"8b92cc04-e16b-5564-942b-1cfa2f168b3e","questionId":"8c442d24-9500-5a13-aa46-b24c0283818f","sourceKey":"bank:ECO101:E101N1-054","payload":{"prompt":"Which economist developed general equilibrium theory, showing how all markets in an economy adjust simultaneously?","options":["Adam Smith","Arthur Pigou","Alfred Marshall","Leon Walras"],"correctOption":3,"section":"Historical Development of Economic Thought","explanation":"Leon Walras developed general equilibrium theory, in which all markets adjust at the same time. Alfred Marshall is better known for price theory and analysing one market at a time, which is partial rather than general equilibrium."}},{"itemId":"4cb4b505-74b8-53a3-9886-46ef2496a471","questionId":"00dc6a06-760b-558e-8f8e-eee2bd730b2f","sourceKey":"bank:ECO101:E101N1-055","payload":{"prompt":"Elements of Pure Economics (1874), which used mathematical modelling to present general equilibrium theory, was written by","options":["David Ricardo","Alfred Marshall","Leon Walras","John Stuart Mill"],"correctOption":2,"section":"Historical Development of Economic Thought","explanation":"Leon Walras wrote Elements of Pure Economics in 1874, presenting general equilibrium with mathematical models. Alfred Marshall's major work was Principles of Economics, published in 1890."}},{"itemId":"83cfea71-e833-5f26-9695-1119b5590c6c","questionId":"e32ca9ff-bcce-5e34-a727-a6d1afd29acd","sourceKey":"bank:ECO101:E101N1-056","payload":{"prompt":"Alfred Marshall argued that the price of a good is determined by","options":["supply and cost of production alone","both demand, based on utility, and supply, based on cost","the amount of labour required alone","demand and utility alone"],"correctOption":1,"section":"Historical Development of Economic Thought","explanation":"Marshall held that demand (reflecting utility) and supply (reflecting cost) together determine price. Pointing to labour alone is the classical labour theory of value, which Marshall moved beyond."}},{"itemId":"52406486-ef06-5a65-9643-786f2f6b13f9","questionId":"6eca613a-b005-5a35-9ad4-103b1c5d1ef6","sourceKey":"bank:ECO101:E101N1-057","payload":{"prompt":"Which economist is associated with developing price elasticity of demand, supply curves and the distinction between short-run and long-run costs?","options":["Alfred Marshall","Thomas Malthus","Jeremy Bentham","Leon Walras"],"correctOption":0,"section":"Historical Development of Economic Thought","explanation":"Alfred Marshall's price theory introduced price elasticity of demand, supply curves and the short-run versus long-run cost distinction. Leon Walras is known for general equilibrium across all markets rather than these single-market tools."}},{"itemId":"dec9d5c4-6597-5ac0-b9a4-9a56135eda8d","questionId":"214518c4-8fb4-5050-aa2b-51e572f97a95","sourceKey":"bank:ECO101:E101N1-058","payload":{"prompt":"Utilitarianism, the view that the best actions and policies are those that maximize happiness for the greatest number, is associated with","options":["Jeremy Bentham and John Stuart Mill","Adam Smith and David Ricardo","Alfred Marshall and Leon Walras","Arthur Pigou and Vilfredo Pareto"],"correctOption":0,"section":"Historical Development of Economic Thought","explanation":"Jeremy Bentham and John Stuart Mill are the leading utilitarians, holding that policies should maximize happiness for the greatest number. Pigou and Pareto are associated with welfare economics, which builds on similar concerns but is a separate school."}},{"itemId":"f9608bd2-6e54-5f6f-b2e6-1948c0a2acd0","questionId":"8dc82328-5a20-5c7d-a848-28948a2562a6","sourceKey":"bank:ECO101:E101N1-059","payload":{"prompt":"Jeremy Bentham's principle of utility holds that human behaviour is driven by","options":["the need to keep population below food supply","the labour required to produce goods","the desire to make others better off first","the pursuit of pleasure and the avoidance of pain"],"correctOption":3,"section":"Historical Development of Economic Thought","explanation":"Bentham's principle of utility says people act to pursue pleasure and avoid pain, which leads to the greatest happiness principle. Labour required to produce goods relates to the classical labour theory of value, not to Bentham's theory of behaviour."}},{"itemId":"af626f8a-e786-5380-a47c-6a59bcf45d94","questionId":"ca7d22a9-9eb8-5756-bdfa-b943b33d2a09","sourceKey":"bank:ECO101:E101N1-060","payload":{"prompt":"The Lagos State Government approves a new bridge only after showing that its total benefits to society exceed its total costs. This approach reflects the utilitarian idea of","options":["the labour theory of value","Pareto efficiency","cost-benefit analysis","the invisible hand"],"correctOption":2,"section":"Historical Development of Economic Thought","explanation":"Cost-benefit analysis, a utilitarian idea, justifies a policy when its benefits exceed its costs. Pareto efficiency is a stricter test that requires no one be made worse off, which a project that simply has net benefits need not satisfy."}},{"itemId":"0cc1567b-ed16-5aec-a57c-26a0a99f9338","questionId":"5f339794-4ef8-5701-a056-27a8e4129a94","sourceKey":"bank:ECO101:E101N1-061","payload":{"prompt":"How did John Stuart Mill's view on the distribution of wealth differ from Jeremy Bentham's?","options":["Both rejected any concern with the well-being of society","Both held that wealth should be shared only by landowners","Bentham argued for reducing inequality, while Mill showed little concern for distribution","Mill argued for reducing inequality, while Bentham showed little concern for distribution"],"correctOption":3,"section":"Historical Development of Economic Thought","explanation":"Mill extended Bentham's ideas to society's well-being and individual freedom and argued for reducing inequality, while Bentham paid little attention to how wealth was distributed. Swapping the two thinkers reverses their actual positions."}},{"itemId":"adaf8ee8-ce6c-580e-a340-a4fb240fe5c9","questionId":"e9f9a363-7081-572e-8fe5-c0f4568f3ed6","sourceKey":"bank:ECO101:E101N1-062","payload":{"prompt":"Welfare economics, which combines efficiency with fairness in studying how resources can be allocated to improve social welfare, is associated with","options":["Leon Walras and Antoine Cournot","Jeremy Bentham and John Stuart Mill","Arthur Pigou and Vilfredo Pareto","David Ricardo and Thomas Malthus"],"correctOption":2,"section":"Historical Development of Economic Thought","explanation":"Welfare economics is linked with Arthur Pigou and Vilfredo Pareto, and it combines efficiency with fairness. Bentham and Mill are the utilitarians, whose ideas on happiness influenced welfare economics but who form a separate school."}},{"itemId":"ce7d64dd-a7da-5ec4-842f-3634a52bd0f0","questionId":"bf67b928-8098-5534-bbb2-152a1f40b11e","sourceKey":"bank:ECO101:E101N1-063","payload":{"prompt":"A corrective tax placed on a harmful activity, such as pollution from a factory in Agbara, so that the producer bears the full social cost, is called a","options":["Pareto tax","Pigovian tax","poll tax","tariff"],"correctOption":1,"section":"Historical Development of Economic Thought","explanation":"A Pigovian tax, named after Arthur Pigou, is a corrective tax on harmful activities that makes producers internalize the social cost. A tariff is a tax on imports, which has nothing to do with correcting pollution."}},{"itemId":"5be35639-7a0b-5fe9-a0c5-1fc073ee05ef","questionId":"a5e7df3a-9bee-5827-82ab-cac9448e867c","sourceKey":"bank:ECO101:E101N1-064","payload":{"prompt":"Arthur Pigou identified market failures such as","options":["externalities such as pollution, and public goods","the division of labour and specialization","diminishing marginal utility and consumer surplus","geometric population growth and famine"],"correctOption":0,"section":"Historical Development of Economic Thought","explanation":"Pigou identified externalities such as pollution, and public goods, as market failures that government can correct with taxes and subsidies. Geometric population growth and famine belong to Malthus's population theory, not to Pigou."}},{"itemId":"0197d35d-2e6a-5d49-90cc-d57a47155c55","questionId":"2021e6fc-869f-5b7b-ae6b-688fad6b4629","sourceKey":"bank:ECO101:E101N1-065","payload":{"prompt":"In welfare economics, a social welfare function is used to","options":["measure the labour required to produce each good","calculate the geometric growth rate of population","aggregate individual utilities while considering distribution and equity","set the exchange rate between two currencies"],"correctOption":2,"section":"Historical Development of Economic Thought","explanation":"A social welfare function combines individual utilities into a measure of society's welfare and takes distribution and equity into account. Measuring the labour required to produce goods is the classical labour theory of value, not a welfare tool."}},{"itemId":"bd8b80fb-c5df-58c0-b0f5-3afa5785b9a4","questionId":"ee63ca68-717f-56ce-b87f-3d8b44a3b39f","sourceKey":"bank:ECO101:E101N1-066","payload":{"prompt":"Two students share a fixed stock of textbooks. Any change in the allocation that helps Ada would make Bola worse off. This allocation is","options":["Pareto inefficient, since Ada could gain","a Pigovian outcome","Pareto efficient","a general equilibrium failure"],"correctOption":2,"section":"Historical Development of Economic Thought","explanation":"An allocation is Pareto efficient when no one can be made better off without making someone else worse off, which is exactly the situation described. Calling it inefficient because Ada could gain ignores that her gain would come at Bola's expense."}},{"itemId":"258bc7b5-5375-5eb4-8195-f21b7e08583c","questionId":"2da8d880-de10-5ada-b79c-91b74298f5d9","sourceKey":"bank:ECO101:ECO-0001","payload":{"prompt":"Use Table 1 (Demand and Supply Schedule: Price / Quantity Demand (Qd) / Quantity Supply (Qs): 2.00 / 70 / 10; 3.50 / 60 / 20; 4.00 / 50 / 30; 4.50 / 40 / 40; 5.00 / 30 / 50; 5.50 / 20 / 60; 6.00 / 10 / 70). Equilibrium price is","options":["2.00","5.50","4.50","1.50"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Equilibrium price is where quantity demanded equals quantity supplied, and in the table that happens at a price of 4.50, where Qd = Qs = 40. At 2.00 (option A) demand is 70 but supply is only 10, a big shortage, while at 5.50 (option B) supply of 60 is far above demand of 20. Option D (1.50) is not even in the table."}},{"itemId":"c6143d34-5c37-5539-8729-3081397db43a","questionId":"d7d7c65a-5284-5042-a272-9dfe9dcff7c9","sourceKey":"bank:ECO101:ECO-0002","payload":{"prompt":"Use Table 1 (Demand and Supply Schedule: Price / Quantity Demand (Qd) / Quantity Supply (Qs): 2.00 / 70 / 10; 3.50 / 60 / 20; 4.00 / 50 / 30; 4.50 / 40 / 40; 5.00 / 30 / 50; 5.50 / 20 / 60; 6.00 / 10 / 70). Equilibrium quantity is","options":["40","20","30","0"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"At the equilibrium price of 4.50, buyers want 40 units and sellers offer 40 units, so the equilibrium quantity is 40. Options B (20) and C (30) are quantities found at other prices, where the market is not clearing, and option D (0) has no basis in the table."}},{"itemId":"d810a502-ac96-564c-bb6d-4c310979f1f0","questionId":"29ca0432-bf0d-56c6-a12e-afdbeb7bea6f","sourceKey":"bank:ECO101:ECO-0003","payload":{"prompt":"Use Table 1 (Demand and Supply Schedule: Price / Quantity Demand (Qd) / Quantity Supply (Qs): 2.00 / 70 / 10; 3.50 / 60 / 20; 4.00 / 50 / 30; 4.50 / 40 / 40; 5.00 / 30 / 50; 5.50 / 20 / 60; 6.00 / 10 / 70). At price = 5.00","options":["supply equals demand","supply exceeds demand by 10","demand exceeds supply by 20","supply exceeds demand by 20"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"At a price of 5.00 the table shows Qd = 30 and Qs = 50, so supply exceeds demand by 50 - 30 = 20, which is a surplus. Option A is wrong because supply equals demand only at 4.50, and option B gets the size of the gap wrong. Option C reverses the gap; excess demand happens at prices below 4.50, not above it."}},{"itemId":"0937dcd7-26df-5efa-9c60-b93f6faa083b","questionId":"0d539e19-0003-580b-86fc-9e66db60cfab","sourceKey":"bank:ECO101:ECO-0004","payload":{"prompt":"A movement along the demand curve indicates that a different quantity is demanded because there has been a change in:","options":["income and price","taste, income of the consumer","price of the commodity","change in population"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A movement along a demand curve happens only when the good's own price changes, all other things held constant. Changes in income, taste or population (options A, B and D) are non-price determinants, and they shift the whole demand curve instead of moving along it."}},{"itemId":"4860868b-00e9-5e65-b30c-de1f1482b621","questionId":"f656a50b-f3c1-5791-a710-a6b9c36d7cb2","sourceKey":"bank:ECO101:ECO-0005","payload":{"prompt":"A bodily shift in demand can be caused by a","options":["change in price","change in income, taste, population","movement along the supply curve","community indifference curve"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A bodily shift of the whole demand curve is caused by non-price factors such as income, taste and population. Option A is wrong because a change in the good's own price only causes a movement along the demand curve. Option C is about sellers, not buyers, and option D is a concept from indifference analysis, not a cause of demand shifts."}},{"itemId":"60409ee0-d8e0-51d1-83b7-da3e9e48b272","questionId":"c4c1cfa8-6146-5ee4-b226-e0e6115a848e","sourceKey":"bank:ECO101:ECO-0006","payload":{"prompt":"A rise in the demand for a commodity can be represented by a bodily shift of the demand curve to","options":["the right","the left","a point higher up the same curve","a point lower down the same curve"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"An increase in demand means buyers want more at every price, so the entire demand curve moves to the right. Option B, a shift to the left, shows a fall in demand. Options C and D describe movements along the same curve, which come from a change in the good's own price, not a shift."}},{"itemId":"fd5e4531-8fb6-53e3-9f79-78231e0a2bc9","questionId":"3f6a6557-ee54-5a11-a7c2-4cd237877e66","sourceKey":"bank:ECO101:ECO-0007","payload":{"prompt":"A leftward shift of the demand curve means a","options":["fall in demand","rise in demand","movement along the demand curve","unitary change in demand"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"When the demand curve shifts to the left, buyers want less at every price, which is a fall (decrease) in demand. Option B describes a rightward shift. Option C is wrong because a movement along the curve comes from a change in the good's own price, not a shift, and option D has nothing to do with the direction of a shift."}},{"itemId":"48d1155e-ee3d-5977-9e9b-cdb1a3c25345","questionId":"244c35ee-eef9-5c83-8b22-f3fd8398cd22","sourceKey":"bank:ECO101:ECO-0008","payload":{"prompt":"A table that shows the price and quantity of a commodity demanded per unit of time is referred to as","options":["time series","slope of demand","demand schedule","demand curve"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A demand schedule is a table listing different prices and the quantity demanded at each price per period of time. Option D, the demand curve, shows the same information as a graph rather than a table. Option A, a time series, is data recorded over time, and option B, the slope, is a property of the curve."}},{"itemId":"60e53f4d-f12f-594a-a01b-ebfe270676d6","questionId":"743c98c5-2e13-5ada-bc62-95caba8540d6","sourceKey":"bank:ECO101:ECO-0009","payload":{"prompt":"The quantity of a good offered in a market at all possible prices per unit of time is referred to as","options":["price elasticity","market offer","supply of a good","quantity demanded"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Supply is the quantity of a good that sellers are willing and able to offer for sale at all possible prices per period of time. Option D, quantity demanded, refers to buyers, not sellers. Option A, price elasticity, measures responsiveness, and option B, market offer, is not a standard economic term."}},{"itemId":"95e7993d-adde-515e-95b4-c33c4cde2970","questionId":"32542768-fba9-5ba4-833a-5dec7d1ec9f0","sourceKey":"bank:ECO101:ECO-0011","payload":{"prompt":"If a negatively sloped demand curve remains unchanged, a leftward shift of the supply curve causes","options":["rise in equilibrium quantity and no change in price","fall in equilibrium quantity and a fall in price","fall in price and a rise in quantity","decrease in equilibrium quantity bought and sold, and an increase in equilibrium price"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A leftward shift of supply with demand unchanged creates a shortage at the old price, so the price rises and the equilibrium quantity falls. Option B gets the quantity right but the price wrong, since a cut in supply pushes price up, not down. Options A and C get the direction of quantity wrong."}},{"itemId":"486cf163-3736-5eb5-becc-7021a7b1371b","questionId":"3eb24c48-2544-5105-9ef2-2a792b4a2d5d","sourceKey":"bank:ECO101:ECO-0013","payload":{"prompt":"A leftward shift of the demand curve when supply remains unchanged, results in","options":["a fall in price, quantity remaining constant","a rise in price and a decrease in the equilibrium quantity bought and sold","a fall in equilibrium price and a decrease in equilibrium quantity bought and sold","a fall in quantity and a rise in price"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A leftward shift of demand with supply unchanged leaves a surplus at the old price, so the price falls and less is bought and sold. Option C gives both effects. Options B and D wrongly say price rises, and option A wrongly says quantity stays constant."}},{"itemId":"0c00d321-6cbd-5407-b35c-d6297cdee6b2","questionId":"87d4c356-d927-5be2-9788-391b1650c8f7","sourceKey":"bank:ECO101:ECO-0014","payload":{"prompt":"Goods that are produced together are said to be (in)","options":["competitive supply","joint supply","complementarity","linked up goods"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Goods in joint supply are produced together from the same source, so producing one automatically yields the other, as with beef and leather from cattle. Option A, competitive supply, refers to different commodities supplied to satisfy the same want, such as butter and margarine. Option C, complementarity, refers to goods demanded together, not produced together, and option D is not a standard term."}},{"itemId":"582e6123-59e3-5171-bea7-a8da6e70df3d","questionId":"d6a7ef7b-51ee-5f2c-95d7-6b84dc81b18b","sourceKey":"bank:ECO101:ECO-0015","payload":{"prompt":"The following goods are said to be complementary","options":["tea and sugar","table and ink","car and rubber bands","door and classroom"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Complementary goods are used together, so demand for one goes with demand for the other, and tea and sugar fit this well. The pairs in options B, C and D are not normally consumed together, so a change in the price of one would hardly affect demand for the other."}},{"itemId":"9e52d1c8-309f-5c4d-8758-26acc18c4249","questionId":"9038853f-a847-59ff-8efc-93520e9e384c","sourceKey":"bank:ECO101:ECO-0016","payload":{"prompt":"Goods that are demanded for several purposes are said to be in","options":["joint demand","elastic demand","composite demand","surplus"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Composite demand arises when one good is wanted for several different uses, such as electricity for lighting, cooking and running machines. Option A, joint demand, is when two goods are wanted together. Option B describes how responsive demand is to price, and option D is an excess of supply over demand."}},{"itemId":"f7bdb6f9-2d40-5c77-b65f-3c94b3be4149","questionId":"51bf94ae-27a0-5f11-be0e-b1832194438d","sourceKey":"bank:ECO101:ECO-0017","payload":{"prompt":"Examples of goods in joint supply include","options":["palm oil and palm kernel","telephone and television","pen and ink","milk and tea"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Palm oil and palm kernel both come from the same oil palm fruit, so producing one gives you the other; that is joint supply. Option D, milk and tea, are consumed together, which makes them complements (joint demand). Options B and C are also not pairs that are produced together."}},{"itemId":"5dfe4e7c-e752-5b40-8264-28823ce79a0b","questionId":"c8b73b76-4526-58f2-a66a-3b636a696369","sourceKey":"bank:ECO101:ECO-0018","payload":{"prompt":"The following are substitute goods","options":["butter and margarine","clothes and table","pen and paper","school room and land"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Substitutes can be used in place of each other, and butter and margarine serve the same purpose as spreads. Option C, pen and paper, are used together, so they are complements. The pairs in options B and D are unrelated goods."}},{"itemId":"853c6ac6-d380-5d09-8e4c-02741f99bcc2","questionId":"a4edeeda-454c-52ba-87b5-70f7535977e1","sourceKey":"bank:ECO101:ECO-0019","payload":{"prompt":"The responsiveness of the quantities demanded of a commodity to changes in the prices of other commodities is called","options":["elasticity of demand","price elasticity of demand","cross elasticity of demand","income elasticity of demand"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Cross elasticity of demand measures how quantity demanded of one good responds to a change in the price of another good. Option B, price elasticity, looks at the good's own price. Option D, income elasticity, looks at changes in income, and option A is just the general term."}},{"itemId":"baca945d-b124-52a2-8660-a4d10aa02b0d","questionId":"be6c9ac8-7edd-566b-828b-06d29065229f","sourceKey":"bank:ECO101:ECO-0020","payload":{"prompt":"Income elasticity of demand is defined as","options":["the ratio of the percentage change in quantity demanded of a commodity to a percentage change in income","the percentage change in quantity demanded to a percentage change in prices","the percentage change in income to a percentage change in quantity demanded","the ratio of price changes to income change"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Income elasticity of demand = (%change in quantity demanded)/(%change in income). Option B is price elasticity, not income elasticity. Option C turns the ratio upside down, and option D does not involve quantity demanded at all."}},{"itemId":"3a22f248-181b-5667-a2eb-1efb3dc69b45","questionId":"383ff633-c3d2-56e6-989d-b586eafbcb29","sourceKey":"bank:ECO101:ECO-0021","payload":{"prompt":"The cross elasticity of two goods that are substitutes is","options":["zero","minus infinity","negative","positive"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"For substitutes, a rise in the price of one good makes people buy more of the other, so both percentage changes move in the same direction and cross elasticity is positive. Option C, a negative value, is what you get for complements. Option A, zero, means the goods are unrelated."}},{"itemId":"11ff77ce-27de-5b23-837e-a4cead9d604f","questionId":"2a3dc52c-7d53-59a7-819d-453db5e4d68c","sourceKey":"bank:ECO101:ECO-0022","payload":{"prompt":"Supply curves are usually positively sloped. This shows that","options":["more is supplied at lower prices","the same quantity is supplied regardless of the price","more is supplied as price increases","more is supplied as price falls"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"An upward (positive) slope means price and quantity supplied move in the same direction, so sellers offer more as price rises. Options A and D describe the opposite relationship. Option B describes a perfectly inelastic (vertical) supply curve, which is not the usual case."}},{"itemId":"be26353c-9517-5041-b2c0-2db8010f87b3","questionId":"e8e844e1-5d49-5d95-b7a0-b3f37b53527f","sourceKey":"bank:ECO101:ECO-0024","payload":{"prompt":"When the demand curve is parallel to the price axis, demand is said to be","options":["perfectly elastic","perfectly inelastic","unit elastic","None of the above"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A demand curve parallel to the price (vertical) axis is a vertical line, meaning quantity demanded stays the same whatever the price; this is perfectly inelastic demand. Option A, perfectly elastic demand, is a horizontal line parallel to the quantity axis. Option C, unit elasticity, gives a curved shape called a rectangular hyperbola."}},{"itemId":"d925696e-49f2-5bc8-b369-9f816c523fe0","questionId":"fa0a9f23-c0fd-5909-bd62-cd7252b4a613","sourceKey":"bank:ECO101:ECO-0026","payload":{"prompt":"If the price elasticity of demand for good X equals to Zero, then","options":["Demand can be said to be perfectly elastic; a tiny change in price leads to an infinite change in quantity demanded.","Demand can be said to be relatively elastic; a given % change in price leads to a larger % change in quantity demanded.","Demand can be said to be unit elastic; a given % change in price leads to an equal % change in quantity demanded.","demand can be said to be perfectly inelastic"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A price elasticity of zero means quantity demanded does not change at all when price changes, which is perfectly inelastic demand shown by a vertical demand curve. Option A describes the opposite extreme, an elasticity of infinity. Option B describes elasticity greater than 1, and option C describes elasticity exactly equal to 1."}},{"itemId":"2f745364-3355-5860-9307-07a53d049e6e","questionId":"acba509c-5d59-5ef0-8569-0bbc35d5025c","sourceKey":"bank:ECO101:ECO-0027","payload":{"prompt":"If the price elasticity of demand for good x is perfectly inelastic, then an increase in price of the good will","options":["reduce the quantity demanded","leave the demand unchanged","demand will rise","first increase demand and their reduce it successively"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Perfectly inelastic demand means the quantity demanded does not respond to price at all, so a price rise leaves it unchanged. Option A would be true for a normal downward-sloping demand curve, not this one. Options C and D describe responses that perfectly inelastic demand rules out."}},{"itemId":"a22f6716-23cf-5c2a-a528-8bfe4f95c2a2","questionId":"a16e46bd-97aa-527f-9cc4-413bba690e30","sourceKey":"bank:ECO101:ECO-0028","payload":{"prompt":"Bayo drinks only Pepsi and Coke. After three bottles of Pepsi, he switches to Coke, indicating that:","options":["the marginal utility of Pepsi falls below zero after three bottles","the marginal utility of the additional Coke exceeds the average utility of the three bottles of Pepsi","total utility will start to fall after three bottles of Pepsi","the marginal utility per Naira of Coke is higher than the marginal utility per Naira of Pepsi after three bottles"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A rational consumer spends where the marginal utility per naira is highest, so switching to Coke after three Pepsis shows that MU/P for Coke has become higher than MU/P for Pepsi. Option A goes too far, because Bayo can switch even while Pepsi still gives positive marginal utility. Option C is also not implied, since total utility only falls once marginal utility is negative, and option B compares marginal with average utility, which is not the switching rule."}},{"itemId":"339beb6b-45ae-5a1c-9a6c-4300ba98500b","questionId":"3ebd17e7-1f00-5530-b9f8-eca67b9e1938","sourceKey":"bank:ECO101:ECO-0029","payload":{"prompt":"If the MRS of Meat for Chicken is higher than Pm/Pc for a consumer at a point on the budget line, the consumer should consume:","options":["More Meat and less Chicken","More Chicken and less Meat","More Meat and the same amount of Chicken","Less Meat and the same amount of Chicken"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"The MRS of meat for chicken shows how much chicken the consumer is willing to give up for one more unit of meat, and it equals MUm/MUc. If this is higher than Pm/Pc, the consumer values meat more than the market charges for it, so they gain by buying more meat and less chicken until the two ratios are equal. Option B moves in the wrong direction, and options C and D would take the consumer off the budget line or leave the gain unused."}},{"itemId":"2614b65a-401a-5f49-b2fc-b7fad4331109","questionId":"97accadd-de53-5fd7-a835-cf8febf65333","sourceKey":"bank:ECO101:ECO-0030","payload":{"prompt":"Sets of indifference curves drawn in the commodity space is called.....","options":["indicators for ranking preference","indifference budgets","indifference maps","indifference line"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"An indifference map is a set of indifference curves drawn on the same graph, each showing a higher or lower level of satisfaction. Option A is a description of what the curves do, not their name. Options B and D are not standard terms."}},{"itemId":"c5021302-225a-55ac-95d1-9886e5be65fa","questionId":"dc0de39a-ae20-5298-8865-78cfd2a247fe","sourceKey":"bank:ECO101:ECO-0033","payload":{"prompt":"Consumer of a goods will maximize utility where","options":["the ratio of marginal utility to the price are all equal for all the commodities in the consumption basket","Marginal social benefits equals marginal social cost","Marginal social cost exceeds marginal social benefit","the deadweight lose is zero"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"A consumer maximises utility when the marginal utility per naira is the same for every good bought, that is MUx/Px = MUy/Py and so on. Options B, C and D are conditions about social welfare and market efficiency, not about an individual consumer's choice."}},{"itemId":"68dc82e9-fa27-52e5-9375-3a0aec4238f9","questionId":"28cc44e2-7d17-527b-9d53-a381f341facc","sourceKey":"bank:ECO101:ECO-0036","payload":{"prompt":"A consumer of Chicken and Chips is willing to pay N600, but he paid N500.00. The difference gained is called","options":["profit","consumer's benefit","consumer's discount","consumer's surplus"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Consumer surplus is the difference between the most a buyer is willing to pay and what they actually pay, here N600 - N500 = N100. Option A, profit, is a gain earned by sellers, not buyers. Options B and C are not the standard names for this gain."}},{"itemId":"8012b6e6-04dc-531e-b8de-9aebce73cc2e","questionId":"9873bf0d-d3e2-5ba8-9d88-06de79f9d7a6","sourceKey":"bank:ECO101:ECO-0037","payload":{"prompt":"________ defines the slope of the indifference curve at a point.","options":["marginal slope","marginal rate of substitution","marginal rate of technical substitution","none of the above"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The slope of an indifference curve at a point is the marginal rate of substitution (MRS), the rate at which a consumer is willing to swap one good for another while staying equally satisfied. Option C, the marginal rate of technical substitution, is the slope of an isoquant in production, not an indifference curve."}},{"itemId":"f83f5b8e-8f74-5985-b2cb-fefcf50220c0","questionId":"d0de18f7-620e-56b1-bed1-ece9857b3265","sourceKey":"bank:ECO101:ECO-0048","payload":{"prompt":"The line that joins quantity of goods bought with level of income is called","options":["Angel curve","Engel curve","Walrasian curve","income curve"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The Engel curve shows how the quantity of a good bought changes as the consumer's income changes. Option A is a misspelling of the same idea, not the correct term. Option C is not a standard curve, and option D is not the name used for this relationship."}},{"itemId":"4ea6e7c5-fc81-5143-9e9d-9bb284b3bf4d","questionId":"f43e599d-17a7-5c23-8cce-6734de235d87","sourceKey":"bank:ECO101:ECO-0101","payload":{"prompt":"A change in people's expectation will result in","options":["a change in demand","a change in quantity demand","a movement along the demand curve","no effect on demand"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Expectations are a non-price determinant of demand; if people expect prices to rise, for example, they buy more now at every price, so the demand curve shifts. Options B and C describe the effect of a change in the good's own price. Option D is wrong because expectations clearly affect buying decisions."}},{"itemId":"d3fbdc30-21ab-50f4-bdd9-f2665b6ac623","questionId":"581a680c-7f7d-56e3-8ab7-d39a3b2df7ba","sourceKey":"bank:ECO101:ECO-0102","payload":{"prompt":"For demand to be effective in the market","options":["seller must make goods and service available in sufficient amounts","people must be willing to pay the same price as others for good and service","the relationship between price and quantity must be known","consumer must have both the ability and willingness to pay for goods and services"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Effective demand is a desire backed by both the ability and willingness to pay. Option A is about supply, not demand. Options B and C are not conditions that make demand effective."}},{"itemId":"c86710f9-a132-5fd3-be60-8bf11eba83a7","questionId":"22574ba2-63ce-5f88-b9ac-84cf2becbee1","sourceKey":"bank:ECO101:ECO-0103","payload":{"prompt":"A change in the firm's technology will always result in","options":["a decrease in supply","a movement along the supply curve","an increase in quantity supplied","a change in supply"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Technology is a non-price determinant of supply, so a change in it shifts the whole supply curve, which is a change in supply. Option A is wrong because better technology usually increases supply. Options B and C describe the effect of a change in the good's own price."}},{"itemId":"3b3f23ae-c1f9-5755-a9ac-301a393ae3a5","questionId":"d75c97bc-20b9-543a-9406-4ac63c9f5cf2","sourceKey":"bank:ECO101:ECO-0104","payload":{"prompt":"An increase income will cause an increase in demand in","options":["a public good","a black market good","a normal good","an inferior goods"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A normal good is one people buy more of when their income rises. Option D, an inferior good, is the opposite: people buy less of it as income rises. Options A and B are not defined by how they respond to income."}},{"itemId":"71238519-e9f5-56af-9212-7bd42d4946fd","questionId":"d1e2072a-a1b3-5c29-8155-747a59148d78","sourceKey":"bank:ECO101:ECO-0105","payload":{"prompt":"An outward shift of the demand curve will lead to","options":["an increase in both the equilibrium price and quantity","a decrease in both the equilibrium price and quantity","a fall in equilibrium price but an increase in equilibrium quantity","no change in either equilibrium price or quantity"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"An outward (rightward) shift of demand with supply unchanged creates a shortage at the old price, so price rises and sellers supply more; both equilibrium price and quantity increase. Option B describes a fall in demand, and option C describes an increase in supply. Option D is wrong because both price and quantity change."}},{"itemId":"94bc4e56-f01c-51ca-8a9c-3a95f3f4e86f","questionId":"0cf8afec-cf54-53ee-9291-30ebe88b987e","sourceKey":"bank:ECO101:ECO-0116","payload":{"prompt":"An outward shift of the supply curve will lead to","options":["a fall in equilibrium price but a rise in equilibrium quantity","an increase in both the equilibrium price and quantity","a decrease in both the equilibrium price and quantity","a rise in equilibrium price but a fall in equilibrium quantity"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"An outward (rightward) shift of supply with demand unchanged creates a surplus at the old price, so price falls and more is bought and sold. Option B describes an increase in demand. Option C describes a fall in demand, and option D describes a fall in supply."}},{"itemId":"db7e865a-fb8f-53ec-b5e1-7beccc362fa8","questionId":"aab29c0f-b41f-50ef-8da3-a5d1635e760e","sourceKey":"bank:ECO101:ECO-0120","payload":{"prompt":"The law of supply states that","options":["an increase in supply is always accompanied by an increase in demand","firms will offer more for sale at higher prices than at lower prices","firms will maintain higher prices, even if they cannot sell all of the goods they want","an increase in supply must drive prices down"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The law of supply says that, other things equal, firms offer more for sale at higher prices than at lower prices. Options A and D mix up supply and demand. Option C describes firms refusing to cut prices, which is not what the law says."}},{"itemId":"115992ac-4dfc-5b47-9dba-62a0da736810","questionId":"340edd15-91ff-505e-9e88-cd8bfe15c8c9","sourceKey":"bank:ECO101:ECO-0122","payload":{"prompt":"The demand for labour as a factor of production is","options":["derived demand","joint demand","complementary demand","composite demand"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Labour is demanded not for itself but for the goods and services it helps produce, so its demand is derived demand. Option B, joint demand, is goods wanted together. Option D, composite demand, is one good wanted for several uses."}},{"itemId":"1d41a658-5aa5-55be-8343-032ff49fd52e","questionId":"63fc3471-3634-56d5-8d54-5e3f3d2aa87c","sourceKey":"bank:ECO101:ECO-0128","payload":{"prompt":"The law of demand states that","options":["quantity demanded is positively related to price","quantity demanded is inversely related to price","quantity demanded is absolutely related to price","quantity demanded is equally related to price"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The law of demand says that, other things equal, quantity demanded rises when price falls and falls when price rises, so the two are inversely related. Option A describes the law of supply. Options C and D are not meaningful relationships."}},{"itemId":"1974601c-6a81-5128-add3-84a1acf74742","questionId":"c9e76d0a-ff1d-5901-84b7-6b7309c63054","sourceKey":"bank:ECO101:ECO-0129","payload":{"prompt":"When there is no tendency for a system to change, then there is","options":["maximization","efficiency","mechanism","equilibrium"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Equilibrium is a state of rest where the forces acting on a system balance, so there is no tendency for it to change. Option B, efficiency, is about making the best use of resources, which is a different idea. Options A and C do not describe a state of rest."}},{"itemId":"06d719a4-53d6-5c0c-b924-b9e3c30b38bf","questionId":"02767caa-6b84-5793-b49d-a069025aadd8","sourceKey":"bank:ECO101:ECO-0133","payload":{"prompt":"A movement along the demand curve is a","options":["increase in quantity demanded","decrease in quantity demanded","change in quantity demanded","change in demand"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A movement along the demand curve is caused by a change in the good's own price, and it is called a change in quantity demanded. Options A and B are only one direction each, while C covers both. Option D, a change in demand, is a shift of the whole curve."}},{"itemId":"921fbfdb-fb41-5674-b875-3f87739812db","questionId":"d4601c55-79a6-5ca2-a990-06b5b337d800","sourceKey":"bank:ECO101:ECO-0134","payload":{"prompt":"A shift of the entire supply curve is a","options":["increase in quantity supply","change in price of goods supplied","change in supply","decrease in quantity supplied"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A shift of the whole supply curve is caused by non-price factors such as technology or input costs, and it is called a change in supply. Options A and D describe movements along the curve caused by the good's own price. Option B is a cause of movement along the curve, not a shift."}},{"itemId":"c0ec7d6d-0182-54b4-80c3-c1d219cb3ea2","questionId":"83c0af8b-6383-5f4f-be53-5ed2f057aa26","sourceKey":"bank:ECO101:ECO-0135","payload":{"prompt":"Complements are","options":["two goods with the same price","two goods serving the same purpose","two goods jointly demanded","two goods that are not related"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Complements are goods that are jointly demanded, so they are used together, like tea and sugar. Option B describes substitutes, which serve the same purpose. Option A has nothing to do with how goods are related, and option D describes unrelated goods."}},{"itemId":"e1f545a8-b610-5624-bb81-6ff134e894d0","questionId":"4dbe0876-7e78-5b79-8ac6-b8d020f963b4","sourceKey":"bank:ECO101:ECO-0137","payload":{"prompt":"Inferior goods depend on","options":["price","income","demand","supply"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Inferior goods are defined by how their demand responds to income: people buy less of them as their income rises. Option A is wrong because price affects the demand for every good, so it does not set inferior goods apart. Options C and D are not what defines the category."}},{"itemId":"5792af53-d569-5807-963f-d8ea67b8f896","questionId":"6fe3017e-7e3f-572d-a6c9-aa953b73993d","sourceKey":"bank:ECO101:ECO-0139","payload":{"prompt":"________ is the practice of buying at a low price in one location and selling at a higher price in another location","options":["arbitrage","haggling","bargaining","racketing"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Arbitrage is buying a good where its price is low and selling it where its price is higher, making a profit from the price difference. Options B and C, haggling and bargaining, are ways of negotiating a price in one place. Option D is not the economic term for this."}},{"itemId":"4d6e0837-beef-5f06-bdbe-96e967244bbb","questionId":"8d2d1618-53f3-5719-9379-363e99f277ba","sourceKey":"bank:ECO101:ECO-0141","payload":{"prompt":"Price of copper in the world market may decline or remain constant for a long time because","options":["copper is a natural resources","demand for copper exceeds supply","miners produce less copper","copper now have very close substitute such as aluminium and fiber optics used in telecommunication infrastructure"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"When close substitutes such as aluminium and fibre optics become available, demand for copper falls or stops growing, so its price may decline or stay flat. Option B would push the price up, not down, and option C, lower output, would also raise the price. Option A is true of copper but does not explain the price trend."}},{"itemId":"0146eb88-0697-5ae8-ab66-2985d3dd557b","questionId":"01be6978-a506-5ba0-8701-86af6bf97ba6","sourceKey":"bank:ECO101:ECO-0142","payload":{"prompt":"Two goods for which the marginal rate of substitution of one for the other is constant are said to be","options":["near substitutes","near complements","perfect substitutes","perfect complements"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Perfect substitutes can be swapped at a fixed rate, so the MRS between them is constant and their indifference curves are straight lines. Option D, perfect complements, are used in fixed proportions and have L-shaped indifference curves. Options A and B have MRS values that change along the curve."}},{"itemId":"7f685ff7-c08c-5ecf-9281-ed6cdc740930","questionId":"8e0dbcba-a35b-544e-bd96-c322c8c0e451","sourceKey":"bank:ECO101:ECO-0143","payload":{"prompt":"If less of a good is preferred to more, then the good is","options":["a bad","an economic good","when needed","desirable only"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"A 'bad' is something a consumer prefers less of, such as pollution or garbage. Option B, an economic good, is something people want more of and that is scarce. Options C and D do not describe goods people prefer less of."}},{"itemId":"6567aaa2-e286-55af-8be9-5cb18475e75b","questionId":"82dfafe7-e7c5-58ee-8193-26310b37aae2","sourceKey":"bank:ECO101:ECO-0144","payload":{"prompt":"________ relates quantity of goods consumed to income of the consumer","options":["Engel curve","Angel curve","Lorenz curve","none of the above"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"The Engel curve relates the quantity of a good consumed to the consumer's income. Option B is just a misspelling, and option C, the Lorenz curve, shows how income is distributed across a population."}},{"itemId":"ab39d598-f7ef-5437-8071-743dc6759e41","questionId":"f78aaf42-5944-5f65-adb2-8cdef0eeadf0","sourceKey":"bank:ECO101:ECO-0145","payload":{"prompt":"The difference between what a consumer is willing to pay for a commodity rather than do without the good and the amount actually paid is","options":["just price","price differentials","consumer surplus","price gain"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Consumer surplus is the gap between the most a consumer would be willing to pay for a good and the price actually paid; it is the extra benefit the buyer enjoys. Options A and D sound similar but are not economic terms for this gap, and option B (price differentials) refers to differences between prices, not to the buyer's gain."}},{"itemId":"64b60ee6-1342-59b0-9481-8c3f5f0ddb0b","questionId":"4d575869-a2f5-546c-a709-15a3d00b9295","sourceKey":"bank:ECO101:ECO-0146","payload":{"prompt":"The aspiration to buy because others are buying is ________ effect","options":["spendthrift","frugal","snob","bandwagon"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"The bandwagon effect happens when people buy a good simply because others are buying it, so demand rises with the number of buyers. Option C, the snob effect, is the opposite: some consumers buy less of a good once it becomes popular. Spendthrift and frugal describe spending habits, not this effect."}},{"itemId":"def423c9-5e62-5143-9d27-0c735afaa451","questionId":"dc0f66fa-52bb-5847-aaa7-22f84abaef35","sourceKey":"bank:ECO101:ECO-0149","payload":{"prompt":"Marginal rate of substitution represents","options":["the arc of the indifference curve","the slope of the indifference curve","indifference maps","the total utility of the consumer"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The marginal rate of substitution (MRS) is the rate at which a consumer gives up one good for another while staying equally satisfied, which is exactly the slope of the indifference curve. Option A (an arc) is a section of the curve, not the rate, and option C (indifference maps) is a whole set of curves. Total utility (option D) is the satisfaction level itself, not a rate of exchange."}},{"itemId":"7819524a-6c2a-5170-bdb9-dd86ff5de8a9","questionId":"2cda61fb-6bbe-5af3-a371-7a76109067e8","sourceKey":"bank:ECO101:ECO-0150","payload":{"prompt":"The slope of the total utility curve is","options":["upward","quasi-concave","constant","the marginal utility"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Marginal utility is the change in total utility from one more unit, so it is the slope of the total utility curve. Option A is only true while marginal utility is positive; once MU becomes negative the TU curve slopes downward. Option C is wrong because diminishing MU means the slope keeps changing."}},{"itemId":"1c0d0aec-0803-59fa-85a7-542af28e601b","questionId":"df0a0014-015f-51b6-b57f-8829e3d73180","sourceKey":"bank:ECO101:ECO-0151","payload":{"prompt":"When total utility is maximum, marginal utility will be","options":["positive","negative","zero","greater than unity"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Total utility keeps rising as long as each extra unit adds positive satisfaction, so it reaches its peak exactly where marginal utility falls to zero. Option A describes the stage where TU is still rising, and option B describes the stage after the peak, when TU is falling."}},{"itemId":"ed2b12a9-120c-5fd8-b2a5-cea25a30ddda","questionId":"76da59c4-e00c-51ee-b80e-7983b20af09a","sourceKey":"bank:ECO101:ECO-0152","payload":{"prompt":"Consumer is assumed to maximize satisfaction subject to","options":["availability of goods","budget constraint","number of sellers in the market","his wants which are insatiable"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A rational consumer tries to get the highest satisfaction possible, but only with the income available at given prices, which is the budget constraint. Option D is wrong because insatiable wants are the reason choice is needed, not the limit on it. Options A and C may affect the market but are not the constraint in consumer theory."}},{"itemId":"2b72a0a5-1bb6-5245-8b28-9f4c2414dccc","questionId":"8b99afc5-8e76-58d2-b860-5fc85b8f7243","sourceKey":"bank:ECO101:ECO-0153","payload":{"prompt":"Use the information: Suppose consumer utility is given as U = XY. The price of X and Y are #4 and #8 respectively. And the consumer's income is #240. What is the quantity of X the consumer should purchase at equilibrium?","options":["20","40","25","30"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"At equilibrium MUx/Px = MUy/Py, so Y/4 = X/8, giving X = 2Y. Putting this in the budget 4X + 8Y = 240 gives 4(2Y) + 8Y = 240, so Y = 15 and X = 30. Option C (25) or B (40) come from slips in substituting into the budget, and 20 ignores the equilibrium condition."}},{"itemId":"301ad8a1-9b59-5af8-bb4d-05ef7130996a","questionId":"7d73db83-1621-5981-9e8c-ea8361531681","sourceKey":"bank:ECO101:ECO-0154","payload":{"prompt":"Use the information: Suppose consumer utility is given as U = XY. The price of X and Y are #4 and #8 respectively. And the consumer's income is #240. What is the quantity of Y the consumer should purchase at equilibrium?","options":["15","20","25","30"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"With U = XY, equilibrium needs Y/4 = X/8, so X = 2Y. Substituting into 4X + 8Y = 240 gives 16Y = 240, so Y = 15 (and X = 30). Option D (30) is the quantity of X, not Y, which is the most common mix-up here."}},{"itemId":"450b5edf-990f-59d2-956d-af5743512a0e","questionId":"493ef1a1-0cea-5109-b0ed-59b6a6f0c46e","sourceKey":"bank:ECO101:ECO-0155","payload":{"prompt":"Use the information: Suppose consumer utility is given as U = XY. The price of X and Y are #4 and #8 respectively. And the consumer's income is #240. What is the value of lambda (the marginal utility of money) at equilibrium?","options":["3.5","3.6","3.75","3.66"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Lambda is the marginal utility of money, equal to MUx/Px = MUy/Py at the optimum. With X = 30 and Y = 15, MUx = Y = 15, so lambda = 15/4 = 3.75 (check: MUy/Py = 30/8 = 3.75). Options B and D are rounding-style guesses that do not match this exact value."}},{"itemId":"95608886-cf90-5cd8-878f-a8f363a632c6","questionId":"cdbe705f-bfb2-56ad-9d56-83d6eec14479","sourceKey":"bank:ECO101:ECO-0157","payload":{"prompt":"Use the information: Suppose consumer utility is given as U = XY. The price of X and Y are #4 and #8 respectively. And the consumer's income is #240. What is the marginal rate of substitution (MRS) of X for Y at the consumer's equilibrium?","options":["2","1/2","3/4","3/5"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"For U = XY, the MRS of X for Y is MUx/MUy = Y/X. Spending half of the #240 income on each good gives X = 120/4 = 30 and Y = 120/8 = 15, so MRS = 15/30 = 1/2, which matches the price ratio Px/Py = 4/8. Option A (2) is the ratio turned upside down, X/Y."}},{"itemId":"a54b5dcd-12db-5786-9532-0db966d53d0a","questionId":"3ee40077-61a3-5b8d-9912-3719cdd14365","sourceKey":"bank:ECO101:ECO-0178","payload":{"prompt":"The total effect of price change can be divided into.","options":["Income and substitution effect","price and income effect","quantity and price effect","income and competitive effect"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"When the price of a good changes, the total effect on quantity demanded can be split into the substitution effect (the good becomes relatively cheaper or dearer than others) and the income effect (the change in real purchasing power). Option B mixes up the cause, the price change, with one of its effects."}},{"itemId":"5674d032-83da-5198-abe6-6abbf4959d63","questionId":"2929d0cf-cfcf-5985-be72-78e8bc476acf","sourceKey":"bank:ECO101:ECO-0195","payload":{"prompt":"Which of the following best explains Engel curve for luxury goods","options":["Continuous increases in income make expenditure to first increase rapidly but become less proportional to the increase in income","Continuous increases in income make expenditure to first increase slowly but become less proportional to the increase in income","Continuous increases in income make expenditure to first decrease rapidly but become less proportional to the increase in income","Continuous increases in income make expenditure to first increase slowly but later increase more rapidly than the increase in income"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"For a luxury good, spending rises more than proportionally as income keeps rising, so the Engel curve starts slowly and then climbs faster than income. Options A and B describe spending that becomes less proportional to income, which is the pattern for necessities, and option C wrongly has spending falling."}},{"itemId":"297a9967-f9ec-542a-b230-fa51a439db77","questionId":"03f5b3d4-10dc-52fa-841f-b9fc5a202833","sourceKey":"bank:ECO101:ECO-0196","payload":{"prompt":"Why does the demand curve traditionally slope downward from left to right? The reason is","options":["consumer's equilibrium","consumer's equilibrium and consumer's choice","Diminishing marginal utility","consumer's choice."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Because each extra unit gives less additional satisfaction (diminishing marginal utility), a consumer will only buy more units if the price falls, which gives the downward-sloping demand curve. Options A and D describe the result of the consumer's decision, not the reason demand slopes down, so option B, which combines them, is also wrong."}},{"itemId":"0192e4b6-7685-5603-852c-f50f56c2a86e","questionId":"3edddb26-0733-56c7-bcf5-107d87c233e0","sourceKey":"bank:ECO101:ECO-0199","payload":{"prompt":"For a normal commodity, the substitution effect of a price change is ----","options":["zero","Positive","constant","negative"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"The substitution effect always moves quantity demanded in the opposite direction to the price change: when a good becomes dearer relative to others, people buy less of it. This inverse relationship is called a negative substitution effect, so option B is wrong. Options A and C would mean price changes have no effect on choice, which is not the case."}},{"itemId":"f2470535-eb42-5dd9-83b1-91146f5a41bd","questionId":"f81a2cde-6a85-5ca1-9417-18b93666a9e6","sourceKey":"bank:ECO101:ECO-0201","payload":{"prompt":"Perfect complements will have indifference curves that are","options":["vertical.","L-shaped.","concave to the origin.","straight lines."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Perfect complements are goods used in fixed proportions, like left and right shoes, so extra units of one without the other add no satisfaction. This makes the indifference curves L-shaped. Option D, straight lines, describes perfect substitutes instead."}},{"itemId":"855595d3-c0ad-52e7-b3bc-f4ca66383d51","questionId":"a99ff5ad-5082-546a-9007-be525dc6f478","sourceKey":"bank:ECO101:ECO-0202","payload":{"prompt":"A producer's price elasticity of demand is greater than 1. What will happen to his total revenue if the price of his product is reduced by 5 percent?","options":["It will be unchanged","It will rise","It will fall by more than 5 percent","It will fall to zero"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"When demand is elastic (Ed > 1), a 5 percent price cut raises quantity demanded by more than 5 percent, so total revenue rises. Option A is the unit-elastic case, where the two percentage changes cancel out. Option C cannot happen here: even with inelastic demand, a 5 percent price cut makes revenue fall by less than 5 percent, because quantity still rises a little."}},{"itemId":"a5050d0c-2bd0-5a1f-8d81-58bd31aea406","questionId":"fd1e6cac-3d9c-5be7-a0f6-f387fabc37f8","sourceKey":"bank:ECO101:ECO-0204","payload":{"prompt":"Diminishing marginal rate of substitution necessarily implies that the marginal rate of substitution","options":["falls as one travels down (eastward) along an indifference curve.","decreases as the quantities of both goods increase","stays the same as one travels up (westward) along an indifference curve.","falls as one travels up (westward) along an indifference curve."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Diminishing MRS means that as a consumer moves down an indifference curve, getting more of the good on the horizontal axis, she is willing to give up less and less of the other good for each extra unit, so the MRS falls. Option D gets the direction wrong, and option C would mean a constant MRS, as with perfect substitutes."}},{"itemId":"e2d6e8ec-ab1b-53ca-a948-f4d788140ba2","questionId":"b2882536-ad84-58a2-88b7-ebf5995c4a04","sourceKey":"bank:ECO101:ECO-0208","payload":{"prompt":"In the ordinal approach to the theory of consumer behavior, which among the following are objective factors","options":["Price and income","Taste and preferences","Price and preferences","Income and preferences"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"In indifference curve analysis, prices and income are objective, measurable facts that define the budget line, while tastes and preferences are subjective and are shown by the indifference curves. Options B, C and D all include preferences, which are subjective."}},{"itemId":"010e6354-df12-53d1-9c65-1e023845ae31","questionId":"982e1d2d-411f-5ee8-a0fc-a5cd54d2aacf","sourceKey":"bank:ECO101:ECO-0210","payload":{"prompt":"If the demand for electricity is inelastic, then when the price of electricity increases, revenues will:","options":["decrease, because consumers will switch to substitutes","increase","decrease","remain the same"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"When demand is inelastic, quantity falls by a smaller percentage than the price rises, so total revenue increases after a price rise. Option A gets this backwards, since inelastic demand means buyers do not switch away much. Option C is the result for elastic demand, and option D is the unit-elastic case."}},{"itemId":"38e43f91-d24d-5609-95eb-28d3262948f9","questionId":"8cf5ad64-77a2-5db8-a937-7b56e665b7e1","sourceKey":"bank:ECO101:ECO-0211","payload":{"prompt":"The consumer surplus can be defined as","options":["The difference between the total amount paid and the total utility gained","The total amount consumers paid and total utility gained","The sum of the total prices paid by the consumers","The difference between the amount consumers would be willing to pay and the amount paid"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Consumer surplus is the difference between what consumers are willing to pay for a good and what they actually pay. Options A and B compare money paid with utility, which are not measured in the same units, and option C is simply total spending."}},{"itemId":"83849cf4-0890-59d0-9405-f5cc63c33fe4","questionId":"0490ba0a-40a7-51ca-82ea-f4ac9f1c1b7f","sourceKey":"bank:ECO101:ECO-0212","payload":{"prompt":"Ugo and Idowu live in the same town where they both face the same prices. Ugo has preferences that can be represented by the utility function U(X,Y)=X+Y. Idowu has preferences that can be represented by the utility function V(X,Y)=3X+3Y. Which of the following statement is true?","options":["The quantity of X purchased by Ugo PLUS the quantity of X purchased by Idowu will equal the total quantity of Y they purchase.","Idowu gets greater satisfaction from her consumption than Ugo","A tax on X would have a greater welfare effect on Idowu than on Ugo","Idowu and Ugo have identical preferences, ranking every bundle of X and Y in the same order"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"V = 3X + 3Y is just U = X + Y multiplied by 3, so Ugo and Idowu rank every bundle in exactly the same order, meaning they have the same preferences. Option B is wrong because utility numbers cannot be compared between people, and option C has no basis because their preferences are identical. Option A has no economic reason to hold."}},{"itemId":"c21dd744-f622-5f61-8e85-ef0cefb601ca","questionId":"dea691ea-a2ce-5bcd-a783-ee2538e056ef","sourceKey":"bank:ECO101:ECO-0213","payload":{"prompt":"Which of the following shifts the supply curve leftward?","options":["An improvement in technology that decreases the cost of production.","An anticipated drought that will make inputs more expensive.","A decrease in the wage rate.","An increase in the number of suppliers."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Supply shifts left when producing becomes more costly, and an expected drought that pushes up input prices does exactly that. Options A, C and D all lower costs or add more sellers, which shift supply to the right."}},{"itemId":"8be91e1d-7414-58f7-a808-c75d7d50d337","questionId":"83ed2858-d1c5-5506-80e2-5a31d4b0a2ae","sourceKey":"bank:ECO101:ECO-0214","payload":{"prompt":"Which of the following best explains Engel curve for necessities?","options":["Continuous increases in income make expenditure to first decrease rapidly but become less proportional to the increase in income","Continuous increases in income make expenditure to first increase rapidly but become less proportional to the increase in income","Continuous increases in income make expenditure to first decrease rapidly but later increase more than the income","Continuous increases in income make expenditure to first increase rapidly but later increase more than the income"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"For a necessity, spending rises with income but by a smaller proportion, so the Engel curve rises quickly at first and then flattens out. Option D describes a luxury, where spending eventually grows faster than income, and options A and C wrongly have spending falling."}},{"itemId":"b2d337c5-a2cb-59d0-a87f-6fef2ef64636","questionId":"d7df7043-9678-525c-8fa7-df0a1ea6997f","sourceKey":"bank:ECO101:ECO-0215","payload":{"prompt":"A rightward shift of the demand curve occurs (and demand increases) when:","options":["price falls","the price of an input used in its production falls","the price of a complementary good falls.","Incomes fall"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"When a complementary good becomes cheaper, people buy more of it and so want more of the good used with it, shifting its demand curve to the right. Option B is wrong because a cheaper input lowers production costs, which shifts supply, not demand. Option A causes a movement along the curve, and option D shifts demand left for a normal good."}},{"itemId":"4886ee4f-88c0-550f-a23d-5df0bd9ae8b7","questionId":"1bae026f-c05d-576b-b54d-88666e939cf9","sourceKey":"bank:ECO101:ECO-0220","payload":{"prompt":"If markets for some addictive drugs are found to have a higher price-elasticity of demand than was often thought, and if many addicts have difficulty holding down steady, well-paying jobs, we might speculate that the most likely reason for the surprising elasticity estimates is that:","options":["the substitution effect is smaller than expected.","the income effect is larger than expected.","the income and substitution effects work in opposite directions.","addictive drugs are inferior goods."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"If addicts have low and unstable incomes, the drug takes a large share of their budget, so a price rise cuts their real income a lot and they buy noticeably less. This bigger-than-expected income effect makes demand more elastic. Option A would make demand less elastic, not more, and option D is not supported by the facts given."}},{"itemId":"d5f80c7c-6846-55e2-bebc-88cb27a3ed67","questionId":"a0d93334-82c7-5458-b6e7-a1233f2db501","sourceKey":"bank:ECO101:ECO-0221","payload":{"prompt":"When total utility is declining, marginal utility is -----:","options":["Zero","Negative","Positive","Rising"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Marginal utility is the change in total utility from one more unit, so when total utility is falling, each extra unit is reducing satisfaction and MU is negative. Option A applies only at the exact peak of total utility, and option C applies while total utility is still rising."}},{"itemId":"3b45e501-3244-5a89-85d2-e55a4d26608d","questionId":"f22c6d68-6588-579a-9807-2f1ea9abcb66","sourceKey":"bank:ECO101:ECO-0228","payload":{"prompt":"Given that the demand for a commodity is Q= 200 - 4.5P, where Q is quantity demanded and P is price, find own price elasticity of demand when price is N10:","options":["0.20","0.29","none of the above","0.28"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"At P = 10, Q = 200 - 4.5(10) = 155. Price elasticity is Ed = (dQ/dP) x (P/Q) = 4.5 x 10/155 = 0.29 in absolute value. Option D (0.28) is a rounding slip, and option A (0.20) would come from using the wrong quantity."}},{"itemId":"d48eb03b-07fa-5df5-9e75-27bf92157d83","questionId":"fe33fb75-e771-5c9b-9c33-09c57aa5bf4a","sourceKey":"bank:ECO101:ECO-0229","payload":{"prompt":"The cross elasticity of two goods X and Y is zero. This means that X and Y are:","options":["X and Y are complements","X and Y are substitutes","X and Y are NOT strongly related","none of the above"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A cross elasticity of zero means a change in the price of one good has no effect on demand for the other, so the goods are unrelated (independent). Option B needs a positive cross elasticity, and option A needs a negative one."}},{"itemId":"690f755b-6d39-50ff-aedd-48a082bf92e2","questionId":"c3572255-e0f7-538e-bcf1-6b3f79fa0725","sourceKey":"bank:ECO101:ECO-0230","payload":{"prompt":"Paul likes two scoop of vanilla ice cream for every chocolate scoop. He gets no extra utility for an additional chocolate scoop if He doesn't have two additional vanilla scoops and no extra utility for extra vanilla scoops without the appropriate amount of chocolate. His utility function can be represented by:","options":["U(c, v) = min{c, 2v}","U(c, v) = c + 2v","U(c, v) = 2c + v","U(c, v) = min{2c, v}"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Paul wants vanilla and chocolate in a fixed ratio of 2 vanilla to 1 chocolate, so they are perfect complements and utility is a min function. With U = min{2c, v}, one chocolate and two vanilla give 2c = v = 2, and extra units of either alone add nothing. Option A gets the ratio backwards, and options B and C are perfect-substitute functions."}},{"itemId":"c945093a-7664-5b46-bdf1-67215ce86621","questionId":"fb391f60-cf9b-5b7e-9c5d-6a403e2b1a0e","sourceKey":"bank:ECO101:ECO-0231","payload":{"prompt":"The income effect of a change in price shows that","options":["As price increases, real income increases as quantity increases","As price increases, real income increases as quantity decreases","As price decreases, real income decreases as quantity increases","As price decreases, real income increases as quantity increases"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"When price falls, the consumer's money income buys more, so her real income rises and she can afford more of the good (for a normal good). Option A wrongly says real income rises when price increases, and option C wrongly says it falls when price decreases."}},{"itemId":"d2f10a8d-a2f5-53f6-b71c-c2dcbb2bdb0e","questionId":"362acbfc-7b35-5391-8097-b863b4c16673","sourceKey":"bank:ECO101:ECO-0233","payload":{"prompt":"Along a given indifference curve:","options":["Both the combination of goods and the consumer's income remain constant","The combination of goods remains constant but the level of utility varies","The combination of goods remains constant","The combination of goods varies but the level of utility remains constant"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"An indifference curve joins different combinations of two goods that all give the consumer the same satisfaction, so the bundles change but utility stays constant. Option B has this backwards, and options A and C wrongly suggest the combination of goods is fixed."}},{"itemId":"e54a844a-fd72-5638-a57e-d99f218e3035","questionId":"bf520340-f60c-51bb-a5ad-cc3b55f5efed","sourceKey":"bank:ECO101:ECO-0236","payload":{"prompt":"Change in supply can be caused by","options":["Change in level of technology.","Change in cost of production.","Both A and B","Change in price of the good"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A change in supply means the whole supply curve shifts, and this is caused by non-price factors such as technology and production costs, so both A and B are correct. Option D is wrong because a change in the good's own price causes a movement along the curve, called a change in quantity supplied."}},{"itemId":"091cc260-1e77-5d09-bc51-88c562862a7a","questionId":"2a0463f0-3c01-5438-889d-afa969f881c4","sourceKey":"bank:ECO101:ECO-0240","payload":{"prompt":"A decrease in supply when demand remains the same will make the equilibrium","options":["P to fall while Q rise","P and Q to both fall","P to rise while Q fall","P and Q to both rise"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A decrease in supply shifts the supply curve to the left along an unchanged demand curve, so the new equilibrium has a higher price and a lower quantity. Option A describes an increase in supply, and option B describes a fall in demand."}},{"itemId":"430369a6-adfa-5251-b537-37b85bfdae5b","questionId":"fbc5b8b5-b749-5d16-9611-3d041bff0aec","sourceKey":"bank:ECO101:ECO-0242","payload":{"prompt":"________ is a positively sloped curve while ________ is a negatively sloped curve","options":["Demand, supply","Equilbrium supply, Equilbrium demand","Equilbrium demand, Equilbrium supply","Supply, demand"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"The supply curve slopes upward (positively) because higher prices encourage more production, while the demand curve slopes downward (negatively) because people buy more at lower prices. Option A reverses the two, and options B and C are not standard curves."}},{"itemId":"bbb4d6db-0bae-51f2-bf32-784d5c335975","questionId":"49c33aef-b136-51b1-b17a-1b7fcb6660f6","sourceKey":"bank:ECO101:ECO-0243","payload":{"prompt":"________ is the quantity of goods and services a consumer is willing and able to purchase at given price in given period of time.","options":["Needs","Supply","Desires","Demand"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Demand is the quantity of a good or service consumers are willing and able to buy at a given price over a given period. Options A and C, needs and desires, lack the 'able to pay' part, and option B describes the sellers' side."}},{"itemId":"9257dfe4-32b6-5bee-b7e6-6a16b26bbc16","questionId":"2112fb99-789e-5dc4-9acf-b76e0b020426","sourceKey":"bank:ECO101:ECO-0244","payload":{"prompt":"Any price below the equilibrium price will lead to ________ which is also referred to as ________","options":["Excess demand, shortage","Excess supply, shortage","Excess supply, surplus","Excess demand, surplus"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Below the equilibrium price, buyers want more than sellers offer, so there is excess demand, also called a shortage. Option C describes a price above equilibrium, and options B and D mix up the two terms."}},{"itemId":"1d50f0d2-ec84-51ae-a8d8-98287bafae03","questionId":"064b39cd-cfe0-519c-b9b2-22da84e208ba","sourceKey":"bank:ECO101:ECO-0245","payload":{"prompt":"For a single commodity, consumer equilibrium is where","options":["MUx = MUy","MUx = Px","MUy = Px","MUx = Py"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"With a single commodity and the marginal utility of money taken as one, the consumer keeps buying until the satisfaction from the last unit equals its price, so MUx = Px. Option A applies when comparing two goods, and options C and D wrongly match one good's utility with another good's price."}},{"itemId":"5e590b72-501c-527f-a949-cac8ad7c803a","questionId":"0c8262f3-5692-59fb-94b6-8d9bf9cc1004","sourceKey":"bank:ECO101:ECO-0248","payload":{"prompt":"All of the following have a negative slope, except","options":["demand curve","aggregate demand curve","supply curve","production possibility curve"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"The supply curve slopes upward because sellers offer more at higher prices. The demand curve, the aggregate demand curve and the production possibility curve all slope downward, so options A, B and D do have a negative slope."}},{"itemId":"05338930-5021-59e9-b354-f9ef03dfa6e9","questionId":"caa862a5-004c-5a91-929b-0593e462bfe1","sourceKey":"bank:ECO101:ECO-0249","payload":{"prompt":"A shift in demand curve is the same as","options":["Change in all factor.","Change in demand","Change in quantity supplied","Change in price"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A shift of the whole demand curve is called a change in demand and is caused by factors other than the good's own price, such as income or tastes. Option D, a change in price, causes a movement along the curve, and option C is about supply."}},{"itemId":"63104cb8-28be-52f3-b186-55bd6edea672","questionId":"18eb4468-af6b-594f-86d7-83e42349580c","sourceKey":"bank:ECO101:ECO-0255","payload":{"prompt":"The first law of demand assumes that","options":["Price can influence demand while other determinants are held constant.","Price is the only determinant of demand.","Price is held constant while other determinants of demand are allowed to influence demand.","Price and other factors influence demand."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"The law of demand looks at how price affects quantity demanded while assuming other determinants, like income and tastes, stay constant (ceteris paribus). Option B is wrong because price is not the only determinant; the others are only held fixed. Option C reverses the assumption."}},{"itemId":"b24bf09f-1a7a-5865-9b93-5c34cae9852d","questionId":"416e042e-2433-5ed5-b31d-f3226dfdfd0a","sourceKey":"bank:ECO101:ECO-0260","payload":{"prompt":"One of the following is not a property of an indifference curve","options":["It gives the same level of satisfaction at all points on the curve","It slopes downward from left to the right","It has no shape for some commodities","Two indifference curves do not intersect"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"An indifference curve shows equal satisfaction at every point, slopes downward, and two indifference curves never cross, so options A, B and D are genuine properties. Option C is not a property, since every indifference curve has a definite shape, usually convex to the origin."}},{"itemId":"74002e8d-9181-5817-819e-3e08a32769f8","questionId":"f364a78f-112e-55ae-a451-57e5ac57b653","sourceKey":"bank:ECO101:ECO-0263","payload":{"prompt":"The school of thought that is of the opinion that utility is measurable is referred to as?","options":["Ordinalist","Cardinalist","Consumer school","Measurability"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The cardinalists, associated with Marshall, held that utility can be measured in units (utils). Option A, the ordinalists, argued that utility can only be ranked, not measured, which is the basis of indifference curve analysis."}},{"itemId":"7b882210-318f-59e9-b2dc-1926a607304a","questionId":"d2121cd2-726b-52bf-afef-4e8fe57ad2a5","sourceKey":"bank:ECO101:ECO-0282","payload":{"prompt":"These are all properties of indifference curve (IC) except","options":["IC is convex to the origin","Higher IC signifies a higher level of satisfaction","The slope of IC is marginal rate of technical substitution","The slope of IC is marginal rate of substitution"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"The slope of an indifference curve is the marginal rate of substitution between two goods, not the marginal rate of technical substitution, which is the slope of an isoquant in production. Options A, B and D are true properties: indifference curves are convex, higher curves mean more satisfaction, and the slope is the MRS."}},{"itemId":"4e5497d4-02c1-5af6-85cb-e0c862767c46","questionId":"e383202b-a10e-5159-8313-ad22f71141d8","sourceKey":"bank:ECO101:ECO-0289","payload":{"prompt":"Suppose that marginal utility of good X=100, the price of X=N10 per unit and the price of good Y=N5. Assuming that the consumer is in equilibrium by consuming both good X and Y, what will the marginal utility of Y be?","options":["40","10","200","50"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"In equilibrium the consumer sets MUx/Px = MUy/Py, so 100/10 = MUy/5. That gives 10 = MUy/5, so MUy = 10 x 5 = 50. Option B (10) is only the ratio MU per naira, and option C (200) comes from inverting the price ratio."}},{"itemId":"cbc4a707-e904-52c0-b16b-17b941052035","questionId":"3e18b024-302b-50c3-93a0-ac0252dbdb22","sourceKey":"bank:ECO101:ECO-0291","payload":{"prompt":"Suppose a rational consumer earns the income of N200 per month and he spends N60 on food which is a necessity and the remaining on other goods and services. Assuming the price of food now increases, what will happen to the consumer's allocation of funds, considering that the demand for food is price inelastic?","options":["The consumer will spend a larger part of his income on food and less on other goods","The consumer will reduce his quantity of food consumption but increase consumption of other goods","The consumer will spend less on food because he buys much less of it","The consumer will increase the quantity of his consumption"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"With price-inelastic demand, quantity bought falls by a smaller percentage than the price rises, so total spending on food goes up. Out of a fixed N200 income, that leaves less for other goods and services. Option C would only happen if demand for food were elastic, and option B is wrong for the same reason, since spending on food rises rather than falls."}},{"itemId":"216251b8-e13e-5602-8d82-9df56766117b","questionId":"2f9e844e-40f2-53bc-b641-18db714f9b97","sourceKey":"bank:ECO101:ECO-0379","payload":{"prompt":"The law of demand states that","options":["The quantity demand is directly related to the commodity's price","At lower prices a lower quantity will be demanded and vice versa","At higher prices, lower quantities will be demanded and vice versa","At higher prices, a higher quantity will be demanded and vice versa"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"The law of demand states that, other things being equal, the higher the price the lower the quantity demanded, and the lower the price the higher the quantity demanded. Options A and D describe a direct relationship, which is the law of supply, and option B wrongly links lower prices with lower quantities."}},{"itemId":"3b011231-eeab-5db7-b19f-ba61363f63fc","questionId":"8e5bdf27-cfe9-50dc-89a8-7d2446f30c3c","sourceKey":"bank:ECO101:ECO-0382","payload":{"prompt":"A movement down a demand curve is called","options":["An increase in demand","A decrease in demand","A decrease in quantity demanded","An increase in the quantity demanded"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Moving down along a demand curve means the price has fallen and buyers respond with a larger quantity, which is an increase in quantity demanded. Option A is tempting, but an increase in demand means the whole curve shifts to the right, not a movement along it. Option C is the opposite, a movement up the curve."}},{"itemId":"e2d4b09d-a1e5-563c-8230-6da79a02e07b","questionId":"97221ec0-6e4f-56d7-9670-07560b8a03bb","sourceKey":"bank:ECO101:ECO-0385","payload":{"prompt":"Supply curve will shift downwards if","options":["Prices of factor inputs fall on the average","Technology improves","Price of other commodities fall on the average","Any of the above occurs."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A supply curve shifts downward (to the right) when it becomes cheaper or more attractive to produce the good at each price. Cheaper inputs (A) and better technology (B) both cut costs, and falling prices of other goods (C) make producers switch resources into this good, so any of these would shift supply."}},{"itemId":"fdfd0040-dd6e-5f9e-9e46-d75ceb599e26","questionId":"174357ca-1979-5712-b686-196597d9dc10","sourceKey":"bank:ECO101:ECO-0386","payload":{"prompt":"Demand curve would shift outward definitely if","options":["Household income rises generally","Average price of substitute good falls","Average price of compliments rises","Any of the above"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"For a normal good, a general rise in household income increases demand at every price, shifting the demand curve outward. Option B is wrong because a cheaper substitute pulls buyers away, shifting demand inward. Option C is also wrong because a dearer complement reduces demand, so D cannot be right."}},{"itemId":"a091fc79-9f9b-515d-9240-5e1ad75432b1","questionId":"02a54fa9-351f-5f9d-bcb5-7649b94818a4","sourceKey":"bank:ECO101:ECO-0387","payload":{"prompt":"The marginal utility theory assumes","options":["Budget constraint","Diminishing marginal utility","Utility maximisation by the consumer","All of the above"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Marginal utility theory assumes the consumer has a limited budget (A), that each extra unit gives less satisfaction (B), and that the consumer aims to maximise total utility (C). Since all three are assumptions of the theory, D is correct."}},{"itemId":"8cfcb52b-0015-51ed-be82-de9a3c598877","questionId":"62977eab-0e7f-5846-8d89-72b37596089c","sourceKey":"bank:ECO101:ECO-0388","payload":{"prompt":"One of the following does not belong to the group. Which is it?","options":["Utility","Income - consumption line","Price - consumption line","Budget line"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"The income-consumption line, the price-consumption line and the budget line are all lines drawn in indifference curve analysis, so utility is the odd one out. Utility is a general concept of satisfaction rather than a line on the indifference diagram. Option D, the budget line, is tempting, but it belongs with the other two."}},{"itemId":"bacc6b02-f743-51ae-9bd8-67fcc2161599","questionId":"fde53fd4-fc56-5577-9a9f-ed401a0b4d01","sourceKey":"bank:ECO101:ECO-0389","payload":{"prompt":"The purpose of indifference curve analysis is:","options":["To prove the law of diminishing utility","To derive a theory of producer behaviour","To prove that the demand curve for all commodities is negatively sloped","To derive a theory of consumer behaviour without requiring cardinal utility measurement"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Indifference curve analysis explains consumer behaviour using only the ranking of preferences (ordinal utility), so it does not need utility to be measured in numbers. Option A is wrong because the approach avoids measuring utility, and option B is wrong because it is about consumers, not producers. Option C is wrong because the analysis allows exceptions such as Giffen goods."}},{"itemId":"0fdd8156-de04-5aa4-a978-16f7ed200481","questionId":"a13c1bde-a581-53b4-89a5-5f277666b078","sourceKey":"bank:ECO101:ECO-0395","payload":{"prompt":"The market price of a commodity is determined by","options":["Household demand","Household income","The excess demand (qd - qs)","Transport cost"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Market price adjusts through excess demand (qd - qs): when it is positive, buyers bid the price up, and when it is negative, sellers cut prices until qd = qs at equilibrium. Option A is only half the story, since household demand alone ignores supply. Options B and D can affect demand or supply, but they do not set the market price directly."}},{"itemId":"2fad35c2-d0c6-52f0-a0cf-aa36f0c6c3c9","questionId":"06a072f7-fdbc-5232-8d04-00c1e4570954","sourceKey":"bank:ECO101:ECO-0400","payload":{"prompt":"One of the most important determinants of elasticity is:","options":["The degree of availability of close substitute","The degree of specificity of various commodities","The cost of production of various commodities","The difference in prices"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"The more close substitutes a good has, the more elastic its demand, because buyers can easily switch when its price rises. Option C, cost of production, affects supply rather than how buyers respond to price. Options B and D are not standard determinants of elasticity."}},{"itemId":"d9d115b6-0935-5f59-9074-df3fd0d93a0f","questionId":"fca038bc-bc91-5b59-a07a-2529aac8f498","sourceKey":"bank:ECO101:ECO-0406","payload":{"prompt":"The normal demand curve is:","options":["Skewed to the left","Positively sloped","Skewed to the right","negatively sloped"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"The demand curve slopes downward from left to right (negatively sloped), because more is bought at lower prices. Option B, positively sloped, is the shape of a normal supply curve. Options A and C describe skewness, which is a statistics term, not the slope of a demand curve."}},{"itemId":"d694788e-bc08-532f-994c-ff08bf7056e9","questionId":"b221dd44-3b35-5608-a2fc-c889cac44ea9","sourceKey":"bank:ECO101:ECO-0407","payload":{"prompt":"The responsiveness of supply to changes in price is known as:","options":["Elasticity of supply","Cross elasticity","Income elasticity","Elasticity of demand"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Elasticity of supply measures how much the quantity supplied responds to a change in the good's price. Option D, elasticity of demand, measures the response of buyers rather than sellers. Options B and C measure responses to other prices and to income."}},{"itemId":"f8e410da-a3e1-55d9-a5f0-2cc199b9d474","questionId":"e3454437-a22b-57d9-bf07-d9e235a02872","sourceKey":"bank:ECO101:ECO-0408","payload":{"prompt":"What does positive cross-elasticity of demand imply?","options":["Goods are supplements","Goods are jointly demanded","Goods are complements","Goods are substitutes"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A positive cross elasticity means that when the price of one good rises, demand for the other rises too, which happens with substitutes such as Coke and Pepsi. Options B and C, jointly demanded goods and complements, have a negative cross elasticity. Option A is not a standard term in this context."}},{"itemId":"4d9806d3-00ff-584c-9325-8f51c127b98e","questionId":"3cfbb8cb-3aee-5673-bd0f-47f99376d45f","sourceKey":"bank:ECO101:ECO-0409","payload":{"prompt":"If the price of a given item is substantial in relation to the consumer's income, demand for it tends to be:","options":["Zero elastic","Infinite","Elastic","Inelastic"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"When a good takes a large share of the consumer's income, a price rise hurts a lot, so buyers cut back noticeably and demand is elastic. Option D is the case for cheap items like salt or matches that take a tiny share of income. Options A and B are extreme cases that do not follow from this."}},{"itemId":"85183e24-0c65-591b-be17-b1589784361c","questionId":"de164f67-b5cf-5bbc-96f5-2f3d23cd3e0d","sourceKey":"bank:ECO101:ECO-0412","payload":{"prompt":"The relation between the changes in demand for one product with respect to changes in the price of another is termed:","options":["Cross elasticity","Supply elasticity","Income elasticity","Demand elasticity"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Cross elasticity of demand measures how the demand for one product responds to a change in the price of another. Option D, demand elasticity, usually means the response to the good's own price. Option C, income elasticity, is the response to a change in income."}},{"itemId":"ae9b73ed-2f32-587a-b56c-31ebe9d3f595","questionId":"fd85905f-96fd-5c7d-a1bc-fc5144515540","sourceKey":"bank:ECO101:ECO-0413","payload":{"prompt":"If a good is considered \"inferior\" then","options":["As its price falls, more of it will be purchased","As the consumer's income increases, less of the good will be purchased","As its price rises, less of it will be bought","If price or income changes, no change will be induced in its consumption"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"An inferior good is one whose demand falls as income rises, because consumers switch to better alternatives, for example from garri to rice. Options A and C simply describe the normal law of demand, which applies to most goods, so they do not define an inferior good. Option D describes something unrelated."}},{"itemId":"40f602e4-0d16-5b1a-85eb-911836cfd17a","questionId":"4145621e-f530-57bf-945e-5a9a5eca2d20","sourceKey":"bank:ECO101:ECO-0414","payload":{"prompt":"Mention one of the basic assumptions of the Cardinalist approach","options":["Negative utility","Increasing marginal utility of money","Rationality","Increasing marginal utility"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"The cardinalist (marginal utility) approach assumes the consumer is rational and aims to maximise utility from their income. Option D is wrong because the theory assumes diminishing, not increasing, marginal utility. Option B is wrong because it assumes the marginal utility of money is constant."}},{"itemId":"1acddc70-6b6f-56f7-a938-b306453d84b3","questionId":"f1eeb0c2-8f3d-5428-8e7c-543174fc2b50","sourceKey":"bank:ECO101:ECO-0415","payload":{"prompt":"What does additivity imply?","options":["Independent utilities of the various commodities","Addition","Related utilities of the various commodities in the bunch","Dependent utilities of the various commodities"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Additivity means the total utility from a bundle is the sum of the separate utilities from each good, which assumes the utilities of the goods are independent of one another. Options C and D are the opposite, since related or dependent utilities could not simply be added. Option B just repeats the word without explaining it."}},{"itemId":"2b8fda35-a1bc-582c-a304-e959d2aceb32","questionId":"1f82a702-bd0d-5acd-a438-ef696fb42e35","sourceKey":"bank:ECO101:ECO-0416","payload":{"prompt":"The slope of the indifference curve is known as","options":["Isoquant","Indifference map","Commodity boundary","The marginal rate of substitution of the commodity"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"The slope of an indifference curve is the marginal rate of substitution, the rate at which the consumer is willing to give up one good for another while staying equally satisfied. Option B, the indifference map, is the whole set of indifference curves, not the slope of one. Option A, the isoquant, is the producer's equal-output curve."}},{"itemId":"94a6390a-4071-554c-b1cf-6f7ffd7e28ff","questionId":"12d3d619-cab0-540b-bf30-aff5c410613b","sourceKey":"bank:ECO101:ECO-0418","payload":{"prompt":"What does the assumption of convexity of the indifference curve imply?","options":["Marginalisation","Substitution","Preference","Choice"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A convex indifference curve reflects a diminishing marginal rate of substitution, meaning the consumer gives up less and less of one good for each extra unit of the other. This is the idea of substitution between goods. Options C and D, preference and choice, are too general and are not what convexity specifically tells us."}},{"itemId":"e78c1fdd-60e8-5f90-98b0-2efbc3b2307e","questionId":"3eaf904f-3f37-50e3-b272-31c6a9c70f74","sourceKey":"bank:ECO101:ECO-0419","payload":{"prompt":"When total utility is at a maximum, marginal utility is","options":["A positive constant","Zero","Increasing at an increasing rate","Increasing at a decreasing rate"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Total utility is at its maximum when one more unit adds nothing, so marginal utility is zero at that point. Option A is wrong because a positive marginal utility means total utility is still rising. Options C and D also describe total utility still increasing."}},{"itemId":"750e069a-e906-5024-bb52-8fe1c7ba5370","questionId":"75d999a9-2ab8-520f-bf78-9d505602f409","sourceKey":"bank:ECO101:ECO-0420","payload":{"prompt":"A concept that shows all the indifference curves which rank a consumer's preferences is known as","options":["Isoquant","Indifference map","Indifference curve","Consumer curve"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"An indifference map is a set of indifference curves, with higher curves showing higher levels of satisfaction, so it ranks the consumer's preferences. Option C, a single indifference curve, shows only one level of satisfaction. Option A, the isoquant, belongs to production theory."}},{"itemId":"748d9d18-cde7-58b1-8cb2-ad924e13c5cc","questionId":"94874b7f-d8f7-5ddd-a59f-192d15655f94","sourceKey":"bank:ECO101:ECO-0421","payload":{"prompt":"If the commodities are perfect substitutes, what will be the shape of the indifference curve?","options":["Convex to the origin","Concave to the origin","A straight line with negative slope","A straight line with positive slope."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Perfect substitutes can be swapped at a constant rate, so the marginal rate of substitution never changes and the indifference curve is a straight, downward-sloping line. Option A, a convex curve, is the normal case for imperfect substitutes. Option D is wrong because indifference curves slope downward, since more of one good must make up for less of the other."}},{"itemId":"8507206e-30e0-5948-bcb7-ac2f910697e8","questionId":"cef93b6e-21d9-57a1-9e84-75a705d1683f","sourceKey":"bank:ECO101:ECO-0424","payload":{"prompt":"In the utility theory what is important to the consumer's equilibrium is:","options":["Diminishing utility","Marginal utility","Increasing Utility","Total Utility"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Consumer equilibrium in utility theory is reached where the marginal utility per naira is equal across goods (MUx/Px = MUy/Py), so marginal utility is what matters. Option D, total utility, is what the consumer wants to maximise, but the decision rule uses marginal utility. Options A and C describe how utility changes, not the equilibrium condition."}},{"itemId":"9bbcc71c-c074-550b-aaa5-aed82da0137e","questionId":"d009bdff-200d-5cc2-9e99-05f03eb14d13","sourceKey":"bank:ECO101:ECO-0425","payload":{"prompt":"A curve that shows how consumption bundles changes as price of one of the commodities changes while the price of other commodities and income remain constant is called:","options":["Income consumption line","Consumption line","Revenue curve","Price consumption curve"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"The price-consumption curve traces the consumer's best bundle as the price of one good changes, with income and other prices held constant. Option A, the income-consumption line, traces the best bundle as income changes instead. Option C, a revenue curve, belongs to the theory of the firm."}},{"itemId":"0e294783-766e-524d-8734-cd59b1195358","questionId":"0693cd9c-303c-50e4-9e28-a7b53f172b32","sourceKey":"bank:ECO101:ECO-0426","payload":{"prompt":"A measure of the difference between the value that consumers place on their total consumption of a commodity and the amount they must pay for it is known as:","options":["Consumer's wants","Consumer's benefit","Consumer's surplus","Consumer's income"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Consumer surplus is the difference between what consumers are willing to pay for a commodity, the value they place on it, and what they actually pay. Option B, consumer's benefit, is a loose term rather than the name of this measure. Option D, income, is what the consumer has to spend."}},{"itemId":"02b92a59-e99e-58ae-808f-eb6dad06f7fb","questionId":"24abed1a-c9e4-5f91-b180-b80c6ad04d6e","sourceKey":"bank:ECO101:ECO-0428","payload":{"prompt":"Whenever real choices concern a little more or a little less, they are influenced by:","options":["Income","Consumption","Total utilities","Marginal utilities"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Most real choices are about a little more or a little less of something, so they depend on the extra satisfaction from one more unit, which is marginal utility. Option C, total utility, measures overall satisfaction rather than the gain from a small change. Options A and B are not what such decisions are weighed against."}},{"itemId":"cf8c7b6e-4074-5605-87a0-76fc9e5f99d7","questionId":"5038bf95-32ac-5519-b4a3-0172d49952a5","sourceKey":"bank:ECO101:ECO-0429","payload":{"prompt":"A consumer that chooses the consumption bundle at which the highest attainable indifference curve is just tangent to the budget line is known as:","options":["Utility - maximising consumer","Utility minimising consumer","Indifference consumer","Utility rationing"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"A consumer who picks the bundle where the highest attainable indifference curve just touches the budget line is maximising utility, since no affordable bundle gives more satisfaction. Option B is the opposite. Options C and D are not standard terms."}},{"itemId":"0fc7dacd-42ee-58cf-8778-60e24788a121","questionId":"508b474c-0c27-5b85-8877-72e0adfa5874","sourceKey":"bank:ECO101:ECO-0430","payload":{"prompt":"A utility-maximising household will consume a commodity only up to the point where its consumer's surplus on the last unit purchased is:","options":["One","Zero","Equal","Negative"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A utility-maximising household keeps buying until the value of the last unit equals the price paid, so the consumer surplus on that last unit is zero. Option D, negative, would mean the household paid more than the unit was worth, so it would stop before that. Option A is wrong because surplus on the last unit is not one."}},{"itemId":"139eb16b-fe5d-5203-82a1-646b81702df8","questionId":"b56158ce-5b27-5b07-ad32-6a9e0ef67dff","sourceKey":"bank:ECO101:ECO-0468","payload":{"prompt":"Ostentatious goods are also known as","options":["Giffen goods","Inferior goods","Veblen goods","Normal goods"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Ostentatious goods are luxury items bought largely to show off status, and they are called Veblen goods; demand for them can rise as their price rises. Option A, Giffen goods, also have upward-sloping demand, but they are inferior necessities consumed by poor households, not status symbols. Option B, inferior goods, are goods whose demand falls as income rises."}},{"itemId":"8ab925e3-d4e8-54ad-86c2-76a90def05e3","questionId":"15437df9-ceaa-5590-b014-80565c3e1f8e","sourceKey":"bank:ECO101:ECO-0542","payload":{"prompt":"Demand backed by the ability to pay for goods and services is:","options":["Ineffective demand","Effective demand","Choice","Opportunity cost"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Effective demand is the desire for a good backed by the ability and willingness to pay for it. Option A, ineffective demand, is the opposite: a wish without the money to pay. Option D, opportunity cost, is the next best alternative given up, which is a different idea."}},{"itemId":"43f1bf00-1f79-5460-920d-1ae3caa4dd08","questionId":"8c25484f-a8d6-5191-9716-b5fe791c85d8","sourceKey":"bank:ECO101:ECO-0672","payload":{"prompt":"The market equilibrium price of a commodity is determined by:","options":["Market demand for the commodity alone","Market supply of the commodity alone","The interaction of market demand and supply for the commodity","The government"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Equilibrium is reached where the quantity buyers want equals the quantity sellers offer, so it depends on demand and supply working together. Options A and B each take only one side of the market, which is like trying to cut paper with one blade of a pair of scissors."}},{"itemId":"29085379-afb2-5b17-b9eb-37ea996933c3","questionId":"93ee690c-4f3e-5992-8645-0b17fa19af02","sourceKey":"bank:ECO101:ECO-0746","payload":{"prompt":"The theory of demand mainly studies the behaviour of the:","options":["consumer","producer","firm","industry"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Demand theory explains how consumers decide how much of a good to buy, given prices, income and tastes. Options B, C and D relate to the supply side, which is studied under the theory of production and the firm."}},{"itemId":"8a3b2d3a-67cc-5e79-be1c-8da0e379fc82","questionId":"95ac5e7b-bdcc-53f9-a86e-4c77f2f0233d","sourceKey":"bank:ECO101:ECO-0747","payload":{"prompt":"The want-satisfying power of a commodity is called:","options":["satisfaction","utility","value","marginal utility"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Utility is the capacity of a good or service to satisfy a human want, such as the ability of bottled water to quench thirst. Option A, satisfaction, is the feeling obtained after consumption, and Option D, marginal utility, is only the extra utility from one more unit."}},{"itemId":"219d83b1-92c7-5b9b-8334-26e53c1b7ae1","questionId":"c9ad065a-f3bd-5a78-8ade-a0978605c7c0","sourceKey":"bank:ECO101:ECO-0748","payload":{"prompt":"Utility is best described as:","options":["objective, the same for everyone","subjective, differing from person to person","measurable in physical units such as kilograms","unrelated to human wants"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Utility is subjective: it depends on each consumer's tastes and needs, so the same plate of food can give a hungry student far more satisfaction than someone who has just eaten. Option A is wrong because utility is not fixed across people, and Option C is wrong because utility cannot be measured in physical units."}},{"itemId":"9cab4b7b-547c-571a-bbd2-c70d653d4b58","questionId":"7417780e-548e-5e7d-801e-7691eda648fa","sourceKey":"bank:ECO101:ECO-0749","payload":{"prompt":"The change in total utility that results from consuming one more unit of a good is called:","options":["total utility","extra cost","marginal utility","average utility"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Marginal utility is the addition to total utility from consuming one extra unit: MU = (change in TU)/(change in quantity). Option A is the overall satisfaction from all units consumed, and Option D is total utility divided by the number of units."}},{"itemId":"9f0b254a-335b-5d64-9e41-f52d0806d658","questionId":"4aaf91e5-7b32-54a2-8fac-a473631b4b03","sourceKey":"bank:ECO101:ECO-0751","payload":{"prompt":"When marginal utility becomes negative, total utility:","options":["falls","rises","remains unchanged","becomes zero immediately"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Negative marginal utility means the extra unit actually reduces satisfaction, like being made to eat a fifth plate of rice, so total utility falls. Option B applies when MU is positive, and Option C applies only at the exact point where MU is zero."}},{"itemId":"7eec25f5-9f48-5380-9f01-c82a5eebac42","questionId":"63dad850-8a55-5029-a043-9ae41e6f4f42","sourceKey":"bank:ECO101:ECO-0752","payload":{"prompt":"The saturation point in consumption is the point where:","options":["TU = 0","MU = 0","MU is positive","TU = 1"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"At the saturation point one more unit adds no extra satisfaction, so MU = 0 and total utility is at its maximum. Option A is wrong because total utility is at its highest there, not zero, and Option C describes the stage before saturation is reached."}},{"itemId":"21d3fb5a-c45d-5a42-95af-894290771be5","questionId":"c3d6b8bb-4818-5ddb-b8da-bd5cf395e642","sourceKey":"bank:ECO101:ECO-0753","payload":{"prompt":"The idea that utility can be measured in cardinal numbers (units) is a postulate of the:","options":["neo-classical (cardinalist) school","ordinalist school","Keynesian school","mercantilist school"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Neo-classical economists such as Alfred Marshall assumed that utility could be measured in units (utils) or in money, which is the cardinal approach. Option B, the ordinalist school associated with Hicks and Allen, held that consumers can only rank combinations, not measure utility, and Option C, the Keynesians, focused on macroeconomics rather than utility measurement."}},{"itemId":"7cdae337-27ec-5063-89f4-4096d8848aaa","questionId":"a82b53c2-2de5-5aaa-975c-27616f2bc91f","sourceKey":"bank:ECO101:ECO-0754","payload":{"prompt":"Gossen's first law is another name for the law of:","options":["diminishing marginal utility","equi-marginal utility","substitution","diminishing returns"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Gossen's first law states that as a person consumes more of a good, the extra satisfaction from each additional unit falls, which is the law of diminishing marginal utility. Option B, the law of equi-marginal utility, is known as Gossen's second law, and Option D, diminishing returns, is a law of production rather than consumption."}},{"itemId":"681bb360-8961-52d3-90fb-b01ada555e2c","questionId":"74938d79-435d-5c51-a854-a81477794c6b","sourceKey":"bank:ECO101:ECO-0755","payload":{"prompt":"For a free good (one with a zero price), a consumer is in equilibrium when:","options":["MU is at its highest","MU = 0","TU = 0","TU = 1"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A consumer buys up to the point where MU = P, and since the price of a free good is zero, they keep consuming until MU = 0. Option C is wrong because total utility is at its maximum, not zero, at that point, and Option A is wrong because MU is highest at the very first unit consumed."}},{"itemId":"ec575b60-6861-5d50-9456-13a000789d6e","questionId":"7aa12c79-4cfb-573f-95ed-076cded95335","sourceKey":"bank:ECO101:ECO-0756","payload":{"prompt":"A change in the demand for a good caused by a change in the price of a related good is called:","options":["cross demand","price demand","income demand","joint supply"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Cross demand links the quantity demanded of one good to the price of another, related good, such as the demand for bread changing when the price of butter changes. Option B, price demand, relates demand to the good's own price, and Option C, income demand, relates it to the consumer's income."}},{"itemId":"64471b87-84af-5386-8a34-ea1b2389c289","questionId":"ef459546-4647-520a-8485-ed68660b5ed1","sourceKey":"bank:ECO101:ECO-0757","payload":{"prompt":"For an ordinary inferior good (one that is not a Giffen good), the relationship between its price and its quantity demanded is:","options":["direct (positive)","inverse (negative)","non-existent","always perfectly inelastic"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Even for an inferior good, the substitution effect usually outweighs the negative income effect, so quantity demanded still rises when price falls and the price-quantity relationship is inverse. Option A, a direct relationship, applies only to the special case of a Giffen good, where the income effect is strong enough to dominate."}},{"itemId":"c7be0b68-b9f2-530f-bdaf-c5c2e923d02a","questionId":"1d4211e1-2339-51ba-ae04-97182a0db65e","sourceKey":"bank:ECO101:ECO-0758","payload":{"prompt":"For a normal good, quantity demanded varies inversely with:","options":["the price of the good","the consumer's income","how fashionable the good is","the price of a substitute good"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"By the law of demand, a higher price of a normal good leads to a lower quantity demanded, so the relationship with its own price is inverse. Option B is wrong because demand for a normal good rises with income, and Option D is also a direct relationship, since a dearer substitute makes consumers buy more of this good."}},{"itemId":"cd05b70b-b1dd-5604-a533-69dccf8153e5","questionId":"3904ca32-ffc2-5a0b-b79e-01d3e64613e8","sourceKey":"bank:ECO101:ECO-0759","payload":{"prompt":"Which of these is a cardinal approach to demand analysis?","options":["Marshallian utility analysis","Indifference curve analysis","Revealed preference theory","None of these"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Marshall's utility analysis assumes utility can be measured in units or in money, which makes it the cardinal approach. Option B, indifference curve analysis, is ordinal because it only ranks combinations, and Option C, revealed preference, is based on observed choices rather than measured utility."}},{"itemId":"270aa9cb-94a9-52d9-adf0-be51246f0d93","questionId":"436ae112-a171-55f0-af09-e0edc0b0a2aa","sourceKey":"bank:ECO101:ECO-0760","payload":{"prompt":"Which of these is a property of a standard indifference curve?","options":["It is convex to the origin.","It is concave to the origin.","It slopes upward from left to right.","Two indifference curves can cross each other."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"A standard indifference curve is convex to the origin because of a diminishing marginal rate of substitution. Option C is wrong because indifference curves slope downward (to keep satisfaction the same, more of one good means less of the other), and Option D is wrong because crossing curves would mean the same bundle gives two different levels of satisfaction."}},{"itemId":"a866cf22-530e-5529-a329-9318bbe4a459","questionId":"7598f7dc-68e3-57b1-9f41-d83d6aea09e8","sourceKey":"bank:ECO101:ECO-0761","payload":{"prompt":"The convexity of an indifference curve reflects:","options":["a diminishing marginal rate of substitution","an increasing marginal rate of substitution","a constant marginal rate of substitution","a zero marginal rate of substitution everywhere"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"As a consumer gets more of good X, they are willing to give up less and less of good Y for each extra unit of X, so the MRS diminishes and the curve bows in toward the origin. Option C, a constant MRS, would give a straight-line indifference curve (perfect substitutes), and Option B would make the curve concave."}},{"itemId":"453133ee-6e9c-5044-8616-56602f45928b","questionId":"5d51366d-8105-582b-a2f4-c5ca60e6a435","sourceKey":"bank:ECO101:ECO-0762","payload":{"prompt":"Moving from one point to another along the same indifference curve leaves the consumer's satisfaction:","options":["higher","lower","unchanged","first higher, then lower"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Every point on an indifference curve gives the same level of satisfaction, which is why the consumer is 'indifferent' between them. Options A and B would require moving to a higher or lower indifference curve, not along the same one."}},{"itemId":"bf7a4623-3d22-5348-828c-a04f546b0329","questionId":"38ab92bf-1bf8-5ae5-8d33-61006cfa5f9d","sourceKey":"bank:ECO101:ECO-0764","payload":{"prompt":"Compared with combinations on a lower indifference curve, combinations on a higher indifference curve (further from the origin) are:","options":["equally satisfying","preferred, because they give more satisfaction","less preferred","impossible to compare"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A higher indifference curve contains bundles with more of at least one good and no less of the other, so, assuming more is better, they give greater satisfaction and are preferred. Option A applies only to points on the same curve, and Option D is wrong because indifference curve analysis is built on the consumer's ability to rank bundles."}},{"itemId":"01531692-edf5-510f-9407-f75f3e158f0e","questionId":"9193cc6e-da64-54a0-b969-9ea58d3f5d18","sourceKey":"bank:ECO101:ECO-0765","payload":{"prompt":"As a consumer moves down an indifference curve from left to right, the marginal rate of substitution of X for Y:","options":["increases","remains the same","decreases","first decreases, then increases"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Moving down the curve, the consumer has more X and less Y, so they are willing to give up fewer units of Y for each extra unit of X, and the MRS of X for Y decreases. Option B would only hold for perfect substitutes, whose indifference curves are straight lines."}},{"itemId":"44823e12-e62f-564e-8725-d99c7f4f36e6","questionId":"7d28e937-241d-5770-8de4-230e0d206e01","sourceKey":"bank:ECO101:ECO-0766","payload":{"prompt":"The slope of an indifference curve measures the:","options":["ratio of the prices of goods X and Y","marginal rate of technical substitution between labour and capital","marginal rate of substitution of X for Y (MRSxy)","marginal rate of transformation along the production possibility curve"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"The slope of an indifference curve shows how much Y the consumer will give up for one more unit of X while staying equally satisfied, which is MRSxy. Option A is the slope of the budget line, Option B is the slope of an isoquant in production, and Option D is the slope of the production possibility curve."}},{"itemId":"324855d5-07d6-5fe3-ac4b-40f2a4fd149f","questionId":"7ba1fe24-16b8-5242-a608-7c9eac2e3f61","sourceKey":"bank:ECO101:ECO-0769","payload":{"prompt":"A consumer spends income on goods X and Y, with X on the horizontal axis. If only the price of Y changes, the X-intercept of the budget line will:","options":["shift to the right","shift to the left","stay the same","move parallel with the whole budget line"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"The X-intercept equals income divided by the price of X (M/Px), and neither of these changes, so it stays fixed while the budget line pivots around it. Only the Y-intercept (M/Py) moves, which rules out A and B, and Option D, a parallel shift, happens when income changes rather than one price."}},{"itemId":"b4f7bf19-8dcc-5f7f-8d3e-6b963fb21a3c","questionId":"947c865d-80bb-5e11-b4f1-d119c3766365","sourceKey":"bank:ECO101:ECO-0770","payload":{"prompt":"At the point where an indifference curve is tangent to the budget line:","options":["MRSxy = Px/Py","MRSxy > Px/Py","MRSxy < Px/Py","MRSxy = Py/Px"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"At the tangency the two slopes are equal: the consumer's willingness to swap Y for X (MRSxy) equals the market rate of exchange (Px/Py), which is the condition for consumer equilibrium. Options B and C describe points where the consumer could still gain by buying more X or more Y, and Option D turns the price ratio upside down."}},{"itemId":"ed0cc611-b0cc-5759-8bf2-fff7ff35e396","questionId":"56468722-8cb6-5e72-a8d2-b4f55edf8c84","sourceKey":"bank:ECO101:ECO-0771","payload":{"prompt":"Goods that consumers buy more of when their income rises are called:","options":["normal goods","inferior goods","Giffen goods","free goods"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Normal goods have a positive income elasticity of demand: as income rises, demand for them rises too. Options B and C are goods whose demand falls as income rises, with a Giffen good being a special kind of inferior good."}},{"itemId":"def18e0c-2843-5835-8875-d4f32cfd14ca","questionId":"a96f06c9-c857-56b3-bba1-e1b09c8692f3","sourceKey":"bank:ECO101:ECO-0772","payload":{"prompt":"The curve showing the quantity of a good a consumer would buy at different levels of income is the:","options":["market demand curve","price consumption curve","Engel curve","indifference curve"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"The Engel curve plots the quantity of a good bought against the consumer's income, showing directly how purchases change as income changes. Option A, the demand curve, relates quantity to the good's own price rather than income, and Option B traces the best bundles as the price of one good changes."}},{"itemId":"2c4bf33c-2d22-5dc3-b84b-10b77d456159","questionId":"0899ab57-2326-59cc-8eca-b998670f5687","sourceKey":"bank:ECO101:ECO-0773","payload":{"prompt":"The change in quantity demanded caused only by a change in relative prices, with real income held constant, is the:","options":["income effect","substitution effect","price effect","ratchet effect"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The substitution effect isolates the response to a change in relative prices alone, as consumers switch toward the good that has become relatively cheaper while real income is held constant. Option A is the response to the change in purchasing power, and Option C, the price effect, is the combined total of the substitution and income effects."}},{"itemId":"5e67d2c2-0de6-5850-b599-49e11706807e","questionId":"03ac1a15-9a20-5e5b-b7a9-50f41bd1c045","sourceKey":"bank:ECO101:ECO-0774","payload":{"prompt":"The substitution effect of a price change on quantity demanded is:","options":["always negative (quantity moves opposite to price)","always positive","rarely negative","always zero"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"When a good becomes relatively cheaper, the substitution effect always leads the consumer to buy more of it, and when it becomes dearer, less of it, so the effect moves opposite to price and is described as negative. It is the income effect, not the substitution effect, that can go either way, which is why Options B and C are wrong."}},{"itemId":"248ccbd5-cea7-5669-97f7-c9cba94c2758","questionId":"bd9f8ade-29fd-5e5d-ac6b-a5f1a25364bf","sourceKey":"bank:ECO101:ECO-0775","payload":{"prompt":"If the income effect of a price change works in the same direction as the substitution effect, the good is:","options":["a normal good","an inferior good","a Giffen good","a neutral good"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"For a normal good, a price fall makes the good relatively cheaper (substitution effect) and also raises real income, which increases demand further (income effect), so both effects push quantity demanded the same way. For inferior and Giffen goods, Options B and C, the income effect works against the substitution effect."}},{"itemId":"98736db6-9d74-59df-a2d6-52a57c3c5a59","questionId":"a9c3af94-a736-5167-937d-d33cbf5bac06","sourceKey":"bank:ECO101:ECO-0776","payload":{"prompt":"If the income effect works in the opposite direction to the substitution effect, the good cannot be a:","options":["Giffen good","inferior good","normal good","good with a negative income elasticity"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Opposite income and substitution effects happen only when the income effect is negative, which is the case for inferior goods, including Giffen goods. A normal good has an income effect that reinforces the substitution effect, so it cannot be the good described, while Options A, B and D are all types of inferior goods."}},{"itemId":"dffff2b0-fc0c-5c0f-a0b7-b59fc720952e","questionId":"dc49b6bb-3f7e-51cd-80ea-cf40c9b3fd38","sourceKey":"bank:ECO101:ECO-0778","payload":{"prompt":"Which theory of consumer demand is based on observing consumers' actual market behaviour?","options":["Cardinal utility analysis","Indifference curve analysis","Revealed preference theory","The law of equi-marginal utility"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Revealed preference theory, developed by Paul Samuelson, infers preferences from the bundles consumers actually choose at given prices and incomes. Options A and D rest on the assumption that utility can be measured, and Option B relies on the consumer's own ranking of bundles, so none of them is built on observed behaviour."}},{"itemId":"3b19e0e5-a2ac-50b1-9836-8071739143d7","questionId":"1c8c5f08-cc03-5452-8297-6e319bcfffc4","sourceKey":"bank:ECO101:ECO-0783","payload":{"prompt":"The indifference curve approach to consumer behaviour is associated with:","options":["Alfred Marshall","J.R. Hicks","Paul Samuelson","Adam Smith"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"J.R. Hicks, working with R.G.D. Allen, popularised the indifference curve (ordinal) approach to consumer demand. Marshall (A) is linked to the cardinal utility approach, and Samuelson (C) to revealed preference theory."}},{"itemId":"d6f59f60-a6a5-50df-84e8-d42da260b49e","questionId":"c6da861a-23b0-578c-b05d-d785cf0cb051","sourceKey":"bank:ECO101:ECO-0784","payload":{"prompt":"Which pair of goods are close substitutes?","options":["Tea and coffee","Bread and butter","Car and petrol","Pen and ink"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Tea and coffee serve the same purpose for many consumers, so if the price of one rises, people switch to the other, which makes them close substitutes. Options B, C and D are complements, goods used together, so a rise in the price of one reduces demand for the other."}},{"itemId":"95277552-ae22-5c26-88c8-05ce9801c3ee","questionId":"9e8acb83-61a3-5429-80b8-01ed167511bd","sourceKey":"bank:ECO101:ECO-0794","payload":{"prompt":"Other things remaining equal, the quantity demanded of a product increases when its price:","options":["increases","decreases","stays the same","becomes uncertain"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The law of demand states that, other things equal, price and quantity demanded move in opposite directions, so quantity demanded rises when price falls. Option A would be true only for special cases like Giffen goods, and Option C gives no reason for quantity demanded to change."}},{"itemId":"4bac416c-0c7d-5a89-be25-2233e3cd1761","questionId":"449e72a5-a8e9-5ca8-89eb-525e5b10ac3f","sourceKey":"bank:ECO101:ECO-0795","payload":{"prompt":"For complementary goods, such as cars and petrol, the cross elasticity of demand is:","options":["positive","negative","zero","infinite"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"When the price of petrol rises, people buy fewer cars, so the quantity demanded of one good moves opposite to the price of the other and cross elasticity is negative. Option A, a positive cross elasticity, is the mark of substitutes, and Option C, zero, indicates unrelated goods."}},{"itemId":"10f181f9-78df-5bc8-afd7-d8bfee10ab79","questionId":"9ca3a878-4f33-5555-a088-2fb0e6b5b0b5","sourceKey":"bank:ECO101:ECO-0796","payload":{"prompt":"The responsiveness of demand for one commodity to a change in the price of another commodity is measured by:","options":["price elasticity of demand","income elasticity of demand","cross elasticity of demand","elasticity of substitution"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Cross elasticity of demand = (%change in Qd of good X)/(%change in price of good Y), so it links one good's demand to another good's price. Option A uses the good's own price, and Option B uses the consumer's income."}},{"itemId":"40e0cf8c-8a4c-5324-866f-55c5cccaabf4","questionId":"fcda75e7-3704-5cab-99c5-bf50dadd4daf","sourceKey":"bank:ECO101:ECO-0797","payload":{"prompt":"The demand curve for a Giffen good:","options":["is vertical","is horizontal","slopes downward","slopes upward"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"For a Giffen good, a strong negative income effect outweighs the substitution effect, so a price rise leads consumers to buy more of it, giving an upward-sloping demand curve. Option C is the normal case under the law of demand, which the Giffen good is an exception to."}},{"itemId":"16702502-2c68-50e7-ba64-5e6f04cfcaa1","questionId":"ce2ff9b5-69a1-5ae7-9939-2ab821175d00","sourceKey":"bank:ECO101:ECO-0798","payload":{"prompt":"When Q = f(P), the price elasticity of demand is measured by:","options":["(change in Q/change in P) / (P/Q)","(change in P/change in Q) x (Q/P)","(change in Q/change in P) x (P/Q)","(P/change in Q) / (Q/P)"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Price elasticity is (%change in Q)/(%change in P) = (change in Q/Q)/(change in P/P), which rearranges to (change in Q/change in P) x (P/Q). Option B uses the inverse slope and gives the reciprocal of elasticity, and Option A divides by P/Q instead of multiplying by it."}},{"itemId":"1f5b894e-ab11-5e85-ad94-d78dd6fae2e5","questionId":"e546c2d8-dae8-57db-ae65-e09c17199a2d","sourceKey":"bank:ECO101:ECO-0799","payload":{"prompt":"The income elasticity of demand for inferior goods is:","options":["negative","positive","zero","equal to one"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"For an inferior good, demand falls as income rises (people switch to better alternatives), so the percentage change in quantity has the opposite sign to the percentage change in income and income elasticity is negative. Option B, a positive income elasticity, belongs to normal goods."}},{"itemId":"5109ac82-bd2c-5a34-90b8-4d645c4fdaab","questionId":"04a6b326-37c4-539c-8189-3af41961e650","sourceKey":"bank:ECO101:ECO-0800","payload":{"prompt":"For luxury goods, the income elasticity of demand is:","options":["less than one","equal to one","greater than one","negative"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Demand for a luxury rises more than proportionately with income, so (%change in Qd)/(%change in income) is greater than one. Option A, positive but less than one, describes a necessity, and Option D describes an inferior good."}},{"itemId":"053c8a0a-8dc3-530a-9e37-4ba75022e40e","questionId":"01e2327b-0760-52dc-811b-0a0ccf7cf595","sourceKey":"bank:ECO101:ECO-0801","payload":{"prompt":"Income elasticity of demand is positive but less than one for:","options":["necessities","luxuries","inferior goods","substitutes"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Demand for necessities, such as salt or basic foodstuffs, rises with income but by a smaller percentage, giving an income elasticity between 0 and 1. Option B, luxuries, have income elasticity above one, and Option C, inferior goods, have a negative income elasticity."}},{"itemId":"6df14fb7-09ce-5d1d-b2e4-739bbb2860c9","questionId":"3ab5ef01-b123-5dac-8bf3-b22bc4c5ab67","sourceKey":"bank:ECO101:ECO-0802","payload":{"prompt":"A movement along a demand curve (a change in quantity demanded) is caused by a change in:","options":["consumers' income","the good's own price","the prices of related goods","consumers' expectations"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Only a change in the good's own price moves the consumer along an existing demand curve, which economists call a change in quantity demanded. Options A, C and D are other determinants of demand, and a change in any of them shifts the whole demand curve instead."}},{"itemId":"4e44ab36-c354-56a4-8906-e295b6a250e7","questionId":"2dfe97e8-fbd2-57f6-be90-e381e949d403","sourceKey":"bank:ECO101:ECO-0803","payload":{"prompt":"A normal supply curve shows a ______ relationship between price and quantity supplied.","options":["direct","inverse","sometimes direct, sometimes inverse","zero"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"By the law of supply, producers offer more at higher prices because production becomes more profitable, so price and quantity supplied move in the same direction. Option B describes the demand curve, not the supply curve."}},{"itemId":"88ab302c-c42b-57b7-b57a-9473302fe757","questionId":"1025300d-8519-557e-a838-557dec0f6b56","sourceKey":"bank:ECO101:ECO-0804","payload":{"prompt":"When drawing an individual's demand curve for a good, all of the following are held constant EXCEPT:","options":["the individual's money income","the prices of related goods","the price of the good itself","the consumer's tastes"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A demand curve shows how quantity demanded responds to the good's own price, so that price must be allowed to vary along the curve. Income, prices of related goods and tastes (A, B and D) are held constant, and a change in any of them shifts the curve."}},{"itemId":"b9d8b85a-04b0-5449-9c9b-4b0c919b736d","questionId":"73ede2ad-8ad5-55bd-a3a9-0aad9fefb136","sourceKey":"bank:ECO101:ECO-0805","payload":{"prompt":"A fall in the price of a good, with all other things held constant, leads to:","options":["an increase in demand","a decrease in demand","an increase in quantity demanded","a decrease in quantity demanded"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A change in a good's own price causes a movement along the demand curve, and a lower price raises the quantity demanded. Option A, an increase in demand, is a rightward shift of the whole curve caused by things like higher income, not by the good's own price."}},{"itemId":"23524877-0612-5b05-8419-f44121f26e1d","questionId":"05ad6ec5-4732-5869-a4c5-991faa68c7ec","sourceKey":"bank:ECO101:ECO-0806","payload":{"prompt":"When a consumer's income rises, with everything else constant, their demand for a normal good:","options":["rises","falls","remains the same","could do any of these"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"A normal good is defined by a positive link between income and demand, so higher income shifts its demand curve to the right. Option B describes an inferior good, and Option D is wrong because the direction for a normal good is not in doubt."}},{"itemId":"75eb1930-7cee-535d-bfc3-489b6aa2795f","questionId":"577a3a48-fdc8-5677-9d9f-dc3e723e039e","sourceKey":"bank:ECO101:ECO-0807","payload":{"prompt":"When a consumer's income falls, with everything else constant, their demand for an inferior good:","options":["increases","decreases","remains unchanged","cannot be predicted"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"With less income, consumers switch from dearer options to cheaper, lower-quality ones, so demand for an inferior good increases when income falls. Option B is what happens to a normal good when income falls."}},{"itemId":"4eb04eb3-a80b-5c6a-aa99-6576eb5a4b85","questionId":"01113108-4374-5e39-b163-0a0e53971ba6","sourceKey":"bank:ECO101:ECO-0808","payload":{"prompt":"When the price of a substitute for good X falls, the demand for X:","options":["rises","falls","remains unchanged","may rise or fall"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"If a substitute becomes cheaper, some consumers switch to it, so demand for X falls; for example, cheaper tea would reduce the demand for coffee. Option A would apply if the price of the substitute rose, or if the price of a complement fell."}},{"itemId":"ad900dc6-3fb8-589e-bbcb-e27679684e3d","questionId":"13358aa3-f4a6-5bed-b12e-7bcc412cc3b6","sourceKey":"bank:ECO101:ECO-0809","payload":{"prompt":"If the price of a substitute for good X and the price of a complement of X both rise at the same time, the demand for X will:","options":["definitely rise","definitely fall","definitely remain unchanged","rise, fall or stay the same, depending on which effect is stronger"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A dearer substitute pushes demand for X up, while a dearer complement pulls demand for X down, so the two effects work in opposite directions. The final result depends on which change is stronger, so none of the definite outcomes in A, B or C can be guaranteed."}},{"itemId":"ca3eef44-265e-51f6-8b2e-60fbf5b93ad9","questionId":"edafc2cc-c002-5ecd-91f8-cf590ef1e352","sourceKey":"bank:ECO101:ECO-0810","payload":{"prompt":"With an upward-sloping supply curve, a rise in the good's own price leads to:","options":["an increase in supply","an increase in quantity supplied","a decrease in supply","a decrease in quantity supplied"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A change in the good's own price moves producers along the existing supply curve, and a higher price raises quantity supplied. Option A, an increase in supply, is a rightward shift of the whole curve caused by factors such as lower input costs or better technology."}},{"itemId":"90e75b81-b750-56db-8d64-8c5f17386a54","questionId":"c4df4d75-61e3-5de0-ab52-0aeed84a2a7a","sourceKey":"bank:ECO101:ECO-0811","payload":{"prompt":"Starting from a stable equilibrium, if market supply decreases while demand is unchanged:","options":["equilibrium price falls","equilibrium quantity rises","both equilibrium price and equilibrium quantity fall","equilibrium price rises but equilibrium quantity falls"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A decrease in supply shifts the supply curve to the left, creating a shortage at the old price, so price rises and the quantity traded falls. Options A and B are results of an increase in supply, and Option C is what happens when demand falls."}},{"itemId":"3fdbaef0-3ff9-5c73-8aa8-c2f66aa40ce4","questionId":"0de634bd-3f0c-54ba-b5b8-15fc4ed9f57c","sourceKey":"bank:ECO101:ECO-0812","payload":{"prompt":"If the percentage rise in quantity demanded is smaller than the percentage fall in price, the price elasticity of demand is:","options":["greater than one","equal to one","less than one","zero"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Ed = (%change in Qd)/(%change in P); when the top is smaller than the bottom, the ratio is less than one and demand is inelastic. Option A would require quantity to respond more than price, and Option D would mean quantity does not respond at all."}},{"itemId":"f566809e-1336-5adf-9e3c-1ce8c1a7743f","questionId":"a016793a-2175-5707-8643-bbaf75ed3b58","sourceKey":"bank:ECO101:ECO-0813","payload":{"prompt":"If a good's demand curve is a rectangular hyperbola, a fall in its price will make total expenditure on the good:","options":["increase","decrease","remain unchanged","fall to zero"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Along a rectangular hyperbola, P x Q is the same at every point, so price elasticity is one everywhere and total expenditure does not change when price changes. Option A would hold for elastic demand, and Option B for inelastic demand."}},{"itemId":"ac0293dc-0ac5-50d8-a4de-8c7590ebd878","questionId":"22a0e46f-a0c4-569d-b077-1c78007602cc","sourceKey":"bank:ECO101:ECO-0814","payload":{"prompt":"If the quantity demanded stays exactly the same when the price of a good falls, the price elasticity of demand is:","options":["greater than one","equal to one","less than one but above zero","zero"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"With no change in quantity demanded, the top of Ed = (%change in Qd)/(%change in P) is zero, so elasticity is zero and demand is perfectly inelastic. Option C describes demand that responds a little, not demand that does not respond at all."}},{"itemId":"602c6b11-a713-5bdb-a83f-ded03151c1dc","questionId":"37b2a398-6bee-5e29-803f-c5f309131af8","sourceKey":"bank:ECO101:ECO-0815","payload":{"prompt":"When demand for a good is inelastic, a rise in its price causes consumers' total expenditure on it to:","options":["increase","decrease","remain unchanged","either rise or fall"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"With inelastic demand, quantity falls by a smaller percentage than price rises, so P x Q goes up; for example, if price rises 10% and quantity bought falls only 4%, spending becomes 1.10 x 0.96 = 1.056 times its old level. Option C is true only for unit elastic demand, and Option B applies when demand is elastic."}},{"itemId":"e5f7e1a2-6f87-5cf5-824c-d7ba2eee6fad","questionId":"26f74792-01c4-5a54-b3a9-7339c0fe9e1c","sourceKey":"bank:ECO101:ECO-0816","payload":{"prompt":"A negative income elasticity of demand for a good means that as income falls, the quantity of the good purchased:","options":["rises","falls","remains unchanged","falls to zero"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"A negative income elasticity means quantity and income move in opposite directions, so a fall in income leads to more of the good being bought, which is the case for inferior goods. Option B describes a normal good with positive income elasticity."}},{"itemId":"eca983d0-e382-5b2d-99b4-21daba561489","questionId":"7d7c5841-f5ae-541a-ac0d-c92834c981bf","sourceKey":"bank:ECO101:ECO-0817","payload":{"prompt":"If the income elasticity of demand for a good is greater than one, the good is a:","options":["necessity","luxury","inferior good","unrelated good"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"An income elasticity above one means demand rises by a bigger percentage than income, which is the mark of a luxury. Option A, a necessity, has income elasticity between 0 and 1, and Option C, an inferior good, has a negative income elasticity."}},{"itemId":"2d2fa2fe-d5fb-5c83-8a51-abc684fab8cd","questionId":"f9f388c0-9e44-58e9-93dd-6d73559c960e","sourceKey":"bank:ECO101:ECO-0818","payload":{"prompt":"If the quantity bought of one good stays unchanged when the price of another good changes, the cross elasticity of demand between them is:","options":["positive","negative","zero","one"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"If the quantity of one good does not respond at all to the other good's price, the top of the cross elasticity formula is zero, so cross elasticity is zero and the goods are unrelated. Option A would indicate substitutes and Option B complements."}},{"itemId":"bc792974-d84a-5321-890f-1e3866eb16dd","questionId":"de6a9faa-fd06-5098-b1b2-176cdb06adeb","sourceKey":"bank:ECO101:ECO-0819","payload":{"prompt":"If the income elasticity of demand for a good is 0.4, the good is a:","options":["luxury","necessity","Giffen good","unrelated good"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"An income elasticity of 0.4 is positive but less than one, so demand rises with income but less than proportionately, which is the mark of a necessity. A luxury (A) has income elasticity above one, and a Giffen good (C) is an inferior good with negative income elasticity."}},{"itemId":"7a9f1e77-acc2-5164-a1ad-c98e8a417ae4","questionId":"dd2a21de-2590-5039-b912-2b73605ddf86","sourceKey":"bank:ECO101:ECO-0820","payload":{"prompt":"For a straight-line, upward-sloping supply curve that cuts the price axis above the origin, the elasticity of supply is:","options":["zero","equal to one","greater than one","less than one"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Such a supply curve can be written Q = c(P - k), where k is the positive price intercept, so Es = (change in Q/change in P) x (P/Q) = P/(P - k), which is always greater than one. Option B applies to a line through the origin, and Option D to a line that cuts the quantity axis."}},{"itemId":"784cb440-3d10-5b13-9944-f011bcab063f","questionId":"a52b3fae-5511-5057-a002-e51e4e6e0a7b","sourceKey":"bank:ECO101:ECO-0821","payload":{"prompt":"If an upward-sloping, straight-line supply curve cuts the quantity axis, supply is:","options":["inelastic","elastic","unit elastic","perfectly elastic"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Such a curve can be written Q = k + cP with k positive, so Es = cP/(k + cP), which is always less than one, meaning supply is inelastic. Option B applies to a line cutting the price axis, and Option C to a line passing through the origin."}},{"itemId":"1261256e-9a47-58a4-baa9-b388de332c93","questionId":"ced30869-d213-5657-bdae-b205cbc3c16b","sourceKey":"bank:ECO101:ECO-0822","payload":{"prompt":"If an upward-sloping, straight-line supply curve passes through the origin, supply is:","options":["inelastic","elastic","unit elastic","perfectly elastic"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A line through the origin is Q = cP, so Es = (change in Q/change in P) x (P/Q) = c x P/(cP) = 1 at every point, which is unit elastic. Options A and B apply to lines that cut the quantity axis and the price axis respectively."}},{"itemId":"3dfe100c-a739-590a-97a4-f62d38f1a370","questionId":"3e72caf2-8fbf-5b56-b258-da28a97d4b94","sourceKey":"bank:ECO101:ECO-0823","payload":{"prompt":"A horizontal supply curve (parallel to the quantity axis) represents:","options":["elastic supply","inelastic supply","perfectly elastic supply","perfectly inelastic supply"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A horizontal supply curve means producers will supply any quantity at one price but nothing below it, so elasticity of supply is infinite: perfectly elastic. Option D, perfectly inelastic supply, is shown by a vertical supply curve."}},{"itemId":"0862906c-5e48-543b-b718-21a1c1f43924","questionId":"e8dc319b-4097-5955-bb72-8d8cfa5fda14","sourceKey":"bank:ECO101:ECO-0824","payload":{"prompt":"For an inferior good, a fall in consumers' income, other things being equal, causes:","options":["an increase in demand","a decrease in demand","an increase in quantity demanded","a decrease in quantity demanded"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Consumers buy more of an inferior good when their income falls, because they switch away from dearer alternatives, so the whole demand curve shifts right: an increase in demand. Option B would apply to a normal good, and Options C and D describe movements along the curve, which only a change in the good's own price can cause."}},{"itemId":"a7fe88eb-88dc-5546-a534-70f2171039f7","questionId":"0d17bfea-5e64-531a-b389-3998f2c27e54","sourceKey":"bank:ECO101:ECO-0825","payload":{"prompt":"Which of the following causes an increase in the supply of a good?","options":["A fall in the price of inputs","An increase in the number of producers","A fall in the price of another good the firms could produce instead","All of the above"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Cheaper inputs lower production costs, more producers add to market output, and a fall in the price of an alternative product makes producing this good relatively more attractive, so each shifts the supply curve to the right. Since A, B and C are all correct, D is the best answer."}},{"itemId":"a757aa68-ced2-5547-945b-7538d7db1dbe","questionId":"4f5b6de6-8d9c-5890-a4bf-4b180050774b","sourceKey":"bank:ECO101:ECO-0826","payload":{"prompt":"Which of these elasticities measures a movement along a demand curve rather than a shift of it?","options":["Price elasticity of demand","Income elasticity of demand","Cross elasticity of demand","None of the above"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Price elasticity of demand measures the response of quantity demanded to the good's own price, which is a movement along the demand curve. Income elasticity (B) and cross elasticity (C) measure responses to income and to other goods' prices, which shift the demand curve."}},{"itemId":"2033d693-4bde-579e-b09c-9ff6b89aad5f","questionId":"3840f5b2-6a33-5a31-b20e-0e7cc2856c5b","sourceKey":"bank:ECO101:ECO-0827","payload":{"prompt":"The cross elasticity of demand between substitutes is:","options":["zero","negative","positive","infinite"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"When the price of one substitute rises, consumers buy more of the other, so the quantity of one good moves in the same direction as the price of the other and cross elasticity is positive. Option B, a negative cross elasticity, is the mark of complements, and Option A indicates unrelated goods."}},{"itemId":"6b38aa4b-c036-5c5e-8067-c248d00a791c","questionId":"9dde6076-6b85-50cc-872f-ac9dc8bbf6b2","sourceKey":"bank:ECO101:ECO-0828","payload":{"prompt":"A movement down along a given demand curve is known as:","options":["an increase in demand","a decrease in demand","an extension of demand","a contraction of demand"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Moving down along the same demand curve means a lower price and a larger quantity demanded, which is called an extension of demand. Option D, a contraction, is a movement up the curve as price rises, while A and B refer to shifts of the whole curve."}},{"itemId":"fa424764-7aa9-5f9a-9c6a-7c04d875e898","questionId":"c2758cde-5074-59ba-801e-3d64e85bc1e5","sourceKey":"bank:ECO101:ECO-0829","payload":{"prompt":"For a normal good, which of the following would cause an increase in demand?","options":["A fall in the price of a substitute","A rise in the price of a complement","A fall in consumers' income","None of the above"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Each listed change actually reduces demand for a normal good: a cheaper substitute draws buyers away (A), a dearer complement makes the pair costlier to use (B), and lower income cuts purchases of normal goods (C). Since none of them raises demand, D is correct."}},{"itemId":"32d58e98-bd94-5a92-aab2-8e97d22316d4","questionId":"4a549999-61ed-5cb2-be7a-8406956bd0c0","sourceKey":"bank:ECO101:ECO-0830","payload":{"prompt":"A change in the quantity supplied of a product (a movement along its supply curve) results from a change in:","options":["its own price","its cost of production","technology","the prices of related products"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Only a change in the good's own price moves producers along the existing supply curve. Changes in production costs, technology or prices of related products (B, C and D) shift the whole supply curve, which is a change in supply rather than in quantity supplied."}},{"itemId":"fde9e2d4-8ba0-575e-89e4-a51f2bed60df","questionId":"60ea922e-b7a2-5800-af54-a5e5db196158","sourceKey":"bank:ECO101:ECO-0831","payload":{"prompt":"An increase in supply means:","options":["a movement down along a given supply curve","a movement up along a given supply curve","a leftward shift of the supply curve","a rightward shift of the supply curve"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"An increase in supply means producers are willing to sell more at every price, which is shown by the whole supply curve shifting to the right. Options A and B are movements along the curve caused by a change in the good's own price, and Option C is a decrease in supply."}},{"itemId":"dc08e723-27b8-50d6-9dd8-81b21020024b","questionId":"97587801-aeaa-53d5-8f69-2d1bf995c2c0","sourceKey":"bank:ECO101:ECO-0832","payload":{"prompt":"At any price above the equilibrium price:","options":["quantity supplied exceeds quantity demanded","quantity demanded exceeds quantity supplied","there is a shortage","the market is in equilibrium"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Above equilibrium, sellers want to sell more than buyers want to buy, creating a surplus (excess supply) that tends to push the price down. Options B and C describe the situation below the equilibrium price, where there is a shortage."}},{"itemId":"25947565-9208-567d-8a63-f11c819c8056","questionId":"3e223a75-2252-5951-8c41-ba6d370644f8","sourceKey":"bank:ECO101:ECO-0833","payload":{"prompt":"An increase in market supply, with demand unchanged, causes:","options":["a rise in equilibrium price","a fall in equilibrium quantity","a fall in equilibrium price and a rise in equilibrium quantity","a rise in both equilibrium price and quantity"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A rightward shift of supply creates a surplus at the old price, so price falls and, moving along the demand curve, more is bought. Option D is what happens when demand increases, not supply."}},{"itemId":"a76d98ae-3dca-5cbd-a1dc-54a511b4f024","questionId":"148e8d74-2f82-5422-b1fd-69f84467a844","sourceKey":"bank:ECO101:ECO-0834","payload":{"prompt":"An increase in market demand, with supply unchanged, results in:","options":["a fall in equilibrium price","a fall in equilibrium quantity","a fall in equilibrium price and a rise in equilibrium quantity","a rise in both equilibrium price and quantity"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A rightward shift of demand creates a shortage at the old price, so price rises and producers respond by supplying more, raising both equilibrium price and quantity. Option C describes the effect of an increase in supply instead."}},{"itemId":"ff396ce4-9fe8-5630-9276-efc2678042b4","questionId":"37a258cc-ba9a-5826-bb81-c1a9f4c38387","sourceKey":"bank:ECO101:ECO-0835","payload":{"prompt":"A fall in market demand, with supply unchanged, results in:","options":["a rise in equilibrium price","a rise in equilibrium quantity","a rise in equilibrium price and a fall in equilibrium quantity","a fall in both equilibrium price and quantity"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A leftward shift of demand creates a surplus at the old price, so price falls and producers move down their supply curve, cutting quantity, so both equilibrium price and quantity fall. Option C describes a decrease in supply, which raises price while cutting quantity."}},{"itemId":"a4cf950d-7a4b-5601-8cd9-88744dc02773","questionId":"dad7d8ca-10ef-5626-8b05-a5577afe7a0d","sourceKey":"bank:ECO101:ECO-0836","payload":{"prompt":"Which elasticity measure uses the average of the two prices and the two quantities?","options":["Point elasticity of demand","Arc elasticity of demand","Income elasticity of demand","Cross elasticity of demand"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Arc elasticity measures elasticity between two points on a demand curve using averages: Ed = (change in Q/average Q)/(change in P/average P), so the answer is the same whichever direction the price moves. Option A, point elasticity, measures elasticity at a single point and needs no averages."}},{"itemId":"e4352734-2c7d-50fb-905c-c78922ebc734","questionId":"124e4e0c-8fee-53ba-b7d4-5675efb7cc0d","sourceKey":"bank:ECO101:ECO-0837","payload":{"prompt":"If a fall in price leads to a fall in total expenditure on a good, the price elasticity of demand is:","options":["equal to one","greater than one","less than one","impossible to tell"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Spending falls after a price cut only if quantity rises by a smaller percentage than price falls, which means demand is inelastic (Ed less than one). With elastic demand (B) spending would rise, and with unit elasticity (A) it would stay the same."}},{"itemId":"16ea6c2e-f18c-5d1b-aeea-80c0eeba2502","questionId":"226293fd-255a-5ec8-b0d0-08d2d3554410","sourceKey":"bank:ECO101:ECO-0838","payload":{"prompt":"If a tiny change in price leads to an infinitely large change in quantity demanded, demand is:","options":["perfectly elastic","perfectly inelastic","elastic","inelastic"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Perfectly elastic demand has an elasticity of infinity and is drawn as a horizontal demand curve: even a small price rise makes quantity demanded fall to zero. Option B, perfectly inelastic demand, is the opposite case where quantity does not respond to price at all, and Option C is a milder case with elasticity merely above one."}},{"itemId":"6c5345b4-f7d6-5995-a862-7983b93218f3","questionId":"84737be9-bcd3-5e7f-9385-afb5092a2d05","sourceKey":"bank:ECO101:ECO-0839","payload":{"prompt":"When the demand curve is a rectangular hyperbola, the price elasticity of demand is:","options":["zero","one","greater than one","infinite"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A rectangular hyperbola has P x Q constant, so any percentage fall in price is matched by an equal percentage rise in quantity and elasticity is one at every point. Option C would mean spending rises as price falls, and Option D describes a horizontal demand curve."}},{"itemId":"980fc967-690d-5fb0-a88e-6beff5c49f35","questionId":"0a2ff630-2fb7-5998-8bda-c89c7caaa4e4","sourceKey":"bank:ECO101:ECO-0840","payload":{"prompt":"On a straight-line demand curve, at the point where price elasticity of demand equals one, marginal revenue is:","options":["positive","zero","negative","equal to one"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"MR = P(1 - 1/Ed), using the absolute value of elasticity, so when Ed = 1, MR = P(1 - 1) = 0; this is the midpoint of the linear demand curve where total revenue is at its maximum. MR is positive on the elastic upper half (A) and negative on the inelastic lower half (C)."}},{"itemId":"cf73d84e-b521-51d9-9d9f-0eb4c5b52f19","questionId":"18a8a246-a4c3-5ea2-9e2e-d6a176fa44d0","sourceKey":"bank:ECO101:ECO-0848","payload":{"prompt":"In a free market, when consumers increase their purchases of a good so that ______ exceeds ______, prices tend to rise.","options":["demand; supply","supply; demand","prices; demand","profits; supply"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"When demand exceeds supply at the current price, there is a shortage, and buyers competing for the limited goods bid the price up. Option B describes a surplus, which pushes prices down instead."}},{"itemId":"f9bca78c-e770-5076-971f-5ec09cc8eb16","questionId":"d4c3d9f5-dcaa-5316-9c0a-8d340c4a0b5d","sourceKey":"bank:ECO101:ECO-0851","payload":{"prompt":"A relative price is:","options":["the ratio of one price to another","the difference between one price and another","the slope of the supply curve","the slope of the demand curve"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"A relative price compares two money prices by dividing one by the other, showing how many units of one good must be given up to get one unit of another. Option B uses subtraction instead of a ratio, which gives a naira amount rather than a rate of exchange between goods."}},{"itemId":"dece698d-f613-5ac2-accc-3e5c82d92bdc","questionId":"166692ac-9019-5780-a7d6-e78c15a34519","sourceKey":"bank:ECO101:ECO-0852","payload":{"prompt":"If a chocolate bar costs N200 and a plate of jollof rice costs N1,000, then:","options":["the money price of a plate of rice is N200","the relative price of a plate of rice is 1/5 of a chocolate bar","the relative price of a plate of rice is 5 chocolate bars","the relative price of a chocolate bar is 5 plates of rice"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Relative price of rice = price of rice / price of chocolate = N1,000/N200 = 5, so one plate of rice costs as much as 5 chocolate bars. Option B turns the ratio upside down, Option D is wrong because a chocolate bar is only 1/5 of a plate of rice, and Option A gives the chocolate bar's money price, not the rice's."}},{"itemId":"73caa11f-0e26-5304-9c5f-89e2174d07fb","questionId":"ef3eeb97-cc1a-5274-ad44-96c5b33e2882","sourceKey":"bank:ECO101:ECO-0853","payload":{"prompt":"If a meat pie costs N500 and a shawarma costs N1,000, then:","options":["the money price of a shawarma is N500","the relative price of a meat pie is 2 shawarmas","the relative price of a meat pie is 1/2 of a shawarma","the relative price of a shawarma is 1/2 of a meat pie"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Relative price of a meat pie = N500/N1,000 = 1/2, so a meat pie costs half a shawarma (and a shawarma costs 2 meat pies). Options B and D flip the ratio, and Option A is wrong because the money price of a shawarma is N1,000."}},{"itemId":"0e250fb1-54d5-537d-a5f7-839e294a8df7","questionId":"76145e62-c643-5de5-a2c5-a6c57e969429","sourceKey":"bank:ECO101:ECO-0854","payload":{"prompt":"The opportunity cost of good A in terms of good B equals the:","options":["ratio of the price of B to the price of A","ratio of the price of A to the price of B","price of A minus the price of B","price of B minus the price of A"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"To buy one unit of A you give up PA/PB units of B, so the opportunity cost of A in terms of B is the relative price PA/PB. Option A is the opportunity cost of B in terms of A, and C and D use differences, which are naira amounts rather than quantities of a good forgone."}},{"itemId":"68a4980f-227a-5c04-becc-77b2a1e7cee5","questionId":"c66d06b9-2dda-5bb4-bc74-20cc059e4385","sourceKey":"bank:ECO101:ECO-0855","payload":{"prompt":"The opportunity cost of a meat pie in terms of shawarma is:","options":["the price of a meat pie minus the price of a shawarma","the ratio of the slope of the meat pie supply curve to the slope of the shawarma supply curve","the ratio of the slope of the meat pie demand curve to the slope of the shawarma demand curve","the ratio of the price of a meat pie to the price of a shawarma"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"The opportunity cost of a meat pie is the number of shawarmas you give up to buy it, which equals the price of a meat pie divided by the price of a shawarma, its relative price. Option A uses a difference, which is a naira amount rather than a number of shawarmas, and B and C use curve slopes, which have nothing to do with this trade-off."}},{"itemId":"8cc7c6ad-f892-5397-add7-313f2750f405","questionId":"7556535c-0734-5c55-bb13-1f6280231a77","sourceKey":"bank:ECO101:ECO-0856","payload":{"prompt":"Unlike demands, wants are:","options":["dependent on price","the goods a consumer plans to buy","the unlimited desires of the consumer","the goods a consumer has already bought"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Wants are the unlimited desires people have for goods and services, whether or not they can afford them. Demands, by contrast, depend on price and reflect plans to buy, so Options A and B describe demand rather than wants."}},{"itemId":"b7144054-d2ed-5c1c-97db-918b155792b9","questionId":"1d0fa07d-336d-5091-a3c2-a61ec4ca60ea","sourceKey":"bank:ECO101:ECO-0857","payload":{"prompt":"Demands differ from wants because:","options":["wants need a plan to buy a good, but demands do not","demands are unlimited, while wants are limited by income","wants involve deciding which demands to satisfy, while demands involve no plan to buy","demands reflect a decision about which wants to satisfy and a plan to buy, while wants are unlimited and involve no plan to buy"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A demand is a want backed by a decision and a plan to buy at a given price with limited income, while wants are unlimited wishes with no buying plan attached. Options A, B and C all reverse the roles of wants and demands."}},{"itemId":"b0d41bcc-3897-52e6-89bf-0ae5a0f086ac","questionId":"c0503457-bd60-55b0-9bad-41046ea4ada6","sourceKey":"bank:ECO101:ECO-0858","payload":{"prompt":"Scarcity guarantees that:","options":["wants will exceed demands","demands will equal wants","demands will exceed wants","most demands will be satisfied"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Scarcity means people's wants are unlimited while their incomes and resources are limited, so they can only turn some of their wants into demands they are able to pay for. That is why wants always exceed demands. Option B would mean scarcity did not exist, option C is impossible because demands come from wants, and option D is not guaranteed by scarcity."}},{"itemId":"6e64ef1b-4bd0-58c1-99e5-b77142a41d72","questionId":"0a14c0ae-db49-5f4e-bd1e-837d5c3994db","sourceKey":"bank:ECO101:ECO-0859","payload":{"prompt":"The quantity demanded of a good is:","options":["the amount consumers plan to buy at a particular price","independent of the good's price","unrelated to consumers' buying plans","always equal to the equilibrium quantity"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Quantity demanded is the amount buyers plan to purchase at one particular price, which is a single point on the demand curve. Option B is wrong because quantity demanded changes with price, and Option D is wrong because at prices other than equilibrium, quantity demanded differs from quantity supplied."}},{"itemId":"b2a370f8-f9b4-50be-b5f2-3a08792a5adb","questionId":"840f0260-390f-5723-9d68-a48198b37b08","sourceKey":"bank:ECO101:ECO-0860","payload":{"prompt":"The law of demand states that, other things equal, the higher the price of a good, the:","options":["smaller the demand for the good","smaller the quantity of the good demanded","larger the quantity of the good demanded","larger the demand for the good"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The law of demand is about a movement along a demand curve: a higher price reduces the quantity demanded. Option A is tempting, but a 'smaller demand' means the whole curve shifts left, which is caused by factors other than the good's own price."}},{"itemId":"cba65ca0-665f-592a-99f2-8c6132e18cbc","questionId":"bee99442-b7f9-5b7c-97a9-8ad3e60c45af","sourceKey":"bank:ECO101:ECO-0861","payload":{"prompt":"The law of demand implies that, other things equal:","options":["as the demand for suya rises, its price will fall","as the price of suya rises, the quantity of suya demanded falls","as income rises, the quantity of suya demanded rises","as the price of suya rises, the quantity of suya demanded rises"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The law of demand links a good's own price to its quantity demanded in opposite directions, so a higher price of suya means less suya is demanded. Option C is about income, which shifts demand rather than being part of the law of demand, and Option A is wrong because a rise in demand tends to raise price, not lower it."}},{"itemId":"56a81bc4-0c8e-5e04-a14f-242f4c4b614e","questionId":"bcff59f6-eeaf-5514-b510-df11d7906f73","sourceKey":"bank:ECO101:ECO-0862","payload":{"prompt":"The law of demand states that the quantity demanded of a good varies:","options":["inversely with its own price","directly with population","directly with income","inversely with the price of substitute goods"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"The law of demand is specifically about the good's own price: as it rises, quantity demanded falls, an inverse relationship. Options B and C are other determinants of demand rather than the law itself, and Option D is wrong because a dearer substitute actually raises demand for the good."}},{"itemId":"e72c1777-7ae8-5765-8856-c50e70dc1153","questionId":"ea132e6f-e3de-5961-b53f-85577c6a53bf","sourceKey":"bank:ECO101:ECO-0863","payload":{"prompt":"Which of these is consistent with the law of demand?","options":["A fall in the price of sachet water reduces the quantity of sachet water demanded.","A rise in the price of a soft drink reduces the quantity of soft drinks demanded.","A rise in the price of a phone charger increases the quantity of chargers demanded.","A fall in the price of juice leaves the quantity of juice demanded unchanged."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The law of demand says price and quantity demanded move in opposite directions, so a dearer soft drink leading to fewer being bought fits it exactly. Options A and C show price and quantity moving in the same direction, and Option D shows no response at all, so none of them follows the law."}},{"itemId":"69bfae35-f45d-5d2e-aa63-82a3ef166fe8","questionId":"f501173a-c4b3-5a71-8d67-32ff9a475c74","sourceKey":"bank:ECO101:ECO-0864","payload":{"prompt":"The law of demand implies that, other things equal, the relationship between a good's price and its quantity demanded is:","options":["linear","positive","negative","exponential"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Price and quantity demanded move in opposite directions, so the relationship is negative and the demand curve slopes downward. Option B would mean quantity rises with price, and the law says nothing about the curve's exact shape, so A and D are not implied."}},{"itemId":"20d5e5aa-a23b-5434-94a3-d7ffeffa64f7","questionId":"6deb3e23-9fb5-563f-97af-382db93f361b","sourceKey":"bank:ECO101:ECO-0865","payload":{"prompt":"Which of the following affects how much of a good people plan to buy AND changes as we move along that good's demand curve?","options":["Consumers' tastes and preferences","The price of the good itself","Consumers' incomes","The prices of related goods"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A demand curve plots quantity demanded against the good's own price, so moving along it means only that price is changing. Options A, C and D also affect buying plans, but a change in any of them shifts the whole demand curve instead of moving us along it."}},{"itemId":"8abacefc-a45e-5ecb-a8db-ea7fc486394c","questionId":"9fc56e25-06be-5f5c-ac34-70003620dcb4","sourceKey":"bank:ECO101:ECO-0866","payload":{"prompt":"Which statement correctly expresses the law of demand?","options":["A fall in the price of a good shifts its demand curve to the left.","Holding other things constant, the higher the price of a good, the smaller the quantity demanded.","Holding other things constant, the higher the price of a good, the larger the quantity demanded.","A rise in the price of a good shifts its demand curve to the left."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The law of demand says price and quantity demanded move in opposite directions, ceteris paribus. Option C reverses this relationship, and Options A and D are wrong because a change in the good's own price causes a movement along the demand curve, not a shift."}},{"itemId":"bc0a8e68-144e-59a8-b6e7-49bcd3d8e07c","questionId":"241f12f7-3e80-51d1-b749-002bde384969","sourceKey":"bank:ECO101:ECO-0867","payload":{"prompt":"Because of the law of demand, demand curves","options":["shift to the left whenever price rises.","shift to the right whenever price rises.","slope downward from left to right.","slope upward from left to right."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"If a higher price means a smaller quantity demanded, then plotting price against quantity gives a downward-sloping curve. Options A and B confuse a price change with a shift, and Option D describes the usual shape of a supply curve."}},{"itemId":"e0a44062-5f31-518f-8682-be6ab7b5f6d8","questionId":"97214ae2-0551-586a-ad80-831fcde3f81e","sourceKey":"bank:ECO101:ECO-0868","payload":{"prompt":"Each point on a demand curve shows","options":["the highest price consumers are willing and able to pay for that particular unit of the good.","the highest price sellers will accept for all the units they produce.","the cheapest technology available for producing the good.","every want of a given household."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Read upward from any quantity, the demand curve tells us the maximum price buyers would pay for that last unit, which reflects its marginal benefit to them. Option B mixes in sellers, who are described by the supply curve, and Option D ignores that demand requires both willingness and ability to pay."}},{"itemId":"c26ff33e-7385-5755-aee0-9ac1e9af2620","questionId":"82e94b97-c02d-54d8-8205-c6fa0c920b1d","sourceKey":"bank:ECO101:ECO-0869","payload":{"prompt":"A fall in the price of Bluetooth earbuds shifts the demand curve for wired earphones to the left. This tells you that Bluetooth earbuds and wired earphones are","options":["normal goods.","substitutes.","inferior goods.","complements."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"When one good becomes cheaper, people switch to it and buy less of a good that does the same job, so demand for the other good falls. That is the definition of substitutes. If they were complements (Option D), a cheaper earbud would raise demand for earphones, not reduce it."}},{"itemId":"54cc16c3-8c0a-501b-8c9a-45684c4eb9d1","questionId":"e69be753-836f-574f-b9df-35eda11071db","sourceKey":"bank:ECO101:ECO-0870","payload":{"prompt":"A substitute is a good that","options":["is of higher quality than another good.","is not used in place of another good.","can be used in place of another good.","is of lower quality than another good."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Substitutes satisfy the same want, so one can be used instead of the other, like bread and yam for breakfast. Quality has nothing to do with the definition, which rules out Options A and D, and Option B is the opposite of the idea."}},{"itemId":"bc0435e5-ea1c-5ac8-99ac-8a7d3906ffb9","questionId":"0404790c-6e20-5c65-b497-b6518ca2f07f","sourceKey":"bank:ECO101:ECO-0871","payload":{"prompt":"People buy more of good X when the price of good Y rises. Goods X and Y are","options":["normal goods.","complements.","substitutes.","inferior goods."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"When Y becomes more expensive, buyers switch towards X, which can take Y's place, so X and Y are substitutes. Complements (Option B) behave the other way: a rise in Y's price would reduce demand for X. Options A and D describe how demand responds to income, not to another good's price."}},{"itemId":"abb18687-aff1-518e-969c-9f9558da03c4","questionId":"b9d2b560-f04c-5941-a259-7fa77d3125e4","sourceKey":"bank:ECO101:ECO-0872","payload":{"prompt":"Which pair of goods is most likely to be substitutes?","options":["DVDs and DVD players","Bread and butter","Cola drinks and lemon-lime soft drinks","Groundnut paste and petrol"],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Two soft drinks satisfy the same want, so a buyer can easily choose one instead of the other. Options A and B are complements, since they are consumed together, while Option D is a pair of unrelated goods."}},{"itemId":"b1c9785d-682c-5082-8903-1ceb8a15771f","questionId":"db9a22fe-746a-5535-83b4-10f8669ecdf0","sourceKey":"bank:ECO101:ECO-0873","payload":{"prompt":"The demand for a good increases when the price of a substitute ________ and also increases when the price of a complement ________.","options":["falls; falls","rises; falls","rises; rises","falls; rises"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A dearer substitute pushes buyers towards our good, and a cheaper complement makes using our good less costly, so both raise its demand. Option C gets the complement wrong, because a dearer complement reduces demand for the good it goes with."}},{"itemId":"0026af76-29d7-56a2-9b77-381c1add8c4c","questionId":"1e7a4241-4b1f-5bc0-b26c-5aae38defa23","sourceKey":"bank:ECO101:ECO-0874","payload":{"prompt":"A complement is a good that is","options":["used together with another good.","used instead of another good.","of lower quality than another good.","of higher quality than another good."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Complements are consumed jointly, like a car and petrol or a phone and airtime. Option B describes a substitute, and Options C and D bring in quality, which is not part of either definition."}},{"itemId":"72691ed5-28aa-5ce5-8069-f1f14de46adb","questionId":"ccfe0c6c-fc5b-5c47-bb30-33adf399e32b","sourceKey":"bank:ECO101:ECO-0875","payload":{"prompt":"People buy more of good X when the price of good Y falls. These goods are","options":["substitutes.","inferior goods.","normal goods.","complements."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A cheaper Y leads people to use more Y, and if X is used along with Y they buy more X too, so the goods are complements. With substitutes (Option A), a cheaper Y would cause people to buy less X."}},{"itemId":"8c5a89b0-65e4-54b8-817c-35cb67e4373e","questionId":"c3091d99-90ef-501e-91ec-71479ce21f80","sourceKey":"bank:ECO101:ECO-0876","payload":{"prompt":"As the opportunity cost of a good falls, people buy","options":["more of that good but less of its complements.","less of that good and less of its complements.","less of that good but more of its complements.","more of that good and more of its complements."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A good's price is its opportunity cost, so a lower opportunity cost means people buy more of it, and because complements are used together with it, they buy more of those as well. Option A is wrong because complements rise with the good rather than move against it."}},{"itemId":"e8b02c51-8936-5255-b268-f7095fe1d376","questionId":"b4f5d96c-40ba-5436-98cb-ef51363dbdc5","sourceKey":"bank:ECO101:ECO-0877","payload":{"prompt":"Motorists come to expect that the price of a litre of petrol will rise next week. As a result,","options":["next week's supply of petrol decreases.","the price of petrol falls today.","today's supply of petrol increases.","today's demand for petrol increases."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Buyers who expect a higher price later try to fill their tanks now, so today's demand curve shifts right. Option C is wrong because sellers expecting higher prices next week would rather hold stock back today, and Option B ignores that higher demand pushes today's price up, not down."}},{"itemId":"0577c662-7656-5726-a3be-ad35a7d14ceb","questionId":"d2a434c3-edf2-5570-9a23-f3fd24a9434c","sourceKey":"bank:ECO101:ECO-0878","payload":{"prompt":"The demand curve for a normal good shifts to the left if income ________ or the expected future price ________.","options":["decreases; falls","increases; rises","increases; falls","decreases; rises"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Lower income reduces demand for a normal good, and if buyers expect the price to fall later they postpone purchases, so demand today falls as well. Option D gets the expectation wrong, because an expected price rise makes people buy more now."}},{"itemId":"b653e5f1-77e6-5253-96b3-d76f9f3c9eb3","questionId":"8269d6ab-4631-5259-a65f-fcc22a0ec857","sourceKey":"bank:ECO101:ECO-0879","payload":{"prompt":"If income increases or the price of a complement falls,","options":["the supply curve of a normal good shifts to the left.","the supply curve of a normal good shifts to the right.","the demand curve for a normal good shifts to the right.","the demand curve for a normal good shifts to the left."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Both changes make buyers want more of a normal good at every price, so its demand curve shifts right. Options A and B are wrong because income and complement prices affect buyers, not the supply curve."}},{"itemId":"f8799043-7aa1-5b53-93a7-74f37cc7c0d6","questionId":"7f0bf2e9-ff50-5e75-b062-63d3de839924","sourceKey":"bank:ECO101:ECO-0880","payload":{"prompt":"If income decreases or the price of a complement rises,","options":["there is an upward movement along the good's demand curve.","there is a downward movement along the good's demand curve.","the demand curve for a normal good shifts to the left.","the demand curve for a normal good shifts to the right."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Lower income and a dearer complement both reduce the amount of a normal good people want at each price, so the whole demand curve shifts left. Options A and B describe movements along the curve, which happen only when the good's own price changes."}},{"itemId":"311b3b28-a2aa-5f35-b313-2e7f4c6fd000","questionId":"be29b6c5-9d2a-5e09-a86f-c8e8de5d9959","sourceKey":"bank:ECO101:ECO-0881","payload":{"prompt":"For a normal good, demand decreases when","options":["the price of a substitute rises.","the price of a complement falls.","the good's own price rises.","income decreases."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A normal good is defined by its link to income, so when income decreases, demand for it falls and the whole demand curve shifts left. Option C is tempting, but a rise in the good's own price only reduces the quantity demanded, a movement along the curve, while a dearer substitute or a cheaper complement (Options A and B) would raise demand."}},{"itemId":"c3deb2c7-8fac-5d08-8fc0-ef2823c1329d","questionId":"df58f5fa-0b62-5ae6-a59c-c8ac03aa02b2","sourceKey":"bank:ECO101:ECO-0882","payload":{"prompt":"A normal good is a good for which","options":["there are very few complements.","demand decreases when income increases.","demand increases when income increases.","there are few substitutes."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Normal goods are bought more as people become richer, so demand moves in the same direction as income. Option B is the definition of an inferior good, and Options A and D have nothing to do with how a good responds to income."}},{"itemId":"52ab56a3-d342-5742-9eb0-d9fab9dfd615","questionId":"5ad3d27b-382e-592b-bae8-800df1096a11","sourceKey":"bank:ECO101:ECO-0883","payload":{"prompt":"Most goods","options":["have vertical demand curves.","have vertical supply curves.","are normal goods.","are complements of each other."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"For most things people buy, demand rises as income rises, which makes them normal goods. Demand curves usually slope downward and supply curves upward, so Options A and B are wrong, and most pairs of goods are not used together, so Option D fails."}},{"itemId":"819c2b19-cfe2-5afe-a026-dbf3acbb58db","questionId":"8e1e3c79-41db-56d8-9d52-9891cc4233f4","sourceKey":"bank:ECO101:ECO-0885","payload":{"prompt":"Inferior goods are those for which demand increases as","options":["income decreases.","income increases.","the price of a complement rises.","the price of a substitute falls."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"With an inferior good, people buy more when they become poorer and switch away from it as they become richer, so demand rises as income decreases. Option B describes a normal good, and Options C and D would actually reduce demand, since a dearer complement and a cheaper substitute both draw buyers away."}},{"itemId":"16cea8e8-83c5-59d4-8fbb-c550db0a54c9","questionId":"a0dc8a6e-6aa4-5cf1-b6a0-f7cd937e5893","sourceKey":"bank:ECO101:ECO-0886","payload":{"prompt":"By definition, an inferior good is a","options":["normal good that is also a substitute.","good for which demand decreases when its own price rises.","want that is not backed by demand.","good for which demand decreases when income increases."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"An inferior good is one people buy less of as their income rises, often because they can now afford a preferred alternative. Option B confuses the law of demand, which applies to almost all goods, with the income-based definition of an inferior good."}},{"itemId":"280ba4c1-29dc-5004-a388-30ca2fcb3741","questionId":"cb37954a-c46a-50ea-92e0-b55f5885b343","sourceKey":"bank:ECO101:ECO-0887","payload":{"prompt":"If a good is inferior, purchases of it will decrease when","options":["the demand for it increases.","population increases.","income increases.","the price of a substitute rises."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Demand for an inferior good moves opposite to income, so higher income means people buy less of it. Options A, B and D would all increase purchases rather than decrease them."}},{"itemId":"2d2dbd12-beba-5856-9acf-480515406c0b","questionId":"dce07374-417d-5ed6-9329-590ecbad8886","sourceKey":"bank:ECO101:ECO-0889","payload":{"prompt":"When economists say that preferences influence demand, they mean","options":["whether a good is available to all income groups.","directly observable changes in prices and incomes.","the excess of wants over the available supply.","an individual's attitudes and tastes towards goods and services."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Preferences are people's likes and dislikes, which shape how much they want of a good at any price. Option B lists prices and incomes, which are separate determinants of demand, and Option C describes scarcity rather than preferences."}},{"itemId":"e48f4491-dc7b-51e1-92a5-e6a8fc30fe52","questionId":"74932265-6e92-5dea-8799-425ad9ce3b9d","sourceKey":"bank:ECO101:ECO-0890","payload":{"prompt":"In one year, 200,000 gas cookers were demanded at a price of N150,000 each. The next year, more than 200,000 were demanded at the same price. This increase could be caused by any of the following EXCEPT","options":["an increase in the supply of gas cookers.","an increase in population.","an increase in income, if gas cookers are a normal good.","a fall in the price of cooking gas, a complement of gas cookers."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"More cookers demanded at an unchanged price means the demand curve has shifted right, and a change in supply does not shift demand. Options B, C and D are all genuine causes of higher demand: more buyers, more income for a normal good, and a cheaper complement."}},{"itemId":"e02fa14e-6680-5b12-b5eb-d8af1200a94d","questionId":"0c6a742e-366b-5669-a85b-a2402ce089d3","sourceKey":"bank:ECO101:ECO-0891","payload":{"prompt":"A change in the price of a good","options":["shifts its demand curve but does not cause a movement along it.","does not shift its demand curve but does cause a movement along it.","shifts its demand curve and also causes a movement along it.","neither shifts its demand curve nor causes a movement along it."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The good's own price is on the axis of the demand curve, so a change in it moves us to a different point on the same curve. Options A and C are wrong because only changes in other factors, such as income or related prices, shift the curve."}},{"itemId":"0440937c-4b34-53a3-8357-db1d30c8e983","questionId":"e24a2cbd-cc06-592d-a526-9b58b9b89eab","sourceKey":"bank:ECO101:ECO-0892","payload":{"prompt":"A fall in the price of a good","options":["shifts its demand curve to the left and decreases the quantity demanded.","shifts its demand curve to the left but leaves the quantity demanded unchanged.","does not shift its demand curve but decreases the quantity demanded.","does not shift its demand curve but increases the quantity demanded."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A lower price moves buyers down along the same demand curve to a larger quantity demanded. Option C gets the direction wrong, since cheaper goods are bought in larger amounts, and Options A and B are wrong because a change in the good's own price never shifts its demand curve."}},{"itemId":"3a859f81-d337-5d7e-a998-dde1bc98ed5b","questionId":"739ab00b-1e27-5ff6-a5e9-9c2e24fbc7fc","sourceKey":"bank:ECO101:ECO-0893","payload":{"prompt":"A decrease in quantity demanded caused by a rise in price is shown by a","options":["movement up and to the left along the demand curve.","movement down and to the right along the demand curve.","leftward shift of the demand curve.","rightward shift of the demand curve."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"A higher price puts us higher up the curve, and the smaller quantity puts us further left, so we slide up and to the left. Option C is tempting, but a leftward shift is a decrease in demand caused by something other than the good's own price."}},{"itemId":"381de0a2-ffcc-5f41-b190-af6519142c48","questionId":"41b5fda4-bfa8-5f96-9143-102879f37822","sourceKey":"bank:ECO101:ECO-0894","payload":{"prompt":"A change in which of the following alters people's buying plans for cars but does NOT shift the demand curve for cars?","options":["A 10 percent fall in the price of car insurance","A 20 percent rise in the price of a car","A 5 percent rise in people's incomes","A growing preference for walking instead of driving"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"The price of the car itself causes a movement along the demand curve for cars rather than a shift. Insurance is a complement (Option A), income is a demand determinant (Option C) and tastes (Option D) also matter, and all of these shift the demand curve."}},{"itemId":"c9bdeb4d-09cc-5a68-bb5f-6859892867ff","questionId":"ed6803da-0444-5bb2-b7e5-01ea361a63e3","sourceKey":"bank:ECO101:ECO-0895","payload":{"prompt":"Which of the following would NOT shift the demand curve for chicken?","options":["A change in consumers' taste for chicken","A fall in the price of beef","A rise in income","A change in the price of chicken"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A change in chicken's own price moves buyers along the existing demand curve for chicken. Tastes, the price of a substitute such as beef, and income (Options A, B and C) are all factors that shift the curve."}},{"itemId":"c20d697d-fcfe-522e-868b-631b709d1781","questionId":"824fd430-0ae6-59c6-9de7-6abe7853f6f3","sourceKey":"bank:ECO101:ECO-0896","payload":{"prompt":"When we say demand has increased, we mean there is a","options":["movement to the right along the demand curve.","movement to the left along the demand curve.","leftward shift of the demand curve.","rightward shift of the demand curve."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"An increase in demand means buyers want more at every price, so the whole curve moves to the right. Option A is an increase in quantity demanded caused by a lower price, which is a different idea."}},{"itemId":"daca1a38-7b14-5dde-8250-001ac96dd65e","questionId":"fadc3956-3171-5096-adfe-bd21e016dfb2","sourceKey":"bank:ECO101:ECO-0897","payload":{"prompt":"The quantity supplied of a good is","options":["the difference between the quantity available and the quantity desired by all buyers and sellers.","the same as the quantity demanded at each price.","the amount producers plan to sell at a particular price during a given period.","the amount a firm would sell if it faced no resource constraints."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Quantity supplied is a planned amount linked to a specific price and time period. Option B confuses it with quantity demanded, which equals quantity supplied only at equilibrium, and Option D ignores that real firms always face limited resources."}},{"itemId":"8cbd7afa-30f3-5291-9f75-88c2ecdfc1d0","questionId":"91097e2c-c462-5ee4-83ae-45bf330526c9","sourceKey":"bank:ECO101:ECO-0898","payload":{"prompt":"The quantity supplied of a good or service is the amount that a producer","options":["actually sells at a particular price in a given period.","ought to sell at a particular price in a given period.","is willing to sell at a particular price in a given period.","needs to sell at a particular price in a given period."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Quantity supplied describes producers' plans: how much they are willing to offer at a given price. Option A is tempting, but actual sales may differ from plans if there is a shortage or surplus."}},{"itemId":"a115d1ea-bf23-508c-8352-2cd37d312155","questionId":"96ed73e6-852d-578a-a803-0f3293e8097c","sourceKey":"bank:ECO101:ECO-0899","payload":{"prompt":"A fall in the price of a good leads producers to reduce the quantity of it they are willing to offer. This illustrates","options":["a change in supply.","the law of demand.","the nature of an inferior good.","the law of supply."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"The law of supply says that, other things equal, a higher price raises quantity supplied and a lower price reduces it. Option A is wrong because a price-driven change is a change in quantity supplied, not a shift in supply, and Option B is about buyers rather than producers."}},{"itemId":"b0f6ee0e-731e-58c9-83fc-28d544437c82","questionId":"ae38e0c8-3262-5d86-84b2-e446e618246c","sourceKey":"bank:ECO101:ECO-0900","payload":{"prompt":"Each point on a supply curve shows","options":["the highest price sellers can get for each unit over time.","the lowest price buyers will accept for each unit of the good.","the lowest price at which a supplier is willing to sell one more unit.","the highest price buyers will pay for the good."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Read upward from a quantity, the supply curve gives the minimum price that covers the cost of producing that extra unit. Options B and D are about buyers, which the demand curve describes, and Option A turns a minimum into a maximum."}},{"itemId":"7e751145-8e11-55a7-b425-223e50bb9f08","questionId":"2deff425-905c-5069-a516-10c6fde8f443","sourceKey":"bank:ECO101:ECO-0901","payload":{"prompt":"Because marginal cost rises as output increases, most supply curves","options":["are horizontal.","slope downward.","are vertical.","slope upward."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"If each extra unit costs more to produce, producers need a higher price to offer more, so the supply curve slopes upward. A downward slope (Option B) is the typical shape of a demand curve."}},{"itemId":"dfb548ec-6c50-5df0-bac9-9386d3e35d62","questionId":"dbd5e5ee-82c6-577d-9440-0e25ce2decbc","sourceKey":"bank:ECO101:ECO-0902","payload":{"prompt":"A supply curve shows the relationship between the quantity supplied of a good and","options":["the price of the good, and it usually slopes downward.","income, and it usually slopes upward.","income, and it usually slopes downward.","the price of the good, and it usually slopes upward."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Supply links quantity supplied to the good's own price, and because higher prices encourage more output, the curve slopes upward. Option A has the right variable but the wrong slope, and income (Options B and C) is a demand factor, not what the supply curve plots."}},{"itemId":"d6048280-60df-5d5c-ab2f-f865888f13e3","questionId":"97e9c5d1-a1bc-5cdd-8434-fdee63734b9d","sourceKey":"bank:ECO101:ECO-0903","payload":{"prompt":"A supply curve differs from a supply schedule because a supply curve","options":["is a graph, while a supply schedule is a table.","holds the number of sellers constant, while the schedule lets it vary.","holds input prices constant, while the schedule lets them vary.","represents one firm, while the schedule represents the whole market."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"A supply schedule and a supply curve carry the same information, one as a table of prices and quantities and the other as a graph. Both hold all other factors constant, so Options B and C are wrong, and either can describe a single firm or a whole market, so Option D is wrong too."}},{"itemId":"c374e660-280a-5142-96f4-14d261974d5a","questionId":"9cb17163-b58e-538d-9166-bd5ace9608bf","sourceKey":"bank:ECO101:ECO-0904","payload":{"prompt":"Which of the following is NOT held constant as we move along a supply curve?","options":["Prices of the inputs used in production","Expected future prices","The number of sellers","The price of the good itself"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Moving along a supply curve means the good's own price is changing, so that is the one thing allowed to vary. Input prices, expectations and the number of sellers (Options A, B and C) are held constant, and a change in any of them shifts the curve."}},{"itemId":"c21cbbde-4b37-571c-899d-41619298bd88","questionId":"a9fb0b40-e432-500e-b725-22d46d6019af","sourceKey":"bank:ECO101:ECO-0905","payload":{"prompt":"If a producer can use the same resources to produce either good X or good Y, then X and Y are","options":["substitutes in consumption.","complements in consumption.","complements in production.","substitutes in production."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"When resources used for one good must be taken away from the other, the goods compete for those resources, which makes them substitutes in production. Complements in production (Option C) come out together from one process, like beef and hides, and Options A and B describe buyers, not producers."}},{"itemId":"06952069-dbda-56f2-843d-1a73d135edce","questionId":"83d3e4ab-2308-5c44-84e7-2569c18585ab","sourceKey":"bank:ECO101:ECO-0906","payload":{"prompt":"Goods X and Y are substitutes in production. The demand for X increases, so the price of X rises. This rise in the price of X shifts the","options":["demand curve for Y to the right.","demand curve for Y to the left.","supply curve of Y to the right.","supply curve of Y to the left."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A higher price for X makes it more profitable, so producers move resources from Y into X and the supply of Y decreases. Options A and B are wrong because the link here runs through production, not through buyers of Y."}},{"itemId":"10f8607e-dc59-5a95-b378-647be1f9404b","questionId":"d24c2623-e550-5224-a4bb-44e7232e1aab","sourceKey":"bank:ECO101:ECO-0907","payload":{"prompt":"A Lagos bakery can use its ovens to bake either bread or meat pies, so the two are substitutes in production. A rise in the price of meat pies will cause","options":["a decrease in the supply of bread.","an increase in the quantity of bread supplied but not in the supply of bread.","a decrease in the quantity of bread supplied but not in the supply of bread.","an increase in the supply of bread."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Dearer meat pies draw oven time away from bread, so the bakery offers less bread at every bread price, which is a decrease in supply. Option C is wrong because the price of bread itself has not changed, so this is a shift of the bread supply curve rather than a movement along it."}},{"itemId":"e8620db3-79ea-58b4-ac39-3eb663e3ab13","questionId":"db788682-01c5-5716-a93a-7e01f5ede102","sourceKey":"bank:ECO101:ECO-0908","payload":{"prompt":"Goods X and Y are substitutes in production. The demand for X decreases, lowering the price of X. The fall in the price of X","options":["increases the demand for Y.","decreases the demand for Y.","increases the supply of Y.","decreases the supply of Y."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"With X less profitable, producers shift resources into Y, so the supply of Y increases. Options A and B are tempting but wrong because substitutes in production are linked through sellers' choices, not buyers'."}},{"itemId":"d7c0c492-191f-5aa8-8f65-77c4621eb0eb","questionId":"c17e084d-d554-54dc-8b4d-97130b65bc6b","sourceKey":"bank:ECO101:ECO-0909","payload":{"prompt":"An increase in the number of fast-food restaurants","options":["increases the demand for substitutes for fast-food meals.","raises the price of fast-food meals.","increases the supply of fast-food meals.","increases the demand for fast-food meals."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"More sellers means more meals are offered at every price, so the supply curve shifts right. Option D confuses sellers with buyers, and Option B gets the price effect backwards, since higher supply tends to lower price."}},{"itemId":"b2752ba1-9341-5400-8d6a-3fa83734bb72","questionId":"25ce67bc-4810-55e4-9be2-0be83c9d8d1d","sourceKey":"bank:ECO101:ECO-0910","payload":{"prompt":"Technological improvements that lower the cost of producing cars have increased","options":["the demand for cars but not the supply.","both the supply of and the demand for cars.","the supply of cars but not the demand.","neither the supply of nor the demand for cars."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Lower production costs let producers offer more cars at each price, which shifts supply to the right. Demand is unaffected because buyers' incomes, tastes and related prices have not changed, which rules out Options A and B."}},{"itemId":"823d70f6-29c5-56f3-9400-04493b2eb024","questionId":"0e33fbb0-2fdc-565c-863e-6199ed2b7e6f","sourceKey":"bank:ECO101:ECO-0911","payload":{"prompt":"Which of the following will shift the supply curve of good X to the left?","options":["Quantity demanded exceeding quantity supplied","A rise in the cost of the machinery used to produce X","A fall in the wages of workers who produce X","A technological improvement in producing X"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Higher input costs make production less profitable, so producers offer less at every price and supply shifts left. Options C and D lower costs and shift supply right, and Option A is a shortage, which changes price rather than shifting supply."}},{"itemId":"dbeb099a-50a1-5102-b728-92156589b7d9","questionId":"24582669-1be5-5fab-96cc-96ba0926d309","sourceKey":"bank:ECO101:ECO-0912","payload":{"prompt":"Which of the following does NOT shift the supply curve?","options":["A rise in the price of the good","A fall in the price of a substitute in production","A fall in the wages of labour used to produce the good","A technological advance"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"A change in the good's own price moves producers along the existing supply curve. Options B, C and D change production costs or profitability, so each of them shifts the curve."}},{"itemId":"26a24df9-36e1-5430-a151-d8ef420313cf","questionId":"fa9b5360-342a-5a38-8c63-04cb0f8c0cfd","sourceKey":"bank:ECO101:ECO-0913","payload":{"prompt":"If the price of a good changes but everything else affecting sellers' plans stays the same, there is a","options":["rotation of the supply curve around the initial price.","new supply curve to the right of the original one.","new supply curve to the left of the original one.","movement along the supply curve."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"When only the good's own price changes, sellers move to a different point on the same supply curve. Options B and C would need a change in some other factor such as costs, technology or the number of sellers."}},{"itemId":"2187c64f-f9a9-53e8-910c-8dfe9d53edaa","questionId":"52c3c29a-1dbd-59fd-a373-f3c97e4c75dd","sourceKey":"bank:ECO101:ECO-0914","payload":{"prompt":"A decrease in the quantity supplied is shown by a","options":["rightward shift of the supply curve.","movement down along the supply curve.","leftward shift of the supply curve.","movement up along the supply curve."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Quantity supplied falls when the good's price falls, which moves sellers down and to the left along the upward-sloping supply curve. Option C is tempting, but a leftward shift is a decrease in supply caused by something other than the good's own price."}},{"itemId":"6b7618b4-c866-5bea-80d7-2a0c0c239e08","questionId":"b76f9e1a-269b-57a3-919e-463f32a3be7e","sourceKey":"bank:ECO101:ECO-0915","payload":{"prompt":"Which of the following increases the quantity supplied of good X but NOT the supply of good X?","options":["A rise in the price of X","A rise in the price of Y, a complement in production of X","An improvement in the technology for producing X","A fall in the price of resources used to produce X"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Only a change in the good's own price causes a movement along the supply curve, which is a change in quantity supplied. Options B, C and D each shift the supply curve of X to the right, which is an increase in supply."}},{"itemId":"f7455c2a-cf6b-5a23-8c02-bb45f36f74a7","questionId":"b29422af-f98d-5ce0-8fe1-2d8b763fbc48","sourceKey":"bank:ECO101:ECO-0916","payload":{"prompt":"The interaction of demand and supply determines","options":["both the prices and the quantities of goods and services.","the quantities of goods and services but not their prices.","the prices of goods and services but not their quantities.","neither the prices nor the quantities of goods and services."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Where the demand and supply curves cross we read off both the equilibrium price and the equilibrium quantity. Options B and C each leave out one half of what the market determines."}},{"itemId":"ad35c573-ecec-5940-9509-3c29684d5bca","questionId":"30b00fc1-f14f-5277-81e8-4b1ab14251fe","sourceKey":"bank:ECO101:ECO-0917","payload":{"prompt":"When the quantity demanded equals the quantity supplied,","options":["the government must be intervening in the market.","there is a shortage.","there is a surplus.","the market is in equilibrium."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Equilibrium is the price at which buyers' plans and sellers' plans match exactly, so nothing pushes the price to change. A shortage or surplus (Options B and C) needs the two quantities to differ, and markets reach equilibrium without government action, so Option A is wrong."}},{"itemId":"0f02a997-c7ca-5111-97c2-f6954204bfa8","questionId":"35882b72-4d1a-5c7c-95bb-007b95bc8b67","sourceKey":"bank:ECO101:ECO-0918","payload":{"prompt":"When the price is below the equilibrium price, the quantity demanded","options":["is less than the equilibrium quantity, and the quantity supplied is greater than it.","is greater than the equilibrium quantity, and the quantity supplied is less than it.","is greater than the equilibrium quantity, and so is the quantity supplied.","is less than the equilibrium quantity, and so is the quantity supplied."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A lower price moves buyers down their demand curve to a larger quantity and moves sellers down their supply curve to a smaller quantity. Option A describes a price above equilibrium, and Options C and D ignore that demand and supply respond to price in opposite directions."}},{"itemId":"5b372188-0322-50ec-987b-b3a8d6bbc72d","questionId":"993f3e50-eb6b-5454-b032-20d5018d5df8","sourceKey":"bank:ECO101:ECO-0919","payload":{"prompt":"A price below the equilibrium price results in","options":["a further fall in price.","a shortage.","excess supply.","a surplus."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Below equilibrium, buyers want more than sellers offer, so quantity demanded exceeds quantity supplied, which is a shortage. Options C and D mean the same thing, a surplus, which happens when price is above equilibrium, and a shortage pushes price up, not down as Option A says."}},{"itemId":"2008a622-5409-591f-a216-0d1336ebc50d","questionId":"70fada16-2d6f-5f42-8e4b-bb24bc036756","sourceKey":"bank:ECO101:ECO-0920","payload":{"prompt":"Which of the following correctly describes how price changes eliminate a shortage?","options":["As the price falls, quantity demanded increases and quantity supplied decreases.","As the price rises, quantity demanded decreases and quantity supplied increases.","As the price falls, quantity demanded decreases and quantity supplied increases.","As the price rises, quantity demanded increases and quantity supplied decreases."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"In a shortage, buyers compete for the limited goods and bid the price up; the higher price cuts quantity demanded and encourages more supply until the gap closes. Option A would make the shortage worse, and Option D gets both responses backwards."}},{"itemId":"af0b04ee-2895-58ee-be04-8e33f64b86c5","questionId":"eb15f2ae-d802-5e86-a662-b5254b2933de","sourceKey":"bank:ECO101:ECO-0921","payload":{"prompt":"A shortage causes the","options":["supply curve to shift to the right.","price to rise.","price to fall.","demand curve to shift to the left."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"When quantity demanded exceeds quantity supplied, frustrated buyers offer more and sellers raise their prices. Options A and D are wrong because a shortage leads to movements along the curves as price adjusts, not shifts of the curves."}},{"itemId":"bb03753b-2dbb-5784-b416-fc566c79677d","questionId":"0b88c327-2e0f-5e9b-9ded-a622d284442c","sourceKey":"bank:ECO101:ECO-0922","payload":{"prompt":"If the quantity demanded exceeds the quantity supplied, there is","options":["a shortage, and the price is above the equilibrium price.","a surplus, and the price is below the equilibrium price.","a shortage, and the price is below the equilibrium price.","a surplus, and the price is above the equilibrium price."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Excess quantity demanded is a shortage, and it only happens when the price is too low to clear the market. Option A names the shortage correctly but puts the price on the wrong side of equilibrium."}},{"itemId":"0faf3c43-c047-53f4-ae34-6bbe4b4ce4b6","questionId":"4a176979-ee7d-5dd3-afce-a98e4712076e","sourceKey":"bank:ECO101:ECO-0923","payload":{"prompt":"A surplus occurs when the price is","options":["equal to the equilibrium price.","greater than the equilibrium price.","less than the equilibrium price.","at any level, because a surplus does not depend on price."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Above equilibrium, sellers offer more than buyers want, leaving unsold stock. Option C describes the condition for a shortage, and Option A is where neither a surplus nor a shortage exists."}},{"itemId":"3deee9e2-876f-59e7-bd0c-0b1bcba7ab08","questionId":"16281a0a-d8bf-5724-8b3d-d994ea008265","sourceKey":"bank:ECO101:ECO-0924","payload":{"prompt":"If the quantity supplied exceeds the quantity demanded, there is","options":["a shortage, and the price is below the equilibrium price.","a surplus, and the price is below the equilibrium price.","a surplus, and the price is above the equilibrium price.","a shortage, and the price is above the equilibrium price."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Excess quantity supplied is a surplus, which arises when the price is set too high for the market to clear. Option B names the surplus correctly but places the price below equilibrium, where a shortage would occur instead."}},{"itemId":"d156e968-4d47-54d9-b46a-3fbb1bc0b056","questionId":"eee510b5-4d3c-575b-9b58-a120883337a0","sourceKey":"bank:ECO101:ECO-0925","payload":{"prompt":"The price of a good will fall if","options":["the price of a complement falls.","there is a surplus at the current price.","the quantity demanded exceeds the quantity supplied.","the current price is below the equilibrium price."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"With unsold goods piling up, sellers cut their prices to clear their stock. Options C and D describe a shortage, which pushes the price up, and Option A raises demand for the good, which also tends to raise its price."}},{"itemId":"9f05a2eb-38d9-567d-b92c-617714e51e8d","questionId":"3de0514d-6aed-59d5-90d9-3ddee776548f","sourceKey":"bank:ECO101:ECO-0926","payload":{"prompt":"A market analyst records the following schedules for the market for honey beans in Lagos. Price (N per kg): 100, 200, 300, 400, 500. Quantity demanded (millions of kg per year) - Demand 1: 15, 12, 9, 6, 3; Demand 2: 10, 8, 6, 3, 2; Demand 3: 5, 4, 3, 2, 1. Quantity supplied (millions of kg per year) - Supply A: 1, 2, 3, 4, 5; Supply B: 2, 4, 6, 8, 10; Supply C: 3, 6, 9, 12, 15. In a normal year, demand is Demand 2 and supply is Supply B. In a normal year, the price of honey beans will be","options":["N300 per kg.","N400 per kg.","N200 per kg.","N100 per kg."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Equilibrium is where quantity demanded equals quantity supplied: with Demand 2 and Supply B, both equal 6 million kg at N300. At N200 (Option C) buyers want 8 million kg but sellers offer only 4 million, a shortage, and at N400 (Option B) sellers offer 8 million while buyers want 3 million, a surplus."}},{"itemId":"af1d1651-4f25-59f5-bcc1-dab2058e0d9a","questionId":"48778edc-9fbd-5e39-b1f3-8327fee28ab1","sourceKey":"bank:ECO101:ECO-0927","payload":{"prompt":"A market analyst records the following schedules for the market for honey beans in Lagos. Price (N per kg): 100, 200, 300, 400, 500. Quantity demanded (millions of kg per year) - Demand 1: 15, 12, 9, 6, 3; Demand 2: 10, 8, 6, 3, 2; Demand 3: 5, 4, 3, 2, 1. Quantity supplied (millions of kg per year) - Supply A: 1, 2, 3, 4, 5; Supply B: 2, 4, 6, 8, 10; Supply C: 3, 6, 9, 12, 15. In a normal year, demand is Demand 2 and supply is Supply B. In a normal year, the equilibrium quantity of honey beans will be","options":["8 million kg.","4 million kg.","6 million kg.","2 million kg."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Under Demand 2 and Supply B, the only price where quantity demanded equals quantity supplied is N300, and the quantity there is 6 million kg. Options A and B are the quantities demanded and supplied at N200, where the market is in shortage rather than equilibrium."}},{"itemId":"795b5975-3a63-592f-a767-f8fd1f977a08","questionId":"c1435d86-ad22-57f3-9dc1-02de7b4c7f5d","sourceKey":"bank:ECO101:ECO-0928","payload":{"prompt":"A market analyst records the following schedules for the market for honey beans in Lagos. Price (N per kg): 100, 200, 300, 400, 500. Quantity demanded (millions of kg per year) - Demand 1: 15, 12, 9, 6, 3; Demand 2: 10, 8, 6, 3, 2; Demand 3: 5, 4, 3, 2, 1. Quantity supplied (millions of kg per year) - Supply A: 1, 2, 3, 4, 5; Supply B: 2, 4, 6, 8, 10; Supply C: 3, 6, 9, 12, 15. In a normal year, demand is Demand 2 and supply is Supply B. If a drought hits the bean-growing areas, supply will ________ and demand will ________.","options":["stay at Supply B; become Demand 3","stay at Supply B; become Demand 1","become Supply A; become Demand 1","become Supply A; stay at Demand 2"],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A drought reduces the harvest, so sellers offer less at every price, which is the move from Supply B to the smaller Supply A. Nothing has changed for buyers, so demand stays at Demand 2; Options A and B wrongly treat the drought as a change in demand."}},{"itemId":"a1b8121a-d579-5080-bf3c-9457a2c23b10","questionId":"42ae881b-ac1c-576e-b074-b8b2ba4433f3","sourceKey":"bank:ECO101:ECO-0929","payload":{"prompt":"A market analyst records the following schedules for the market for honey beans in Lagos. Price (N per kg): 100, 200, 300, 400, 500. Quantity demanded (millions of kg per year) - Demand 1: 15, 12, 9, 6, 3; Demand 2: 10, 8, 6, 3, 2; Demand 3: 5, 4, 3, 2, 1. Quantity supplied (millions of kg per year) - Supply A: 1, 2, 3, 4, 5; Supply B: 2, 4, 6, 8, 10; Supply C: 3, 6, 9, 12, 15. In a normal year, demand is Demand 2 and supply is Supply B. If the bean-growing areas enjoy exceptionally good weather, supply will ________ and demand will ________.","options":["stay at Supply B; become Demand 1","become Supply C; stay at Demand 2","become Supply C; become Demand 3","become Supply C; become Demand 1"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Good weather increases the harvest, so the market moves to Supply C, which offers more beans at every price. Buyers' incomes, tastes and other factors are unchanged, so demand remains Demand 2, which rules out Options C and D."}},{"itemId":"ad038bc0-bc86-54d7-b9e2-dae1aa0dd629","questionId":"edd0c305-7065-52c3-90b6-aae9f66b5dfe","sourceKey":"bank:ECO101:ECO-0930","payload":{"prompt":"A market analyst records the following schedules for the market for honey beans in Lagos. Price (N per kg): 100, 200, 300, 400, 500. Quantity demanded (millions of kg per year) - Demand 1: 15, 12, 9, 6, 3; Demand 2: 10, 8, 6, 3, 2; Demand 3: 5, 4, 3, 2, 1. Quantity supplied (millions of kg per year) - Supply A: 1, 2, 3, 4, 5; Supply B: 2, 4, 6, 8, 10; Supply C: 3, 6, 9, 12, 15. In a normal year, demand is Demand 2 and supply is Supply B. If it is discovered that honey beans help prevent a serious disease, supply will ________ and demand will ________.","options":["stay at Supply B; become Demand 1","become Supply C; stay at Demand 2","become Supply A; become Demand 1","become Supply C; become Demand 1"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"A health discovery changes buyers' preferences, so people want more beans at every price and demand moves to the larger Demand 1. Growing conditions and costs are unchanged, so supply stays at Supply B; Options C and D wrongly shift supply as well."}},{"itemId":"a3503aeb-72a5-5f71-b0e0-fbbf08b80239","questionId":"3430e9e1-3eb0-5289-9304-c6a278900189","sourceKey":"bank:ECO101:ECO-0931","payload":{"prompt":"When the demand for a good decreases (and supply is unchanged), its equilibrium price ________ and its equilibrium quantity ________.","options":["rises; decreases","falls; decreases","falls; increases","rises; increases"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A leftward shift of demand along an unchanged upward-sloping supply curve moves the equilibrium down and to the left, so both price and quantity fall. Option A would need supply, not demand, to decrease."}},{"itemId":"bacbe905-32d2-59a0-86f4-311ea7e5e5c4","questionId":"222fc00f-7ff2-5d3b-89f1-046c39593077","sourceKey":"bank:ECO101:ECO-0932","payload":{"prompt":"Good A is a normal good. If income increases, the equilibrium price of A","options":["and its equilibrium quantity both increase.","and its equilibrium quantity both decrease.","rises and its equilibrium quantity decreases.","falls and its equilibrium quantity increases."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Higher income raises demand for a normal good, shifting demand right along the supply curve, so price and quantity both go up. Option B would be the result for an inferior good, and Options C and D come from supply shifts."}},{"itemId":"6a51fefc-3f49-5118-9603-9461d8d75727","questionId":"56222bfd-7afa-5769-b9c6-20207eeacf77","sourceKey":"bank:ECO101:ECO-0933","payload":{"prompt":"The price of a litre of milk falls. Which of the following could be the cause?","options":["A discovery that drinking milk causes diabetes","A drought that reduces the supply of feed for dairy cows","A rise in average household income, with milk a normal good","A fall in the price of oats, a complement of milk"],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"A health scare cuts demand for milk, and lower demand with unchanged supply lowers the price. Option B reduces supply, while Options C and D raise demand, and all three would push the price of milk up."}},{"itemId":"1d79b98a-7c4b-5335-ae29-2e953a50e674","questionId":"b9003bb2-0dd4-59fc-bed6-7ee8d13c1715","sourceKey":"bank:ECO101:ECO-0934","payload":{"prompt":"Beef and pork are substitutes for consumers. A drought hits the cattle-grazing areas. The drought will cause the","options":["supply curve of pork to shift to the right.","supply curve of pork to shift to the left.","demand curve for pork to shift to the left.","demand curve for pork to shift to the right."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"The drought cuts the supply of beef and raises its price, so consumers switch to pork and the demand for pork increases. Options A and B are wrong because the drought affects cattle, not pig farming, so pork supply is unchanged."}},{"itemId":"344f7ee3-1cdf-5a4b-9c2c-92aed99c0873","questionId":"a2a9393d-ea16-5047-aed8-d0d80b26a6f6","sourceKey":"bank:ECO101:ECO-0935","payload":{"prompt":"An increase in demand with no change in supply causes","options":["a decrease in demand, because supply does not shift.","the equilibrium price to fall.","a movement to the right along the demand curve.","the equilibrium price to rise."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"A rightward shift of demand creates a shortage at the old price, which pushes the price up to a new, higher equilibrium. Option C is wrong because the demand curve itself has shifted; the movement that happens is along the supply curve."}},{"itemId":"9f3f935f-227b-5f2c-9f72-87ae23216bd3","questionId":"be0ebfd6-5994-593c-92c2-16c084bb3d01","sourceKey":"bank:ECO101:ECO-0936","payload":{"prompt":"Goods A and B are complements in consumption. The cost of an input used to produce A falls. As a result,","options":["the equilibrium price of B falls and the equilibrium price of A rises.","the equilibrium prices of both A and B rise.","the equilibrium price of B rises and the equilibrium price of A falls.","the equilibrium prices of both A and B fall."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Cheaper inputs increase the supply of A, so A's price falls and more A is bought. Because B is used with A, demand for B rises and B's price goes up. Option D is tempting but forgets that the link to B runs through higher demand, which raises B's price."}},{"itemId":"0805a0be-c477-50e9-afb5-5eb7204511ed","questionId":"aa427d01-02c5-52b0-8b54-5d94ec2a3d22","sourceKey":"bank:ECO101:ECO-0938","payload":{"prompt":"When supply decreases and demand does not change, the equilibrium quantity","options":["decreases and the price rises.","increases and the price falls.","decreases and the price falls.","increases and the price rises."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Supply shifting left along a fixed demand curve creates a shortage at the old price, so price rises and the quantity bought falls. Option C would come from a decrease in demand, not supply."}},{"itemId":"b8812210-3f40-556c-bf63-42f916e0585a","questionId":"5e8d846a-e6fe-55f0-9b53-76c67447df63","sourceKey":"bank:ECO101:ECO-0939","payload":{"prompt":"Beef and leather are complements in production (hides come from the same cattle). If health concerns shift the demand for beef to the left, the market for leather belts will see a","options":["lower equilibrium price for belts, because the supply of belts increases.","higher equilibrium price for belts, because the supply of belts decreases.","lower equilibrium price for belts, because the supply of belts decreases.","higher equilibrium price for belts, because the supply of belts increases."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Less beef demanded means fewer cattle slaughtered, which means fewer hides, so the supply of leather belts decreases and their price rises. Option C gets the supply change right but the price effect wrong, since lower supply raises price."}},{"itemId":"6f6c7dba-bec3-58cb-8777-bce3ef4e3a53","questionId":"b3065a87-7bc7-53e5-a9ad-f69c26dda1c7","sourceKey":"bank:ECO101:ECO-0940","payload":{"prompt":"You observe that the price of a good rises while the quantity traded falls. This could be the result of","options":["the supply curve shifting to the right.","the demand curve shifting to the right.","the demand curve shifting to the left.","the supply curve shifting to the left."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Price and quantity moving in opposite directions points to a supply shift, and a higher price with lower quantity means supply decreased. Option B would raise both price and quantity, and Option C would lower both."}},{"itemId":"e29cad2e-2a41-50d6-9351-37434be94fc2","questionId":"b51abc45-9fa3-509c-9e9a-9591ce87017d","sourceKey":"bank:ECO101:ECO-0941","payload":{"prompt":"Leather belts and leather shoes are substitutes in production. If fashion changes increase the demand for leather belts, the supply curve of leather shoes will shift","options":["to the right, and the price of leather shoes will fall.","to the left, and the price of leather shoes will rise.","to the left, and the price of leather shoes will fall.","to the right, and the price of leather shoes will rise."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Higher belt prices pull leather and labour away from shoes, so the supply of shoes decreases and their equilibrium price rises. Option C has the right shift but the wrong price effect, because a fall in supply raises price."}},{"itemId":"f7a2ed36-3e2a-5f75-a66c-12945f507896","questionId":"07917210-d1e5-579e-8a3f-8fddd61454fe","sourceKey":"bank:ECO101:ECO-0942","payload":{"prompt":"If both demand and supply increase, what happens to the equilibrium price and quantity?","options":["Price rises, but quantity could increase, decrease or stay the same.","Quantity increases, but price could rise, fall or stay the same.","Both price and quantity increase.","Price falls and quantity increases."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Both shifts push quantity up, so quantity definitely increases, but the demand shift pushes price up while the supply shift pushes it down. Which effect wins depends on the size of the shifts, so Options C and D claim more certainty about price than we have."}},{"itemId":"504606c8-839d-56a7-87b9-e9634e3950a8","questionId":"5da374f5-596b-525b-a656-22effd95f145","sourceKey":"bank:ECO101:ECO-0944","payload":{"prompt":"The price will rise while the equilibrium quantity might increase, decrease or stay the same when","options":["demand and supply both increase.","demand and supply both decrease.","demand increases and supply decreases.","demand decreases and supply increases."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Higher demand and lower supply both push price up, so price definitely rises, while their effects on quantity cancel in an uncertain way. Options A and B give a definite change in quantity but an uncertain price, the reverse of what is described."}},{"itemId":"0f017e88-b208-515e-9a9c-4480ad92cbb9","questionId":"a718c205-f93f-5ebf-9cd5-ce0f65a05086","sourceKey":"bank:ECO101:ECO-0945","payload":{"prompt":"The price will fall while the equilibrium quantity might increase, decrease or stay the same when","options":["demand increases and supply decreases.","demand and supply both decrease.","demand decreases and supply increases.","demand and supply both increase."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Lower demand and higher supply both push price down, while one lowers quantity and the other raises it, so the quantity effect is uncertain. Option A is the mirror case, in which price definitely rises."}},{"itemId":"44234b5a-ea02-5d3e-8255-d451050e8fc6","questionId":"3ff9c7f7-c80f-5920-a344-9851f8c35c26","sourceKey":"bank:ECO101:ECO-0946","payload":{"prompt":"The equilibrium quantity will decrease while the price might rise, fall or stay the same when","options":["demand and supply both decrease.","demand increases and supply decreases.","demand decreases and supply increases.","demand and supply both increase."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"When both curves shift left, each one reduces quantity, but the fall in demand lowers price while the fall in supply raises it. Option D also leaves price uncertain, but there quantity rises rather than falls."}},{"itemId":"13e52ec1-ee86-5e5a-9434-26c47d3a1c61","questionId":"aa9bd214-29bf-5bd1-8297-914ea04b18d6","sourceKey":"bank:ECO101:ECO-0947","payload":{"prompt":"The equilibrium quantity of a good will increase while its price might rise, fall or stay the same when","options":["demand decreases and supply increases.","demand increases and supply decreases.","demand and supply both increase.","demand and supply both decrease."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Two rightward shifts both raise quantity, but their price effects work against each other. Options A and B give a definite price change with an uncertain quantity, which is the opposite pattern."}},{"itemId":"fb01fa9d-6fa6-51c1-b43f-0a97cf7ce29e","questionId":"ca6f1676-42c5-56d4-8d10-67ae731c7444","sourceKey":"bank:ECO101:ECO-0948","payload":{"prompt":"Over several years, the price of solar inverters fell even though improving technology, rising incomes and falling prices of solar panels (a complement) were all affecting the market. The price fell because","options":["demand for inverters shifted right by more than supply shifted right.","supply of inverters shifted right by more than demand shifted right.","demand for inverters and supply of inverters both shifted left.","supply of inverters shifted right while demand for inverters shifted left."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Better technology raises supply, while higher incomes and cheaper panels raise demand, so both curves shift right. For the price to fall, the supply increase must have been larger than the demand increase. Option A would raise the price, and Option D is wrong because the demand factors described all increase demand."}},{"itemId":"7e57d106-061f-5892-bba9-9f48ea61ff5e","questionId":"82b59583-326a-5354-93c2-70b3eaa170c8","sourceKey":"bank:ECO101:ECO-0950","payload":{"prompt":"The demand and supply functions for a good are Qd = 20 - 2P and Qs = 5 + 3P, where P is the price in naira. The equilibrium price is","options":["N2.","N3.","N4.","N1."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"At equilibrium Qd = Qs, so 20 - 2P = 5 + 3P, which gives 15 = 5P and P = 3. At P = 2 (Option A), Qd = 16 but Qs = 11, so there would still be a shortage."}},{"itemId":"ee5bedfc-fdc6-53ce-a3a0-02a24ad30191","questionId":"ec5edfaa-be97-5b01-bbc4-2c9ed25c31b9","sourceKey":"bank:ECO101:ECO-0951","payload":{"prompt":"The demand and supply functions for a good are Qd = 20 - 2P and Qs = 5 + 3P, where P is the price in naira. The equilibrium quantity is","options":["14.","5.","20.","3."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Setting 20 - 2P = 5 + 3P gives P = 3, and substituting back gives Qd = 20 - 6 = 14 and Qs = 5 + 9 = 14. Option D is the equilibrium price, not the quantity, and Options B and C are just the intercepts of the two equations."}},{"itemId":"08fd1690-94d6-57ae-945c-61c6787b2e19","questionId":"b8f74078-110a-5b56-a47a-7cd2d4bdd663","sourceKey":"bank:ECO101:ECO-0952","payload":{"prompt":"A consumer would most likely regard roller skates and elbow pads as","options":["unrelated goods.","substitutes.","goods with upward-sloping demand curves.","complements."],"correctOption":3,"section":"Demand and Supply Analysis","explanation":"Elbow pads are bought to be used while skating, so the two goods are consumed together, which makes them complements. They are not substitutes (Option B), because one cannot replace the other."}},{"itemId":"0e61206d-8dd1-57fb-9641-231a278507f2","questionId":"6137718c-fa64-5dc9-8feb-f6c5b0b24e29","sourceKey":"bank:ECO101:ECO-0953","payload":{"prompt":"A fall in the price of renting a five-a-side football pitch shifts the","options":["demand curve for football boots to the right.","supply curve of football boots to the left.","supply curve of football boots to the right.","demand curve for football boots to the left."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Cheaper pitch rental means more people play, and since boots are used with the pitch, the two are complements and demand for boots rises. Options B and C are wrong because pitch prices affect buyers of boots, not the cost of making them."}},{"itemId":"539de106-7a2d-5978-9964-e5c44cf245f9","questionId":"aaef8808-f5ee-58f9-83a9-307cab7ab15f","sourceKey":"bank:ECO101:ECO-0954","payload":{"prompt":"If a fall in the price of petrol increases the demand for large cars, then","options":["petrol and large cars are complements in consumption.","large cars are an inferior good.","petrol is an inferior good.","petrol and large cars are substitutes in consumption."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"When a cheaper good raises demand for another good, the two are used together, which defines complements. With substitutes (Option D), cheaper petrol would reduce demand for cars, and Options B and C are about income effects, not related prices."}},{"itemId":"3a27090c-fd64-5a28-b657-6206ed444f21","questionId":"8a088bcd-da23-5ff3-963a-cdf382bbc1e2","sourceKey":"bank:ECO101:ECO-0955","payload":{"prompt":"Assume that second-hand clothing is an inferior good. A fall in people's incomes","options":["shifts the supply curve of second-hand clothing to the left.","shifts the demand curve for second-hand clothing to the right.","shifts the demand curve for second-hand clothing to the left.","decreases the quantity of second-hand clothing supplied."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"For an inferior good, demand moves opposite to income, so poorer consumers buy more of it at every price and demand shifts right. Option C is what would happen to a normal good, and Options A and D wrongly link income to the sellers' side."}},{"itemId":"b2da9af7-103f-5033-8c46-6fcb5db5c337","questionId":"8f7d0c52-11da-564b-85ed-7df732bfe099","sourceKey":"bank:ECO101:ECO-0956","payload":{"prompt":"An unusually short and light rainy season","options":["shifts the supply curve of umbrellas to the left.","shifts the demand curve for umbrellas to the right.","shifts the demand curve for umbrellas to the left.","shifts the supply curve of umbrellas to the right."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"With less rain, people need umbrellas less, so they want fewer at every price and demand shifts left. The weather does not change the cost of making umbrellas, so Options A and D are wrong."}},{"itemId":"dd4d0b10-64d2-5e97-b2d7-ad546d568346","questionId":"7f778f10-0f8e-5aec-9f8b-c605a23e20d0","sourceKey":"bank:ECO101:ECO-0957","payload":{"prompt":"A rise in the price of a good leads producers to supply more of it. This illustrates","options":["the nature of an inferior good.","the law of demand.","the law of supply.","a change in supply."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"The law of supply says that, other things equal, a higher price raises the quantity supplied. Option D is wrong because a response to the good's own price is a movement along the supply curve, and Option B describes buyers rather than producers."}},{"itemId":"f4be74a7-c9de-5cda-8b09-0f79c1625c74","questionId":"4a4206cd-b607-5564-b9c7-6698cb3e063e","sourceKey":"bank:ECO101:ECO-0958","payload":{"prompt":"The price of aviation fuel falls. This shifts the","options":["supply curve of air travel to the right.","demand curve for air travel to the left.","demand curve for air travel to the right.","supply curve of air travel to the left."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Fuel is a major input for airlines, so cheaper fuel lowers their costs and they offer more flights at every fare. Option C is tempting, but fuel is bought by airlines, not passengers, so the effect works through supply."}},{"itemId":"396e91de-5aca-5d4a-81e7-39d7c7ade376","questionId":"b7c53a10-bfb3-5173-bd05-a734e6e9a1e8","sourceKey":"bank:ECO101:ECO-0959","payload":{"prompt":"If there is a surplus of a good, the quantity demanded ________ the quantity supplied, and the price will ________.","options":["is less than; rise","is less than; fall","is greater than; fall","is greater than; rise"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"A surplus means sellers have more than buyers want, so quantity demanded is below quantity supplied and sellers cut prices to clear stock. Option A gets the quantities right but the price direction wrong."}},{"itemId":"2ecfb1df-0d5c-5cbc-81d9-020e8983c74c","questionId":"089ce2b6-2b98-577c-963d-b984cfac2ad8","sourceKey":"bank:ECO101:ECO-0960","payload":{"prompt":"Shawarma and burgers are substitutes for consumers. A fall in the price of shawarma ________ the price of burgers and ________ the quantity of burgers bought.","options":["raises; decreases","lowers; decreases","raises; increases","lowers; increases"],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Cheaper shawarma draws buyers away from burgers, so demand for burgers shifts left, and with unchanged supply both the price and quantity of burgers fall. Option D is wrong because a decrease in demand reduces quantity rather than increasing it."}},{"itemId":"3374eae6-9b5d-528a-b72c-19cd7f88f154","questionId":"3f71f067-7ccc-511e-9ce2-14cf5a2085e6","sourceKey":"bank:ECO101:ECO-0961","payload":{"prompt":"How does an unusually short and light rainy season affect the equilibrium price and quantity of umbrellas?","options":["It lowers both the price and the quantity.","It raises both the price and the quantity.","It raises the price and lowers the quantity.","It lowers the price and raises the quantity."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Less rain reduces the demand for umbrellas, and a leftward demand shift along an unchanged supply curve lowers both price and quantity. Option D would need supply to increase, which the weather does not cause."}},{"itemId":"d9f4a55c-253b-55e2-a21d-cbef9e81d41b","questionId":"2ba5fae7-b0e3-5f44-b308-1a5769ce5726","sourceKey":"bank:ECO101:ECO-0962","payload":{"prompt":"You notice that the price and the quantity of maize both fall. This could be the result of the","options":["demand curve for maize shifting to the left.","supply curve of maize shifting to the right.","demand curve for maize shifting to the right.","supply curve of maize shifting to the left."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"When price and quantity move in the same direction, demand has shifted, and since both fell, demand decreased. Option B would lower the price but raise the quantity."}},{"itemId":"801e9dfd-dcec-5a2c-bf0e-b619f1c1a543","questionId":"ce0f796d-67a3-50d7-b90f-3b5b1c9cab4c","sourceKey":"bank:ECO101:ECO-0963","payload":{"prompt":"A technological improvement lowers the cost of producing coffee. At the same time, consumers' preference for coffee increases. The equilibrium price of coffee will","options":["rise, fall or stay the same, depending on the relative sizes of the demand and supply shifts.","stay the same.","fall.","rise."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Lower costs increase supply, which pushes price down, while stronger preferences increase demand, which pushes price up. Without knowing which shift is larger we cannot say which way price moves, so Options C and D are too certain; only the quantity definitely rises."}},{"itemId":"25810839-34b6-5336-b8d9-dd86d35f12de","questionId":"b4aff206-d429-5f85-8f8e-80dc1dd5f9c5","sourceKey":"bank:ECO101:ECO-0965","payload":{"prompt":"The price of video-streaming subscriptions rises while the price of DVDs falls. The combined effect of these two changes is","options":["a leftward shift of the demand curve for DVD players.","a rightward shift of the demand curve for DVD players.","a rightward shift of the supply curve of DVD players.","a leftward shift of the supply curve of DVD players."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Streaming is a substitute for DVD players, so a dearer subscription raises demand for players, and DVDs are a complement, so cheaper discs also raise demand. Both forces shift demand for DVD players to the right, and neither affects producers' costs, which rules out Options C and D."}},{"itemId":"2c6862bb-c22d-58bc-b520-fc9b2bd3700a","questionId":"0780df74-f673-5435-9667-abdcffebc6d2","sourceKey":"bank:ECO101:ECO-0966","payload":{"prompt":"A Lagos market analyst who studies portable rechargeable fans expects a recession. If rechargeable fans are a normal good, you would predict that the demand for them will","options":["increase.","either increase or decrease.","decrease.","remain unchanged."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"A recession lowers incomes, and lower income reduces demand for a normal good. Option A would be the prediction for an inferior good."}},{"itemId":"b35e8e1d-c29b-5b36-a96e-4a2f4b0ceeb2","questionId":"6cd54a5d-5352-5f94-b716-d112fe14aaa0","sourceKey":"bank:ECO101:ECO-0967","payload":{"prompt":"Wages for the workers who make rechargeable fans and similar products will rise next year. What is the main effect you would predict in next year's market for rechargeable fans?","options":["The demand curve for fans shifts to the left.","The supply curve of fans shifts to the right.","The supply curve of fans shifts to the left.","The demand curve for fans shifts to the right."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Higher wages raise production costs, so producers offer fewer fans at each price and supply decreases. Option A is wrong because the wage change affects producers' costs rather than buyers' demand."}},{"itemId":"080cb29a-4cfe-5f15-97df-7fca6e12dd82","questionId":"ddb2566a-e237-52fb-9aef-e798b2449647","sourceKey":"bank:ECO101:ECO-0969","payload":{"prompt":"The wage rate paid by producers of rechargeable fans falls, and at the same time the price of the raw materials they use rises. You predict that the supply curve of fans will","options":["definitely shift to the left.","definitely become steeper.","shift either to the left or to the right.","definitely shift to the right."],"correctOption":2,"section":"Demand and Supply Analysis","explanation":"Cheaper labour increases supply while dearer raw materials decrease it, so the net shift depends on which cost change is bigger. Options A and D each ignore one of the two opposing forces."}},{"itemId":"16de3fe2-2954-5b19-bc4c-0d1b8c08b775","questionId":"de795765-14e8-55f3-a1fc-a248cacda9c7","sourceKey":"bank:ECO101:ECO-0970","payload":{"prompt":"Basic MP3 players and smartphones are substitutes. A new technology will soon make smartphones much cheaper to produce. What would you predict for the market for basic MP3 players?","options":["The demand curve for MP3 players shifts left and their price falls.","The price of MP3 players rises, and so does the quantity demanded.","The price of MP3 players falls, and the quantity demanded increases.","The demand curve for MP3 players shifts right and their price rises."],"correctOption":0,"section":"Demand and Supply Analysis","explanation":"Cheaper production lowers the price of smartphones, and since smartphones are a substitute, buyers move away from MP3 players. Demand for MP3 players shifts left, lowering their price and quantity. Option C wrongly treats the change as a movement along the demand curve."}},{"itemId":"ac57cc58-16cf-5d39-9c51-a9a4021548e8","questionId":"1a4c34ce-a219-52cc-a21b-6473fd5e63e6","sourceKey":"bank:ECO101:ECO-0971","payload":{"prompt":"Producers of rechargeable fans will be able to lower the wage rate they pay their workers. What happens to the supply of fans and the price of a fan?","options":["Supply shifts left and the price stays the same.","Supply shifts right and the price falls.","Supply shifts left and the price rises.","Supply shifts right and the price stays the same."],"correctOption":1,"section":"Demand and Supply Analysis","explanation":"Lower wage costs increase supply, and with unchanged demand the larger supply creates a surplus at the old price, so the price falls. Option D is wrong because a supply shift along a downward-sloping demand curve always changes the equilibrium price."}},{"itemId":"446a3453-60f6-5897-bebe-f8846e4be799","questionId":"0a40f90d-98ac-5542-a86e-6c9854a0929d","sourceKey":"bank:ECO101:ECO-0035","payload":{"prompt":"The accumulated skill and knowledge of human beings is called","options":["human worth","education","the opportunity cost of education","human capital"],"correctOption":3,"section":"Production and the Firm","explanation":"Human capital is the stock of skills, knowledge and experience that people build up through education, training and work. Option B, education, is one way of building human capital, not the stock itself. Option C is the cost of schooling, and option A is not an economic term."}},{"itemId":"4b2a29b1-de0c-5dc4-9502-42967df4a48f","questionId":"e7e64f16-d100-5ebd-a307-26719a736766","sourceKey":"bank:ECO101:ECO-0040","payload":{"prompt":"A locus showing different inputs that will give same level of output is called","options":["Locus of point equidistance from the centre.","Isoprofit","Isoquant","Isoline cost"],"correctOption":2,"section":"Production and the Firm","explanation":"An isoquant joins all the combinations of inputs, such as labour and capital, that produce the same level of output. Option D, an isocost line, shows input combinations with the same total cost, not the same output. Option B, an isoprofit line, joins points of equal profit."}},{"itemId":"670c36c3-4727-5964-9d0e-9633b393d08e","questionId":"6f4edc46-19cc-54fc-b083-3ad39bba1b74","sourceKey":"bank:ECO101:ECO-0042","payload":{"prompt":"If output increased by 50% following a 60% increase in inputs, the firm is operating under","options":["Increasing return to scale","Decreasing return to scale","Constant return to scale","Diminishing return"],"correctOption":1,"section":"Production and the Firm","explanation":"Output rose by 50% while inputs rose by 60%, so output grew by less than inputs (50/60 is about 0.83), which is decreasing returns to scale. Option A would need output to rise by more than 60%, and option C would need exactly 60%. Option D, diminishing returns, is a short-run idea about adding one variable input, not about increasing all inputs together."}},{"itemId":"dd822719-e091-5899-9a8b-991215cb80ba","questionId":"03b5a017-2fb9-5ec4-b796-e66d4f5bf188","sourceKey":"bank:ECO101:ECO-0056","payload":{"prompt":"In the long run which costs to the firm are fixed?","options":["Variable costs","Average Costs","Marginal Cost","No costs"],"correctOption":3,"section":"Production and the Firm","explanation":"In the long run all inputs can be changed, so no costs are fixed; every cost becomes variable. Options A, B and C name types of cost that can still change in the long run, so none of them is fixed."}},{"itemId":"b8d8f32e-4864-57de-bf4e-fe1b852a78b3","questionId":"edd9733d-4061-5bab-99bf-16c709228f4e","sourceKey":"bank:ECO101:ECO-0058","payload":{"prompt":"The U-Shaped nature of the average cost curve is due to the operation of the","options":["Law of diminishing returns","Law of comparative cost","Law of demand and supply","None of the above"],"correctOption":0,"section":"Production and the Firm","explanation":"In the short run, average cost first falls as variable inputs are used more fully and then rises once diminishing returns set in, which gives the U shape. Option B, comparative cost, is a trade idea, and option C explains market prices, not a firm's cost curve."}},{"itemId":"b92c559e-4f9f-5b6f-afef-148b42c3427f","questionId":"2bb6059c-e217-5a62-8105-1b956146a21a","sourceKey":"bank:ECO101:ECO-0068","payload":{"prompt":"To the economists, the cost of producing any good or service is the","options":["Production costs","Explicit costs","Opportunity costs","Implicit cost"],"correctOption":2,"section":"Production and the Firm","explanation":"Economists measure the cost of producing anything as its opportunity cost, the value of the next best alternative use of the resources, which includes both explicit and implicit costs. Option A just repeats the question. Option B (explicit costs) and option D (implicit costs) are each only part of opportunity cost."}},{"itemId":"5e6f95e9-821c-5f6e-9a21-2042b602b3b9","questionId":"08dbb406-d5d1-55d7-871f-93dd9d6a462d","sourceKey":"bank:ECO101:ECO-0069","payload":{"prompt":"The money costs which an accountant records in the firms books are known as","options":["Explicit costs","Implicit costs","Opportunity cost","Production costs"],"correctOption":0,"section":"Production and the Firm","explanation":"Explicit costs are actual money payments, such as wages and rent, which an accountant records in the firm's books. Option B, implicit costs, are the value of resources the firm already owns (like the owner's time) and are not recorded as payments. Option C includes these implicit costs too."}},{"itemId":"dfe0e561-e75b-5c7b-89a7-e766d1b9d3a5","questionId":"5db6a63b-aad0-593c-98e3-ded26bddca0c","sourceKey":"bank:ECO101:ECO-0072","payload":{"prompt":"Any surplus earned by any factor of production above the minimum payment necessary to induce the factor to work is","options":["transfer payment","just income","unjust income","economic rent"],"correctOption":3,"section":"Production and the Firm","explanation":"Economic rent is any payment to a factor above its transfer earnings, the minimum needed to keep it in its current use. Option A, transfer payment, is money paid without any productive service in return, such as a pension. Options B and C are value judgements, not economic terms."}},{"itemId":"d37cccb0-f422-5d20-85a7-344bdf4fcd51","questionId":"9d8e1588-aee6-5e3e-9cd0-7f21072b538c","sourceKey":"bank:ECO101:ECO-0074","payload":{"prompt":"Based on the marginal productivity theory, the demand for labour curve is determined by","options":["MRP curve","MRC curve","MC curve","MP curve"],"correctOption":0,"section":"Production and the Firm","explanation":"Marginal productivity theory says a firm hires labour up to the point where the extra revenue from the last worker (MRP) equals the wage, so the MRP curve is the firm's demand curve for labour. Option C, the MC curve, is the firm's cost curve for output, not labour demand. Option D, MP, is in physical units and needs to be multiplied by revenue to give MRP."}},{"itemId":"c686da33-e5d6-5e69-947f-e906a371c209","questionId":"319baca2-1a8b-53a2-a885-9470f5ee29b5","sourceKey":"bank:ECO101:ECO-0075","payload":{"prompt":"Use the table (L / TPL / MPL / P / TR / VMPL / MRPL: 1 / 15 / 15 / 8 / 120 / 120 / 120; 2 / 25 / 10 / 7 / 175 / - / -; 3 / 32 / 7 / 6 / 192 / - / -; Note: L = workers or labour). From the table above, determine the VMPL when 2 workers are employed","options":["42","20","70","192"],"correctOption":2,"section":"Production and the Firm","explanation":"VMPL = P x MPL. When 2 workers are employed, MPL = 10 and P = 7, so VMPL = 7 x 10 = 70. Option A (42) comes from using the third worker's MPL of 7 with P = 6. Option D (192) is total revenue with 3 workers, not VMPL."}},{"itemId":"3eb0227f-3606-5153-a27e-80e6133b0fd8","questionId":"f4790f0a-82a8-5310-85ca-a127f1977d6e","sourceKey":"bank:ECO101:ECO-0076","payload":{"prompt":"Use the table (L / TPL / MPL / P / TR / VMPL / MRPL: 1 / 15 / 15 / 8 / 120 / 120 / 120; 2 / 25 / 10 / 7 / 175 / - / -; 3 / 32 / 7 / 6 / 192 / - / -; Note: L = workers or labour). From the table above, determine the MRPL when 2 workers are employed.","options":["55","70","75","120"],"correctOption":0,"section":"Production and the Firm","explanation":"MRPL is the change in total revenue from hiring one more worker. Going from 1 to 2 workers, TR rises from 120 to 175, so MRPL = 175 - 120 = 55. Option B (70) is VMPL (P x MPL), which is larger than MRPL here because price falls as output rises. Option D (120) is the MRPL for the first worker."}},{"itemId":"dc48aa73-cb74-5ed9-91af-467478b19757","questionId":"7b8f3147-ea4c-5ad1-8e03-7f5cdec40eed","sourceKey":"bank:ECO101:ECO-0087","payload":{"prompt":"The price of labour is determined by","options":["mobility of labour","market demand and supply","years of experience","years of schooling"],"correctOption":1,"section":"Production and the Firm","explanation":"The wage, the price of labour, is determined by the demand for and supply of labour in the labour market. Options A, C and D, mobility, experience and schooling, affect wages by shifting demand or supply, but they do not set the price on their own."}},{"itemId":"e1748fec-2c00-56f2-8f79-0042b2e109f9","questionId":"6b57279b-c835-5010-97b2-faf274b66411","sourceKey":"bank:ECO101:ECO-0092","payload":{"prompt":"There are two effects to changes in the price of labour....","options":["substitution and income effects","wages and price effects","income and leisure effects","demand and supply effects"],"correctOption":0,"section":"Production and the Firm","explanation":"A change in the wage has a substitution effect, since leisure becomes more or less costly compared with work, and an income effect, since workers become richer or poorer. Options B, C and D are not the standard names for these two effects."}},{"itemId":"064b5a1b-7441-5d2e-8693-a25826e75e12","questionId":"9b3c7555-c2f5-5ab8-85a7-18fadb023d50","sourceKey":"bank:ECO101:ECO-0093","payload":{"prompt":"In the early years, productive inputs were divided into three namely.....","options":["land, entrepreneur and labour","labour, capital and entrepreneur","land, labour and capital","capital, entrepreneur and land"],"correctOption":2,"section":"Production and the Firm","explanation":"Early classical economists grouped factors of production into land, labour and capital. The entrepreneur was added later as a separate fourth factor, which is why options A, B and D, which include the entrepreneur, do not match the early classification."}},{"itemId":"097b1706-f264-5765-a688-b714e26c1303","questionId":"a40ab9eb-d3ce-5c29-b5a4-e26aacb95a8b","sourceKey":"bank:ECO101:ECO-0115","payload":{"prompt":"If output increased by 50% following a 50% increase in inputs, the firm is operating under","options":["Increasing return to scale","Decreasing return to scale","Constant return to scale","Diminishing return"],"correctOption":2,"section":"Production and the Firm","explanation":"Output and inputs both rose by 50%, so output grew in exact proportion to inputs (50/50 = 1), which is constant returns to scale. Option B would need output to rise by less than 50%, and option A by more than 50%. Option D, diminishing returns, is a short-run idea about adding just one variable input."}},{"itemId":"65da5d89-9382-5c47-b737-1d652faa6da4","questionId":"0cc512fc-f624-51e4-b996-73d432b7fdf3","sourceKey":"bank:ECO101:ECO-0121","payload":{"prompt":"Wage can best be described as","options":["the sacrifice made by labour","the price of labour","the weekly payment to labour","the opportunity cost of labour"],"correctOption":1,"section":"Production and the Firm","explanation":"A wage is the price paid for labour services, determined by labour demand and supply. Option D is wrong because opportunity cost is what the worker gives up, which helps explain the supply of labour, not what a wage is. Option C is too narrow, because wages can be paid daily or monthly, and option A describes the effort, not the payment."}},{"itemId":"e9f627d0-7d28-597a-88d2-95a19a58a682","questionId":"71c325f9-60e2-5897-a933-bf978f73003c","sourceKey":"bank:ECO101:ECO-0161","payload":{"prompt":"Marginal cost curve cut average variable cost and average cost curve from","options":["above at their highest point","from the middle","from below at their lowest points","none of the above"],"correctOption":2,"section":"Production and the Firm","explanation":"Marginal cost pulls average cost down while it is below it and pulls it up once it is above it, so the MC curve cuts both the AVC and AC curves from below at their minimum points. Option A gets both the direction and the point wrong, since the U-shaped average curves have lowest points, not highest points, where MC crosses them."}},{"itemId":"3df7d3b3-1049-5d4e-8906-d0d66092a516","questionId":"73b4e686-8411-5c13-a58f-0266c08253a9","sourceKey":"bank:ECO101:ECO-0172","payload":{"prompt":"When a worker earns more than his transfer earnings, the excess is called","options":["economic sabotage","economic rent","economic quasi-wage","super wage package"],"correctOption":1,"section":"Production and the Firm","explanation":"Economic rent is any payment to a factor of production above its transfer earnings, the minimum needed to keep it in its present job. So when a worker earns more than this minimum, the excess is economic rent. Options A, C and D are not standard economic terms for this surplus."}},{"itemId":"040cbf85-0d6f-5a14-bb56-aff7997c214d","questionId":"89ade1ce-be05-5f95-9ac8-36845d043a15","sourceKey":"bank:ECO101:ECO-0173","payload":{"prompt":"________ is worth in terms of earning of a worker in his next employment should he desire to change his job","options":["economic wage","economic interest","transfer earnings","transfer payments"],"correctOption":2,"section":"Production and the Firm","explanation":"Transfer earnings are what a factor could earn in its next best alternative use, so for a worker it is the pay in the next job he could move to. Option D, transfer payments, are payments like pensions or grants made without any goods or services in return, which is a different idea."}},{"itemId":"681d47a7-932e-5daa-852b-42cf97b90476","questionId":"c99d2659-5717-595d-9243-1e1b134c569f","sourceKey":"bank:ECO101:ECO-0174","payload":{"prompt":"Most light electronics industries are shifted from the West to China possibly because","options":["Chinese are good people","China is the greatest economy in the world","cost of labour is cheaper and the technical competencies comparable with the west","western countries are no more interested in production"],"correctOption":2,"section":"Production and the Firm","explanation":"Firms locate production where costs are lower for a given quality of output, and cheaper labour combined with comparable technical skills lowers costs of production. Options A and D are not economic reasons, and option B is not why firms move; size of an economy alone does not lower a firm's costs."}},{"itemId":"42fd9059-1cf0-5e67-ba58-12c7f7675c83","questionId":"ecf6acfe-876f-5edc-8f04-971fe2340a7c","sourceKey":"bank:ECO101:ECO-0200","payload":{"prompt":"The reason the marginal cost curve eventually increases as output increases for the typical firm is because:","options":["normal profit exceeds economic profit.","of minimum efficient scale.","of the law of diminishing returns.","of diseconomies of scale."],"correctOption":2,"section":"Production and the Firm","explanation":"In the short run, adding more of a variable input to fixed inputs eventually gives smaller and smaller increases in output (diminishing returns), so each extra unit of output costs more and MC rises. Option D, diseconomies of scale, is a long-run idea about changing all inputs, not the short-run MC curve."}},{"itemId":"416b7768-d170-5511-86ca-fc0f4261014e","questionId":"0ff5786c-bd78-50de-9d2a-6205657ce52f","sourceKey":"bank:ECO101:ECO-0206","payload":{"prompt":"Marginal rate of Technical Substitution is the ........of an isoquant","options":["Curve","Function","Price","Slope"],"correctOption":3,"section":"Production and the Firm","explanation":"The marginal rate of technical substitution measures how much capital can be replaced by one more unit of labour while output stays the same, which is the slope of the isoquant. Options A, B and C do not describe this rate of exchange."}},{"itemId":"71f196c4-b620-5d21-ab63-df7fe1afea9a","questionId":"f6f3548e-8f6c-5dbc-802f-93ff961ce1a0","sourceKey":"bank:ECO101:ECO-0207","payload":{"prompt":"According to Iso-quant analysis, the firm maximizes its profit, when the.............is equal to the price ratio of labour and capital.","options":["MRS of two goods","MRTS of labour and capital","MRTS of all costs","MRS of land and labour"],"correctOption":1,"section":"Production and the Firm","explanation":"A firm chooses its best input mix where the isoquant is tangent to the isocost line, that is where MRTS of labour for capital equals the ratio of their prices (w/r). Options A and D use the MRS, which belongs to consumer theory, not production."}},{"itemId":"7601bcfc-7ff4-5662-87c8-3238a4057224","questionId":"605b9ec0-1a75-524e-95ee-c10fc97d46c2","sourceKey":"bank:ECO101:ECO-0209","payload":{"prompt":"When a firm doubles its inputs and finds that its output has more than doubled, this is known as:","options":["constant returns to scale.","increasing returns to scale.","a violation of the law of diminishing returns.","decreasing returns to scale."],"correctOption":1,"section":"Production and the Firm","explanation":"When all inputs are increased in the same proportion and output rises by a bigger proportion, the firm enjoys increasing returns to scale; this is what makes its long-run average cost fall (economies of scale). Option A would mean output exactly doubles, and option D means output rises by less than double. Option C is wrong because the law of diminishing returns applies when only one input changes while others stay fixed."}},{"itemId":"0c45bd17-44ef-50c3-a34a-eef2a18cb01f","questionId":"08bbb815-e936-5cd6-bf52-4cd140acd24e","sourceKey":"bank:ECO101:ECO-0216","payload":{"prompt":"Economies and diseconomies of scale explain why the:","options":["long-run average total cost curve is typically U-shaped.","short-run average fixed cost curve declines so long as output increases.","short-run average variable cost curve is U-shaped.","demand curve slopes downward from left to right."],"correctOption":0,"section":"Production and the Firm","explanation":"Economies of scale make long-run average cost fall as a firm grows, and diseconomies of scale make it rise beyond some size, which gives the U-shaped long-run average cost curve. Option C is also U-shaped, but in the short run that shape comes from diminishing returns, not scale effects. Option B is just fixed cost spread over more units."}},{"itemId":"1adcc435-18d2-5ac0-8595-d108f46137cf","questionId":"94f07234-7671-5540-a053-a3c284058f75","sourceKey":"bank:ECO101:ECO-0218","payload":{"prompt":"U-shaped average cost curve is based on:","options":["Law of constant returns to scale","Law of increasing cost","Law of variable proportions","Law of decreasing cost"],"correctOption":2,"section":"Production and the Firm","explanation":"The short-run U-shaped average cost curve comes from the law of variable proportions: at first, adding variable inputs to fixed ones raises efficiency and lowers average cost, but eventually diminishing returns set in and average cost rises. Options A, B and D each describe only a flat, rising or falling cost pattern, not the U shape."}},{"itemId":"7086bd32-90d2-5fb7-9183-e5f40946fb45","questionId":"c9ad451e-0928-5e59-9bf3-8e1509a7b177","sourceKey":"bank:ECO101:ECO-0222","payload":{"prompt":"At which time all the factors of production may be changed:","options":["Market period (very short run)","Short run","At no time","Long run"],"correctOption":3,"section":"Production and the Firm","explanation":"The long run is defined as a period long enough for the firm to vary all its factors of production, including plant size. Option B is wrong because in the short run at least one factor, such as capital, is fixed. Option A, the market period, is even shorter, with supply fixed, and option C is wrong because all factors do become variable given enough time."}},{"itemId":"ad5f5fa0-a9e0-5ba9-91c1-6b678015864a","questionId":"1821f1f1-25d3-5736-b973-794a5ed0cb5f","sourceKey":"bank:ECO101:ECO-0223","payload":{"prompt":"The cost which a firm incurs for purchasing or hiring factors is called:","options":["Implicit","Nominal","Real","Explicit"],"correctOption":3,"section":"Production and the Firm","explanation":"Explicit costs are actual money payments a firm makes to buy or hire factors, such as wages, rent and raw materials. Option A, implicit costs, are the opportunity costs of resources the firm already owns, for which no payment is made."}},{"itemId":"4e993215-864c-581a-aa77-7cc66621e477","questionId":"d698a125-4aa9-55cd-913a-9e0730317885","sourceKey":"bank:ECO101:ECO-0224","payload":{"prompt":"When marginal product reaches its maximum, what can be said of total product:","options":["total product levels off","total product starts to decline even if marginal product is positive","total product must be at its maximum","total product is increasing if marginal product is still positive"],"correctOption":3,"section":"Production and the Firm","explanation":"Marginal product is the slope of total product. When MP is at its maximum it is still positive, so total product is still rising (this is the point where TP stops rising at an increasing rate). Option C is wrong because TP is at its maximum only when MP falls to zero."}},{"itemId":"de5d999a-4cb2-5423-8ead-21ed9ed78b77","questionId":"eba5fb87-1e58-5d08-aa8f-fdd1ff9c5eb5","sourceKey":"bank:ECO101:ECO-0226","payload":{"prompt":"The long run is a:","options":["Period long enough to allow firm to make economic decisions","A period which affects larger than smaller firms","Period long enough to allow firms to change plant size and capacity","Period in which at least one factor of production is fixed"],"correctOption":2,"section":"Production and the Firm","explanation":"The long run is a period long enough for firms to change all inputs, including plant size and capacity. Option D describes the short run, when at least one factor is fixed. Option A is too vague, since firms make economic decisions in every period."}},{"itemId":"477c44ec-a5ac-5f52-b3e9-51e27f26a30e","questionId":"19369943-3835-5799-9871-baf626a9110b","sourceKey":"bank:ECO101:ECO-0227","payload":{"prompt":"As output increases:","options":["MC continuously rises","None of these","MC firstly rises then falls","MC curve firstly falls then rises"],"correctOption":3,"section":"Production and the Firm","explanation":"Marginal cost first falls as the firm gains from using its fixed inputs better, then rises once diminishing returns set in, giving a U-shaped MC curve. Option A ignores the falling stage, and option C gets the order the wrong way round."}},{"itemId":"0df82421-9c5f-5064-acc1-d9c1c3a17d0f","questionId":"21d1c3b0-e398-5e83-b61b-90210b5c6ec9","sourceKey":"bank:ECO101:ECO-0232","payload":{"prompt":"The relationship between the variable input and output, keeping all other inputs constant, is often referred to as ___ of the variable input:","options":["None of the above","Marginal Product","Average Product","Total Product (TP)"],"correctOption":3,"section":"Production and the Firm","explanation":"Total product shows how much output is produced as more of the variable input is used while other inputs are fixed. Options B and C are derived from total product: marginal product is the extra output per extra unit, and average product is output per unit of the input."}},{"itemId":"4f29ef0e-d8b1-5669-bf42-93487fec0323","questionId":"12c28e93-03f3-521d-9f6f-29fd785d5678","sourceKey":"bank:ECO101:ECO-0246","payload":{"prompt":"An economy's resources can be classified into four dimensions namely: Land resources, capital resources, ________ and innovators.","options":["financial","state","human","market"],"correctOption":2,"section":"Production and the Firm","explanation":"The four factors of production are land, capital, labour (human resources) and entrepreneurship (the innovators who organise the others). Option A, financial resources, is a form of capital, so human resources is the missing category."}},{"itemId":"3164cfd3-3972-562c-a658-beb31f1aecb0","questionId":"cdd0654a-1f4d-5456-9faf-4b09e15c7d90","sourceKey":"bank:ECO101:ECO-0256","payload":{"prompt":"The rate at which one factor of production say, labour, is substituted for the other factor, say capital, in the production process is known as the ________","options":["marginal rate of substitution","returns to scale rate","marginal rate of technical substitution","marginal production rate"],"correctOption":2,"section":"Production and the Firm","explanation":"The marginal rate of technical substitution is the rate at which one input, such as labour, can replace another, such as capital, while keeping output the same. Option A, the marginal rate of substitution, is the consumer-theory version for goods."}},{"itemId":"973ead2d-51cc-500e-9baf-480a731ef12c","questionId":"8ac5a488-6a8b-523f-b6e1-3031901df0f7","sourceKey":"bank:ECO101:ECO-0268","payload":{"prompt":"The curve showing the locus of all the combinations of two inputs (say, labour and capital) that yield the same level of output is known as","options":["production curve","utility curve","isoquant","indifference curve"],"correctOption":2,"section":"Production and the Firm","explanation":"An isoquant joins all combinations of two inputs, such as labour and capital, that produce the same output. Option D, the indifference curve, is the consumer version, showing combinations of goods that give the same satisfaction."}},{"itemId":"8f480942-a1fc-5bf8-a140-78eda6551cd3","questionId":"fc96684a-1444-5735-bcb3-3157a97737e5","sourceKey":"bank:ECO101:ECO-0272","payload":{"prompt":"The factors of production that are human related include","options":["Capital and labour","Land and Labour","Entrepreneur and capital","Labour and Entreprenuer"],"correctOption":3,"section":"Production and the Firm","explanation":"Labour and entrepreneurship are both human efforts: labour is physical and mental work, while the entrepreneur organises production and bears risk. Land is a natural resource and capital is man-made, so options A, B and C each include a non-human factor."}},{"itemId":"80108a94-1e80-574d-8f90-132263319b0b","questionId":"2047e87d-7bc3-54c7-be86-a1e5dbcd65df","sourceKey":"bank:ECO101:ECO-0275","payload":{"prompt":"The term revenue refers to","options":["Profits obtained by a firm","Gross profit obtained by a firm","Net profit","The receipts obtained by a firm by selling a commodity at a given price."],"correctOption":3,"section":"Production and the Firm","explanation":"Revenue is the money a firm receives from selling its output, price times quantity sold. Options A, B and C are types of profit, which is revenue minus costs."}},{"itemId":"58cf1ca5-2290-5d96-b239-a70615ed78d0","questionId":"cc11b7f6-0deb-57de-baaf-a5f3614718c7","sourceKey":"bank:ECO101:ECO-0278","payload":{"prompt":"In a free market structure, the marginal productivity theory states that in equilibrium firm should pay factors a unit price just equal","options":["marginal revenue cost","marginal revenue productivity","all of the above","none of the above"],"correctOption":1,"section":"Production and the Firm","explanation":"The marginal productivity theory says that in equilibrium a factor is paid a price equal to its marginal revenue product, the extra revenue it brings to the firm. Option A is the cost side, not what the factor produces, so it does not fit."}},{"itemId":"c42d12f8-fd3a-52b5-a69b-4822de8efba9","questionId":"11bc0b83-a6b0-54a5-9dfa-2737fc0bf193","sourceKey":"bank:ECO101:ECO-0279","payload":{"prompt":"For profit maximization, according to the marginal productivity approach, firms must employ factors up to","options":["MRP = MRC","MRP < MRC","MRP > MRC","none of the above"],"correctOption":0,"section":"Production and the Firm","explanation":"A profit-maximising firm keeps hiring a factor until the extra revenue it brings (MRP) equals the extra cost of hiring it (MRC). If MRP > MRC (option C) more should be hired, and if MRP < MRC (option B) fewer should be hired."}},{"itemId":"c0af2527-81ba-56de-8f9b-63be0a5fe798","questionId":"b350a456-03bf-5360-b04d-4c591c67597d","sourceKey":"bank:ECO101:ECO-0284","payload":{"prompt":"Diminishing returns is said to occur when","options":["Total product rises at increasing rate and marginal product declines","Total product rises at a decreasing rate and marginal product declines","Total product rises at increasing rate and marginal product rises","Total product is at a maximum and marginal product declines"],"correctOption":1,"section":"Production and the Firm","explanation":"Diminishing returns set in when adding more of a variable input still raises total product but by smaller and smaller amounts, so TP rises at a decreasing rate while MP declines. Option A mixes rapid TP growth with falling MP, option C describes increasing returns, and option D describes the point where diminishing returns have already pushed MP to zero."}},{"itemId":"65fe8c7a-3df6-5a0c-ab32-5828f44b9203","questionId":"78d65992-8147-5d44-8958-af54b8a961ab","sourceKey":"bank:ECO101:ECO-0285","payload":{"prompt":"In the production of automobiles, the factory and assembly lines are examples of","options":["Land","Labour","Capital","Entrepreneur"],"correctOption":2,"section":"Production and the Firm","explanation":"Factories and assembly lines are man-made aids to production, which is what economists call capital. Option B, labour, is human effort, and option A, land, covers natural resources. Option D, the entrepreneur, is the person who organises these factors."}},{"itemId":"533865d5-bbb4-5c8e-9a99-af4eca7bc108","questionId":"5c4c1f08-851f-5b61-a0fc-7469a40d203b","sourceKey":"bank:ECO101:ECO-0290","payload":{"prompt":"The reward that accrues to the entrepreneur is:","options":["Interest","Wages","Profit","Rent"],"correctOption":2,"section":"Production and the Firm","explanation":"Profit is the reward for the entrepreneur, who organises the other factors and bears the risk of the business. Option A, interest, is the reward for capital, option B, wages, goes to labour, and option D, rent, goes to land."}},{"itemId":"1255fb4f-041b-521a-8ab6-721a7de1e4a4","questionId":"75feb137-7aa3-550e-9a25-864ddc687b5d","sourceKey":"bank:ECO101:ECO-0373","payload":{"prompt":"The purpose of production is to","options":["Satisfy people's wants","Generate higher income","Eliminate poverty","Make every citizen comfortable"],"correctOption":0,"section":"Production and the Firm","explanation":"Production is undertaken to create goods and services that satisfy human wants. Options B, C and D, higher income, ending poverty and making everyone comfortable, may follow from production, but they are outcomes or policy goals rather than the basic purpose."}},{"itemId":"cfc0f24e-62ed-5297-856e-0bb628eb7a60","questionId":"1fc1c65c-b837-50a3-97e6-42040bac634f","sourceKey":"bank:ECO101:ECO-0374","payload":{"prompt":"The possibility of using some of one factor for some of another is known as","options":["The law of equity","The principle of substitution","The law of variability","The law of proportions"],"correctOption":1,"section":"Production and the Firm","explanation":"The principle of substitution says that one factor of production can be used in place of another, for example using more machines and fewer workers. Option D, the law of proportions, concerns what happens to output as factor proportions change, not the possibility of swapping them. Options A and C are not standard economic laws."}},{"itemId":"1f375ad3-b852-5095-bf40-501971ade7c8","questionId":"fc6974b9-c0dc-5b0a-b7d0-d832ea8c77ec","sourceKey":"bank:ECO101:ECO-0381","payload":{"prompt":"The supply of labour available in a country depend on:","options":["The number of hours worked by each person per year","The total population","The proportion of the population available for employment","All of the above"],"correctOption":3,"section":"Production and the Firm","explanation":"The supply of labour depends on the size of the population, the share of it available for work, and the number of hours each person works. Options A, B and C each name only one of these determinants, so all of the above is correct."}},{"itemId":"7b260d50-c865-5243-8e55-227489b8e7e8","questionId":"97c8f280-0ff0-5bae-9931-41681997c66b","sourceKey":"bank:ECO101:ECO-0392","payload":{"prompt":"Division of labour paved the way for:","options":["Reduction in recruitment of workers","Mass production","The introduction of production methods","Mass recruitment of workers"],"correctOption":1,"section":"Production and the Firm","explanation":"When work is broken into small specialised tasks, each worker becomes faster and more skilled, which makes large-scale or mass production possible. Option A is not the main result, and option D may happen in some firms but is not what division of labour made possible."}},{"itemId":"96acefd0-e515-56db-b3fb-6a71c1b49110","questionId":"10a898e2-71ec-5c92-8fd7-5cf0302652e1","sourceKey":"bank:ECO101:ECO-0393","payload":{"prompt":"Specialisation of tasks within the production process of a particular commodity is referred to as:","options":["Efficient utilisation of resources","Capitalistic method of production","Division of labour","Technological advancement"],"correctOption":2,"section":"Production and the Firm","explanation":"Division of labour means breaking the production of one commodity into separate tasks, with each worker specialising in one task. Option A is a possible benefit of it, not its name. Option D, technological advancement, is about new methods or machines."}},{"itemId":"960b991e-8b11-5ff6-ba8d-ad96519803f5","questionId":"2af50c48-4cb8-5426-b27a-3dea61671853","sourceKey":"bank:ECO101:ECO-0427","payload":{"prompt":"Negative slope, non-intersection, density and convexity are all properties of an:","options":["Isoquant","Iso revenue curve","Total Utilities","Marginal utilities"],"correctOption":0,"section":"Production and the Firm","explanation":"Isoquants share these properties: they slope downward, never cross, fill the whole space (density) and are convex to the origin, just like indifference curves. Options C and D, total and marginal utilities, are quantities of satisfaction, not curves with these properties. Option B, an iso-revenue curve, does not have these properties."}},{"itemId":"6f98e495-aca1-5241-aed4-26b3656a4778","questionId":"3c9844da-b607-5fe9-b4f0-0ac677b93c16","sourceKey":"bank:ECO101:ECO-0433","payload":{"prompt":"The main aim of a firm is achieved when:","options":["AC is minimum and AR > AC","MC < MR and AC < AR","MC = MR and AR >= AC","MR = 0 and AR > AC"],"correctOption":2,"section":"Production and the Firm","explanation":"A firm's main aim, profit maximisation, is reached where marginal cost equals marginal revenue (MC = MR), provided average revenue at least covers average cost (AR >= AC) so the firm is not making a loss. Option A describes minimum average cost, which is about efficiency, not maximum profit. Option B is wrong because while MC is still below MR, producing more units would add to profit, so profit has not yet peaked."}},{"itemId":"2a5743db-241a-5b38-ac3a-6e7cc71e72ca","questionId":"0a2f567e-53d1-5ec8-b45a-3131f05dbd77","sourceKey":"bank:ECO101:ECO-0434","payload":{"prompt":"The increase in total cost when output is increased by 1 unit is known as:","options":["Marginal cost","Average cost","Average revenue","Marginal revenue"],"correctOption":0,"section":"Production and the Firm","explanation":"Marginal cost is the extra cost of producing one more unit, i.e. the change in total cost when output rises by 1. Option B, average cost, is total cost divided by output, not the extra cost of one unit. Option D, marginal revenue, is the extra revenue from selling one more unit, not a cost."}},{"itemId":"5ead422a-a5a2-5d37-93b4-8d16fb264465","questionId":"e4e7de45-476a-5871-836b-81d9c08d36f2","sourceKey":"bank:ECO101:ECO-0435","payload":{"prompt":"The part of after-tax profits that is ploughed back into the business rather than paid out to shareholders as dividends is called:","options":["Gross profit","Shares","Net profit","Retained earnings"],"correctOption":3,"section":"Production and the Firm","explanation":"Retained earnings are the part of after-tax profit a company keeps and reinvests in the business instead of paying out as dividends. Option C, net profit, is the whole profit after expenses and tax, before deciding how much to keep or distribute. Option A, gross profit, comes even earlier, before operating expenses and tax are deducted."}},{"itemId":"7cd60ac4-e6d1-5953-bc25-170108fc8663","questionId":"e027291a-7fae-50d3-a919-f8f32841dbb0","sourceKey":"bank:ECO101:ECO-0436","payload":{"prompt":"Goods held in stock by the firm for future sales are called:","options":["Raw materials","Inventories","Inputs","Intermediate goods"],"correctOption":1,"section":"Production and the Firm","explanation":"Inventories are stocks of goods a firm holds so that it can sell them (or use them) later. Option A, raw materials, are inputs waiting to be processed rather than goods kept for future sales. Option D, intermediate goods, are goods used up in making other goods, which is a different idea."}},{"itemId":"57fdcbed-aea1-50a5-a372-46c8f90ed4e0","questionId":"bc0960a1-8ca5-5571-9b4c-6237aa0c1138","sourceKey":"bank:ECO101:ECO-0437","payload":{"prompt":"What does profit maximisation imply?","options":["Allocation of cost","Minimisation of costs for each output level","Allocation of output","Maximisation of costs for each output level"],"correctOption":1,"section":"Production and the Firm","explanation":"To earn the highest possible profit, a firm must produce each level of output at the lowest possible cost, so profit maximisation implies cost minimisation for every output level. Option D is the opposite of what a profit-seeking firm wants. Options A and C talk about allocation in general and miss the link between profit and cost."}},{"itemId":"f226c88e-699d-5800-abae-dc08087f2278","questionId":"95c372e9-0451-5b6e-bfe9-c920f4741378","sourceKey":"bank:ECO101:ECO-0438","payload":{"prompt":"At the point where marginal product is zero, the total product must:","options":["Be decreasing","Be rising","Be zero","Be at the maximum"],"correctOption":3,"section":"Production and the Firm","explanation":"Marginal product is the change in total product from adding one more unit of the variable input. When it falls to zero, the extra unit adds nothing, so total product has stopped rising and is at its maximum. Option B is wrong because total product rises only while marginal product is positive, and option A applies once marginal product turns negative."}},{"itemId":"30ee9618-340c-51f1-9fc8-375336f402ff","questionId":"8bd81f5e-c4e6-51a5-b839-e58136176cbc","sourceKey":"bank:ECO101:ECO-0439","payload":{"prompt":"Methods of production will change if the:","options":["The firm changes the brand name of its product","Factor incomes change","Relative prices of factors change","Absolute prices of factors change"],"correctOption":2,"section":"Production and the Firm","explanation":"Firms choose a method of production by comparing what factors cost relative to each other, for example labour against machines. If all factor prices rise by the same percentage the cheapest combination stays the same, so only a change in relative prices makes firms switch methods. Option D is tempting, but a change in absolute factor prices that leaves their ratio unchanged does not alter the best technique."}},{"itemId":"d33daab1-af80-5660-b54b-c3b75a190120","questionId":"1cc61c45-ef7d-5e90-83ab-80e3c2879a23","sourceKey":"bank:ECO101:ECO-0440","payload":{"prompt":"The goal of output maximisation by the firm is subject to:","options":["Cost constraint","Input surplus","Output constraint","Profit constraint"],"correctOption":0,"section":"Production and the Firm","explanation":"When a firm tries to produce as much output as possible, it is limited by how much it can spend on inputs, so the goal is subject to a cost (budget) constraint. Option C is wrong because output is what is being maximised, not the constraint. Option D, a profit constraint, belongs to other goals such as sales maximisation subject to a minimum profit."}},{"itemId":"cf9291d4-f619-5f9b-af9c-2b6115ad08b7","questionId":"c318e589-18a3-5fde-acf7-1b3b10302173","sourceKey":"bank:ECO101:ECO-0441","payload":{"prompt":"The goal of the firm in the conventional theory is:","options":["Output maximisation","Cost minimisation","Profit maximisation","Revenue maximisation"],"correctOption":2,"section":"Production and the Firm","explanation":"In the conventional (traditional) theory of the firm, the firm is assumed to aim at maximising profit, the difference between total revenue and total cost. Options A and D, output and revenue maximisation, are alternative goals proposed in other theories of the firm. Option B, cost minimisation, is a means of reaching maximum profit rather than the final goal itself."}},{"itemId":"af38b77e-4a4e-548d-9a16-95969566c867","questionId":"679ab48b-c7ea-5b51-9048-be84754e5080","sourceKey":"bank:ECO101:ECO-0442","payload":{"prompt":"Cost functions are derived from:","options":["Production function","Input function","Output function","Cost function"],"correctOption":0,"section":"Production and the Firm","explanation":"Cost functions are derived from the production function together with input prices: the production function tells us how much input each output needs, and input prices turn that into cost. Option D is circular, since a cost function cannot be derived from itself. Options B and C are not standard concepts here."}},{"itemId":"4e1a8870-2bf2-527c-9f75-81cfa7dea75b","questionId":"2dd70ea7-db18-5379-92fd-3320c9581563","sourceKey":"bank:ECO101:ECO-0443","payload":{"prompt":"As long as marginal cost is lower than average cost, average cost will be:","options":["Rising","Negative","Falling","Constant"],"correctOption":2,"section":"Production and the Firm","explanation":"If the cost of the extra unit (MC) is below the current average, adding that unit pulls the average down, so AC falls. Option A happens the other way round, when MC is above AC. Option D, constant AC, occurs only at the point where MC equals AC."}},{"itemId":"39683e8f-d0d9-541d-b573-45b20b97713d","questionId":"2ced3a87-70f7-56ac-9a81-c58ef5c0d179","sourceKey":"bank:ECO101:ECO-0445","payload":{"prompt":"Fixed costs are:","options":["Relative","Constant","Variable","Marginal"],"correctOption":1,"section":"Production and the Firm","explanation":"Fixed costs, such as rent or insurance, stay constant whatever the level of output in the short run. Option C, variable, describes costs like raw materials that change with output. Option D, marginal cost, is the extra cost of one more unit, and fixed costs do not add to it."}},{"itemId":"3a88fa08-5378-529f-a78e-511935255107","questionId":"3dba81b8-c500-5193-a418-0434c3608130","sourceKey":"bank:ECO101:ECO-0446","payload":{"prompt":"Where a firm is operating at a scale which gives it the lowest unit cost possible, it is said to be operating at the:","options":["Minimum","Optimum","Normal","Maximum"],"correctOption":1,"section":"Production and the Firm","explanation":"A firm working at the scale that gives the lowest possible average (unit) cost is said to be at its optimum. Option A, minimum, describes the cost level, not the name given to that scale. Option D, maximum, is wrong because the lowest-cost scale is not necessarily the largest scale the firm could reach."}},{"itemId":"c11465fa-3ab3-540f-b002-7fd6584f1dbe","questionId":"a89349d4-b2f7-529e-8682-36f068ca11a0","sourceKey":"bank:ECO101:ECO-0448","payload":{"prompt":"An increase in the long-run average costs of production which comes about when the scale of production is increased is called:","options":["Internal economies","External economies","Economies of scale","Diseconomies of scale"],"correctOption":3,"section":"Production and the Firm","explanation":"Diseconomies of scale occur when expanding the scale of production pushes long-run average cost up, often because very large firms become hard to manage and coordinate. Option C, economies of scale, is the opposite: average cost falling as scale rises. Options A and B are types of economies of scale, so they also involve falling costs."}},{"itemId":"bb23f176-1268-539d-8f51-a93694a56fd9","questionId":"dcbaea74-b0b7-5052-8255-e12af6f39006","sourceKey":"bank:ECO101:ECO-0451","payload":{"prompt":"When economic profits are zero, we say the firm is making:","options":["Excess profit","Normal profits","A loss","Abnormal profits"],"correctOption":1,"section":"Production and the Firm","explanation":"Zero economic profit means total revenue just covers all costs, including the opportunity cost of the owner's resources, so the firm earns normal profit. Options A and D, excess or abnormal profit, mean revenue is above all costs. Option C, a loss, would mean economic profit is negative, not zero."}},{"itemId":"6b97efc8-30d7-56b7-be36-d262d20a53f2","questionId":"af4e9aa5-a4fd-5576-9645-ad509a60fbcd","sourceKey":"bank:ECO101:ECO-0457","payload":{"prompt":"The marginal cost curve always cuts the average cost curve at its:","options":["Lowest point","Relative point","Maximum point","Highest point"],"correctOption":0,"section":"Production and the Firm","explanation":"MC cuts AC at the lowest point of AC: while MC is below AC it pulls the average down, and once MC is above AC it pushes the average up, so they meet exactly where AC stops falling and starts rising. Options C and D are wrong because the U-shaped AC curve has a minimum, not a maximum, at its turning point. Option B is not a recognised point on the curve."}},{"itemId":"53e4aa50-5d7c-56b6-a0ea-e06448be1a79","questionId":"9bc64989-455a-5ee7-96b6-188dc93d1c6a","sourceKey":"bank:ECO101:ECO-0471","payload":{"prompt":"In production, labor, capital, land, and entrepreneurship are also known as?","options":["Inputs","Output","MPP","Production function"],"correctOption":0,"section":"Production and the Firm","explanation":"Labour, capital, land and entrepreneurship are the factors of production, also called inputs, because they are put into the production process to create goods and services. Option B, output, is what the process produces. Option D, the production function, is the relationship between inputs and output, not the inputs themselves."}},{"itemId":"8bb4480f-13e6-5a0c-aed4-17c38ad50f1c","questionId":"f9f3ce04-60fe-5714-a2be-71b03418100a","sourceKey":"bank:ECO101:ECO-0474","payload":{"prompt":"________ graphically indicates the quantity of a factor that is supplied at alternative factor prices?","options":["factor demand curve","factor supply curve","factor supply schedule","factor demand schedule"],"correctOption":1,"section":"Production and the Firm","explanation":"A factor supply curve is a graph showing how much of a factor, such as labour, is offered at different factor prices. Option C, a factor supply schedule, carries the same information as a table rather than a graph. Options A and D are about the demand for factors, not supply."}},{"itemId":"8a2b3633-3c6a-53fc-a50d-8989b4bfda91","questionId":"8650e7a3-9247-5870-a4fb-b40eba297a2d","sourceKey":"bank:ECO101:ECO-0481","payload":{"prompt":"The key role of capital in the production process is to:","options":["Make labour more productive","Save time","Pay for rent","Buy machines"],"correctOption":0,"section":"Production and the Firm","explanation":"Capital goods such as machines and tools help workers produce more output per hour, so the key role of capital is to make labour more productive. Option B, saving time, is one result of this, but it is part of the wider point about productivity. Options C and D are not roles of capital: rent is a payment for land, and buying machines is how capital is acquired, not what it does."}},{"itemId":"2f50217f-2ea6-51d7-bc40-6bbfbcd14311","questionId":"2badd120-8aa9-5240-9a0b-873cb2d6c9a8","sourceKey":"bank:ECO101:ECO-0482","payload":{"prompt":"Factors that determine pay include:","options":["Demand for the product","MPP","Price of the good","All of the above"],"correctOption":3,"section":"Production and the Firm","explanation":"Under marginal productivity theory, pay depends on the marginal revenue product of labour, which is the marginal physical product (MPP) multiplied by the price of the good, and demand for the product affects that price. So demand for the product, MPP and the price of the good all help determine pay. Choosing only A, B or C leaves out the other parts of the MRP = MPP x P relationship."}},{"itemId":"42791b8e-0b99-509f-8375-f2ea71a211e8","questionId":"52337e19-5832-501e-bf35-70e724d6e82c","sourceKey":"bank:ECO101:ECO-0483","payload":{"prompt":"In economics, MRP stands for:","options":["Marginal revenue product","Maximum revenue production","Minimum revenue product","Mean rate product"],"correctOption":0,"section":"Production and the Firm","explanation":"MRP stands for marginal revenue product, the extra revenue a firm earns from employing one more unit of a factor; it equals the factor's marginal physical product multiplied by marginal revenue. Options B, C and D are not recognised economic terms, they simply reuse similar words."}},{"itemId":"5e88055e-4531-5db3-a6c9-3188367dde4c","questionId":"c0354e62-548c-5da5-a472-471a17cbb965","sourceKey":"bank:ECO101:ECO-0485","payload":{"prompt":"This is a payment to the owner of capital in exchange for the productive services of capital?","options":["Wage","Rent","Interest","Profit"],"correctOption":2,"section":"Production and the Firm","explanation":"Interest is the reward paid to owners of capital for the use of their capital in production. Option A, wages, go to labour; option B, rent, goes to land; and option D, profit, is the reward for entrepreneurship."}},{"itemId":"02107ac7-281c-5c46-b707-97a74920fa45","questionId":"329e991a-0e5c-59a6-a5c2-ccd4155b264b","sourceKey":"bank:ECO101:ECO-0491","payload":{"prompt":"The factor payment of labor is","options":["wage","interest","rent","profit"],"correctOption":0,"section":"Production and the Firm","explanation":"Wages are the reward paid to labour for its services. Option B, interest, goes to capital, option C, rent, goes to land, and option D, profit, is the reward for entrepreneurship."}},{"itemId":"efed9dc6-2dd7-533d-8c54-adb79856a921","questionId":"b346d0bb-5c71-59da-86c8-80bf0d6f193d","sourceKey":"bank:ECO101:ECO-0492","payload":{"prompt":"Factor markets exchange a factor service for a:","options":["Factor of production","Product","Monetary payment or price","Good or service"],"correctOption":2,"section":"Production and the Firm","explanation":"In a factor market, a factor service such as labour or the use of land is exchanged for a money payment, its price, such as a wage or rent. Option A is wrong because factors of production are what is being sold, not what is received in return. Options B and D are what is bought in product markets."}},{"itemId":"1fea9b4e-dd0f-502d-a1fb-22ff673265d8","questionId":"49217684-4c54-549f-a129-06315035afd0","sourceKey":"bank:ECO101:ECO-0504","payload":{"prompt":"Economic profit is the excess of:","options":["Total revenue over total cost","Total cost over total revenue","Price Equals to Total revenue","Marginal cost to Total revenue"],"correctOption":0,"section":"Production and the Firm","explanation":"Economic profit is the amount by which total revenue exceeds total cost, where total cost includes the opportunity cost of the owner's own resources. Option B, total cost over total revenue, would be a loss. Options C and D do not describe a meaningful measure of profit."}},{"itemId":"db0959e5-b2f6-5008-82b6-4362486d8c7e","questionId":"256b2ff1-c9e7-54c4-9ba9-40b9c939f08b","sourceKey":"bank:ECO101:ECO-0512","payload":{"prompt":"________ refers to the naturally occurring materials of the planet that are used for the production of goods and services, including the land itself; the minerals and nutrients in the ground; the water, wildlife and vegetation on the surface; and the air above.","options":["Labour","Capital","Land","Entrepreneurship"],"correctOption":2,"section":"Production and the Firm","explanation":"In economics, land means all natural resources: the land surface itself plus minerals, water, wildlife, vegetation and even the air, used in producing goods and services. Option B, capital, refers to man-made aids to production such as machines. Option A, labour, is human effort, and option D, entrepreneurship, is organising production and bearing risk."}},{"itemId":"95ce69e4-198d-5129-832d-265c38d268e7","questionId":"bbc7d985-50eb-5a0f-8abd-630396c9361b","sourceKey":"bank:ECO101:ECO-0517","payload":{"prompt":"This is a payment to the owner of entrepreneurship in exchange for the productive services of entrepreneurship:","options":["Wage","Rent","Interest","Profit"],"correctOption":3,"section":"Production and the Firm","explanation":"Profit is the reward for entrepreneurship, earned for organising the other factors and bearing the risk of production. Option A, wages, is paid to labour, option B, rent, to land, and option C, interest, to capital."}},{"itemId":"5b497d42-620b-5862-8a48-4dfef0ecea98","questionId":"bfe77d44-0ad0-5111-a2b7-3ea12336fbac","sourceKey":"bank:ECO101:ECO-0519","payload":{"prompt":"________ refers to income earned from a factor of production which is greater than the minimum necessary to bring the factor of production into operation?","options":["Transfer earnings","Production function","PPC","Economic rent"],"correctOption":3,"section":"Production and the Firm","explanation":"Economic rent is the part of a factor's earnings above its transfer earnings, the minimum needed to keep it in its present use. Option A, transfer earnings, is exactly that minimum, the other part of the payment. Options B and C, the production function and the PPC, are unrelated concepts."}},{"itemId":"1628ffe3-85d5-5a70-8340-3fabfed5b118","questionId":"f813af80-d2a9-54b5-a593-b887ec5037f1","sourceKey":"bank:ECO101:ECO-0520","payload":{"prompt":"Suppose a footballer would be willing to work for N200 a week but is actually paid N1,000 a week. What is the footballer's economic rent per week?","options":["N800","N200","N1000","N500"],"correctOption":0,"section":"Production and the Firm","explanation":"Economic rent is what a factor earns above the minimum it would accept, its transfer earnings. Here economic rent = N1,000 - N200 = N800 a week. Option B, N200, is the transfer earnings, and option C, N1,000, is total earnings, not the surplus."}},{"itemId":"5918c99e-b9c3-5da1-b6bd-3863148c5565","questionId":"a3fc8b3f-9c48-5757-8bef-8fd2e547797f","sourceKey":"bank:ECO101:ECO-0525","payload":{"prompt":"________ is the special sort of human effort that takes on the risk of bringing labour, capital and land together to produce goods.","options":["Labour","Capital","Land","Entrepreneurship"],"correctOption":3,"section":"Production and the Firm","explanation":"Entrepreneurship is the human effort that organises labour, capital and land and bears the risk of producing goods. Option A, labour, is ordinary physical and mental effort without this risk-taking role. Options B and C, capital and land, are non-human factors."}},{"itemId":"c9f328a2-3f12-5842-ab11-4b21374277c2","questionId":"93a6051a-ed91-5b22-8b09-b8efbaa050b6","sourceKey":"bank:ECO101:ECO-0529","payload":{"prompt":"The general term for the monetary payments made to factors of production is:","options":["Factor payments","Commodity","Money","Cost"],"correctOption":0,"section":"Production and the Firm","explanation":"The money payments made for the use of factors of production, wages, rent, interest and profit, are together called factor payments. Option C, money, is just the medium in which these payments are made, and option D, cost, is the general expense of production rather than the name for these rewards."}},{"itemId":"62cb090e-eba2-558e-bbb7-3ad08e584d00","questionId":"5deae3ed-93cf-52f7-b542-193623c26e6a","sourceKey":"bank:ECO101:ECO-0536","payload":{"prompt":"________ are used to exchange and allocate the services of factor inputs and scarce resources among productive activities.","options":["Factor markets","Factors of production","Capital","Entrepreneurship"],"correctOption":0,"section":"Production and the Firm","explanation":"Factor markets are where the services of labour, land, capital and entrepreneurship are bought and sold, and they allocate these scarce resources among different productive uses. Option B, factors of production, are what is traded in these markets, not the markets themselves. Options C and D are individual factors."}},{"itemId":"68cbed83-a2d6-59d8-b44b-5562d581c90f","questionId":"646b94ae-9545-5c48-b393-661b17be7d98","sourceKey":"bank:ECO101:ECO-0537","payload":{"prompt":"In the long run:","options":["Only fixed costs are not variable","Variable costs are fixed","Land is fixed","No cost is fixed"],"correctOption":3,"section":"Production and the Firm","explanation":"The long run is a period long enough for the firm to change all its inputs, including plant size and land, so all costs become variable and no cost is fixed. Option C is wrong because even land can be varied by the firm in the long run, and options A and B describe a mix of fixed and variable costs, which belongs to the short run."}},{"itemId":"bbeec713-725f-5d71-b59e-9840836e7f55","questionId":"b07f62bd-e6e3-5d7b-a51b-fa09de1b2694","sourceKey":"bank:ECO101:ECO-0543","payload":{"prompt":"Average total cost to a firm is N600 when it produces 10 units of output and N640 when output is 11 units. The MC of the 11th unit is:","options":["N40","N540","N840","N1,040"],"correctOption":3,"section":"Production and the Firm","explanation":"Total cost = ATC x output, so TC at 10 units = N600 x 10 = N6,000 and TC at 11 units = N640 x 11 = N7,040. MC of the 11th unit = N7,040 - N6,000 = N1,040. Option A, N40, is only the change in average cost, not the change in total cost."}},{"itemId":"e26c2a87-dba0-58b8-9f8a-d77df7ffaf46","questionId":"925c1264-7112-593f-830c-4cb955573eb4","sourceKey":"bank:ECO101:ECO-0684","payload":{"prompt":"Average revenue (AR) is calculated as:","options":["TR - TC","TR / quantity sold","TC / TR","MC / AR"],"correctOption":1,"section":"Production and the Firm","explanation":"Average revenue is total revenue divided by the number of units sold, AR = TR/Q, which equals the price per unit. Option A is the formula for profit, and C and D are not standard revenue measures."}},{"itemId":"775cf121-bc7e-55d1-892a-36c3a9c38fbb","questionId":"303693c4-f74b-53d2-899c-6ee6253ce303","sourceKey":"bank:ECO101:ECO-0688","payload":{"prompt":"Average fixed cost (AFC) is obtained by:","options":["TFC / Q","MC / Q","TAC / Q","AVC / Q"],"correctOption":0,"section":"Production and the Firm","explanation":"Average fixed cost is total fixed cost divided by output, AFC = TFC/Q, which is why it keeps falling as output rises. Options B, C and D divide measures that are already per unit or marginal by Q, which does not give any standard cost measure."}},{"itemId":"bb68a339-49da-5ddb-86b1-21ea54514d57","questionId":"2950fbf7-1825-5746-acff-0c347df95096","sourceKey":"bank:ECO101:ECO-0700","payload":{"prompt":"Implicit costs are:","options":["Equal to total fixed costs","Made up entirely of variable costs","The value of resources owned and used by the firm's own owner","Always greater in the short run than in the long run"],"correctOption":2,"section":"Production and the Firm","explanation":"Implicit costs are the opportunity costs of resources the owner supplies, such as the salary a Lagos shop owner gives up by working in her own business. Options A and B confuse implicit costs with fixed and variable costs, which are a different way of classifying costs."}},{"itemId":"a5ed8732-1610-517a-bb8d-757ad9fdef8b","questionId":"c11bd069-e9a3-5c23-8ee1-2547326b3602","sourceKey":"bank:ECO101:ECO-0701","payload":{"prompt":"Which of the following is an implicit cost for a firm?","options":["Wages and salaries paid to workers","Rent paid for leasing a building","Payments for production supplies","The salary the owner gives up by running the firm"],"correctOption":3,"section":"Production and the Firm","explanation":"An implicit cost involves no cash payment: it is the income the owner sacrifices by using his own time or resources in the business. Options A, B and C are all cash payments to outsiders, which makes them explicit costs."}},{"itemId":"1e33d417-d1fe-5052-91ad-147dbf10b53c","questionId":"6f231755-2169-557c-9903-17a7f6ca6b34","sourceKey":"bank:ECO101:ECO-0702","payload":{"prompt":"If a firm's total revenue just covers all of its opportunity costs, then:","options":["Normal profit is zero","Economic profit is zero","Total revenue equals its explicit costs only","Total revenue equals its implicit costs only"],"correctOption":1,"section":"Production and the Firm","explanation":"Economic profit = total revenue - (explicit + implicit costs), so when revenue exactly covers all opportunity costs, economic profit is zero. Option A is the trap: at this point the firm is earning exactly a normal profit, because normal profit is counted as part of implicit costs."}},{"itemId":"c878ac8f-d738-525c-bc07-f1a1b2c90136","questionId":"bd2b9732-12ba-5244-a137-e441d3153bd6","sourceKey":"bank:ECO101:ECO-0703","payload":{"prompt":"A firm sells its product at a price below the opportunity cost of the inputs used to make it. Which is true?","options":["The firm earns both accounting and economic profits","The firm suffers both accounting and economic losses","The firm suffers an accounting loss but earns an economic profit","The firm may earn an accounting profit but suffers an economic loss"],"correctOption":3,"section":"Production and the Firm","explanation":"Accounting profit only subtracts explicit costs, while economic profit also subtracts implicit costs, so a firm can cover its cash costs but still fail to cover all opportunity costs. Option B is possible but not certain, and C is impossible because economic profit can never be higher than accounting profit."}},{"itemId":"4188879d-c492-53ae-8cd6-662b3c08fddf","questionId":"3871bf7f-158a-5138-8bf7-8f81c693370c","sourceKey":"bank:ECO101:ECO-0704","payload":{"prompt":"A Lagos firm produces 200,000 units a year and sells them all at N10 each. Its explicit costs are N1,500,000 and its implicit costs are N300,000. The firm has an accounting profit of:","options":["N500,000 and an economic profit of N200,000","N400,000 and an economic profit of N200,000","N300,000 and an economic profit of N400,000","N200,000 and an economic profit of N500,000"],"correctOption":0,"section":"Production and the Firm","explanation":"Total revenue = 200,000 x 10 = N2,000,000. Accounting profit = 2,000,000 - 1,500,000 = N500,000, and economic profit = 2,000,000 - (1,500,000 + 300,000) = N200,000. Option D swaps the two figures, which cannot be right because economic profit is always lower when there are implicit costs."}},{"itemId":"65a8b6b7-2d6b-5e62-ba23-4532cb7875dd","questionId":"fee396d6-1f8f-51e9-a338-456fd963ffd5","sourceKey":"bank:ECO101:ECO-0705","payload":{"prompt":"The short run is a period of time in which:","options":["All resources are fixed","The level of output is fixed","The size of the plant can be changed","Some resources are fixed while others are variable"],"correctOption":3,"section":"Production and the Firm","explanation":"In the short run, at least one input, such as factory size, cannot be changed, so the firm can only vary inputs like labour and raw materials. Option C describes the long run, when all inputs including plant size can be changed, and output (B) can still change in the short run."}},{"itemId":"b08edea6-7922-583b-a3ff-0cb385bdbefc","questionId":"b869ad8b-1e01-5c6e-ae5e-43c69a425e96","sourceKey":"bank:ECO101:ECO-0706","payload":{"prompt":"The law of diminishing returns states that:","options":["As more of a variable input is added to fixed inputs, average product will keep rising","As more of a variable input is added to fixed inputs, marginal product will eventually fall","In the short run, average total cost will eventually fall","In the long run, average total cost will eventually fall"],"correctOption":1,"section":"Production and the Firm","explanation":"When more and more of a variable input, such as labour, is added to a fixed input, such as land, each extra unit eventually adds less to total output than the one before. Option A is wrong because average product also starts to fall eventually, and D describes economies of scale, which is a long-run idea."}},{"itemId":"15e0445a-3d99-57bf-9922-af070b2c3710","questionId":"903af1d7-a818-5154-afba-e8547da4daa6","sourceKey":"bank:ECO101:ECO-0707","payload":{"prompt":"The law of diminishing returns applies only when:","options":["Factors of production are becoming increasingly scarce","The price of extra units of a factor is rising","At least one factor of production is fixed","Capital is a variable input"],"correctOption":2,"section":"Production and the Firm","explanation":"Diminishing returns happen because extra units of a variable factor have to share a fixed factor, so the law needs at least one input to be fixed, which is a short-run situation. Option B is about input prices, not physical output, and if every input could vary we would be dealing with returns to scale instead."}},{"itemId":"80183aa6-0481-501e-8743-4833353a045b","questionId":"822f0de9-65a7-5b6c-8e13-75243d266a6f","sourceKey":"bank:ECO101:ECO-0708","payload":{"prompt":"The marginal product of labour shows the change in total product resulting from:","options":["A one-unit increase in labour while other inputs are also allowed to change","A one-unit increase in labour while other inputs are held constant","A change in the cost of a variable input","A change in the cost of a fixed input"],"correctOption":1,"section":"Production and the Firm","explanation":"Marginal product measures the extra output from one more unit of labour while all other inputs stay the same, MPL = change in TP / change in L. Option A is wrong because letting other inputs change would mix their effect into the result, and C and D are about costs, not physical output."}},{"itemId":"d4bb8ee5-c0b8-5363-8a7f-d6b12a97e1f9","questionId":"5eb9e2fe-118e-5ca3-aa33-8cb60a9540a9","sourceKey":"bank:ECO101:ECO-0709","payload":{"prompt":"When the total product curve is falling:","options":["The marginal product of labour is zero","The marginal product of labour is negative","The average product of labour is rising","The average product of labour must be negative"],"correctOption":1,"section":"Production and the Firm","explanation":"Marginal product is the change in total product from one more worker, so if total product is falling, each extra worker is reducing output and MP is negative. Option A is the tempting one, but MP is zero only at the exact point where total product is at its maximum, and average product (D) stays positive as long as total output is positive."}},{"itemId":"f0c2bc9e-eb99-52bb-be68-85df1126afcb","questionId":"9ced83fe-2302-5c74-9c8c-27ca55880eed","sourceKey":"bank:ECO101:ECO-0710","payload":{"prompt":"Variable costs are:","options":["Sunk costs","Fixed costs multiplied by output","Costs that change as the level of output changes","The change in total cost from producing one more unit"],"correctOption":2,"section":"Production and the Firm","explanation":"Variable costs, such as raw materials and casual labour, rise and fall with the amount produced. Option D is the definition of marginal cost, and A is wrong because sunk costs are already spent and cannot be recovered whatever the output level."}},{"itemId":"0dd11be8-449b-5d19-8296-0b56505be127","questionId":"b71e0f17-0a75-54dc-80f4-ccf189beac36","sourceKey":"bank:ECO101:ECO-0711","payload":{"prompt":"Which of the following is NOT a fixed cost for a Lagos firm?","options":["Monthly rent of N100,000 fixed in a one-year lease","An annual insurance premium of N50,000 already paid","A lawyer's annual retainer of N500,000","A worker's wage of N1,500 per hour worked"],"correctOption":3,"section":"Production and the Firm","explanation":"An hourly wage depends on how many hours are worked, so it rises as the firm produces more, making it a variable cost. Rent, insurance and a retainer (A, B and C) must be paid whatever the level of output, so they are fixed costs."}},{"itemId":"5474db85-9a80-577b-ace7-e21c4ad433f4","questionId":"fdc6549b-8e1a-513d-82a9-fb434d599b7d","sourceKey":"bank:ECO101:ECO-0712","payload":{"prompt":"At an output of 8 units, average fixed cost is N12.50 and average variable cost is N81.25. Total cost at this output is:","options":["N93.75","N97.78","N750","N880"],"correctOption":2,"section":"Production and the Firm","explanation":"ATC = AFC + AVC = 12.50 + 81.25 = 93.75, and TC = ATC x Q = 93.75 x 8 = N750. Option A is the trap: 93.75 is the average total cost per unit, not total cost."}},{"itemId":"317d4979-3f53-5fa8-9202-8eb15a7975d5","questionId":"357a474a-75da-59ad-bc5b-6687fc0a55ae","sourceKey":"bank:ECO101:ECO-0713","payload":{"prompt":"A firm has fixed costs of N400, average total cost of N3 and average variable cost of N2.50. What is its output?","options":["200 units","400 units","800 units","1,600 units"],"correctOption":2,"section":"Production and the Firm","explanation":"AFC = ATC - AVC = 3 - 2.50 = 0.50, and since AFC = TFC/Q, Q = 400/0.50 = 800 units. Option B divides 400 by 1 instead of by the AFC, and A divides 400 by 2 instead of by 0.5."}},{"itemId":"20f4dd7b-a192-587e-8b6f-79d8c245ff93","questionId":"dea43743-7de9-5684-9f80-b5cc87d6126f","sourceKey":"bank:ECO101:ECO-0714","payload":{"prompt":"If a firm's short-run average variable cost is rising, this means that:","options":["Average total cost is at its maximum","Average fixed cost is constant","Marginal cost is above average variable cost","Average variable cost is below average fixed cost"],"correctOption":2,"section":"Production and the Firm","explanation":"Whenever marginal cost is above an average, it pulls the average up, so a rising AVC means MC is above AVC. Option B is wrong because AFC keeps falling as output rises, and A is wrong because ATC curves have a minimum point, not a maximum."}},{"itemId":"4351a074-6e9b-5361-abd6-e8714f7a4a4c","questionId":"ef0494ce-69f3-542f-95c6-089ce9ad41d4","sourceKey":"bank:ECO101:ECO-0715","payload":{"prompt":"If a firm discovers a more efficient production technology, there will be:","options":["An upward shift in the AVC curve","An upward shift in the AFC curve","A downward shift in the AFC curve","A downward shift in the MC curve"],"correctOption":3,"section":"Production and the Firm","explanation":"Better technology means each unit can be produced with fewer variable inputs, so marginal cost (and average variable cost) shift down. Option C is tempting, but fixed costs such as rent are not changed by a more efficient method, so the AFC curve stays where it is, and A goes in the wrong direction."}},{"itemId":"0d1dbe30-d22b-5f48-bab1-c973eff82857","questionId":"6695e97d-aa79-571a-90df-113874095400","sourceKey":"bank:ECO101:ECO-0716","payload":{"prompt":"A firm's short-run marginal cost curve rises when:","options":["Marginal product is increasing","Marginal product is decreasing","Total fixed cost is increasing","Average fixed cost is decreasing"],"correctOption":1,"section":"Production and the Firm","explanation":"MC = wage / MP, so when each extra worker adds less output (diminishing marginal product), each extra unit of output costs more and MC rises. Option A gives the opposite, falling MC, and fixed costs (C and D) do not affect marginal cost at all."}},{"itemId":"ffa4ab90-1941-5a6d-9ca8-b3097bb5fda6","questionId":"20776b5f-bfd0-531a-b6a0-46f41ea064a6","sourceKey":"bank:ECO101:ECO-0717","payload":{"prompt":"A firm that enjoys economies of scale over a range of output will have:","options":["A rising long-run average cost curve","A falling long-run average cost curve","A constant long-run average cost curve","A long-run average cost curve that rises, then falls, then rises"],"correctOption":1,"section":"Production and the Firm","explanation":"Economies of scale mean that average cost per unit falls as the firm grows, so the LRAC curve slopes downward over that range. Option A describes diseconomies of scale, and C describes constant returns to scale."}},{"itemId":"7fce640f-be20-5f6e-9249-a068c40cf789","questionId":"61102459-ae84-5c50-a11e-29b38552834f","sourceKey":"bank:ECO101:ECO-0718","payload":{"prompt":"The wider the diameter of a gas pipeline, the lower the average cost of transporting each unit of gas over a long distance. This is an example of:","options":["Economies of scale","Normative economics","Diminishing marginal returns","An increasing marginal product of labour"],"correctOption":0,"section":"Production and the Firm","explanation":"A bigger pipeline costs more to build, but its capacity grows faster than its cost, so the cost per unit of gas carried falls as the scale of operation rises, which is economies of scale. Option C is about adding a variable input to a fixed one in the short run, and D is about labour rather than the size of the whole operation."}},{"itemId":"ae8778ce-a28a-5f12-9281-d251fd9c14b3","questionId":"9031634a-dcbc-56a2-945a-0674f785785a","sourceKey":"bank:ECO101:ECO-0719","payload":{"prompt":"If all inputs used to produce a product increase by 20 percent and output also increases by 20 percent, there are:","options":["Economies of scale","Diseconomies of scale","Constant returns to scale","Increasing average total costs"],"correctOption":2,"section":"Production and the Firm","explanation":"When output rises in exactly the same proportion as all inputs, the firm has constant returns to scale and its long-run average cost stays the same. Option A would need output to rise by more than 20 percent, and B would mean output rose by less than 20 percent."}},{"itemId":"1077ef37-8982-56f1-9cf9-8708550c04ed","questionId":"16e3bf1d-c1b4-5e03-a6ac-ed792b137c0d","sourceKey":"bank:ECO101:ECO-0720","payload":{"prompt":"In any production process, the marginal product of labour equals:","options":["Total output divided by total labour input","Total output minus the total capital stock","The change in total output resulting from a small change in labour input","Total output produced by labour"],"correctOption":2,"section":"Production and the Firm","explanation":"Marginal product of labour = change in total product / change in labour, that is the extra output from a small increase in labour. Option A is the definition of average product of labour, which is a common confusion, and D is simply total product."}},{"itemId":"d27575da-8e12-5bf8-88b5-e7a7e2fd1dcd","questionId":"70143fb8-6fe5-50bb-8cf7-6c488ca3e921","sourceKey":"bank:ECO101:ECO-0721","payload":{"prompt":"Consider these statements about a production function: (i) It shows a purely technical link between quantities of inputs and quantities of output. (ii) It reflects the state of technology of a firm or a sector of the economy. (iii) Input and output prices do not appear in it. (iv) It is a flow concept, showing how inputs are turned into output per period of time. Which statements are correct?","options":["(i), (ii) and (iv) only","(i) and (ii) only","(i) and (iv) only","(i), (ii), (iii) and (iv)"],"correctOption":3,"section":"Production and the Firm","explanation":"A production function is a purely physical relationship between inputs and output for a given technology, measured per period of time, and prices play no part in it, so all four statements hold. Options A, B and C each leave out at least one true statement, such as (iii), the point that input and output prices do not enter the production function."}},{"itemId":"54751ef6-3138-5064-ab35-84a6b92b2d2e","questionId":"64e93938-f329-55ca-9260-be72674133e5","sourceKey":"bank:ECO101:ECO-0722","payload":{"prompt":"When at least one input is held fixed, diminishing marginal returns are present when the marginal product of the variable input is:","options":["positive and rising","positive but falling","constant as more of the input is used","rising faster than average product"],"correctOption":1,"section":"Production and the Firm","explanation":"Diminishing returns means each extra unit of the variable input adds less to output than the one before, while total output is still rising, so marginal product is positive but falling. Option A describes increasing returns to the variable factor, and Option C describes constant returns."}},{"itemId":"02d76887-23e6-5171-af4a-72eec4d2f2d8","questionId":"030a0ff8-c407-5d76-a655-c23788a5068e","sourceKey":"bank:ECO101:ECO-0723","payload":{"prompt":"Which of these is an example of increasing returns to scale?","options":["A Lagos bakery doubles all its inputs and its output exactly doubles.","A firm raises all its inputs by 50% and its output rises by 25%.","A firm raises all its inputs by one quarter (25%) and its output rises by one third (about 33%).","None of these."],"correctOption":2,"section":"Production and the Firm","explanation":"Increasing returns to scale occur when output rises by a bigger proportion than all inputs; in C, inputs rise by 25% but output rises by about 33.3%. Option A is constant returns to scale, because output changes in the same proportion as inputs, and Option B is decreasing returns, because output grows by less than the inputs."}},{"itemId":"0453008b-0caf-52f0-89a2-80d18390ae85","questionId":"b7910939-069b-5870-8567-01e139b825a6","sourceKey":"bank:ECO101:ECO-0725","payload":{"prompt":"A key difference between the short run and the long run is that:","options":["in the long run a firm that produces nothing still has costs, but in the short run it has costs only when it produces","opportunity costs are fixed in the long run but variable in the short run","in the long run some inputs are fixed, while in the short run all inputs can be varied","in the short run not all inputs can be fully adjusted, while in the long run every input can be changed"],"correctOption":3,"section":"Production and the Firm","explanation":"The short run is a period in which at least one input, such as factory space or machinery, is fixed, while in the long run the firm has enough time to change all its inputs. Option C reverses the two periods, and Option A is also backwards: it is in the short run that fixed costs must be paid even at zero output."}},{"itemId":"e02a80c8-6c08-59af-be4e-1c3d3e96622f","questionId":"5806b7b4-2964-5fee-be7c-45212be39926","sourceKey":"bank:ECO101:ECO-0726","payload":{"prompt":"When the marginal product of an input is falling but still positive as more of it is used, which of the following must be true?","options":["Total product falls as more of the input is used.","Average product must be falling.","Marginal product must be greater than average product.","Total product rises, but at a decreasing rate."],"correctOption":3,"section":"Production and the Firm","explanation":"As long as marginal product is positive, each extra unit of input still adds to total output, but a falling marginal product means each addition is smaller, so total product rises at a decreasing rate. Option A would require marginal product to be negative, and Options B and C are not guaranteed, because average product can still be rising (MP above AP) or already falling (MP below AP) while MP declines."}},{"itemId":"ed22a157-3acd-5899-bb0f-e2fbba668272","questionId":"e3cad78d-8ca0-5cc3-99c7-77bf9eb35916","sourceKey":"bank:ECO101:ECO-0727","payload":{"prompt":"When the marginal product of an input is rising as more of it is used:","options":["total product rises at a decreasing rate","total product rises at an increasing rate","marginal product is below average product","average product is falling"],"correctOption":1,"section":"Production and the Firm","explanation":"If each extra unit of input adds more output than the previous one, total product is not just rising but rising faster and faster, that is, at an increasing rate. Option A describes falling marginal product, and C and D are wrong because a rising marginal product in this early stage stays above average product and pulls average product up."}},{"itemId":"bdeeeaad-93b8-5e64-b091-d0f7821d4d42","questionId":"0f853eaa-72d9-5cea-aea4-23c268b233f1","sourceKey":"bank:ECO101:ECO-0728","payload":{"prompt":"At the point where average product is at its maximum, marginal product is:","options":["zero","rising","equal to average product","greater than average product"],"correctOption":2,"section":"Production and the Firm","explanation":"The marginal product curve cuts the average product curve at the highest point of average product, so at that point MP = AP. Option A is the condition for maximum total product, not maximum average product, and Option D holds only while average product is still rising."}},{"itemId":"1596d5d3-0870-5d25-a643-e74b4fcb39b3","questionId":"1e94f93a-d8c6-55b6-8482-946faeed94e4","sourceKey":"bank:ECO101:ECO-0729","payload":{"prompt":"If average product is falling as more of a variable input is used, then:","options":["marginal product is below average product","total product must be falling","total product must be rising","marginal product is above average product"],"correctOption":0,"section":"Production and the Firm","explanation":"Average product falls whenever the extra output from the last unit (marginal product) is less than the current average, so MP must be below AP. Options B and C are not necessarily true, because total product keeps rising as long as MP is positive and only falls once MP turns negative, and Option D is the condition for a rising average product."}},{"itemId":"ed049bab-1047-5ee0-b332-22a954e080c6","questionId":"5751a5af-a31f-559f-b450-144da8a9ca5d","sourceKey":"bank:ECO101:ECO-0730","payload":{"prompt":"A total product curve may first show output rising at an increasing rate as a Lagos factory hires more workers. This is because of:","options":["a decline in the quality of the workforce","the principle of comparative advantage","the law of diminishing marginal returns","a rising marginal physical product of labour"],"correctOption":3,"section":"Production and the Firm","explanation":"In the early stage of production, extra workers allow better division of labour and fuller use of the fixed equipment, so the marginal physical product of labour rises and total output grows at an increasing rate. Option C, diminishing marginal returns, explains the later stage where output grows at a decreasing rate, and Option B relates to trade, not to the shape of a total product curve."}},{"itemId":"339f12c8-4497-55e4-b748-783d704ba869","questionId":"458bdf44-60e3-55d3-82ff-c9c889c1f5f9","sourceKey":"bank:ECO101:ECO-0732","payload":{"prompt":"When average product and total product are both positive and marginal product equals average product, total product is:","options":["at its maximum","positive and rising","falling","negative but rising"],"correctOption":1,"section":"Production and the Firm","explanation":"MP = AP happens at the peak of average product, and at that point MP is still positive, so each extra unit of input is still adding to output and total product is rising. Option A is wrong because total product reaches its maximum only later, when MP falls to zero, and Option D is impossible since total product is stated to be positive."}},{"itemId":"42a08846-be1f-5e67-bf2a-0abd8c354588","questionId":"2f6373d1-6b7a-5aca-b780-630578891e25","sourceKey":"bank:ECO101:ECO-0733","payload":{"prompt":"Costs that a firm incurs only when it actually produces output are called:","options":["explicit costs","fixed costs","variable costs","sunk costs"],"correctOption":2,"section":"Production and the Firm","explanation":"Variable costs, such as raw materials and fuel for a production line, change with output and fall to zero when nothing is produced. Option B, fixed costs, must be paid even at zero output (rent, for example), and Option A, explicit costs, are simply money payments and can be either fixed or variable."}},{"itemId":"748df269-fdf3-5694-9a03-93bf697d8bcf","questionId":"297e2148-a7e4-5748-91a8-062ce54f60e6","sourceKey":"bank:ECO101:ECO-0734","payload":{"prompt":"Why do diminishing marginal returns set in as a firm keeps hiring more workers while its land and capital stay fixed?","options":["Each additional worker hired is less skilled than the one before.","Experienced workers are always hired before less skilled ones.","Each extra worker has less land and capital to work with, so the workplace becomes crowded and harder to manage.","Selling more output requires the firm to cut its price."],"correctOption":2,"section":"Production and the Firm","explanation":"Diminishing returns come from the fixed factors: as more workers share the same machines and space, each has less capital and land to work with, so each additional worker adds less output. Options A and B are wrong because the law assumes all workers are equally skilled, and Option D is about demand and prices, not about production."}},{"itemId":"bc994d8e-b361-51f5-b186-00ebbd3dda6b","questionId":"44a5e206-2aa5-5ad2-aec5-56a04ff174c3","sourceKey":"bank:ECO101:ECO-0735","payload":{"prompt":"When a firm is deciding how much to produce in the short run, which of these is irrelevant to the decision?","options":["Total variable cost (TVC)","Marginal cost (MC)","Average fixed cost (AFC)","Marginal revenue (MR)"],"correctOption":2,"section":"Production and the Firm","explanation":"Fixed costs must be paid whatever the firm produces, so average fixed cost does not change the comparison of extra revenue with extra cost and is irrelevant to the output decision. Options A, B and D all matter: the firm compares marginal revenue with marginal cost, and it checks that revenue covers total variable cost before producing at all."}},{"itemId":"12840b63-bcc4-5bee-8879-a1276f1302e3","questionId":"b2143cbb-5e18-5c41-9b4a-3c0c48f0687e","sourceKey":"bank:ECO101:ECO-0736","payload":{"prompt":"Which cost curve can never be U-shaped?","options":["Average variable cost curve","Marginal cost curve","Average fixed cost curve","Average total cost curve"],"correctOption":2,"section":"Production and the Firm","explanation":"Average fixed cost is total fixed cost divided by output (AFC = TFC/Q), so it keeps falling as output rises, giving a curve that slopes downward throughout and never turns up. Options A, B and D are U-shaped in the short run because diminishing returns eventually push them upward."}},{"itemId":"eae9943b-3820-5f48-ad3c-cce322cd1a05","questionId":"daa954ae-0730-56ec-933c-801b6f799b76","sourceKey":"bank:ECO101:ECO-0737","payload":{"prompt":"Diminishing marginal returns are most consistent with:","options":["economies of scale","gains from specialisation","an upward-sloping marginal cost curve","depreciation of the capital stock"],"correctOption":2,"section":"Production and the Firm","explanation":"When each extra worker adds less output, each extra unit of output needs more input and so costs more, which makes the short-run marginal cost curve slope upward. Option B, gains from specialisation, actually explains increasing returns in the early stage, and Option A is a long-run idea about the scale of the whole firm."}},{"itemId":"bde5302f-9828-5952-b809-427583eb3924","questionId":"e0220013-f254-586e-9b4c-d2a1ebf637e4","sourceKey":"bank:ECO101:ECO-0739","payload":{"prompt":"In economics, the costs of a firm:","options":["are smaller than costs in the everyday sense","include implicit costs as well as explicit costs","always fall as more output is produced","are measured so that profit is larger than in everyday accounting"],"correctOption":1,"section":"Production and the Firm","explanation":"Economists measure opportunity cost, so a firm's costs include explicit money payments plus implicit costs, such as the income the owner could have earned by using their own time or building elsewhere. Because implicit costs are added, economic costs are larger, not smaller, than accounting costs, so A and D are wrong, and C is wrong because costs eventually rise with output."}},{"itemId":"7659ed8d-93e8-5479-81e7-d48fe671be4e","questionId":"c05dc704-0314-595f-b0a3-fc97c3cfd0b9","sourceKey":"bank:ECO101:ECO-0740","payload":{"prompt":"In economic theory, average total cost is:","options":["total fixed and variable costs divided by the number of workers employed","the sum of fixed and variable costs","average fixed cost plus total variable cost","total fixed and variable costs divided by the quantity of output"],"correctOption":3,"section":"Production and the Firm","explanation":"Average total cost is total cost per unit of output: ATC = (TFC + TVC)/Q, which is the same as AFC + AVC. Option B is total cost rather than average cost, Option A divides by labour instead of output, and Option C wrongly mixes an average with a total."}},{"itemId":"d6870b87-855a-5b32-8635-81c828d52b45","questionId":"e3174b52-f839-557b-a173-914248202c14","sourceKey":"bank:ECO101:ECO-0741","payload":{"prompt":"In the theory of the firm, the short run is a period:","options":["too short for the firm to change all its inputs","of not more than one week","long enough for the firm to change all its inputs","in which fixed costs are zero"],"correctOption":0,"section":"Production and the Firm","explanation":"The short run is defined by what the firm can change, not by calendar time: at least one input, like plant size, stays fixed. Option B is wrong because the short run has no fixed length, Option C describes the long run, and Option D is wrong because fixed costs exist precisely because some inputs are fixed."}},{"itemId":"e157add2-a165-593e-91aa-9a3b3ec2440f","questionId":"375d2124-7d52-515f-a754-09060ce0a873","sourceKey":"bank:ECO101:ECO-0742","payload":{"prompt":"The law of diminishing marginal productivity implies that, in the short run:","options":["costs per unit must eventually fall as output rises","marginal product falls continuously from the very first unit of input","as output rises, more and more input is needed for each extra unit of output, so cost per unit eventually rises","total output becomes negative once marginal product starts falling"],"correctOption":2,"section":"Production and the Firm","explanation":"With a fixed factor, each extra unit of the variable input adds less output, so producing each additional unit of output requires more input and costs per unit rise. Option A is the opposite, Option B ignores the early stage where marginal product may rise, and Option D confuses falling marginal product with negative total output."}},{"itemId":"7354488c-f005-5cae-a71a-042234882967","questionId":"4bf5cd41-26f3-5806-908f-def7cce9828b","sourceKey":"bank:ECO101:ECO-0743","payload":{"prompt":"Economies of scale:","options":["begin as soon as diminishing marginal productivity appears","are generally regarded as a long-run concept","arise only because some inputs are fixed","ensure that industries stay competitive rather than monopolised"],"correctOption":1,"section":"Production and the Firm","explanation":"Economies of scale describe what happens to average cost when a firm changes the scale of all its inputs, which is only possible in the long run. Option A mixes them up with diminishing returns, a short-run idea, Option C describes the short run, and Option D is backwards, since large economies of scale favour a few big firms or even a natural monopoly."}},{"itemId":"59f42ffe-ab7e-5e9c-b7dd-f409f2175221","questionId":"4a944e4b-6d19-5644-b84e-040c005357a8","sourceKey":"bank:ECO101:ECO-0744","payload":{"prompt":"If a typical firm's long-run average cost curve keeps sloping downward over the relevant range of output, it becomes hard to maintain the assumption of:","options":["diminishing returns","perfect competition","ceteris paribus","rising short-run marginal cost"],"correctOption":1,"section":"Production and the Firm","explanation":"A continuously falling long-run average cost means bigger firms always produce more cheaply, so the industry tends to end up with a few large firms or a single firm, which conflicts with the many small firms of perfect competition. Options A and D are short-run ideas that can still hold, and C, ceteris paribus, is simply the 'other things equal' assumption used in analysis."}},{"itemId":"d2171eee-40ad-5b1b-a223-a4eeb0c83bd2","questionId":"6dc2d76f-84e3-5b3e-94ab-354eae42632e","sourceKey":"bank:ECO101:ECO-0745","payload":{"prompt":"Marginal cost equals average variable cost when average variable cost is:","options":["at its maximum","rising","falling","at its minimum"],"correctOption":3,"section":"Production and the Firm","explanation":"The marginal cost curve cuts the average variable cost curve at the lowest point of AVC: when MC is below AVC it pulls the average down, and when MC is above AVC it pulls the average up. So MC = AVC only at minimum AVC, while in B and C MC is above or below AVC respectively."}},{"itemId":"27a47a6a-db02-5188-a932-9847f308b2a3","questionId":"99fccd0d-9ea5-517d-863b-786a93cb592b","sourceKey":"bank:ECO101:ECO-0785","payload":{"prompt":"The addition to total revenue from selling one more unit of output is called:","options":["total revenue","average revenue","value added","marginal revenue"],"correctOption":3,"section":"Production and the Firm","explanation":"Marginal revenue is the extra revenue from selling one more unit: MR = (change in TR)/(change in Q). Option B, average revenue, is total revenue per unit sold (TR/Q), and Option C, value added, is a national income concept."}},{"itemId":"e1f3c5a0-c85e-5a67-aa67-3a20b8b5301a","questionId":"95d0726d-c959-528b-9d1e-6b32473285a8","sourceKey":"bank:ECO101:ECO-0786","payload":{"prompt":"Which cost must a firm pay even when its output is zero?","options":["Opportunity cost","Fixed cost","Variable cost","Marginal cost"],"correctOption":1,"section":"Production and the Firm","explanation":"Fixed costs, such as shop rent in Yaba or interest on a loan, do not depend on output and must be paid even if the firm produces nothing. Variable cost (C) and marginal cost (D) arise only from producing, so they are zero when output is zero."}},{"itemId":"de7f0ef6-2bef-53c1-bc35-380df0c7f2c5","questionId":"c5ea0eb5-e771-5e67-91a6-6cc0c3d8ecf2","sourceKey":"bank:ECO101:ECO-0788","payload":{"prompt":"The reward earned by the entrepreneur as a factor of production is:","options":["rent","wages","interest","profit"],"correctOption":3,"section":"Production and the Firm","explanation":"Each factor earns a reward: land earns rent, labour earns wages, capital earns interest, and the entrepreneur, who organises production and bears risk, earns profit. Options A, B and C are the rewards of the other three factors."}},{"itemId":"f308c735-8b0f-50d4-8d29-e7278ba41a46","questionId":"c7afeaef-0454-5876-a9ad-de46e6e29e91","sourceKey":"bank:ECO101:ECO-0790","payload":{"prompt":"Average revenue is equal to:","options":["price","cost","profit","total revenue"],"correctOption":0,"section":"Production and the Firm","explanation":"Average revenue is total revenue divided by quantity sold, and since TR = P x Q, AR = (P x Q)/Q = P. Option D, total revenue, is the full amount received rather than the amount per unit, and Options B and C refer to costs and profit, not revenue."}},{"itemId":"f70c7e1b-0805-5be7-be59-c680b63e97d0","questionId":"24d8a26a-d77a-551b-abf8-a236bec664d4","sourceKey":"bank:ECO101:ECO-0791","payload":{"prompt":"Total revenue is at its maximum when marginal revenue is:","options":["positive","negative","one","zero"],"correctOption":3,"section":"Production and the Firm","explanation":"Total revenue rises while MR is positive and falls once MR turns negative, so it peaks at the point where MR = 0. Option A describes the range where TR is still increasing, and Option B the range where TR is falling."}},{"itemId":"7be9527d-d8be-540e-b9b5-b441265d4a03","questionId":"2b304aff-5c30-5146-bec5-415892e4f302","sourceKey":"bank:ECO101:ECO-0793","payload":{"prompt":"If the demand curve is a downward-sloping straight line, the slope of the marginal revenue curve is:","options":["negative","positive","zero","sometimes negative and sometimes positive"],"correctOption":0,"section":"Production and the Firm","explanation":"For a linear demand curve P = a - bQ, total revenue is TR = aQ - bQ^2, so MR = a - 2bQ, a straight line with slope -2b, which is negative and twice as steep as demand. MR therefore slopes downward throughout, ruling out B, C and D."}},{"itemId":"dbaab66b-72d1-5c90-9bad-ccba70a6618f","questionId":"a4f697d2-e432-55ad-9785-3aa098c754b6","sourceKey":"bank:ECO101:ECO-1491","payload":{"prompt":"Labour productivity is best measured by which of the following?","options":["Output per worker employed","Number of workers per unit of capital","Amount of capital per worker","Output per head of the total population"],"correctOption":0,"section":"Production and the Firm","explanation":"Labour productivity is output divided by the number of workers employed, which is the same idea as the average product of labour. Option C, capital per worker, is a cause of higher productivity but not a measure of it. Option D, output per head of population, is a measure of living standards and includes people who are not working."}},{"itemId":"050de553-bc86-5f3d-84a5-e2ec5964a69a","questionId":"049f2c70-a348-5296-ad8b-a672c3a30e15","sourceKey":"bank:ECO101:ECO-1682","payload":{"prompt":"Assume diminishing returns to capital and constant returns to scale. Holding the number of workers constant, a fall in the capital stock will cause","options":["a fall in output","a rise in the capital-labour ratio","a rise in output per worker","no change in output"],"correctOption":0,"section":"Production and the Firm","explanation":"Capital still has a positive marginal product even with diminishing returns, so less capital means less output, as in A. Option D would only hold if capital contributed nothing to production. With fewer machines per worker, output per worker falls rather than rising as in C, and the capital-labour ratio falls rather than rising as in B."}},{"itemId":"a4eac479-3411-5c4a-8bc0-f136f32a7ddd","questionId":"958b8061-3e77-530f-a089-835d7d826fb4","sourceKey":"bank:ECO101:ECO-1683","payload":{"prompt":"Assume diminishing returns to capital. If capital per worker is increased in successive equal steps, output per worker will","options":["increase by a constant amount each time","decline","increase by successively larger amounts","increase, but by successively smaller amounts"],"correctOption":3,"section":"Production and the Firm","explanation":"Diminishing returns mean each extra unit of capital per worker adds less output than the one before, so output per worker keeps rising but by smaller and smaller amounts, as in D. Option B is wrong because extra capital still raises output. Option A describes constant returns to capital, and option C describes increasing returns."}},{"itemId":"2effd5e7-0d84-515e-bea2-54ff1a1a1f57","questionId":"7dbe4ca0-f25f-57a4-8b9b-da65a4ca468b","sourceKey":"bank:ECO101:ECO-1699","payload":{"prompt":"Assume constant returns to scale. If labour (N) and capital (K) both increase by 2%, output (Y) will","options":["increase by 2%","increase by 4%","increase by more than 2% but less than 4%","increase by less than 2%"],"correctOption":0,"section":"Production and the Firm","explanation":"Constant returns to scale means that raising all inputs by the same percentage raises output by exactly that percentage, so Y rises by 2%, as in A. Option B wrongly adds the two 2% increases together. Option D would be decreasing returns to scale, and option C would be increasing returns to scale."}},{"itemId":"491caa23-db90-58b7-b038-2c249110981c","questionId":"43c065b7-3f7d-5b0e-a4d4-28a43a06aa5c","sourceKey":"bank:ECO101:ECO-1700","payload":{"prompt":"Assume constant returns to scale. If labour (N) and capital (K) both decrease by 3%, then","options":["output (Y) will decrease by less than 3%","output (Y) will decrease by 6%","output (Y) will decrease by 3%","the capital-labour ratio (K/N) will decrease"],"correctOption":2,"section":"Production and the Firm","explanation":"Under constant returns to scale, cutting all inputs by 3% cuts output by exactly 3%, as in C. Option B wrongly adds the two cuts together, and option A would describe a different type of returns to scale. Option D is wrong because K and N fall by the same percentage, so K/N stays the same."}},{"itemId":"6db8c7ab-e6cb-5cf3-b272-1febc6985c78","questionId":"b7c5084d-a3cb-5d15-902a-e174c1fdc051","sourceKey":"bank:ECO101:ECO-1704","payload":{"prompt":"Assume diminishing returns to labour. If employment increases by 3% while capital and technology stay the same, we know for certain that","options":["the capital-labour ratio will increase","output per worker will increase by 3%","output will increase by less than 3%","output will increase by exactly 3%"],"correctOption":2,"section":"Production and the Firm","explanation":"With capital fixed, each extra worker adds less output than the one before, so a 3% rise in employment raises output by less than 3%, as in C. Option D would need capital to rise by 3% too (constant returns to scale). Output per worker actually falls, which rules out B, and with more workers sharing the same capital the capital-labour ratio falls, which rules out A."}},{"itemId":"b71025af-fc4f-519d-b873-6507fa5380b3","questionId":"f7f78484-1391-52e8-8bda-148c8656e05c","sourceKey":"bank:ECO101:ECO-1706","payload":{"prompt":"Diminishing returns to capital (K) imply that a 4% increase in K, with labour unchanged, will cause","options":["output (Y) to increase by less than 4%","a fall in output per worker (Y/N)","a fall in the capital-labour ratio (K/N)","output (Y) to increase by exactly 4%"],"correctOption":0,"section":"Production and the Firm","explanation":"With diminishing returns to capital, raising only capital increases output, but proportionally less, so Y rises by less than 4%, as in A. Option D would need labour to rise by 4% as well. Output per worker and K/N both rise when capital increases with labour fixed, so options B and C are wrong."}},{"itemId":"89ef7d9a-c35b-5762-9ce9-a894270ad35d","questionId":"bc601e84-b06f-54d1-8deb-85318af38c33","sourceKey":"bank:ECO101:ECO-1849","payload":{"prompt":"A Lagos garment factory's output is given by Y = A x N, where N is the number of workers and A is a positive constant. Labour productivity (output per worker) is","options":["Y","N/A","A/N","A"],"correctOption":3,"section":"Production and the Firm","explanation":"Labour productivity is output per worker, Y/N. With Y = A x N, Y/N = (A x N)/N = A, so each worker produces A units. Option A gives total output, not output per worker, and options B and C wrongly divide A and N in place of dividing Y by N."}},{"itemId":"3cabd2b1-aa3f-58ad-87c1-0929eb8a1857","questionId":"18e12534-b377-575f-b9ee-8c0bffeac207","sourceKey":"bank:ECO101:ECO-1857","payload":{"prompt":"A firm's output is given by Y = A x N, where N is the number of workers and A is a positive constant. How many additional workers are needed to raise output by one unit?","options":["1/A","Y/N","1/N","1/Y"],"correctOption":0,"section":"Production and the Firm","explanation":"Each extra worker adds A units of output, because the marginal product of labour is dY/dN = A. To get one more unit you need 1/A workers; for example, if A = 4, a quarter of a worker's time produces one unit. Option B, Y/N, equals A, which is output per worker rather than workers per unit, and options C and D have no link to the extra labour needed."}},{"itemId":"23609ecc-dd1d-5fb2-a13d-0ae48ea85ad0","questionId":"d3561bdb-a11e-538b-90c2-0185c14af1d4","sourceKey":"bank:ECO101:ECO-1858","payload":{"prompt":"A firm's output is given by Y = A x N, where N is the number of workers and A is a positive constant. If each worker is paid a wage of W naira, the marginal cost of producing one more unit of output is","options":["W","W/A","A/W","(1 + A)W"],"correctOption":1,"section":"Production and the Firm","explanation":"One more unit of output needs 1/A extra workers, since each worker produces A units. Each worker costs W naira, so marginal cost = W x (1/A) = W/A, which is the wage divided by the marginal product of labour. Option A would only be right if a worker produced exactly one unit, and option C turns the ratio upside down."}},{"itemId":"34b5b622-eadd-5952-b0ff-45019294f995","questionId":"90daec02-ab45-5da9-842d-6618bfbd15aa","sourceKey":"bank:ECO101:ECO-1962","payload":{"prompt":"Entrepreneurs do all of the following EXCEPT","options":["organise labour, land and capital.","come up with new ideas about what and how to produce.","bear the risks of business decisions.","own all the other resources used in production."],"correctOption":3,"section":"Production and the Firm","explanation":"Entrepreneurs organise the other factors of production, come up with new business ideas and bear the risk of their decisions, but they do not have to own all the other resources. They often rent land, hire labour and borrow capital. Options A, B and C are all genuine roles of an entrepreneur."}},{"itemId":"39f94471-59b5-5683-bdc4-295f4f9a321a","questionId":"808c148d-fe38-5a60-b0b3-c46279b0a5c7","sourceKey":"bank:ECO101:ECO-1965","payload":{"prompt":"Which of the following is NOT a factor of production?","options":["the water used to cool a factory's generator","the effort of farmers raising cattle","the wages paid to workers","the management skill of a small business owner"],"correctOption":2,"section":"Production and the Firm","explanation":"Wages are the income paid to labour, not a factor of production; the factor itself is the labour that earns the wage. Option A is a natural resource, which counts as land, Option B is labour, and Option D is entrepreneurship, so all three are factors of production."}},{"itemId":"24c98f77-2bd2-50e7-8d54-9eb3e6ef69b5","questionId":"65337d14-f8c1-5bce-8de7-4d05157116dc","sourceKey":"bank:ECO101:ECO-1968","payload":{"prompt":"What are the four categories into which factors of production are grouped?","options":["profit, wages, rent and interest","land, labour, capital and entrepreneurship","capital, human capital, land and labour","entrepreneurship, profit, labour and wages"],"correctOption":1,"section":"Production and the Firm","explanation":"The four factors of production are land, labour, capital and entrepreneurship. Option A lists the incomes these factors earn (rent, wages, interest and profit), not the factors themselves. Option C counts human capital separately, but human capital is the quality of labour, and Option D mixes factors with their incomes."}},{"itemId":"a053fc56-61d3-58f9-bbdb-a5e00d1eefe9","questionId":"a6391f10-403a-5904-b3d0-8a3d1b87c6c6","sourceKey":"bank:ECO101:ECO-1969","payload":{"prompt":"The income earned by people who supply the factor of production ________ is called ________.","options":["capital; rent","entrepreneurship; wages","land; profit","entrepreneurship; profit"],"correctOption":3,"section":"Production and the Firm","explanation":"Entrepreneurship earns profit, which is the reward for organising production and bearing risk. The other pairings are mixed up: capital earns interest (not rent), labour earns wages, and land earns rent. That is why Options A, B and C are wrong."}},{"itemId":"ada5fff7-09c5-5d58-8e4a-b8d0fbad5c83","questionId":"ac40f24f-b7a8-5c09-a1fb-343789ee362a","sourceKey":"bank:ECO101:ECO-1971","payload":{"prompt":"Which of the following is correct? Factors of production are","options":["land, labour, the price system and capital.","the inputs used to produce goods and services.","the fundamental source of abundance.","only land and labour."],"correctOption":1,"section":"Production and the Firm","explanation":"Factors of production are the productive resources, or inputs, used to produce goods and services. Option A wrongly includes the price system, which is a way of allocating resources, not a resource itself. Option C is wrong because these resources are limited, which is what causes scarcity, and Option D leaves out capital and entrepreneurship."}},{"itemId":"8ca88ea8-1db1-5f6c-a5be-c783de8f4f64","questionId":"22f2571b-8b5f-50ae-8848-7f481468eb7f","sourceKey":"bank:ECO101:ECO-1973","payload":{"prompt":"Using economists' definition of factors of production, which of the following is NOT a factor of production?","options":["money","low-skilled labour","coal","an engineer"],"correctOption":0,"section":"Production and the Firm","explanation":"Money is not a factor of production, because money itself does not produce anything; it is used to buy the real resources that do. Option B and Option D are labour, and Option C, coal, is a natural resource that counts as land. Money is often confused with capital, but capital means real tools, machines and buildings."}},{"itemId":"2f288937-39c0-5123-81fb-7db02329c736","questionId":"eb45e9cd-be3d-5a35-a639-25cf8898a0b0","sourceKey":"bank:ECO101:ECO-1976","payload":{"prompt":"Which of the following best defines capital as a factor of production?","options":["the gifts of nature that businesses use to produce goods and services","the knowledge and skills people gain from education and use in production","financial assets used by businesses","the tools, machines and buildings used in production"],"correctOption":3,"section":"Production and the Firm","explanation":"In economics, capital means the tools, machines, buildings and other equipment that are made by people and used to produce goods and services. Option C is the common trap: money and financial assets are not capital in this sense. Option A describes land, and Option B describes human capital."}},{"itemId":"1fe9a47f-9bf2-58c4-80b0-277bca160b80","questionId":"dd2c97a7-7cc4-5e04-bfa5-08c04822d747","sourceKey":"bank:ECO101:ECO-1977","payload":{"prompt":"In economics, the term 'land' means","options":["only land used for farming.","land, mineral resources and other gifts of nature.","only land devoted to business activities.","land used for farming and building towns."],"correctOption":1,"section":"Production and the Firm","explanation":"In economics, land covers all the gifts of nature used in production, including the ground itself, minerals, water, forests and fish. Options A, C and D are too narrow, because they limit land to particular uses of the ground and leave out other natural resources."}},{"itemId":"09a01867-1f4f-5098-af13-7960c11d4fde","questionId":"37e56fb1-3dcd-5486-a46f-f3d3f0eb0a93","sourceKey":"bank:ECO101:ECO-1980","payload":{"prompt":"Crude oil in the Niger Delta falls into which factor of production category?","options":["land","labour","capital","entrepreneurship"],"correctOption":0,"section":"Production and the Firm","explanation":"Crude oil is a natural resource, a gift of nature, so economists classify it as land. Option C is tempting because oil is valuable, but capital means man-made tools, machines and buildings. Labour and entrepreneurship (Options B and D) are human efforts, not natural resources."}},{"itemId":"35650fb9-6011-5897-ace1-065a354778a7","questionId":"11e9bced-f3c9-5e84-9e1e-26505254b66c","sourceKey":"bank:ECO101:ECO-1981","payload":{"prompt":"A worker on a car assembly line is an example of ________ and earns ________.","options":["labour; rent","entrepreneurship; wages","labour; wages","capital; rent"],"correctOption":2,"section":"Production and the Firm","explanation":"The assembly-line worker supplies labour, the work time and effort people put into production, and labour earns wages. Option A pairs labour with rent, which is the income of land. Option B is wrong because the worker is not organising production or bearing the firm's risk, so he is not an entrepreneur."}},{"itemId":"63ddc3e8-3303-5958-8194-0ecd289a496e","questionId":"112e5de4-f0d9-585d-80fb-0f10e8e674dc","sourceKey":"bank:ECO101:ECO-1983","payload":{"prompt":"The term human capital refers to","options":["labour used to make capital equipment.","buildings and machinery.","people's knowledge and skill.","entrepreneurship and risk-taking."],"correctOption":2,"section":"Production and the Firm","explanation":"Human capital is the knowledge and skill people gain through education, training and experience. Option B describes physical capital, not human capital. Option A describes a use of labour, and Option D describes entrepreneurship, which is a separate factor of production."}},{"itemId":"ee34772c-25fd-504a-adc6-bf8a31385d02","questionId":"04c37d94-bd6a-535a-8032-2a1291c40442","sourceKey":"bank:ECO101:ECO-1985","payload":{"prompt":"Joy is training to become a chef. The skills she gains from her training will increase which type of resource?","options":["land","physical capital","entrepreneurship","human capital"],"correctOption":3,"section":"Production and the Firm","explanation":"Skills gained from education and training are human capital, so Joy's culinary training adds to her human capital. Option B, physical capital, would be things like the ovens and pots she uses. Option C is tempting only if she starts her own restaurant, but the training itself builds skill, not entrepreneurship."}},{"itemId":"d09087b3-5a06-597f-83be-bdf812adc3a9","questionId":"72dbee09-cd69-5eaa-87b7-40fa7a8688cd","sourceKey":"bank:ECO101:ECO-1986","payload":{"prompt":"Which of the following is NOT an investment in human capital?","options":["a business student attends a seminar on using a laptop","a student buys a laptop","a computer science student learns how to repair a laptop","a computer science student takes a course on programming"],"correctOption":1,"section":"Production and the Firm","explanation":"Buying a laptop adds a piece of equipment, which is physical capital, not knowledge or skill. Options A, C and D all involve gaining new knowledge or skills, which is exactly what investment in human capital means."}},{"itemId":"13201cec-b939-5e0a-b3b0-5045e2dd84a6","questionId":"cd5feca9-6a36-57dd-b58c-4143d4c0965a","sourceKey":"bank:ECO101:ECO-1990","payload":{"prompt":"Kunle works in a bottling plant in Lagos, operating a machine that fills bottles. The machine he operates is which type of resource?","options":["capital","land","labour","entrepreneurship"],"correctOption":0,"section":"Production and the Firm","explanation":"A machine is a man-made tool used to produce other goods, so it is capital. Option C is tempting because Kunle operates it, but Kunle's effort is the labour; the machine itself is capital. Land refers to natural resources, and entrepreneurship refers to organising production and bearing risk."}},{"itemId":"288fd67e-fd01-591d-8546-8b66709328a4","questionId":"4d2841e4-3c5d-5dba-9138-28fa28c91b57","sourceKey":"bank:ECO101:ECO-1993","payload":{"prompt":"The economic resource that organises the use of the other economic resources is","options":["labour.","capital.","entrepreneurship.","land."],"correctOption":2,"section":"Production and the Firm","explanation":"Entrepreneurship brings together and organises land, labour and capital to produce goods and services. Option A is tempting because entrepreneurs are people, but labour is the work effort itself, not the organising role. Capital and land are resources that get organised, not the ones doing the organising."}},{"itemId":"2a44f206-1d37-5854-926f-7a7d79113fa4","questionId":"a875904c-c231-5a7c-a9f3-43bd56376703","sourceKey":"bank:ECO101:ECO-1994","payload":{"prompt":"Entrepreneurs directly do all of the following EXCEPT","options":["create new ideas about what and how to produce.","make business decisions.","face the risks that come from their business decisions.","decide for whom goods and services are produced."],"correctOption":3,"section":"Production and the Firm","explanation":"Who gets goods and services is decided by people's incomes and how the economy is organised, not directly by entrepreneurs. Entrepreneurs do come up with new ideas, make business decisions and bear the risks of those decisions, so Options A, B and C are all part of their role."}},{"itemId":"c699ed78-48e4-557c-86ed-1e30dc89cfdb","questionId":"9daa4f3b-887c-577b-a9f1-95ee5b14cd2e","sourceKey":"bank:ECO101:ECO-2125","payload":{"prompt":"A phone company sends its sales staff on training courses. This is an example of","options":["a macroeconomic decision.","scarcity.","a firm investing in its workers' human capital.","entrepreneurship."],"correctOption":2,"section":"Production and the Firm","explanation":"Human capital is the knowledge and skill people gain through education, training and experience, so training staff builds it. Option A is wrong because this is one firm's decision, which is microeconomic. Option D, entrepreneurship, is the resource that organises the other factors of production, not the training of workers."}},{"itemId":"b9ee4b4e-6776-5297-aa5e-4a416951ceb5","questionId":"eb813e34-59ee-5d44-8deb-e26c8d52c522","sourceKey":"bank:ECO101:ECO-2143","payload":{"prompt":"The tools, instruments, machines and buildings that people use to produce goods and services are called","options":["entrepreneurship.","capital.","human capital.","land."],"correctOption":1,"section":"Production and the Firm","explanation":"Capital is the man-made equipment and structures used in production. Option C, human capital, is the knowledge and skill of workers, not physical equipment. Option D, land, covers natural resources, and option A is the resource that organises the other factors."}},{"itemId":"6b6eb3bc-9c80-5fa4-bd1e-4289b2758523","questionId":"0adca2fb-af06-5c88-8c34-5e9ccc098b57","sourceKey":"bank:ECO101:ECO-0038","payload":{"prompt":"Attempt by the government to impose a maximum allowable price, below the equilibrium price, on the manufacturers of cement will lead to ________ in the quantity demanded of cement.","options":["decrease","increase","uncertain","none of the above"],"correctOption":1,"section":"Partial Equilibrium Analysis","explanation":"A maximum price set below equilibrium makes cement cheaper, so buyers want to buy more and the quantity demanded increases. Option A describes what happens to quantity supplied, which falls because producers now earn less per bag. Option C is wrong because the law of demand gives a clear direction once the price is pushed down."}},{"itemId":"02bd9e04-7c84-52a8-a5a4-3385f8157631","questionId":"9adc2da7-f1e0-5d9a-9bd6-6ee03bc2da16","sourceKey":"bank:ECO101:ECO-0046","payload":{"prompt":"The difference between the prices the buyers pay and what the sellers get as a result of tax imposed is known as","options":["tax burden","tax incidence","tax elasticity","wedge"],"correctOption":3,"section":"Partial Equilibrium Analysis","explanation":"A tax wedge is the gap between the price buyers pay and the price sellers receive after a tax is imposed, and it equals the tax per unit. Option B, tax incidence, is about who bears the tax, not the size of the price gap. Option A is a general phrase, and option C is not the name for this gap."}},{"itemId":"05317636-fc1c-5719-8b87-b5032861ae01","questionId":"ce3d1c99-7448-582c-89ba-7043e921d0cb","sourceKey":"bank:ECO101:ECO-0047","payload":{"prompt":"When the supply is less elastic than demand, the incidence of tax falls more heavily on the ________","options":["consumers","producers","all of the above","none of the above"],"correctOption":1,"section":"Partial Equilibrium Analysis","explanation":"Whoever is less able to respond to price ends up bearing more of the tax. If supply is less elastic than demand, producers cannot easily cut output, so most of the tax falls on them. Option A would be true if demand were the less elastic side."}},{"itemId":"366e4584-26b0-53b3-9b1d-eec68925425b","questionId":"b6973f7d-e4f5-59dc-b0a3-3bc92c844dca","sourceKey":"bank:ECO101:ECO-0080","payload":{"prompt":"If the demand for a product is perfectly inelastic, who bears the tax?","options":["buyer","seller","both","none of the above"],"correctOption":0,"section":"Partial Equilibrium Analysis","explanation":"When demand is perfectly inelastic, buyers purchase the same quantity whatever the price, so sellers can pass the whole tax on to them and the buyer bears it. Option B would be the case if demand were perfectly elastic. Option C is wrong here because buyers do not cut back at all, so sellers have no reason to absorb any of the tax."}},{"itemId":"feba3160-0c97-5a05-ac82-0d7d40aca3a7","questionId":"15ccc9b7-666b-5546-806a-0159e12df062","sourceKey":"bank:ECO101:ECO-0088","payload":{"prompt":"If the demand for a product is perfectly elastic, who bears the tax?","options":["buyer","seller","both","none of the above"],"correctOption":1,"section":"Partial Equilibrium Analysis","explanation":"When demand is perfectly elastic, buyers will not pay even slightly more than the going price, so sellers cannot pass any of the tax on and must bear it themselves. Option A would be the case if demand were perfectly inelastic. Option C is wrong here because any attempt to share the tax through a higher price would lose all the sellers' customers."}},{"itemId":"d3a1706e-58ba-5e8f-89da-586ede265118","questionId":"49115bf9-85bc-5b79-ac74-36205d582d69","sourceKey":"bank:ECO101:ECO-0089","payload":{"prompt":"If the demand for and supply of a product are equally elastic, who bears the tax?","options":["buyer","seller","both","none of the above"],"correctOption":2,"section":"Partial Equilibrium Analysis","explanation":"When demand and supply are equally elastic, buyers and sellers are equally responsive to price, so the tax burden is shared between both of them. Options A and B describe cases where one side is much less responsive than the other and carries most of the tax. Option D is wrong because a tax is always borne by someone."}},{"itemId":"45c56ba0-3693-5c3f-aec7-37901e66f6b1","questionId":"0df12b37-32d2-5f5c-8548-bafcc6366b03","sourceKey":"bank:ECO101:ECO-0117","payload":{"prompt":"If the government establishes a minimum wage for labour above the equilibrium price","options":["a shortage of labour will appear on the market","an excess supply of labour will appear on the market","the law will have no effects","the law will help people making low wages"],"correctOption":1,"section":"Partial Equilibrium Analysis","explanation":"A minimum wage above equilibrium raises the wage, so more people want to work while firms want to hire fewer, leaving an excess supply of labour (unemployment). Option A has it backwards, because a shortage comes from a wage below equilibrium. Option C is wrong because a binding minimum wage does change the market."}},{"itemId":"9239f3a4-09c2-52a7-8e35-c5f110cadd23","questionId":"cf08ffea-a8d5-5117-af3e-10cec40a469c","sourceKey":"bank:ECO101:ECO-0119","payload":{"prompt":"A price ceiling imposed on apartment rents","options":["will always cause excess demand for rental units","will result in excess supply in the market for rental units","may give rise to black market transaction","will disrupt the market only of the ceiling is higher than the market equilibrium price"],"correctOption":2,"section":"Partial Equilibrium Analysis","explanation":"A rent ceiling set below the equilibrium rent creates a shortage of flats, and that shortage may give rise to black market deals and side payments. Option A says 'always', but a ceiling above equilibrium has no effect, so it is not always true. Option B is wrong because ceilings cause shortages, not surpluses, and option D has it backwards, since only a ceiling below equilibrium disrupts the market."}},{"itemId":"87380ff1-2ff6-5dc6-b6d8-ec092f16c553","questionId":"63660756-d8c0-5ec9-8378-9fa6c82c8a29","sourceKey":"bank:ECO101:ECO-0132","payload":{"prompt":"A price ceiling below the equilibrium price would result in","options":["excess supply","excess demand","a rise in the quantity supplied","all of the above"],"correctOption":1,"section":"Partial Equilibrium Analysis","explanation":"A price ceiling below equilibrium makes the good cheaper, so quantity demanded rises while quantity supplied falls, leaving excess demand (a shortage). Option C is wrong because a lower price makes producers offer less, not more. Option A, excess supply, is what a price floor above equilibrium causes, so option D cannot be right either."}},{"itemId":"39f839ca-7135-50c0-9411-afe8908e672d","questionId":"bc79e7ea-93cc-57af-956e-316aecae9ba2","sourceKey":"bank:ECO101:ECO-0140","payload":{"prompt":"One of the adverse effects of minimum wage legislation is that","options":["it will improve the standard of living of workers","it will improve the level of worker's productivity","it will lead to unemployment among young and unskilled workers","it will lead to wastage spending by workers as a result of higher income"],"correctOption":2,"section":"Partial Equilibrium Analysis","explanation":"A minimum wage above the market wage makes labour more expensive, so firms hire fewer workers, and young and unskilled workers are often the first to lose out. Options A and B are possible benefits, not adverse effects. Option D is not a standard argument against minimum wages."}},{"itemId":"2fa0e8b6-af17-57f1-80e3-b8f2deb87162","questionId":"0d3372d2-ed99-505a-bce7-ad0ada117baf","sourceKey":"bank:ECO101:ECO-0628","payload":{"prompt":"Minimum wage is an example of a price of labor .......... and results in a ..........","options":["floor; surplus","ceiling; surplus","floor; shortage","ceiling; shortage"],"correctOption":0,"section":"Partial Equilibrium Analysis","explanation":"A minimum wage is a price floor because it sets the lowest legal wage, and when it is above the equilibrium wage more people want to work than firms want to hire, creating a surplus of labour (unemployment). Option C has the right type of control but the wrong result, since shortages come from price ceilings set below equilibrium."}},{"itemId":"2fc8464c-ea0a-5cee-ac27-5d5a32c5c97b","questionId":"f99e5c17-8a16-5e06-a38e-8d83f7668747","sourceKey":"bank:ECO101:ECO-0660","payload":{"prompt":"Which economist is regarded as the master of partial equilibrium analysis?","options":["Alfred Marshall","A.C. Pigou","J.M. Keynes","J.S. Mill"],"correctOption":0,"section":"Partial Equilibrium Analysis","explanation":"Marshall developed partial equilibrium analysis, studying one market at a time while holding other things constant (ceteris paribus). Option C, Keynes, is known for aggregate macroeconomic analysis of the whole economy, not single-market analysis."}},{"itemId":"bda68bf4-07f9-5a88-b945-9ac7a317e52a","questionId":"fda945d3-21f6-578a-a3b9-a6d3c1378889","sourceKey":"bank:ECO101:ECO-0670","payload":{"prompt":"Which statement is most closely linked with general equilibrium analysis?","options":["Everything in the economy depends on everything else","The price of a factor is set by the demand and supply of that factor alone","The price of a good is set by the demand and supply of that good alone","None of these"],"correctOption":0,"section":"Partial Equilibrium Analysis","explanation":"General equilibrium analysis, linked with Leon Walras, recognises that all markets are connected, so a change in one market affects all the others. Options B and C look at one market in isolation, which is partial equilibrium analysis."}},{"itemId":"e32359f5-bb13-5372-a369-769c1f66070f","questionId":"e8aa4f9d-59c6-581f-9283-acff017f26a6","sourceKey":"bank:ECO101:E101N1-067","payload":{"prompt":"Partial equilibrium analysis examines","options":["only the international trade of a country","all markets in the economy and how they adjust together","a single market or industry while assuming all other markets remain unchanged","the economy's total output, inflation and unemployment"],"correctOption":2,"section":"Partial Equilibrium Analysis","explanation":"Partial equilibrium analysis looks at one market or industry and holds all other markets unchanged. Studying all markets and how they adjust together is general equilibrium analysis."}},{"itemId":"6c0c1caa-8c42-5036-9593-63dc6255fdff","questionId":"fa891946-d90f-5cd9-b515-f5e89bfe69d8","sourceKey":"bank:ECO101:E101N1-068","payload":{"prompt":"A UNILAG economics student wants to use partial equilibrium analysis for her project. Which topic suits that method?","options":["Studying the equilibrium of a single firm producing bread in Ikeja","Studying how a tax on all industries spreads through the economy","Studying the interconnection of every market in West Africa","Studying how all prices in Nigeria adjust together"],"correctOption":0,"section":"Partial Equilibrium Analysis","explanation":"Partial equilibrium covers the equilibrium of a single consumer, producer, firm or industry. A tax on all industries and the interconnection of every market are general equilibrium questions because they involve the whole economy."}},{"itemId":"7d4b53f0-9f95-5b34-8abf-1fd105bb7152","questionId":"019dae02-1ccd-57e4-a196-e5beccd05dce","sourceKey":"bank:ECO101:E101N1-069","payload":{"prompt":"When partial equilibrium analysis is used to study a policy, its effects are examined","options":["only in markets other than the one directly affected","only in the sector directly affected, with effects on other markets ignored","only through changes in inflation and exchange rates","in every sector of the economy at the same time"],"correctOption":1,"section":"Partial Equilibrium Analysis","explanation":"Partial equilibrium looks at a policy's effect only in the sector directly affected and ignores effects on other markets, which are assumed to be small. Tracing effects through every sector at once is what general equilibrium analysis does."}},{"itemId":"f626931a-ed21-5ede-852a-fc97a42a7a02","questionId":"3e88cb61-22a5-5f40-9c22-835b5457439d","sourceKey":"bank:ECO101:E101N1-070","payload":{"prompt":"Which economist first formalized the one-period general equilibrium of the whole economic system?","options":["Adam Smith","Leon Walras","Alfred Marshall","Antoine Augustin Cournot"],"correctOption":1,"section":"Partial Equilibrium Analysis","explanation":"Leon Walras first formalized a one-period general equilibrium of the whole economic system. Alfred Marshall is linked with partial equilibrium, the analysis of one market at a time, not with the general model."}},{"itemId":"945fae95-3acd-5114-ae0f-006758828137","questionId":"b5449d4e-4d78-52a8-85db-154750e514c4","sourceKey":"bank:ECO101:E101N1-071","payload":{"prompt":"Which pair of economists developed tractable partial equilibrium models?","options":["Adam Smith and David Ricardo","Leon Walras and Vilfredo Pareto","Jeremy Bentham and John Stuart Mill","Antoine Augustin Cournot and Alfred Marshall"],"correctOption":3,"section":"Partial Equilibrium Analysis","explanation":"Antoine Augustin Cournot of France and Alfred Marshall of England developed tractable partial models. Leon Walras is credited with formalizing general equilibrium of the whole economy, which is the opposite approach."}},{"itemId":"9f42fbe5-2add-50c3-8504-fd86fd25222f","questionId":"1adec027-d55d-5daa-abd2-1e6781003294","sourceKey":"bank:ECO101:E101N1-072","payload":{"prompt":"In partial equilibrium analysis of the market for tea, the prices of substitutes such as coffee and complements such as sugar are held constant. This reflects the assumption of","options":["price-taking behaviour","general equilibrium feedback","constant returns to scale","independence of markets"],"correctOption":3,"section":"Partial Equilibrium Analysis","explanation":"Independence of markets means the market studied is treated as separate, so prices of substitutes and complements are held constant. Price-taking behaviour is a different assumption, that buyers and sellers cannot influence the price."}},{"itemId":"4de3152d-ab01-5967-87e8-ef6d0dbc5dff","questionId":"1281c95f-dbb1-5e49-b7ba-ab8081d6e9fa","sourceKey":"bank:ECO101:E101N1-073","payload":{"prompt":"In partial equilibrium analysis, the assumption that buyers and sellers cannot influence the market price, as in a perfectly competitive market, is","options":["single market focus","independence of markets","ceteris paribus","price-taking behaviour"],"correctOption":3,"section":"Partial Equilibrium Analysis","explanation":"Price-taking behaviour means no buyer or seller can affect the price, as in perfect competition. Ceteris paribus is the separate assumption that factors like income, tastes and technology stay unchanged."}},{"itemId":"593bfd1d-1463-518f-8aaf-668d07ca925b","questionId":"f71ba67c-e08d-5c55-a97e-11bc78563069","sourceKey":"bank:ECO101:E101N1-074","payload":{"prompt":"A partial equilibrium analysis of the rice market keeps consumers' income, tastes, technology and input prices unchanged and adjusts one variable at a time. This is the assumption of","options":["no feedback effects","price-taking behaviour","ceteris paribus","independence of markets"],"correctOption":2,"section":"Partial Equilibrium Analysis","explanation":"Ceteris paribus holds income, tastes, technology and input prices constant so that one variable can be changed at a time. Independence of markets concerns holding the prices of substitutes and complements constant, not income or tastes."}},{"itemId":"1c735c30-ab71-596b-802b-4604bf4f716a","questionId":"b0e0ec52-408f-5780-a30b-992075ddab5b","sourceKey":"bank:ECO101:E101N1-075","payload":{"prompt":"An analyst assumes that a rise in the price of wheat does not affect wages or the markets for other crops. Which partial equilibrium assumption is this?","options":["Constant returns to scale","No general equilibrium feedback effects","Price-taking behaviour","Ceteris paribus on tastes"],"correctOption":1,"section":"Partial Equilibrium Analysis","explanation":"The assumption of no general equilibrium feedback effects rules out a wheat price change spilling over into wages or other crops. Price-taking behaviour is about buyers and sellers being unable to influence price, not about spillovers to other markets."}},{"itemId":"248017b8-9da5-52a1-aa38-df7fd39be499","questionId":"ecdfd926-2eee-5fe0-b44e-249ad2276b80","sourceKey":"bank:ECO101:E101N1-076","payload":{"prompt":"The single market focus assumption of partial equilibrium analysis means that the good studied","options":["is traded only in international markets","is produced by only one firm in the economy","has no interaction with macro variables such as inflation or exchange rates","is affected by every other price in the economy"],"correctOption":2,"section":"Partial Equilibrium Analysis","explanation":"Single market focus means the analysis covers one good or service and ignores interaction with macro variables such as inflation and exchange rates. Being produced by only one firm describes a monopoly, which is a market structure, not this assumption."}},{"itemId":"8fe5d04b-1626-5dbf-825e-7ed845774336","questionId":"5fd45551-2d3e-59d1-854e-5706359e53a1","sourceKey":"bank:ECO101:E101N1-077","payload":{"prompt":"A student is listing the assumptions behind partial equilibrium analysis. Which item should NOT be on the list?","options":["Ceteris paribus","Independence of markets","All markets are interconnected and adjust together","Price-taking behaviour"],"correctOption":2,"section":"Partial Equilibrium Analysis","explanation":"Treating all markets as interconnected is the defining assumption of general equilibrium analysis, not partial equilibrium. Ceteris paribus, price-taking behaviour and independence of markets are all assumptions of partial equilibrium."}},{"itemId":"7170f9ed-d4e4-5904-8820-9757483fed71","questionId":"efe1a86e-f92a-5248-a6b8-d315f5b3da87","sourceKey":"bank:ECO101:E101N1-078","payload":{"prompt":"Compared with general equilibrium analysis, partial equilibrium analysis is","options":["simpler, while general equilibrium is more complex with many equations","used only for the whole economy, never for one industry","concerned with all markets, while general equilibrium studies one","more complex, while general equilibrium needs only one equation"],"correctOption":0,"section":"Partial Equilibrium Analysis","explanation":"Partial equilibrium is simpler because it handles one market, while general equilibrium is more complex and involves many equations. Saying partial equilibrium covers all markets reverses the scope of the two approaches."}},{"itemId":"d37463b8-ce70-51f4-8ddf-2859adf0f9b0","questionId":"4fd62902-25d3-5b05-8f03-d8aeb0a6a7e1","sourceKey":"bank:ECO101:E101N1-079","payload":{"prompt":"The Federal Government introduces a tax on petrol only and wants to know its effect on the petrol market alone. The appropriate method is","options":["Walrasian analysis of all markets","general equilibrium analysis","balance of payments analysis","partial equilibrium analysis"],"correctOption":3,"section":"Partial Equilibrium Analysis","explanation":"A tax on a single product such as gasoline, studied within that one market, is the standard example of partial equilibrium analysis. General equilibrium would be needed for a tax on all industries, where the interaction between sectors matters."}},{"itemId":"ea1c2347-9c6b-5b86-aa98-2d4410d2bb2a","questionId":"1740dd47-0229-532e-b7da-f4be3d1a61d4","sourceKey":"bank:ECO101:E101N1-080","payload":{"prompt":"In the market for corn, Qd = 500 - 5P and Qs = 2P + 100. What is the equilibrium price?","options":["N80.00","N57.14","N50.00","N85.71"],"correctOption":1,"section":"Partial Equilibrium Analysis","explanation":"Setting Qd = Qs gives 500 - 5P = 2P + 100, so 400 = 7P and P = 57.14. The figure N85.71 comes from adding 100 to 500 instead of subtracting it (600 / 7), a common sign slip when moving terms across."}},{"itemId":"caf47069-3b1e-5363-bf0f-b5544d6495d6","questionId":"3e0c5426-1cdc-550a-96af-d81a30ea465d","sourceKey":"bank:ECO101:E101N1-081","payload":{"prompt":"Given demand Qd = 500 - 5P and supply Qs = 2P + 100 for corn, how many units are traded at equilibrium, to one decimal place?","options":["285.7 units","400.0 units","100.0 units","214.3 units"],"correctOption":3,"section":"Partial Equilibrium Analysis","explanation":"Equilibrium price is P = 400 / 7 = 57.14, so Q = 500 - 5(57.14) = 214.3 units, and supply gives the same 2(57.14) + 100 = 214.3. The figure 285.7 is 5 x 57.14, the amount subtracted, rather than the quantity demanded."}},{"itemId":"0dfed642-616b-544d-bad5-e100270da713","questionId":"b3c45864-6be5-5b25-91da-6561c12980fe","sourceKey":"bank:ECO101:E101N1-082","payload":{"prompt":"In the corn market, Qd = 500 - 5P and Qs = 2P + 100. The government imposes a tax of N10 per unit on producers, so supply becomes Qs = 2(P - 10) + 100. What is the new equilibrium price?","options":["N54.29","N67.14","N60.00","N57.14"],"correctOption":2,"section":"Partial Equilibrium Analysis","explanation":"With the tax, 500 - 5P = 2P + 80, so 420 = 7P and P = 60, up from 57.14. N67.14 assumes the whole N10 is passed on to buyers, but here consumers pay only about N2.86 more because producers absorb the rest."}},{"itemId":"c95230a8-0ec1-5cde-a07c-4d0c7d9e9eb7","questionId":"9cfa1493-9b25-5858-9f90-a04b4c555730","sourceKey":"bank:ECO101:E101N1-083","payload":{"prompt":"In the corn market, Qd = 500 - 5P and Qs = 2P + 100. After a tax of N10 per unit on producers, the new equilibrium price is N60. What is the new equilibrium quantity?","options":["200 units","250 units","228.6 units","214.3 units"],"correctOption":0,"section":"Partial Equilibrium Analysis","explanation":"At P = 60, Qd = 500 - 5(60) = 200 units, down from 214.3, showing that taxes raise prices and reduce output. The figure 228.6 is the quantity after a subsidy, which increases output rather than reducing it."}},{"itemId":"72dabc0e-f0d7-561f-bbcc-85cd0d43d7ff","questionId":"0302d605-eb5f-5b7a-915f-9f5a88581112","sourceKey":"bank:ECO101:E101N1-084","payload":{"prompt":"In the corn market, Qd = 500 - 5P and Qs = 2P + 100. The government sets a price ceiling of N50. What happens?","options":["No effect, because the ceiling is not binding","A shortage of 50 units","A shortage of 250 units","A surplus of 50 units"],"correctOption":1,"section":"Partial Equilibrium Analysis","explanation":"At N50, Qd = 500 - 5(50) = 250 and Qs = 2(50) + 100 = 200, so demand exceeds supply by 50 units, a shortage. The ceiling does bind because N50 is below the equilibrium price of N57.14."}},{"itemId":"7e47edd0-a99c-5adc-ae4c-b837e12e253a","questionId":"431d2968-501c-5cfd-a845-a6a9e013a11b","sourceKey":"bank:ECO101:E101N1-085","payload":{"prompt":"Corn producers receive a government subsidy of N10 per unit. Before the subsidy, Qd = 500 - 5P and Qs = 2P + 100; with it, Qs = 2(P + 10) + 100. To two decimal places, the market price becomes","options":["N47.14","N54.29","N60.00","N57.14"],"correctOption":1,"section":"Partial Equilibrium Analysis","explanation":"With the subsidy, 500 - 5P = 2P + 120, so 380 = 7P and P = 54.29, down from 57.14. N60.00 is the price after a N10 tax, which shifts supply left and raises price, the opposite of a subsidy."}},{"itemId":"19dd8ab0-5a75-5d1c-999d-58627506c1a4","questionId":"20867fa0-417b-50e8-abc7-327c5c65615d","sourceKey":"bank:ECO101:E101N1-086","payload":{"prompt":"In the wheat market, Qd = 500 - 50P and Qs = 200 + 30P, where P is in naira per kg. What is the equilibrium price?","options":["N3.75 per kg","N15.00 per kg","N6.00 per kg","N8.75 per kg"],"correctOption":0,"section":"Partial Equilibrium Analysis","explanation":"Setting 500 - 50P = 200 + 30P gives 300 = 80P, so P = 3.75 and Q = 312.5 kg. N8.75 comes from adding 200 to 500 instead of subtracting it (700 / 80), a common sign slip."}},{"itemId":"d3a401af-39f8-5d2d-9662-19425c1d4976","questionId":"7007926e-1fba-5ae2-8113-d263deaa7f5e","sourceKey":"bank:ECO101:E101N1-087","payload":{"prompt":"In the wheat market, Qd = 500 - 50P and Qs = 200 + 30P, with equilibrium price N3.75 per kg. To support farmers, the government sets a price floor of N6 per kg. What is the result?","options":["No effect, because the floor is below equilibrium","A surplus of 67.5 kg","A surplus of 180 kg","A shortage of 180 kg"],"correctOption":2,"section":"Partial Equilibrium Analysis","explanation":"At N6, Qd = 500 - 50(6) = 200 kg and Qs = 200 + 30(6) = 380 kg, so supply exceeds demand by 180 kg, a surplus. A floor causes a surplus, not a shortage, because it holds price above equilibrium where sellers offer more than buyers want."}},{"itemId":"5805149c-db9a-52d8-be15-4f2412579cea","questionId":"25dfbf13-c8ce-5806-878c-12ada389aaa7","sourceKey":"bank:ECO101:E101N1-088","payload":{"prompt":"In the garri market in Lagos, Qd = 1200 - 20P and Qs = 30P - 300, where P is in naira per cup. What are the equilibrium price and quantity?","options":["P = N60, Q = 0 cups","P = N18, Q = 840 cups","P = N30, Q = 900 cups","P = N30, Q = 600 cups"],"correctOption":3,"section":"Partial Equilibrium Analysis","explanation":"Setting 1200 - 20P = 30P - 300 gives 1500 = 50P, so P = 30 and Q = 1200 - 20(30) = 600 cups. P = N18 comes from wrongly subtracting 300 from 1200 instead of adding it when moving terms across."}},{"itemId":"1338aa3b-60ec-5464-90e6-1f6c30635b1c","questionId":"218bf787-bfa9-582e-bbe9-f0773ac610e9","sourceKey":"bank:ECO101:E101N1-089","payload":{"prompt":"In the garri market, Qd = 1200 - 20P and Qs = 30P - 300, with equilibrium at P = N30. The government imposes a tax of N5 per cup on sellers, so supply becomes Qs = 30(P - 5) - 300. What is the new price paid by buyers?","options":["N33","N30","N35","N27"],"correctOption":0,"section":"Partial Equilibrium Analysis","explanation":"With the tax, 1200 - 20P = 30P - 450, so 1650 = 50P and P = 33. N35 assumes the full N5 is passed on to buyers, but buyers pay only N3 more and sellers absorb the other N2."}},{"itemId":"b8e24207-9ae9-5c55-9e71-1eccaddb2d97","questionId":"74f62819-0578-55c0-a0be-b2bef8b1decb","sourceKey":"bank:ECO101:E101N1-090","payload":{"prompt":"In a partial equilibrium diagram, a per-unit subsidy to producers","options":["shifts supply right, lowering price and raising output","leaves supply unchanged and creates a shortage","shifts supply left, raising price and reducing output","shifts demand left, lowering both price and output"],"correctOption":0,"section":"Partial Equilibrium Analysis","explanation":"A subsidy lowers producers' costs, shifting supply to the right so that price falls and quantity rises. Shifting supply left with a higher price and lower output is the effect of a tax, the opposite policy."}},{"itemId":"0704958f-5526-5e7c-9cc1-402910f0a2e5","questionId":"63ed7278-9079-574b-b191-9d1cadc32b95","sourceKey":"bank:ECO101:E101N1-091","payload":{"prompt":"One weakness of analysing a single market in isolation is that the method","options":["requires many simultaneous equations to solve","cannot be applied to a single industry","cannot explain how disturbances spread from one market to another","ignores the market being studied"],"correctOption":2,"section":"Partial Equilibrium Analysis","explanation":"Because it isolates one market, partial equilibrium cannot show how a disturbance spreads to other markets through second- and third-order effects. Needing many simultaneous equations is a feature of general equilibrium, which is the more complex approach."}},{"itemId":"1e6813d2-19d3-5244-b518-9b92e5a13724","questionId":"01bfa410-b5d0-50f1-8fe7-46c14117e411","sourceKey":"bank:ECO101:E101N1-092","payload":{"prompt":"Which of the following is NOT a limitation of partial equilibrium analysis?","options":["It cannot study the interrelations of all parts of the economy","It is simpler to use than general equilibrium analysis","It relies on the improbable assumption of disconnecting one market","It is restricted to one part of the economy"],"correctOption":1,"section":"Partial Equilibrium Analysis","explanation":"Being simpler than general equilibrium is an advantage of partial equilibrium, not a limitation. Its limitations are that it is restricted to one part of the economy, cannot study interrelations of all parts and rests on the improbable assumption that one market can be disconnected."}},{"itemId":"6396f8e3-5322-50bf-947f-394d2361ef67","questionId":"f64a9365-07f0-5791-a19a-99f2359f7bd7","sourceKey":"bank:ECO101:E101N1-093","payload":{"prompt":"Fuel subsidies in Nigeria, minimum wage laws and import tariffs are all real-world examples of","options":["policies that can be studied with partial equilibrium analysis","institutions studied only with general equilibrium analysis","examples of Pareto-efficient allocations","theories of institutional change"],"correctOption":0,"section":"Partial Equilibrium Analysis","explanation":"Fuel subsidies in Nigeria, minimum wage laws as wage floors, and import tariffs affecting domestic production are standard real-world applications of partial equilibrium analysis. They are policy actions in particular markets, not Pareto-efficient allocations."}},{"itemId":"a208b744-e387-500e-9a77-f9b24407fc7d","questionId":"b280297d-6a83-58b5-b620-f7a88356217a","sourceKey":"bank:ECO101:ECO-0052","payload":{"prompt":"A producer sustains a loss in the short run if","options":["Marginal revenue is less than price","Price is less than average cost","Average variable cost is less than average cost","Marginal cost is less than marginal revenue"],"correctOption":1,"section":"Market Structures","explanation":"A firm makes a loss when the price it gets per unit is below its average cost, because total revenue (P x Q) is then less than total cost (AC x Q). Option D tells you the firm could raise profit by producing more, not that it is making a loss. Option C is always true because AC includes AFC, so it says nothing about losses."}},{"itemId":"971f3874-2070-54e8-9297-45c985e34bb5","questionId":"8c5dcd8d-2625-5a10-aed8-f8c9dc7bf724","sourceKey":"bank:ECO101:ECO-0054","payload":{"prompt":"In the short run, the monopolistic competitor","options":["always makes profit","Always incurs a loss","Always break even","May close down"],"correctOption":3,"section":"Market Structures","explanation":"In the short run a monopolistic competitor can make a profit, break even or make a loss, and if price falls below average variable cost it may close down. Option D is the only statement that is not ruled out by the word 'always'. Option C, always breaking even, describes the long-run outcome once new firms enter, not the short run."}},{"itemId":"ebdeb9c9-fb50-583f-87cb-77f79f7d718d","questionId":"de068630-b812-521a-9f10-ce5160acd2df","sourceKey":"bank:ECO101:ECO-0055","payload":{"prompt":"If a perfectly competitive firm in long-run equilibrium were to lower its price","options":["It would receive a larger share of the market","Other firms would lower other prices also","It would operate at a loss","It would drive all other firms our of business"],"correctOption":2,"section":"Market Structures","explanation":"A perfectly competitive firm in long-run equilibrium charges a price equal to its minimum average cost, so cutting its price would push it below cost and it would make a loss. Option A is wrong because the firm can already sell all it wants at the market price, so a lower price wins it nothing. Options B and D are wrong because one tiny firm cannot influence the market."}},{"itemId":"769c3657-e1be-505a-a6ac-cfa1876af01f","questionId":"8c886d57-6c6f-5569-98e5-6e684f998617","sourceKey":"bank:ECO101:ECO-0057","payload":{"prompt":"Other things remain equal, a change in technology which increases efficiency in a perfectly competitive industry will:","options":["Lower price","Increase price","Leave price unchanged","Produce price uncertainty"],"correctOption":0,"section":"Market Structures","explanation":"Better technology lowers firms' costs, so the industry supply curve shifts to the right and, with demand unchanged, the market price falls. Option C ignores the supply shift. Option B gets the direction wrong, and option D is wrong because the effect on price is clear."}},{"itemId":"dfa61f27-023a-5754-9541-210a7bb31d3a","questionId":"d0621f9d-cc7b-5c34-8358-ca1c3fe931b7","sourceKey":"bank:ECO101:ECO-0059","payload":{"prompt":"In the long run, if marginal cost is equal to marginal revenue, and selling price is below average total cost, the firm will","options":["Leave the industry","Maximize profits","Incur losses, but continues to operate","Increase output"],"correctOption":0,"section":"Market Structures","explanation":"In the long run a firm that cannot cover its average total cost even at its best output (where MC = MR) is making a lasting loss, so it will leave the industry. Option C describes a short-run decision, where a firm may keep operating as long as it covers its variable cost. Option B is wrong because the firm is making a loss, not a profit."}},{"itemId":"61250d6c-9b74-5a83-8c85-ff2428ed19cc","questionId":"467a394d-ad15-50fb-b9f9-c749028c9ab0","sourceKey":"bank:ECO101:ECO-0060","payload":{"prompt":"A monopolistic firm will expand its output when:","options":["Marginal revenue exceeds marginal cost","Marginal cost exceeds marginal revenue","Marginal cost equals marginal revenue","Marginal revenue is negative"],"correctOption":0,"section":"Market Structures","explanation":"If marginal revenue exceeds marginal cost, each extra unit adds more to revenue than to cost, so the firm raises profit by producing more. Option B is the signal to cut output, and option C is the profit-maximising point where the firm stops expanding. Option D would mean extra units reduce revenue."}},{"itemId":"ea55a711-d059-511d-ba49-6061b5973e4a","questionId":"f0388114-1bc9-506a-b86e-3dcbc52b5224","sourceKey":"bank:ECO101:ECO-0061","payload":{"prompt":"Which of these can you accept as correct?","options":["Monopoly occurs when there is one, and only one, seller in a market","Monopoly occurs when other sellers fail to challenge a seller","Monopoly is what fuel distributors practice to create artificial scarcity","None of the above"],"correctOption":0,"section":"Market Structures","explanation":"A monopoly is a market with one and only one seller of a product that has no close substitutes. Option B is wrong because a firm being unchallenged by rivals does not make it the only seller. Option C describes one kind of market behaviour (hoarding), not the definition of monopoly."}},{"itemId":"101bf806-68a1-5dce-98d5-7471021420e0","questionId":"dbfe868c-0627-550a-9c5c-eef6e577efb3","sourceKey":"bank:ECO101:ECO-0062","payload":{"prompt":"The producer in a perfectly competitive market is faced with a demand curve that is","options":["Perfectly elastic","Perfectly inelastic","Unitarily elastic","Infinitely inelastic"],"correctOption":0,"section":"Market Structures","explanation":"A perfectly competitive firm is a price taker that can sell any quantity at the market price, so its demand curve is a horizontal line, which means it is perfectly elastic. Options B and D describe a vertical demand curve, and option C describes a curve of unit elasticity."}},{"itemId":"d4ae04e8-8af6-5ac5-8b9e-92d60773ae1e","questionId":"0908f35c-60e7-5578-8b05-f1ce8dd5aead","sourceKey":"bank:ECO101:ECO-0063","payload":{"prompt":"In perfect competition, every firm is","options":["A price taker","A price seller","A price giver","A price Bidder"],"correctOption":0,"section":"Market Structures","explanation":"Each firm in perfect competition is too small to affect the market price, so it simply accepts the price set by market demand and supply; it is a price taker. Options B, C and D suggest the firm can set or bargain over price, which only firms with market power can do."}},{"itemId":"73d7c27f-a94b-5e92-b587-c0d184aa471e","questionId":"8b177fef-5d84-5ca4-809c-10d268000c32","sourceKey":"bank:ECO101:ECO-0071","payload":{"prompt":"The Nigerian communication industry is an example of...","options":["monopolistically competitive market","oligopoly","perfect competition","duopoly"],"correctOption":1,"section":"Market Structures","explanation":"The Nigerian telecommunication market is dominated by a few large network operators, which makes it an oligopoly: few sellers, big market shares and firms that watch each other's moves. Option C is wrong because perfect competition needs many small firms selling identical products. Option D, duopoly, means only two firms, and option A needs many small sellers."}},{"itemId":"eea6e62e-f737-53b0-8bfe-cea17b385208","questionId":"8534a26f-c44e-54f6-9666-2464b03bc5ea","sourceKey":"bank:ECO101:ECO-0077","payload":{"prompt":"In the labour market, many sellers and a single buyer is termed","options":["monopsony","monopoly","duopoly","bilateral monopoly"],"correctOption":0,"section":"Market Structures","explanation":"Monopsony is a market with a single buyer, so in the labour market it means one employer facing many workers. Option B, monopoly, is a single seller. Option D, bilateral monopoly, is a single buyer facing a single seller."}},{"itemId":"2133738e-3a81-533e-b169-a83d681b609e","questionId":"6cd908c4-b021-5804-8141-d08de1ac72d6","sourceKey":"bank:ECO101:ECO-0078","payload":{"prompt":"Single seller and single buyer in the labour market is called.....","options":["Multi lateral monopoly","bilateral monopoly","monopsony","pure monopoly"],"correctOption":1,"section":"Market Structures","explanation":"Bilateral monopoly is a market with a single seller facing a single buyer, such as one trade union bargaining with one employer. Option C, monopsony, has only a single buyer with many sellers. Option D, pure monopoly, has a single seller with many buyers."}},{"itemId":"0c099f9f-df4c-5b6b-b1cf-3d741cd4fbd2","questionId":"04f9e315-b464-5ff0-9f76-ef1a21f16fc1","sourceKey":"bank:ECO101:ECO-0147","payload":{"prompt":"The necessary condition for profit maximization MC = MR is true only in","options":["perfect competitive market","monopoly market","in all types of market","duopoly market"],"correctOption":2,"section":"Market Structures","explanation":"MC = MR is the profit-maximising rule for every firm, whatever the market structure: if MR is above MC, producing more adds to profit, and if MC is above MR, producing less does. Options A, B and D each name only one market structure, but the rule is not limited to any one of them."}},{"itemId":"4d10b1f7-bbee-5eb2-98f0-15566b40a85f","questionId":"8e41665b-4e2f-5fb2-968a-e36d0d3da4b8","sourceKey":"bank:ECO101:ECO-0148","payload":{"prompt":"For monopoly to practice price discrimination, the elasticity of demand in both segmented markets must","options":["be the same","be different","be elastic in both market","be inelastic in both market"],"correctOption":1,"section":"Market Structures","explanation":"Price discrimination only pays when the separated markets have different price elasticities of demand, so the monopolist can charge a higher price where demand is less elastic and a lower price where it is more elastic. If the elasticities were the same (option A), the best price would be the same in both markets. Options C and D miss the point, because what matters is that the elasticities differ, not whether both markets are elastic or both inelastic."}},{"itemId":"908e8f29-7f72-5792-b331-9daeed0b9229","questionId":"07ba9f9f-ae29-516e-8d36-9570d37e132d","sourceKey":"bank:ECO101:ECO-0158","payload":{"prompt":"The demand curve facing a firm in a perfectly competitive market is","options":["downward sloping from left to right","upward sloping from left to right","perfectly elastic","perfectly inelastic"],"correctOption":2,"section":"Market Structures","explanation":"A single firm in perfect competition is so small that it can sell any amount at the market price, so the demand curve it faces is horizontal, or perfectly elastic. Option A describes the market (industry) demand curve, not the individual firm's. Option D, perfectly inelastic, would mean quantity never responds to price."}},{"itemId":"822bf95f-e0cb-5d27-b2a3-0cbb9933ebfc","questionId":"2788c418-18aa-5848-99be-092733d84db5","sourceKey":"bank:ECO101:ECO-0159","payload":{"prompt":"A firm under perfect competitive market structure can sell an infinite amount of the commodity at prevailing market price and none at all at a price above the prevailing market price","options":["true","false","uncertain","none of the above"],"correctOption":0,"section":"Market Structures","explanation":"A perfectly competitive firm is a price taker: it can sell as much as it wants at the going market price, but if it raises its price even slightly, buyers switch to identical products from other sellers and it sells nothing. This is why its demand curve is perfectly elastic, so the statement is true and option B is wrong."}},{"itemId":"ab6df730-7761-536c-b575-0fdc8f1fe968","questionId":"b9ca5508-621a-56a4-9f29-3a56b5ca354b","sourceKey":"bank:ECO101:ECO-0160","payload":{"prompt":"When the slope of total revenue is less than that of total cost, a firm under perfect competitive market","options":["should increase output in order to increase revenue","should not increase output as additional output will add more to cost than to revenue","should reduce revenue by cutting price","should increase labour and capital irrespective of their marginal contribution of output"],"correctOption":1,"section":"Market Structures","explanation":"The slope of total revenue is marginal revenue and the slope of total cost is marginal cost, so this situation means MR < MC. Each extra unit then adds more to cost than to revenue, so the firm should not expand output. Option A is the right move only when MR > MC, and option D ignores marginal contribution altogether."}},{"itemId":"0a19de31-7374-550e-9477-df956a3633b8","questionId":"06b5cbc1-87e5-50db-b525-6c62dc694979","sourceKey":"bank:ECO101:ECO-0162","payload":{"prompt":"Under perfect competitive market, firms can make ________ in the short run but not in the long run","options":["normal profit","normal loss","abnormal profit","quasi-super profit"],"correctOption":2,"section":"Market Structures","explanation":"In the short run the number of firms is fixed, so if price is above average cost a perfectly competitive firm can earn abnormal (supernormal) profit. In the long run new firms enter and compete this extra profit away. Option A, normal profit, is wrong here because it is exactly what firms earn in the long run, and options B and D are not standard terms."}},{"itemId":"84a3d87d-7bd4-5bc3-a2bb-ac2389d1cf8e","questionId":"701e147f-6a43-5f3b-9680-c3932645b60e","sourceKey":"bank:ECO101:ECO-0163","payload":{"prompt":"Monopolists make ________ in long run","options":["abnormal profit","normal profit","discriminating profit","loss"],"correctOption":0,"section":"Market Structures","explanation":"A monopolist is protected by barriers to entry, so new firms cannot come in to compete away its profits, and it can keep earning abnormal profit in the long run. Option B, normal profit, is the long-run result in perfect competition, where free entry removes excess profit."}},{"itemId":"730deb0f-8b37-5cfb-9578-ffd0177621cf","questionId":"de81d104-af84-55c9-b69d-568cfbe6dc6f","sourceKey":"bank:ECO101:ECO-0170","payload":{"prompt":"Product differentiation is a feature of","options":["perfectly competitive market","monopoly","monopolistic competition","duopoly"],"correctOption":2,"section":"Market Structures","explanation":"Monopolistic competition has many sellers offering similar but slightly different products, through brands, packaging or quality, which is product differentiation. Option A is wrong because firms in perfect competition sell identical products, and option B is wrong because a monopolist is the only seller with no close substitutes."}},{"itemId":"100cc69c-b8f7-58f9-8cbb-5063ee8f2696","questionId":"90feae28-c51a-57b3-9529-0225f18902eb","sourceKey":"bank:ECO101:ECO-0177","payload":{"prompt":"Monopolist can influence price and quantity of the product simultaneously","options":["True","False","uncertain","none of the above"],"correctOption":1,"section":"Market Structures","explanation":"A monopolist faces a downward-sloping demand curve, so it can choose the price or the quantity it sells, but not both independently. Once it sets the price, demand decides how much is bought, and once it sets output, demand decides the price. That makes the statement false, and option A overstates the monopolist's power."}},{"itemId":"fd2dbecf-47f8-5f59-925e-d160a97b5b5c","questionId":"80af79fc-5d59-519c-a523-dffa82625716","sourceKey":"bank:ECO101:ECO-0273","payload":{"prompt":"Under perfect competition, the long-run equilibrium requires","options":["MR = MC","MR = MC and AR > AC","MR > MC","MR = MC = AR = AC"],"correctOption":3,"section":"Market Structures","explanation":"In long-run equilibrium under perfect competition, firms produce where MR = MC to maximise profit, and free entry pushes price (AR = MR) down to average cost, so MR = MC = AR = AC and only normal profit is earned. Option B, with AR above AC, describes supernormal profit, which can exist in the short run but is competed away in the long run. Option A holds in the short run too, so it is not the full long-run condition."}},{"itemId":"563171a8-27f2-58aa-9816-d2e9adf3bc0e","questionId":"637c9ce3-631c-5601-9f57-7f5f16bda6c8","sourceKey":"bank:ECO101:ECO-0274","payload":{"prompt":"The shut-down point for a firm in the short-run is the output at which","options":["The price of the production is lowest","Marginal cost is constant","Price just equals minimum average variable cost","Average cost is minimum"],"correctOption":2,"section":"Market Structures","explanation":"A firm shuts down in the short run at the output where price just equals minimum average variable cost; any lower and it loses more by producing than by closing, since it cannot even cover its variable costs. Option D, minimum average cost, is the break-even point, not the shut-down point, and option B has nothing to do with the decision."}},{"itemId":"77ecf6a4-04ef-5c0e-b01d-625e17faf5b7","questionId":"5b68b910-39cf-56b6-8f0f-eaaa5cf1208e","sourceKey":"bank:ECO101:ECO-0286","payload":{"prompt":"In perfect competition firms are","options":["price fixers","Price takers","Price takers and fixers","none of the above"],"correctOption":1,"section":"Market Structures","explanation":"In perfect competition each firm is too small to affect the market price, so it simply accepts the price set by demand and supply, making it a price taker. Option A describes a monopolist, which can set its price, and option C is contradictory."}},{"itemId":"098cc959-67ac-5378-b4cb-dfc32bf86248","questionId":"e56b51f5-5231-5e25-bdc3-db4a01f50394","sourceKey":"bank:ECO101:ECO-0287","payload":{"prompt":"A pure monopoly is an extreme case where the downward-sloping demand curve of the firm is the:","options":["Kinked demand curve of an oligopolist","Monopolistically competitive industry demand curve","Agents demand curve","Industry demand curve"],"correctOption":3,"section":"Market Structures","explanation":"In a pure monopoly there is only one firm in the industry, so the firm's downward-sloping demand curve is the whole industry demand curve. Option A, the kinked demand curve, belongs to oligopoly, where a few interdependent firms share the market. Option B refers to a different market structure with many firms."}},{"itemId":"5774f4d9-a52a-5f82-b830-dc795510460d","questionId":"ed922095-aa5f-58d8-bf09-9cf146525b37","sourceKey":"bank:ECO101:ECO-0444","payload":{"prompt":"It is a feature of the monopolistic competition that, in the long-run, there will be:","options":["Excess profit","Full output","Maximum utilisation","Excess capacity"],"correctOption":3,"section":"Market Structures","explanation":"In the long run, free entry under monopolistic competition removes supernormal profit, and each firm ends up producing on the falling part of its average cost curve, short of the output with minimum cost. That unused potential is called excess capacity. Option A is wrong because long-run profit is only normal, and options B and C describe the opposite of what happens."}},{"itemId":"ebc4e946-3348-5fce-82f1-fa52317abe60","questionId":"ed2805f0-35a4-5107-9b4b-bd04eac44359","sourceKey":"bank:ECO101:ECO-0447","payload":{"prompt":"What is meant by the phrase \"the monopolist is subject to the authority of the consumer\"?","options":["The monopolist can decide price or output, but not both","Consumers are always right","The monopolist has the overall say","The monopolist can decide both price and output"],"correctOption":0,"section":"Market Structures","explanation":"A monopolist faces the market demand curve, which reflects what consumers are willing to buy. It can fix the price and let consumers decide how much to buy, or fix the quantity and let demand decide the price, but it cannot set both at once. Options C and D overstate the monopolist's power, since consumer demand still limits it."}},{"itemId":"c3815aa5-0f5d-5111-8cff-2702f3de98e0","questionId":"6b5f87d4-eeea-54a6-a60f-b1bda8968bd3","sourceKey":"bank:ECO101:ECO-0449","payload":{"prompt":"A monopolist will never produce on the:","options":["Elastic part of the supply curve","Inelastic part of the supply curve","Elastic part of the demand curve","Inelastic part of the demand curve"],"correctOption":3,"section":"Market Structures","explanation":"A profit-maximising monopolist produces where MR = MC, and since MC is positive, MR must be positive too. MR is positive only on the elastic part of the demand curve, so the monopolist never produces on the inelastic part, where MR is negative. Option C is where it actually produces, and options A and B wrongly refer to a supply curve, which a monopolist does not have."}},{"itemId":"7656eb83-eead-52c9-9525-3076a49e5887","questionId":"c23f48cc-0756-5a10-a814-92bd2f06e495","sourceKey":"bank:ECO101:ECO-0450","payload":{"prompt":"A discriminating monopolist charges:","options":["Same prices to different customers","Different prices for products of different quality","Same customer","Different prices to different customers"],"correctOption":3,"section":"Market Structures","explanation":"Price discrimination means selling the same product to different customers or groups of customers at different prices, for reasons not linked to differences in cost. Option B is wrong because charging more for a better-quality product is not discrimination, since the products are not the same. Option A describes ordinary single pricing, the opposite of discrimination."}},{"itemId":"6f0caf45-5eef-5382-b3e2-b81307b316e3","questionId":"693f0bc1-421f-5867-b3da-76e5c6d1ccfd","sourceKey":"bank:ECO101:ECO-0452","payload":{"prompt":"A monopolist is:","options":["Both buyer and seller in industry","The only seller in an industry","One of the buyers in an industry","The only buyer or potential buyer of the goods in an industry"],"correctOption":1,"section":"Market Structures","explanation":"A monopolist is the single seller of a product with no close substitutes, so the firm is the whole industry. Option D describes a monopsonist, the only buyer in a market. Option A mixes up the two sides of the market."}},{"itemId":"9ebb398a-4579-5916-9c3c-db040539f48f","questionId":"52b00258-9b59-58ea-a3eb-50f3e8a55f56","sourceKey":"bank:ECO101:ECO-0453","payload":{"prompt":"The marginal revenue (MR) of a monopoly or oligopoly is:","options":["Positively sloped","Downward sloping","Constant","Upward sloped"],"correctOption":1,"section":"Market Structures","explanation":"A monopolist or oligopolist faces a downward-sloping demand curve, so to sell an extra unit it must lower the price on all units. As a result marginal revenue also slopes downward and lies below the demand (AR) curve. Option C, constant MR, applies to a perfectly competitive firm, and options A and D are wrong because MR falls as output rises."}},{"itemId":"3e0c0919-625e-5581-9820-cd246040beba","questionId":"14fe6d31-bfad-50af-9bee-d2a0c9982f08","sourceKey":"bank:ECO101:ECO-0454","payload":{"prompt":"A monopoly is said to misallocate resources:","options":["Because it faces a downward sloping demand curve","Because the market price under monopoly is greater than the marginal cost of additional output","Because without competition, there is no pressure on the firm to be efficient","Because under certain circumstances different consumers are charged different prices for the same product or service."],"correctOption":1,"section":"Market Structures","explanation":"Resources are allocated efficiently when price equals marginal cost, meaning the value consumers place on the last unit equals the cost of producing it. A monopolist restricts output and charges a price above marginal cost, so too few resources go into making the good. Option C describes a lack of pressure to keep costs down, which is technical (X-) inefficiency rather than misallocation, and option A is only the reason the monopolist is able to set price above MC."}},{"itemId":"96cdae9f-7acf-5d77-af7f-b93d6b7cd9d1","questionId":"7c979a3d-e74b-5081-a714-71fd93ccaad9","sourceKey":"bank:ECO101:ECO-0455","payload":{"prompt":"Which of the following is a unique characteristic of oligopoly?","options":["The use of advertising and product development","Production of a standardised product","The existence of barriers to entry, including patents and copyrights","Mutual interdependence among firms in the industry"],"correctOption":3,"section":"Market Structures","explanation":"Oligopoly is the only structure with so few firms that each must consider how rivals will react to its decisions, which is called mutual interdependence. Option A, advertising, is also common under monopolistic competition, and option C, barriers to entry, also applies to monopoly. Option B, a standardised product, is typical of perfect competition."}},{"itemId":"76b1711b-0641-533f-b9fc-1dc37dea3600","questionId":"38eb0c4b-5fc6-5783-a2a1-01ee04723d24","sourceKey":"bank:ECO101:ECO-0456","payload":{"prompt":"What are the chief types of market situation?","options":["Perfect competition, monopoly, monopolistic competition and oligopoly","Perfect competition and monopoly","Monopolistic competition and oligopoly","Monopolistic competition and perfect competition"],"correctOption":0,"section":"Market Structures","explanation":"Markets are usually grouped into four main types: perfect competition, monopoly, monopolistic competition and oligopoly, running from many firms down to one. Options B, C and D each list only part of this classification and leave out important structures."}},{"itemId":"694b7139-1b85-545b-ac67-36432c65495c","questionId":"d8019b8f-0911-576d-9166-e82ff060c942","sourceKey":"bank:ECO101:ECO-0459","payload":{"prompt":"The structure of a market is:","options":["The behaviour of buyers and sellers in that market","The behaviour of buyers and sellers","The composition of buyers and sellers","The behaviour of sellers in the market"],"correctOption":2,"section":"Market Structures","explanation":"Market structure refers to the make-up of a market, especially the number and size of its buyers and sellers, because this decides how much market power each one has. Options A and B describe behaviour, which is market conduct, something shaped by structure rather than the structure itself. Option D is narrower still, covering only sellers' behaviour."}},{"itemId":"3ebe95a2-71dd-55e2-9c57-19fa2e794d56","questionId":"c519304f-c7cd-55c8-bea1-e10b9175311e","sourceKey":"bank:ECO101:ECO-0477","payload":{"prompt":"A perfectly competitive firm attains maximum profit where:","options":["MR = AC","MC = MU = AC","MC = MR = P","AVC = MR"],"correctOption":2,"section":"Market Structures","explanation":"A perfectly competitive firm is a price taker, so its marginal revenue equals the market price. It maximises profit where marginal cost equals marginal revenue, giving MC = MR = P. Option A, MR = AC, is not the profit-maximising rule, and option D compares MR with average variable cost, which matters for the shutdown decision rather than for maximum profit."}},{"itemId":"2b9d7932-eb02-5848-8e62-a8fe6b63aad3","questionId":"3d110b7e-f305-5637-bcb3-8f608b1fc608","sourceKey":"bank:ECO101:ECO-0494","payload":{"prompt":"A perfectly competitive firm faces:","options":["a perfectly elastic, horizontal supply curve","a perfectly inelastic supply curve","a perfectly inelastic demand curve","a perfectly elastic demand curve"],"correctOption":3,"section":"Market Structures","explanation":"A perfectly competitive firm is a price taker: it can sell any quantity at the market price, so the demand curve it faces is horizontal, or perfectly elastic. Option A is tempting because the curve is horizontal, but it is the demand curve facing the firm, not a supply curve. Option C is wrong because a perfectly inelastic curve would be vertical."}},{"itemId":"2726360e-ce74-515d-95bf-cb0d16a3de3c","questionId":"e04a8ea5-9f63-54ad-8bcb-224624476cd2","sourceKey":"bank:ECO101:ECO-0495","payload":{"prompt":"A monopsony firm faces:","options":["a negatively-sloped supply curve","a positively-sloped supply curve","a negatively-sloped demand curve","None of the above"],"correctOption":1,"section":"Market Structures","explanation":"A monopsonist is the only buyer of a factor, so it faces the whole market supply curve of that factor, which slopes upward: to hire more, it must offer a higher price. Option A is wrong because factor supply curves normally slope upward, not downward. Option C describes the demand curve facing a monopolist, a sole seller."}},{"itemId":"ecbec783-4bb4-5b3d-bc73-464065aef9a7","questionId":"9591ceed-670b-5e3f-b332-ff7c1afda248","sourceKey":"bank:ECO101:ECO-0500","payload":{"prompt":"A highly concentrated market with just a few interdependent firms","options":["Perfect competition","Monopolistic competition","Oligopoly","Monopoly"],"correctOption":2,"section":"Market Structures","explanation":"An oligopoly is a market dominated by a few large firms, so the market is highly concentrated and each firm must watch its rivals' reactions. Option D, monopoly, has only one firm, so there are no rivals to be interdependent with. Option B, monopolistic competition, has many firms, so it is not highly concentrated."}},{"itemId":"fb786c8e-6a95-5aeb-bc71-f5d08f1b24bb","questionId":"3c13a7d7-19e6-5bb9-87d0-522946cd8782","sourceKey":"bank:ECO101:ECO-0501","payload":{"prompt":"A highly competitive market where firms are price takers","options":["Perfect competition","Monopolistic competition","Oligopoly","Monopoly"],"correctOption":0,"section":"Market Structures","explanation":"In perfect competition there are so many firms selling identical products that no single firm can influence the price, so each is a price taker. Options C and D, oligopoly and monopoly, give firms power to set prices. Option B, monopolistic competition, is competitive, but each firm has some control over price because its product is differentiated."}},{"itemId":"815ccc66-ea62-5b7c-83c5-46a4ef9b7960","questionId":"2e4320b6-74f2-562b-bb2a-904f51b1532d","sourceKey":"bank:ECO101:ECO-0503","payload":{"prompt":"A perfectly competitive firm is a price:","options":["Taker","Maker","A & B","None of the above"],"correctOption":0,"section":"Market Structures","explanation":"A perfectly competitive firm is a price taker because it is too small relative to the market to affect the price; it simply accepts the market price. Option B, price maker, describes a firm with market power, such as a monopolist. Option C is wrong because a firm cannot be both a taker and a maker of price."}},{"itemId":"e1e6cc66-4087-5590-a727-1d9e43812845","questionId":"44a515fb-a94b-50a9-85e2-62602253331f","sourceKey":"bank:ECO101:ECO-0532","payload":{"prompt":"A monopsonist is a price:","options":["Taker","Maker","A & B","None of the above"],"correctOption":1,"section":"Market Structures","explanation":"A monopsonist is the only buyer in a market, so it can influence the price it pays, for example by offering a lower wage and hiring fewer workers. That makes it a price maker (price setter). Option A, price taker, describes a buyer or seller in a perfectly competitive market who must accept the going price."}},{"itemId":"ec413da7-1060-5598-9ea1-e1461b853277","questionId":"b620e999-a486-5f70-bad9-2846c1e40b54","sourceKey":"bank:ECO101:ECO-0689","payload":{"prompt":"The average revenue curve of a monopolist is:","options":["Upward sloping","Downward sloping","A horizontal straight line","A vertical straight line"],"correctOption":1,"section":"Market Structures","explanation":"A monopolist faces the whole market demand curve, which is also its AR curve, so it must lower its price to sell more and the AR curve slopes downward. Option C is the AR curve of a firm in perfect competition, which can sell any amount at the market price."}}]}$official_bank_source$::jsonb;
  v_course uuid := (v_bank->>'courseId')::uuid;
  v_actor uuid := (v_bank->>'actor')::uuid;
  v_seed_actor uuid := (v_bank->>'seedActor')::uuid;
  v_audited jsonb;
  v_final jsonb;
  v_live jsonb;
  v_row jsonb;
  v_id uuid;
  v_item public.managed_content_items%rowtype;
  v_catalogue uuid;
begin
  if p_action is null or p_action not in ('apply', 'rollback') then
    raise exception 'Official bank %: unknown action %', v_bank->>'code', p_action;
  end if;
  -- Every CBT question of the course, locked in one order before anything is read or written.
  perform 1 from public.managed_content_items
    where course_id = v_course and kind = 'cbt_question' order by id for update;
  -- A new course, once: its repository identity and the link from its catalogue course, which must already apply at the
  -- official level and semesters. A rerun finds them in place; anything else is refused.
  if p_action = 'apply' then
    insert into public.courses (id, content_key, is_shared)
      values (v_course, v_bank->'shell'->>'contentKey', null) on conflict do nothing;
    if not exists (select 1 from public.courses where id = v_course and content_key = v_bank->'shell'->>'contentKey') then
      raise exception 'Official bank %: the repository identity is not this course''s', v_bank->>'code';
    end if;
    update public.institutional_courses set repository_course_id = v_course
      where course_code = v_bank->>'code' and repository_course_id is null
        and display_title in (select jsonb_array_elements_text(v_bank->'shell'->'titles'));
    select id into v_catalogue from public.institutional_courses
      where course_code = v_bank->>'code' and repository_course_id = v_course;
    if v_catalogue is null or (select count(*) from public.institutional_courses where course_code = v_bank->>'code') <> 1 then
      raise exception 'Official bank %: the catalogue course is not linked exactly once', v_bank->>'code';
    end if;
    -- Which students see the course stays the catalogue's: the import never adds or removes applicability rows.
    -- It refuses a catalogue course that does not already apply at the official level in every official semester.
    if exists (select 1 from jsonb_array_elements_text(v_bank->'shell'->'semesters') s(key)
        where not exists (select 1 from public.course_applicability a
          join public.academic_levels l on l.id = a.academic_level_id
          join public.academic_periods p on p.id = a.academic_period_id
          where a.institutional_course_id = v_catalogue and l.key = v_bank->'shell'->>'level' and p.key = s.key)) then
      raise exception 'Official bank %: the catalogue course does not apply at the official level in every official semester',
        v_bank->>'code';
    end if;
  end if;
  select coalesce(jsonb_object_agg(value, 1), '{}') into v_audited from jsonb_array_elements_text(v_bank->'audited');
  select coalesce(jsonb_object_agg(k.value->>'itemId', case when (k.value->>'revise')::boolean then 2 else 1 end), '{}')
    || coalesce((select jsonb_object_agg(a.value->>'itemId', 1) from jsonb_array_elements(v_bank->'add') a), '{}')
    into v_final from jsonb_array_elements(v_bank->'keep') k;
  select coalesce(jsonb_object_agg(id::text, published_revision), '{}') into v_live from public.managed_content_items
    where course_id = v_course and kind = 'cbt_question' and published_revision is not null;

  if p_action = 'apply' then
    if v_live = v_final then
      return 'unchanged';
    end if;
    if v_live <> v_audited then
      raise exception 'Official bank %: the published questions are not the audited set', v_bank->>'code';
    end if;

    -- Kept questions keep their item and question id; a different bank payload becomes the next revision.
    for v_row in select value from jsonb_array_elements(v_bank->'keep') where (value->>'revise')::boolean loop
      select * into v_item from public.managed_content_items where id = (v_row->>'itemId')::uuid;
      if v_item.created_by is distinct from v_seed_actor then
        raise exception 'Official bank %: % is not a migration-owned question', v_bank->>'code', v_item.id;
      end if;
      if exists (select 1 from public.managed_content_revisions where item_id = v_item.id and revision = 2) then
        if not exists (select 1 from public.managed_content_revisions where item_id = v_item.id and revision = 2
            and payload = v_row->'payload' and authored_by = v_actor) or v_item.current_revision <> 2 then
          raise exception 'Official bank %: % has another revision two', v_bank->>'code', v_item.id;
        end if;
      else
        if v_item.current_revision <> 1 then
          raise exception 'Official bank %: % has an unpublished edit', v_bank->>'code', v_item.id;
        end if;
        perform private.assert_managed_payload('cbt_question', v_row->'payload');
        insert into public.managed_content_revisions (item_id, revision, payload, authored_by)
          values (v_item.id, 2, v_row->'payload', v_actor);
        update public.managed_content_items set current_revision = 2, lock_version = lock_version + 1,
          updated_at = now() where id = v_item.id returning * into v_item;
      end if;
      if v_item.approved_revision is distinct from 2 then
        insert into public.managed_content_reviews (item_id, revision, parent_revision, decision, reviewed_by, lock_version)
          values (v_item.id, 2, null, 'approved', v_actor, v_item.lock_version + 1);
        update public.managed_content_items set approved_revision = 2, lock_version = lock_version + 1,
          updated_at = now() where id = v_item.id returning * into v_item;
      end if;
      insert into public.managed_content_publications (item_id, lock_version, action, revision, parent_revision,
          previous_revision, previous_parent_revision, acted_by)
        values (v_item.id, v_item.lock_version + 1, 'publish', 2, null, v_item.published_revision, null, v_actor);
      update public.managed_content_items set published_revision = 2, lock_version = lock_version + 1,
        updated_at = now() where id = v_item.id;
    end loop;

    -- Retired questions are unpublished, never deleted: past attempts and reports keep their pinned revision.
    for v_id in select value::uuid from jsonb_array_elements_text(v_bank->'retire') loop
      select * into v_item from public.managed_content_items where id = v_id;
      insert into public.managed_content_publications (item_id, lock_version, action, previous_revision, acted_by)
        values (v_id, v_item.lock_version + 1, 'unpublish', v_item.published_revision, v_actor);
      update public.managed_content_items set published_revision = null, lock_version = lock_version + 1,
        updated_at = now() where id = v_id;
    end loop;

    -- New questions: created, approved and published at revision one, or republished after a rollback.
    for v_row in select value from jsonb_array_elements(v_bank->'add') loop
      select * into v_item from public.managed_content_items where id = (v_row->>'itemId')::uuid for update;
      if found then
        if v_item.created_by is distinct from v_actor or v_item.course_id is distinct from v_course or
           v_item.kind is distinct from 'cbt_question' or v_item.question_id is distinct from (v_row->>'questionId')::uuid or
           v_item.source_key is distinct from v_row->>'sourceKey' or v_item.approved_revision is distinct from 1 or
           not exists (select 1 from public.managed_content_revisions r where r.item_id = v_item.id and r.revision = 1
             and r.payload = v_row->'payload' and r.authored_by = v_actor) then
          raise exception 'Official bank %: % is not the same migration-owned question', v_bank->>'code', v_item.id;
        end if;
        insert into public.managed_content_publications (item_id, lock_version, action, revision,
            previous_revision, acted_by)
          values (v_item.id, v_item.lock_version + 1, 'publish', 1, v_item.published_revision, v_actor);
        update public.managed_content_items set published_revision = 1, lock_version = lock_version + 1,
          updated_at = now() where id = v_item.id;
        continue;
      end if;
      perform private.assert_managed_payload('cbt_question', v_row->'payload');
      insert into public.managed_content_items (id, course_id, kind, question_id, source_key, parent_item_id,
          current_revision, approved_revision, published_revision, published_parent_revision, lock_version, created_by)
        values ((v_row->>'itemId')::uuid, v_course, 'cbt_question', (v_row->>'questionId')::uuid,
          v_row->>'sourceKey', null, 1, 1, 1, null, 3, v_actor);
      insert into public.managed_content_revisions (item_id, revision, payload, authored_by)
        values ((v_row->>'itemId')::uuid, 1, v_row->'payload', v_actor);
      insert into public.managed_content_reviews (item_id, revision, parent_revision, decision, reviewed_by, lock_version)
        values ((v_row->>'itemId')::uuid, 1, null, 'approved', v_actor, 2);
      insert into public.managed_content_publications (item_id, lock_version, action, revision, parent_revision, acted_by)
        values ((v_row->>'itemId')::uuid, 3, 'publish', 1, null, v_actor);
    end loop;

    select coalesce(jsonb_object_agg(id::text, published_revision), '{}') into v_live from public.managed_content_items
      where course_id = v_course and kind = 'cbt_question' and published_revision is not null;
    if v_live <> v_final or (select count(*) from jsonb_object_keys(v_live)) <> (v_bank->>'bankCount')::integer then
      raise exception 'Official bank %: the final published count is not the bank count', v_bank->>'code';
    end if;
    return 'applied';
  end if;

  -- Rollback: publication is a pointer, so the audited set is republished through the same history.
  if v_live = v_audited then
    return 'unchanged';
  end if;
  if v_live <> v_final then
    raise exception 'Official bank %: the published questions are not the imported set', v_bank->>'code';
  end if;
  for v_row in select value from jsonb_array_elements(v_bank->'keep') where (value->>'revise')::boolean loop
    select * into v_item from public.managed_content_items where id = (v_row->>'itemId')::uuid;
    insert into public.managed_content_reviews (item_id, revision, parent_revision, decision, reviewed_by, lock_version)
      values (v_item.id, 1, null, 'approved', v_actor, v_item.lock_version + 1);
    insert into public.managed_content_publications (item_id, lock_version, action, revision, parent_revision,
        previous_revision, previous_parent_revision, acted_by)
      values (v_item.id, v_item.lock_version + 2, 'publish', 1, null, v_item.published_revision, null, v_actor);
    update public.managed_content_items set approved_revision = 1, published_revision = 1,
      lock_version = lock_version + 2, updated_at = now() where id = v_item.id;
  end loop;
  for v_id in select value::uuid from jsonb_array_elements_text(v_bank->'retire') loop
    select * into v_item from public.managed_content_items where id = v_id;
    if v_item.approved_revision is distinct from 1 then
      raise exception 'Official bank %: % is no longer approved at revision one', v_bank->>'code', v_id;
    end if;
    insert into public.managed_content_publications (item_id, lock_version, action, revision, acted_by)
      values (v_id, v_item.lock_version + 1, 'publish', 1, v_actor);
    update public.managed_content_items set published_revision = 1, lock_version = lock_version + 1,
      updated_at = now() where id = v_id;
  end loop;
  for v_row in select value from jsonb_array_elements(v_bank->'add') loop
    select * into v_item from public.managed_content_items where id = (v_row->>'itemId')::uuid;
    insert into public.managed_content_publications (item_id, lock_version, action, previous_revision, acted_by)
      values (v_item.id, v_item.lock_version + 1, 'unpublish', v_item.published_revision, v_actor);
    update public.managed_content_items set published_revision = null, lock_version = lock_version + 1,
      updated_at = now() where id = v_item.id;
  end loop;
  select coalesce(jsonb_object_agg(id::text, published_revision), '{}') into v_live from public.managed_content_items
    where course_id = v_course and kind = 'cbt_question' and published_revision is not null;
  if v_live <> v_audited then
    raise exception 'Official bank %: rollback did not restore the audited set', v_bank->>'code';
  end if;
  return 'rolled-back';
end;
$official_bank$;

revoke all on function private.official_bank_eco101(text) from public, anon, authenticated, service_role;
select private.official_bank_eco101('apply');
